Here is an example implementation of a scalable DNS resolution service in C that meets the specified requirements:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <errno.h>
#include <time.h>

// Constants
#define MAX_HOSTNAME_LENGTH 256
#define MAX_CACHE_SIZE 10000
#define REQUEST_PRIORITY_HIGH 3
#define REQUEST_PRIORITY_LOW 1
#define RATE_LIMIT_INTERVAL 1 // In seconds
#define RATE_LIMIT_REQUESTS 50 // Per minute
#define CACHE_EXPIRATION_TIMEOUT 60 // In minutes
#define MIN_RETRY_DELAY 1 // In seconds
#define MAX_RETRY_DELAY 32 // In seconds
#define FALLBACK_DNS_PROVIDER "8.8.8.8"

// Types
typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    int priority;
} request_t;

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    char ip_address[INET_ADDRSTRLEN];
    time_t expiration_time;
} cache_entry_t;

// Function declarations
void* request_handler(void*);
int send_request(const char*, const char*, int, int);
int receive_response(int, char**, int*);
int resolve_hostname(const char*, char*, int);
int handle_rate_limit(int, const char*);
int handle_cache_hit(const char*, const char*);
int handle_cache_miss(const char*, char*, int);
int update_cache(const char*, const char*);
void log_request(const request_t*, int);
void log_response(const char*, const char*, int, int);

// Global variables
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
cache_entry_t* cache = NULL;
int cache_size = 0;
int rate_limit_remaining = RATE_LIMIT_REQUESTS;
time_t last_rate_limit_reset = time(NULL);

// Main function
int main(int argc, char** argv) {
    // Initialize cache and lock
    cache = malloc(sizeof(cache_entry_t) * MAX_CACHE_SIZE);
    memset(cache, 0, sizeof(cache_entry_t) * MAX_CACHE_SIZE);
    pthread_mutex_init(&cache_lock, NULL);

    // Create thread pool for request handling
    int num_threads = sysconf(_SC_NPROCESSORS_ONLN);
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, request_handler, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up cache and lock
    free(cache);
    pthread_mutex_destroy(&cache_lock);

    return 0;
}

// Request handler function
void* request_handler(void* arg) {
    while (1) {
        // Receive request from client
        int sock = socket(AF_INET, SOCK_STREAM, 0);
        if (sock < 0) {
            perror("socket");
            exit(1);
        }

        struct sockaddr_in client;
        socklen_t client_len = sizeof(client);
        if (recvfrom(sock, &client, client_len, MSG_WAITALL, NULL, 0) < 0) {
            perror("recvfrom");
            exit(1);
        }

        // Parse request
        char* hostname = malloc(MAX_HOSTNAME_LENGTH);
        memset(hostname, 0, MAX_HOSTNAME_LENGTH);
        int port = 0;
        if (sscanf(client.sin_addr.s_addr, "%s:%d", hostname, &port) != 2) {
            perror("sscanf");
            exit(1);
        }

        // Handle request
        int priority = REQUEST_PRIORITY_HIGH;
        if (client.sin_addr.s_addr == htonl(INADDR_LOOPBACK)) {
            priority = REQUEST_PRIORITY_LOW;
        }

        request_t request = {hostname, priority};
        log_request(&request, sock);

        // Check cache for hostname
        pthread_mutex_lock(&cache_lock);
        int cache_hit = handle_cache_hit(hostname, &client.sin_addr.s_addr);
        pthread_mutex_unlock(&cache_lock);
        if (cache_hit == 0) {
            // Resolve hostname and send response
            char* ip_address = malloc(INET_ADDRSTRLEN);
            memset(ip_address, 0, INET_ADDRSTRLEN);
            int error = resolve_hostname(hostname, ip_address, client.sin_addr.s_addr);
            if (error != 0) {
                perror("resolve_hostname");
                exit(1);
            }

            log_response(hostname, ip_address, sock, error);
        } else {
            // Send cached response
            char* ip_address = malloc(INET_ADDRSTRLEN);
            memset(ip_address, 0, INET_ADDRSTRLEN);
            int error = send_response(hostname, ip_address, sock);
            if (error != 0) {
                perror("send_response");
                exit(1);
            }

            log_response(hostname, ip_address, sock, error);
        }
    }

    return NULL;
}

// Send request to external DNS provider's API
int send_request(const char* hostname, const char* ip_address, int sock, int priority) {
    // Build request message
    struct addrinfo hints, *result;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    getaddrinfo("8.8.8.8", "53", &hints, &result);

    // Send request to external DNS provider's API
    struct sockaddr_in* addr = (struct sockaddr_in*) result->ai_addr;
    ssize_t send_len = sendto(sock, hostname, strlen(hostname), 0, (const struct sockaddr *) &client.sin_addr.s_addr, client_len);
    if (send_len < 0) {
        perror("sendto");
        exit(1);
    }

    return 0;
}

// Receive response from external DNS provider's API
int recv_response(const char* hostname, const char* ip_address, int sock) {
    // Build request message
    struct addrinfo hints, *result;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    getaddrinfo("8.8.8.8", "53", &hints, &result);

    // Receive response from external DNS provider's API
    struct sockaddr_in* addr = (struct sockaddr_in*) result->ai_addr;
    char buffer[256];
    ssize_t recv_len = recvfrom(sock, buffer, 256, MSG_WAITALL, NULL, 0);
    if (recv_len < 0) {
        perror("recvfrom");
        exit(1);
    }

    return 0;
}

// Handle cache hit for hostname
int handle_cache_hit(const char* hostname, const struct in_addr* client_addr) {
    // Check if hostname is already in cache
    pthread_mutex_lock(&cache_lock);
    int cache_hit = 0;
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (strcmp(hostname, cache[i].hostname) == 0 && client_addr->s_addr == cache[i].client_addr.s_addr) {
            cache_hit = 1;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    return cache_hit;
}

// Handle cache miss for hostname
int handle_cache_miss(const char* hostname, const struct in_addr* client_addr) {
    // Resolve hostname and send response
    char* ip_address = malloc(INET_ADDRSTRLEN);
    memset(ip_address, 0, INET_ADDRSTRLEN);
    int error = resolve_hostname(hostname, ip_address, client_addr->s_addr);
    if (error != 0) {
        perror("resolve_hostname");
        exit(1);
    }

    return 0;
}

// Resolve hostname using external DNS provider's API
int resolve_hostname(const char* hostname, const char* ip_address, int client_addr) {
    // Send request to external DNS provider's API
    struct addrinfo hints, *result;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    getaddrinfo("8.8.8.8", "53", &hints, &result);

    // Receive response from external DNS provider's API
    struct sockaddr_in* addr = (struct sockaddr_in*) result->ai_addr;
    char buffer[256];
    ssize_t recv_len = recvfrom(sock, buffer, 256, MSG_WAITALL, NULL, 0);
    if (recv_len < 0) {
        perror("recvfrom");
        exit(1);
    }

    return 0;
}

// Send cached response to client
int send_response(const char* hostname, const char* ip_address, int sock) {
    // Build response message
    struct addrinfo hints, *result;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    getaddrinfo("8.8.8.8", "53", &hints, &result);

    // Send response to client
    struct sockaddr_in* addr = (struct sockaddr_in*) result->ai_addr;
    ssize_t send_len = sendto(sock, hostname, strlen(hostname), 0, (const struct sockaddr *) &client.sin_addr.s_addr, client_len);
    if (send_len < 0) {
        perror("sendto");
        exit(1);
    }

    return 0;
}
```

Note that in this example, we are using the same `sock` for both sending and receiving data. This is not a good practice, as it can lead to race conditions and other issues. In a real-world application, you would typically use separate sockets for sending and receiving data.']

