['Here is a sample code for the encryption service:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/cipher.h>
#include <openssl/x509.h>
#include <openssl/err.h>

// Constants for the encryption service
#define BLOCK_SIZE 16
#define KEY_SIZE 32
#define IV_SIZE 16
#define CIPHER "aes-256-cbc"

// Struct for storing metadata about a file
struct file_metadata {
    char filename[256];
    int size;
    char* iv;
};

// Function to generate a random IV for encryption
void generate_iv(unsigned char *iv) {
    RAND_bytes(iv, IV_SIZE);
}

// Function to encrypt a file using AES-256 CBC
int encrypt_file(const char* filename, const unsigned char* key) {
    // Open the file for reading
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("Error opening file");
        return -1;
    }

    // Allocate memory for the encrypted data
    unsigned char* encrypted_data = malloc(BLOCK_SIZE);
    if (!encrypted_data) {
        fprintf(stderr, "Failed to allocate memory for encrypted data\n");
        close(fd);
        return -1;
    }

    // Generate a random IV
    unsigned char iv[IV_SIZE];
    generate_iv(iv);

    // Initialize the cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        free(encrypted_data);
        close(fd);
        return -1;
    }

    // Set the encryption key and IV
    EVP_CipherInit(ctx, EVP_get_cipherbyname(CIPHER), NULL, NULL, 1);
    EVP_CIPHER_CTX_set_key_length(ctx, KEY_SIZE);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_IVLEN, IV_SIZE, NULL);
    EVP_CipherInit(ctx, NULL, key, iv, 1);

    // Encrypt the file block by block
    int encrypted_size = 0;
    while (1) {
        int read_bytes = read(fd, encrypted_data, BLOCK_SIZE);
        if (read_bytes <= 0) {
            break;
        }
        EVP_CipherUpdate(ctx, NULL, &encrypted_size, encrypted_data, read_bytes);
    }

    // Finalize the encryption and get the IV
    unsigned char final_iv[IV_SIZE];
    int final_iv_len = 0;
    EVP_CipherFinal(ctx, NULL, &encrypted_size);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GET_FINAL_IV, IV_SIZE, final_iv);
    EVP_CIPHER_CTX_free(ctx);

    // Write the encrypted data to a new file
    char* encrypted_filename = malloc(strlen(filename) + 5);
    sprintf(encrypted_filename, "%s.enc", filename);
    int efd = open(encrypted_filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (efd < 0) {
        perror("Error opening encrypted file");
        free(encrypted_data);
        free(encrypted_filename);
        close(fd);
        return -1;
    }
    write(efd, encrypted_data, encrypted_size);
    close(efd);

    // Store the metadata about the encrypted file
    struct file_metadata* meta = malloc(sizeof(struct file_metadata));
    strcpy(meta->filename, filename);
    meta->size = encrypted_size;
    meta->iv = malloc(IV_SIZE);
    memcpy(meta->iv, final_iv, IV_SIZE);
    free(encrypted_data);
    free(encrypted_filename);
    close(fd);
    return 0;
}

// Function to decrypt a file using AES-256 CBC
int decrypt_file(const char* filename, const unsigned char* key) {
    // Open the encrypted file for reading
    int efd = open(filename, O_RDONLY);
    if (efd < 0) {
        perror("Error opening encrypted file");
        return -1;
    }

    // Get the metadata about the encrypted file
    struct file_metadata* meta = malloc(sizeof(struct file_metadata));
    strcpy(meta->filename, filename);
    meta->size = lseek(efd, 0, SEEK_END);
    meta->iv = malloc(IV_SIZE);
    read(efd, meta->iv, IV_SIZE);
    close(efd);

    // Open the decrypted file for writing
    char* decrypted_filename = malloc(strlen(filename) + 5);
    sprintf(decrypted_filename, "%s.dec", filename);
    int dfd = open(decrypted_filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (dfd < 0) {
        perror("Error opening decrypted file");
        free(meta->iv);
        free(meta);
        return -1;
    }

    // Initialize the cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        free(meta->iv);
        free(meta);
        close(dfd);
        return -1;
    }

    // Set the decryption key and IV
    EVP_CipherInit(ctx, EVP_get_cipherbyname(CIPHER), NULL, NULL, 0);
    EVP_CIPHER_CTX_set_key_length(ctx, KEY_SIZE);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_IVLEN, IV_SIZE, NULL);
    EVP_CipherInit(ctx, NULL, key, meta->iv, 0);

    // Decrypt the file block by block
    int decrypted_size = 0;
    while (1) {
        int read_bytes = read(dfd, encrypted_data, BLOCK_SIZE);
        if (read_bytes <= 0) {
            break;
        }
        EVP_CipherUpdate(ctx, NULL, &decrypted_size, encrypted_data, read_bytes);
    }

    // Finalize the decryption and get the final IV
    unsigned char final_iv[IV_SIZE];
    int final_iv_len = 0;
    EVP_CipherFinal(ctx, NULL, &decrypted_size);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GET_FINAL_IV, IV_SIZE, final_iv);
    EVP_CIPHER_CTX_free(ctx);

    // Compare the final IV with the original one and fail if they don't match
    if (memcmp(final_iv, meta->iv, IV_SIZE)) {
        fprintf(stderr, "Failed to verify integrity of decrypted file\n");
        free(decrypted_data);
        free(decrypted_filename);
        return -1;
    }

    // Write the decrypted data to a new file
    char* decrypted_filename = malloc(strlen(filename) + 5);
    sprintf(decrypted_filename, "%s.dec", filename);
    int dfd = open(decrypted_filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (dfd < 0) {
        perror("Error opening decrypted file");
        free(meta->iv);
        free(meta);
        return -1;
    }
    write(dfd, decrypted_data, decrypted_size);
    close(dfd);

    // Free the metadata and return successfully
    free(decrypted_data);
    free(decrypted_filename);
    free(meta->iv);
    free(meta);
    return 0;
}

// Main function to demonstrate the usage of the above functions
int main() {
    // Prepare some test data
    char* filename = "test.txt";
    unsigned char key[] = "secretkey";

    // Encrypt and decrypt the file using AES-256 CBC
    encrypt_file(filename, key);
    decrypt_file(filename, key);

    return 0;
}']

['Here's an example implementation of a multi-threaded semaphore management system using Java:
```java
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.ReentrantLock;
import java.util.logging.Logger;

public class SemaphoreManager {
  private static final Logger LOGGER = Logger.getLogger(SemaphoreManager.class.getName());
  private AtomicInteger semaphoreCounter = new AtomicInteger();
  private ReentrantLock lock = new ReentrantLock();

  public void acquire() {
    try {
      int currentValue;
      do {
        currentValue = semaphoreCounter.get();
        if (currentValue >= 1000) {
          Thread.sleep(100); // Wait for a short time before retrying
        } else {
          semaphoreCounter.incrementAndGet();
          break;
        }
      } while (true);
    } catch (InterruptedException e) {
      LOGGER.log(Level.WARNING, "Acquire interrupted", e);
    } finally {
      lock.unlock();
    }
  }

  public void release() {
    try {
      int currentValue = semaphoreCounter.decrementAndGet();
      if (currentValue < 0) {
        // Semaphore counter has gone below zero, reset it to zero
        semaphoreCounter.set(0);
      }
    } catch (Exception e) {
      LOGGER.log(Level.WARNING, "Release failed", e);
    } finally {
      lock.unlock();
    }
  }

  public boolean isAvailable() {
    return semaphoreCounter.get() < 1000;
  }
}
```
This implementation uses an `AtomicInteger` to keep track of the number of available slots in the semaphore, and a `ReentrantLock` to ensure that only one thread can modify the counter at a time. The `acquire()` method tries to increment the counter by 1 until it is able to do so without exceeding the maximum value of 1000. If the counter has already reached its maximum value, the method waits for a short period of time before retrying.

The `release()` method decrements the counter and checks if it has gone below zero. If it has, it sets the counter to zero to prevent any further decrements from causing issues.

The `isAvailable()` method returns `true` if there are still available slots in the semaphore, and `false` otherwise. This can be used to check whether a request can be processed or not.

