    std::atomic<bool> isUpdating_ = false;
    std::vector<int> seq_;
};

// Sequence.cpp

#include "Sequence.h"

void Sequence::append(int value) {
    std::lock_guard<std::mutex> lock(mtx_);
    seq_.push_back(value);
}

void Sequence::update(int index, int value) {
    std::lock_guard<std::mutex> lock(mtx_);
    if (index >= 0 && index < seq_.size()) {
        seq_[index] = value;
    } else {
        // handle out-of-range update
    }
}

void Sequence::remove(int index) {
    std::lock_guard<std::mutex> lock(mtx_);
    if (index >= 0 && index < seq_.size()) {
        seq_.erase(seq_.begin() + index);
    } else {
        // handle out-of-range remove
    }
}

const std::vector<int>& Sequence::get() const {
    return seq_;
}

// applyUpdates function implementation
void applyUpdates(Sequence& seq, const std::vector<std::pair<int, int>>& updates) {
    // 1. Atomically update the sequence using a lock-free data structure or atomic operations
    for (const auto& [index, value] : updates) {
        if (index >= 0 && index < seq.size()) {
            seq.update(index, value);
        } else {
            // handle out-of-range update
        }
    }

    // 2. Remove any duplicates or invalid indices from the sequence
    std::sort(seq.begin(), seq.end());
    seq.erase(std::unique(seq.begin(), seq.end()), seq.end());
}

// Unit tests for Sequence and applyUpdates functions

TEST(SequenceTest, AppendAndGet) {
    Sequence seq;
    seq.append(1);
    EXPECT_EQ(seq.get().size(), 1);
    EXPECT_EQ(seq.get()[0], 1);
}

TEST(SequenceTest, UpdateAndGet) {
    Sequence seq;
    seq.update(0, 10);
    EXPECT_EQ(seq.get().size(), 1);
    EXPECT_EQ(seq.get()[0], 10);
}

TEST(SequenceTest, RemoveAndGet) {
    Sequence seq;
    seq.append(5);
    seq.remove(0);
    EXPECT_EQ(seq.get().size(), 0);
}

TEST(ApplyUpdatesTest, Basic) {
    Sequence seq;
    std::vector<std::pair<int, int>> updates = {{1, 2}, {3, 4}};
    applyUpdates(seq, updates);
    EXPECT_EQ(seq.get().size(), 2);
    EXPECT_EQ(seq.get()[0], 1);
    EXPECT_EQ(seq.get()[1], 3);
}

TEST(ApplyUpdatesTest, Duplicates) {
    Sequence seq;
    std::vector<std::pair<int, int>> updates = {{1, 2}, {3, 4}, {1, 5}};
    applyUpdates(seq, updates);
    EXPECT_EQ(seq.get().size(), 2);
    EXPECT_EQ(seq.get()[0], 1);
    EXPECT_EQ(seq.get()[1], 3);
}

TEST(ApplyUpdatesTest, OutOfRange) {
