import os
import sys
import requests
import json
from concurrent.futures import ThreadPoolExecutor

class SandeshClient:
    def __init__(self):
        self.metadata_url = "https://external-metadata-service.com"
        self.cache = {}

    def get_vm_uuid(self, ip_address):
        # Check cache first
        if ip_address in self.cache:
            return self.cache[ip_address]

        # Make API request to external metadata service
        try:
            response = requests.get(f"{self.metadata_url}/vm/{ip_address}")
            data = json.loads(response.content)
            uuid = data["uuid"]
            self.cache[ip_address] = uuid
            return uuid
        except requests.exceptions.RequestException as e:
            print(f"Error connecting to metadata service: {e}")

    def get_vms_by_ips(self, ip_list):
        # Create a list of futures for concurrent API requests
        futures = []
        for ip in ip_list:
            futures.append(ThreadPoolExecutor.submit(self.get_vm_uuid, ip))

        # Wait for all futures to complete and handle errors
        results = []
        for future in as_completed(futures):
            try:
                results.append(future.result())
            except Exception as e:
                print(f"Error retrieving VM UUID for IP {ip}: {e}")

        return results

    def get_vm_ips(self, vm_uuids):
        # Create a list of futures for concurrent API requests
        futures = []
        for uuid in vm_uuids:
            futures.append(ThreadPoolExecutor.submit(self.get_vm_ip, uuid))

        # Wait for all futures to complete and handle errors
        results = []
        for future in as_completed(futures):
            try:
                results.append(future.result())
            except Exception as e:
                print(f"Error retrieving IP address for VM {uuid}: {e}")

        return results

    def get_vms_by_ips_and_uuids(self, ip_list, vm_uuids):
        # Create a list of futures for concurrent API requests
        futures = []
        for ip in ip_list:
            futures.append(ThreadPoolExecutor.submit(self.get_vm_uuid, ip))

        # Wait for all futures to complete and handle errors
        results = []
        for future in as_completed(futures):
            try:
                results.append(future.result())
            except Exception as e:
                print(f"Error retrieving VM UUID for IP {ip}: {e}")

        return results
```

