namespace ConfigurationManager {
    public class ConfigManager {
        private static readonly object _lock = new object();
        private static readonly Dictionary<string, string> _configs = new Dictionary<string, string>();
        private static readonly List<string> _sections = new List<string>();

        private const int DEFAULT_TIMEOUT = 5000; // milliseconds
        private const int MAX_RETRY_ATTEMPTS = 3;

        public static void LoadConfig(string configPath) {
            lock (_lock) {
                if (!File.Exists(configPath)) {
                    throw new FileNotFoundException($"Config file '{configPath}' does not exist");
                }

                XDocument doc = XDocument.Load(configPath);
                foreach (var section in doc.Root.Elements()) {
                    if (!_sections.Contains(section.Name.LocalName)) {
                        _sections.Add(section.Name.LocalName);
                    }

                    foreach (var param in section.Elements()) {
                        string key = $"{section.Name.LocalName}.{param.Name.LocalName}";
                        if (!_configs.ContainsKey(key)) {
                            _configs[key] = param.Value;
                        }
                    }
                }
            }
        }

        public static string GetConfig(string section, string parameter) {
            lock (_lock) {
                string key = $"{section}.{parameter}";
                if (!_configs.ContainsKey(key)) {
                    throw new KeyNotFoundException($"Parameter '{parameter}' not found in section '{section}'");
                }

                return _configs[key];
            }
        }

        public static void SetConfig(string section, string parameter, string value) {
            lock (_lock) {
                string key = $"{section}.{parameter}";
                if (!_configs.ContainsKey(key)) {
                    _configs[key] = value;
                } else {
                    _configs[key] = value;
                }
            }
        }

        public static void SaveConfig() {
            lock (_lock) {
                // Save config to file
            }
        }

        private static async Task<string> GetExternalServiceResponse(string url, int timeout, int retryAttempts = MAX_RETRY_ATTEMPTS) {
            if (retryAttempts <= 0) {
                throw new TimeoutException("Timed out while trying to get response from external service");
            }

            try {
                using var httpClient = new HttpClient();
                httpClient.Timeout = timeout;
                return await httpClient.GetStringAsync(url);
            } catch (HttpRequestException e) {
                Console.WriteLine($"Error while trying to get response from external service: {e.Message}");
                retryAttempts--;
                return await GetExternalServiceResponse(url, timeout, retryAttempts);
            }
        }

        public static async Task<string> GetConfigFromExternalServiceAsync(string url) {
            int timeout = DEFAULT_TIMEOUT;
            string response = "";

            while (response == "") {
                try {
                    response = await GetExternalServiceResponse(url, timeout);
                } catch (TimeoutException e) {
                    Console.WriteLine($"Timed out while trying to get response from external service: {e.Message}");
                    timeout *= 2; // exponential backoff
                } catch (HttpRequestException e) {
                    Console.WriteLine($"Error while trying to get response from external service: {e.Message}");
                }
            }

            return response;
        }
    }
}
