import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ResourceManagementSystem {
  private static final int BATCH_SIZE = 100; // adjust this value based on the rate limits of the external API
  private static final long BATCH_DELAY = 5000L; // milliseconds between batch requests
  private static final long FALLBACK_DELAY = 30000L; // milliseconds to wait before retrying a failed request

  private final ScheduledExecutorService executor;
  private final ResourceApiClient apiClient;

  public ResourceManagementSystem(ResourceApiClient apiClient) {
    this.apiClient = apiClient;
    this.executor = Executors.newScheduledThreadPool(5); // adjust the number of threads based on your needs
  }

  public void updateResources(List<Long> resourceIds, boolean delete) throws IOException {
    if (resourceIds == null || resourceIds.isEmpty()) {
      return;
    }

    int numBatches = (int) Math.ceil((double) resourceIds.size() / BATCH_SIZE);
    List<List<Long>> batches = new ArrayList<>();

    for (int i = 0; i < numBatches; i++) {
      List<Long> batch = resourceIds.subList(i * BATCH_SIZE, Math.min((i + 1) * BATCH_SIZE, resourceIds.size()));
      batches.add(batch);
    }

    for (int i = 0; i < numBatches; i++) {
      executor.schedule(() -> updateBatch(batches.get(i), delete), i * BATCH_DELAY, TimeUnit.MILLISECONDS);
    }
  }

  private void updateBatch(List<Long> resourceIds, boolean delete) throws IOException {
    try {
      List<Resource> resources = apiClient.getResources(resourceIds);
      if (resources != null && !resources.isEmpty()) {
        if (delete) {
          apiClient.deleteResources(resources);
        } else {
          apiClient.updateResources(resources);
        }
      }
    } catch (IOException e) {
      System.out.println("Error updating resources: " + e.getMessage());
    }
  }

  public void deleteResource(Long resourceId) throws IOException {
    updateResource(resourceId, true);
  }

  public void updateResource(Long resourceId, boolean delete) throws IOException {
    if (delete) {
      apiClient.deleteResource(resourceId);
    } else {
      Resource resource = apiClient.getResource(resourceId);
      if (resource != null) {
        apiClient.updateResource(resource);
      }
    }
  }

  public List<Resource> getResources() throws IOException {
    return apiClient.getResources();
  }

  public Resource getResource(Long resourceId) throws IOException {
    return apiClient.getResource(resourceId);
  }
}
```
