        public void RemoveSource(string source)
        {
            if (sources.Contains(source))
                sources.Remove(source);
        }

        public void AddNamespace(string prefix, string uri)
        {
            namespaces[prefix] = uri;
        }

        public void RemoveNamespace(string prefix)
        {
            if (namespaces.ContainsKey(prefix))
                namespaces.Remove(prefix);
        }

        public void AddXPathExpression(string xpath, XPathExpression expression)
        {
            xpathExpressions[xpath] = expression;
        }

        public void RemoveXPathExpression(string xpath)
        {
            if (xpathExpressions.ContainsKey(xpath))
                xpathExpressions.Remove(xpath);
        }

        public void AddXQueryExpression(string xquery, XQueryExpression expression)
        {
            xqueryExpressions[xquery] = expression;
        }

        public void RemoveXQueryExpression(string xquery)
        {
            if (xqueryExpressions.ContainsKey(xquery))
                xqueryExpressions.Remove(xquery);
        }

        public void ProcessXml(string source, string xpath = null, string xquery = null)
        {
            XDocument document;
            XPathExpression compiledXPath = null;
            XQueryExpression compiledXQuery = null;

            // Check if the source is already in the cache
            lock (cacheLock)
            {
                if (cache.ContainsKey(source))
                {
                    document = cache[source];
                }
                else
                {
                    // Load the XML document from the source
                    document = LoadXmlDocument(source);
                    cache[source] = document;
                }
            }

            if (xpath != null)
            {
                // Compile the XPath expression and evaluate it on the document
                compiledXPath = GetCompiledXPathExpression(xpath);
                var xpathResult = compiledXPath.Evaluate(document);
                PrintResults(xpath, xpathResult);
            }

            if (xquery != null)
            {
                // Compile the XQuery expression and evaluate it on the document
                compiledXQuery = GetCompiledXQueryExpression(xquery);
                var xqueryResult = compiledXQuery.Evaluate(document);
                PrintResults(xquery, xqueryResult);
            }
        }

        private void PrintResults(string expression, object result)
        {
            Console.WriteLine("Results for expression: " + expression);
            if (result is XPathExpressionResult)
            {
                var nodes = (XPathExpressionResult)result;
                foreach (var node in nodes)
                {
                    Console.WriteLine(node.ToString());
                }
            }
            else if (result is XQueryExpressionResult)
            {
                var items = (XQueryExpressionResult)result;
                foreach (var item in items)
                {
                    Console.WriteLine(item);
                }
            }
        }

        private XDocument LoadXmlDocument(string source)
        {
            try
            {
                if (source.StartsWith("http://") || source.StartsWith("https://"))
                {
                    // Load the XML document from a URL
                    var url = new Uri(source);
                    return XDocument.Load(url.ToString());
                }
                else
                {
                    // Load the XML document from a file path
                    return XDocument.Load(source);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error loading XML document: " + ex.Message);
                throw;
            }
        }

        private XPathExpression GetCompiledXPathExpression(string xpath)
        {
            // Check if the expression is already compiled and cached
            var compiledXPath = cache.ContainsKey(xpath) ? (XPathExpression)cache[xpath] : null;
            if (compiledXPath == null)
            {
                // Compile the XPath expression and add it to the cache
                compiledXPath = new XPathExpression(xpath);
                cache[xpath] = compiledXPath;
            }
            return compiledXPath;
        }

        private XQueryExpression GetCompiledXQueryExpression(string xquery)
        {
            // Check if the expression is already compiled and cached
            var compiledXQuery = cache.ContainsKey(xquery) ? (XQueryExpression)cache[xquery] : null;
            if (compiledXQuery == null)
            {
                // Compile the XQuery expression and add it to the cache
                compiledXQuery = new XQueryExpression(xquery);
                cache[xquery] = compiledXQuery;
            }
            return compiledXQuery;
        }
    }
}
```
This library provides several features, including:

