['```java
package com.example.filehashing;

import java.io.FileInputStream;
import java.io.IOException;
import java.math.BigInteger;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import org.apache.commons.codec.binary.Hex;

public class FileHashingService {
    private static final int MAX_CHUNK_SIZE = 1024 * 1024; // 1MB
    private static final int MAX_CONCURRENT_CHUNKS = Runtime.getRuntime().availableProcessors();

    public BigInteger hashFile(String filePath) throws IOException {
        FileInputStream inputStream = new FileInputStream(filePath);
        MessageDigest digest = MessageDigest.getInstance("SHA-256");

        List<Chunk> chunks = new ArrayList<>();
        int chunkSize = Math.min(MAX_CHUNK_SIZE, inputStream.available());
        byte[] buffer = new byte[chunkSize];
        long totalBytesRead = 0;

        while (inputStream.read(buffer) > 0) {
            chunks.add(new Chunk(buffer));
            totalBytesRead += chunkSize;
        }

        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_CHUNKS);
        List<FutureResult> results = new ArrayList<>();

        for (Chunk chunk : chunks) {
            FutureResult result = new FutureResult();
            executor.submit(() -> {
                try {
                    digest.update(chunk.getData());
                    result.setResult(new BigInteger(1, digest.digest()));
                } catch (IOException e) {
                    result.setException(e);
                } finally {
                    executor.shutdown();
                }
            });
            results.add(result);
        }

        for (FutureResult result : results) {
            try {
                result.get().join();
            } catch (InterruptedException | ExecutionException e) {
                // handle error
            }
        }

        return digest.digest(results);
    }
}

class Chunk {
    private byte[] data;

    public Chunk(byte[] data) {
        this.data = data;
    }

    public byte[] getData() {
        return data;
    }
}

class FutureResult implements Runnable, Callable<BigInteger> {
    private BigInteger result;
    private Exception exception;

    @Override
    public void run() {
        // implementation of the runnable interface
    }

    @Override
    public BigInteger call() throws IOException {
        // implementation of the callable interface
    }

    public BigInteger getResult() {
        return result;
    }

    public void setResult(BigInteger result) {
        this.result = result;
    }

    public Exception getException() {
        return exception;
    }

    public void setException(Exception exception) {
        this.exception = exception;
    }
}
```
