<?php

// Define the request handler class
class RequestHandler {
  private $database;
  private $authenticationApi;

  // Constructor to initialize dependencies
  public function __construct(Database $database, AuthenticationApi $authenticationApi) {
    $this->database = $database;
    $this->authenticationApi = $authenticationApi;
  }

  // Handle incoming requests
  public function handleRequest($request) {
    switch ($request['action']) {
      case 'CREATE':
        return $this->createUser($request['user']);
      case 'UPDATE':
        return $this->updateUser($request['user']);
      case 'DELETE':
        return $this->deleteUser($request['user']);
      case 'FETCH_STATS':
        return $this->fetchStats($request['user']);
    }
  }

  // Create a new user
  private function createUser($user) {
    // Validate the user data using a schema
    $validationResult = $this->validateUserData($user);
    if ($validationResult['valid']) {
      // Save the user to the database
      return $this->database->saveUser($user);
    } else {
      // Return an error message
      return $validationResult['message'];
    }
  }

  // Update an existing user
  private function updateUser($user) {
    // Validate the user data using a schema
    $validationResult = $this->validateUserData($user);
    if ($validationResult['valid']) {
      // Save the user to the database
      return $this->database->updateUser($user);
    } else {
      // Return an error message
      return $validationResult['message'];
    }
  }

  // Delete a user
  private function deleteUser($user) {
    // Validate the user data using a schema
    $validationResult = $this->validateUserData($user);
    if ($validationResult['valid']) {
      // Save the user to the database
      return $this->database->deleteUser($user);
    } else {
      // Return an error message
      return $validationResult['message'];
    }
  }

  // Fetch statistics for a user
  private function fetchStats($user) {
    // Validate the user data using a schema
    $validationResult = $this->validateUserData($user);
    if ($validationResult['valid']) {
      // Fetch statistics from the database
      return $this->database->fetchStatistics($user);
    } else {
      // Return an error message
      return $validationResult['message'];
    }
  }

  // Validate user data using a schema
  private function validateUserData($user) {
    // Define the schema for validating user data
    $schema = [
      'name' => ['type' => 'string', 'minLength' => 2, 'maxLength' => 50],
      'email' => ['type' => 'string', 'format' => 'email'],
      'password' => ['type' => 'string', 'minLength' => 8],
    ];

    // Validate the user data against the schema
    $result = json_schema_validate($user, $schema);

    // If validation fails, return an error message
    if (!$result['valid']) {
      return [
        'valid' => false,
        'message' => 'Invalid user data',
      ];
    } else {
      return [
        'valid' => true,
        'message' => 'User data is valid',
      ];
    }
  }
}
