const fs = require('fs');
const path = require('path');
const util = require('util');
const logger = require('logger');

class FileProcessor {
  constructor(options) {
    this.directory = options.directory;
    this.fileExtension = options.fileExtension;
    this.parallelism = options.parallelism || 10;
    this.progressUpdateInterval = options.progressUpdateInterval || 10000; // 10 seconds
  }

  async start() {
    const files = await fs.promises.readdir(this.directory);
    const filteredFiles = files.filter((file) => path.extname(file) === this.fileExtension);
    const promises = filteredFiles.map((file) => this.processFile(file));
    const results = await Promise.allSettled(promises);
    logger.info(`Finished processing ${results.length} files`);
  }

  async processFile(file) {
    const filePath = path.join(this.directory, file);
    const contents = await fs.promises.readFile(filePath);
    try {
      // Process the file contents here
      const processedContents = this.processContent(contents);
      return processedContents;
    } catch (error) {
      logger.error(`Error processing ${file}: ${error}`);
      throw error;
    }
  }

  processContent(contents) {
    // Implement the file processing logic here
    const processedContents = contents; // For example, you could split the contents on newlines and return an array of lines.
    return processedContents;
  }

  async updateProgress() {
    const files = await fs.promises.readdir(this.directory);
    const progress = Math.round((files.length / this.parallelism) * 100);
    logger.info(`Progress: ${progress}%`);
  }
}

module.exports = FileProcessor;
```
This implementation uses the `fs` module to read and write files, as well as the `path` module to manipulate file paths. It also uses the `util` module for promisifying asynchronous functions and the `logger` module for logging. The `FileProcessor` class has a constructor that takes an options object with `directory`, `fileExtension`, and `parallelism` properties, which are used to configure the service.

The `start()` method reads the files in the specified directory and filters them based on the file extension using the `filter()` method. It then maps each filtered file to a promise using the `map()` method, which is then resolved using the `Promise.allSettled()` method. The results are logged at the end of processing.

The `processFile()` method reads the contents of a file and processes it using the `processContent()` method. It logs any errors that occur during processing.

The `processContent()` method is where you would implement your own file processing logic. In this example, we're simply returning the contents unmodified.

The `updateProgress()` method updates the progress every 10 seconds using the `setInterval()` method and logs the current progress percentage.

This implementation assumes that the files to be processed are located in a single directory, and it filters them based on the specified file extension. It processes each file in parallel, with a maximum of `parallelism` promises running at any given time. You can adjust these parameters as needed to fit your specific use case."]

