Here is an example of how you could implement the given programming task using AngularJS:
```
// Define a service for refreshing dialog fields
app.service('dialogFieldRefresher', function($http, $q) {
  // Function to refresh specified dialog fields based on resource ID and URL
  this.refreshFields = function(resourceId, url, fieldNames) {
    // Create a promise to handle asynchronous HTTP requests
    var deferred = $q.defer();

    // Send an HTTP GET request to the server for the updated data
    $http({
      method: 'GET',
      url: url + '/' + resourceId,
      params: { fields: fieldNames }
    }).then(function(response) {
      // Resolve the promise with the updated data
      deferred.resolve(response);
    }, function(error) {
      // Reject the promise if there is an error
      deferred.reject(error);
    });

    return deferred.promise;
  }
});

// Establish a communication protocol with the parent window to request and receive updates for the fields
