  var deferred = $q.defer();

  // Send an HTTP GET request to the server for the updated data
  $http({
    method: 'GET',
    url: 'https://example.com/parent-window-updates',
    params: { fields: fieldNames }
  }).then(function(response) {
    // Resolve the promise with the updated data
