// lib.rs
pub struct HttpClient {
    auth_service: AuthService,
    client: reqwest::Client,
}

impl HttpClient {
    pub fn new(auth_service: &AuthService) -> Self {
        let client = reqwest::Client::new();
        Self { auth_service, client }
    }

    pub async fn request(&self, method: Method, url: &str, body: Option<&[u8]>) -> Result<Response> {
        let mut request = self.client.request(method, url);

        // Add authentication headers
        let auth_headers = self.auth_service.get_auth_headers()?;
        for (name, value) in auth_headers {
            request.header(name, value);
        }

        // Add body if present
        if let Some(body) = body {
            request.body(body);
        }

        // Send the request and handle errors
        let response = self.client.execute(request).await?;
        match response.error_for_status() {
            Ok(response) => Ok(response),
            Err(err) => {
                if err.is_server_error() || err.is_rate_limited() {
                    // Retry with exponential backoff
                    let delay = std::time::Duration::from_secs(1 << self.client.retries);
                    tokio::time::sleep(delay).await;
                    self.request(method, url, body).await
                } else {
                    Err(err)
                }
            }
        }
    }
}
```
