const express = require('express');
const app = express();
const bodyParser = require('body-parser');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const sentimentAnalysisAPI = require('sentiment-analysis-api');
const mongoose = require('mongoose');
const redis = require('redis');

// Set up the database connection
mongoose.connect('mongodb://localhost/comment-processing', { useNewUrlParser: true });

// Set up the Redis client
const redisClient = redis.createClient();

// Set up the sentiment analysis API
const sentimentAnalysisAPI = new SentimentAnalysisAPI({
  url: 'https://sentiment-analysis-api.com',
  key: process.env.SENTIMENT_ANALYSIS_KEY,
});

// Define the schema for the comments
const CommentSchema = new mongoose.Schema({
  author: String,
  content: String,
  timestamp: Date,
  sentiment: { type: Number, enum: [-1, 0, 1] },
});

// Create a model from the schema
const CommentModel = mongoose.model('Comment', CommentSchema);

// Set up the Express app
app.use(cors());
app.use(bodyParser.json());
app.use(rateLimit({ windowMs: 60 * 1000, max: 100 })); // limit to 100 requests per minute

// Handle incoming comments and process them
app.post('/comments', (req, res) => {
  const comment = req.body;
  console.log(`Received comment from ${comment.author} at ${comment.timestamp}`);

  // Filter comments older than 60 days
  if (new Date() - new Date(comment.timestamp) > 60 * 24 * 60 * 60 * 1000) {
    console.log('Comment too old, discarding');
    return res.status(403).send();
  }

  // Sanitize the content and remove any offensive language
  comment.content = sanitizeContent(comment.content);

  // Perform sentiment analysis on the comment
  sentimentAnalysisAPI.analyzeSentiment(comment.content)
    .then((sentiment) => {
      console.log(`Comment sentiment: ${sentiment}`);

      // Store the processed comment in the database
      const newComment = new CommentModel({
        author: comment.author,
        content: comment.content,
        timestamp: comment.timestamp,
        sentiment: sentiment,
      });
      newComment.save()
        .then(() => {
          console.log('Comment saved successfully');
          res.status(201).send();
        })
        .catch((err) => {
          console.error(`Error saving comment to database: ${err}`);
          res.status(500).send();
        });
    })
    .catch((err) => {
      console.error(`Sentiment analysis API error: ${err}`);
      res.status(502).send();
    });
});

// Handle incoming comment moderation requests
app.post('/comments/moderate', (req, res) => {
  const comment = req.body;
  console.log(`Received moderation request for ${comment.author} at ${comment.timestamp}`);

  // Find the comment in the database and update its status
  CommentModel.findOne({ author: comment.author, timestamp: comment.timestamp })
    .then((existingComment) => {
      if (!existingComment) {
        console.log('No such comment found');
        return res.status(404).send();
      }

      // Update the sentiment and save the comment
      existingComment.sentiment = comment.sentiment;
      existingComment.save()
        .then(() => {
          console.log('Comment moderation request processed successfully');
          res.status(201).send();
        })
        .catch((err) => {
          console.error(`Error updating comment sentiment: ${err}`);
          res.status(500).send();
        });
    })
    .catch((err) => {
      console.error(`Error finding comment to moderate: ${err}`);
      res.status(500).send();
    });
});

// Handle incoming comment retrieval requests
