// C++ implementation of a scalable, multi-threaded text file processing system
#include <iostream>
#include <string>
#include <fstream>
#include <vector>
#include <cmath>
#include <limits>
#include <regex>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <algorithm>

// Struct to represent a file being processed
struct File {
  std::string filename;
  std::ifstream stream;
  int line_number = 0;
};

// Struct to represent a thread-safe queue of files
struct Queue {
  std::mutex mutex;
  std::condition_variable condition;
  std::vector<File> files;
};

// Function to parse a single line from a file and extract the last field
double parse_line(const std::string& line) {
  // Use regular expressions to extract the last field as a double
  const std::regex pattern("^.* ([0-9]+.[0-9]+)$");
  std::smatch matches;
  if (std::regex_search(line, matches, pattern)) {
    return std::stod(matches[1].str());
  } else {
    return std::numeric_limits<double>::quiet_NaN();
  }
}

// Function to process a file and update the average of the last three fields
void process_file(File& file) {
  // Parse the first three lines of the file to get the starting values for the average
  double value1 = parse_line(file.stream.str());
  file.stream >> std::ws;
  double value2 = parse_line(file.stream.str());
  file.stream >> std::ws;
  double value3 = parse_line(file.stream.str());

  // Update the average of the last three fields
  double average = (value1 + value2 + value3) / 3.0;

  // Replace the last field with the new average, or leave unchanged if not all fields are present
  file.stream.clear();
  file.stream << "[" << std::setprecision(std::numeric_limits<double>::digits10 + 1) << average << "]";
}

// Function to handle a single file in the thread-safe queue
void process_file_thread(Queue& queue, int thread_id) {
  while (true) {
    std::unique_lock<std::mutex> lock(queue.mutex);
    // Wait for the next file to be available
    while (queue.files.empty()) {
      queue.condition.wait(lock);
    }
    File& file = queue.files[0];
    if (file.line_number == 0) {
      // If this is the first line of a new file, open the stream and reset the line number
      file.stream.open(file.filename);
      file.line_number = 1;
    } else {
      // Skip to the next line in the stream
      ++file.line_number;
    }
    // Process the current line of the file
    process_file(file);

    if (file.stream.eof()) {
      // If we have reached the end of the file, close it and remove it from the queue
      file.stream.close();
      queue.files.erase(queue.files.begin());
    }
  }
}

int main() {
  // Initialize the thread-safe queue and spawn worker threads
  Queue queue;
  std::vector<std::thread> workers;
  for (int i = 0; i < 4; ++i) {
    workers.emplace_back(process_file_thread, std::ref(queue), i);
  }

  // Create a directory watcher to monitor new files in the input directory
  const char* input_dir = "path/to/input/directory";
  DIR *dir;
  struct dirent *ent;
  if ((dir = opendir(input_dir)) != NULL) {
    while ((ent = readdir(dir)) != NULL) {
      // Ignore non-text files and hidden files
      if (std::regex_match(ent->d_name, std::regex("^[^.].*\\.[^.]*$"))) {
        File file;
        file.filename = std::string(input_dir) + ent->d_name;
        // Add the new file to the queue
        std::lock_guard<std::mutex> lock(queue.mutex);
        queue.files.push_back(file);
        queue.condition.notify_all();
      }
    }
    closedir(dir);
  } else {
    // Handle errors when opening the directory watcher
  }

  // Join all worker threads to wait for completion
  for (auto& worker : workers) {
    worker.join();
  }

  return 0;
}']

