// Define the size of the salt and IV
#define SALT_SIZE 32
#define IV_SIZE 16

// Define the number of iterations for key derivation
#define PBKDF2_ITERATIONS 2048

// Define the digest used for key derivation
#define PBKDF2_DIGEST SHA256

// Define the salt and IV generation functions
void generate_salt(unsigned char *salt) {
    // Generate a random salt using OpenSSL's RAND_bytes function
    RAND_bytes(salt, SALT_SIZE);
}

void generate_iv(unsigned char *iv) {
    // Generate a random IV using OpenSSL's RAND_bytes function
    RAND_bytes(iv, IV_SIZE);
}

// Define the AES-256-GCM encryption and decryption functions
int encrypt(const unsigned char *plaintext, size_t plaintext_len, const unsigned char *key,
            const unsigned char *iv, unsigned char *ciphertext) {
    // Initialize the OpenSSL library
    OPENSSL_init_crypto();

    // Create a new AES context
    AES_KEY ctx;
    AES_set_encrypt_key(key, 256, &ctx);

    // Encrypt the plaintext using GCM
    int len = AES_gcm_128_encrypt(plaintext, plaintext_len, iv, NULL, NULL, 0, NULL, &ctx);
    if (len < 0) {
        return -1;
    }

    // Copy the ciphertext to the output buffer
    memcpy(ciphertext, plaintext + len, plaintext_len - len);

    // Clean up the OpenSSL library
    OPENSSL_cleanup();

    return 0;
}

int decrypt(const unsigned char *ciphertext, size_t ciphertext_len, const unsigned char *key,
            const unsigned char *iv, unsigned char *plaintext) {
    // Initialize the OpenSSL library
    OPENSSL_init_crypto();

    // Create a new AES context
    AES_KEY ctx;
    AES_set_decrypt_key(key, 256, &ctx);

    // Decrypt the ciphertext using GCM
    int len = AES_gcm_128_decrypt(ciphertext, ciphertext_len, iv, NULL, NULL, 0, NULL, &ctx);
    if (len < 0) {
        return -1;
    }

    // Copy the plaintext to the output buffer
    memcpy(plaintext, ciphertext + len, ciphertext_len - len);

    // Clean up the OpenSSL library
    OPENSSL_cleanup();

    return 0;
}

// Define the error handling function
void handle_error(int error) {
    switch (error) {
        case -1:
            printf("Error: Could not encrypt/decrypt data\n");
            break;
        default:
            printf("Unknown error occurred\n");
    }
}

// Define the main function for the encryption service
int main(int argc, char *argv[]) {
    // Initialize the OpenSSL library
    OPENSSL_init_crypto();

    // Check if a password was provided
    if (argc < 2) {
        printf("Usage: %s <password>\n", argv[0]);
        return 1;
    }

    // Create a new salt and IV for encryption/decryption
    unsigned char salt[SALT_SIZE], iv[IV_SIZE];
    generate_salt(salt);
    generate_iv(iv);

    // Derive a 32-byte AES key and a 96-bit IV from the user-provided password using PBKDF2 with SHA-256 as the PRF
    unsigned char key[32];
    PBKDF2_HMAC(argv[1], strlen(argv[1]), salt, SALT_SIZE, PBKDF2_ITERATIONS, key, 32);

    // Create a new buffer for the encrypted/decrypted data
    unsigned char *buffer = malloc(sizeof(unsigned char) * 64);
    if (!buffer) {
        handle_error(-1);
        return -1;
    }

    // Encrypt some test data using the derived key and IV
    memcpy(buffer, "Hello, world!", 13);
    encrypt(buffer, 13, key, iv, buffer + 16);

    // Decrypt the encrypted data using the same key and IV
    decrypt(buffer + 16, 16, key, iv, buffer);

    // Print the plaintext result
    printf("Plaintext: %s\n", buffer);

    // Clean up the OpenSSL library
    OPENSSL_cleanup();

    return 0;
}
