import logging
import threading
import time
from typing import Optional, List

class CommandExecutor:
    """
    Robust command execution utility that integrates with an existing system of service components.
    Handles multiple command executions concurrently, respecting system resource limits to avoid overloading the host machine.
    Integrates seamlessly with a monitoring framework to report the status and errors of each command execution.
    Gracefully handles command failures and retry mechanisms with configurable back-off strategies.
    Provides a command-line interface for users to specify command execution parameters, including priority levels and resource allocation quotas.
    Ensures thread safety and proper cleanup of resources upon process termination.
    Supports logging for auditing and debugging purposes, with configurable log levels and formats.
    """

    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.command_queue: List[str] = []
        self.thread_pool: List[threading.Thread] = []
        self.resource_usage: Dict[str, float] = {}
        self.command_status: Dict[str, bool] = {}
        self.backoff_strategy: Dict[str, int] = {}
        self.retry_count: Dict[str, int] = {}

    def add_command(self, command: str):
        """Add a new command to the queue for execution."""
        self.logger.info(f"Adding command '{command}' to queue")
        self.command_queue.append(command)

    def remove_command(self, command: str):
        """Remove a command from the queue."""
        try:
            self.logger.info(f"Removing command '{command}' from queue")
            del self.command_queue[self.command_queue.index(command)]
        except ValueError:
            self.logger.warning(f"Tried to remove non-existent command {command}")

    def execute_commands(self):
        """Execute the commands in the queue, respecting system resource limits and retry mechanisms."""
        while self.command_queue:
            try:
                command = self.command_queue.pop(0)
                self.logger.info(f"Executing command '{command}'")
                self.run_command(command)
            except Exception as e:
                self.logger.error(f"Error executing command {command}: {e}")

    def run_command(self, command: str):
        """Run a single command and update resource usage and status accordingly."""
        try:
            proc = subprocess.Popen(command, shell=True)
            self.logger.info(f"Command '{command}' started with PID {proc.pid}")
            self.resource_usage[proc.pid] = 0
            self.command_status[proc.pid] = True
        except Exception as e:
            self.logger.error(f"Error starting command {command}: {e}")

    def update_resources(self):
        """Update resource usage and status for all running commands."""
        for proc in psutil.process_iter():
            try:
                if proc.name() == "python":
                    self.logger.info(f"Updating resource usage for process {proc.pid}")
                    self.resource_usage[proc.pid] = proc.memory_percent()
                    self.command_status[proc.pid] = True
            except psutil.NoSuchProcess:
                pass
        for pid in list(self.resource_usage):
            try:
                if psutil.process_exists(pid):
                    self.logger.info(f"Updating resource usage for process {pid}")
                    self.resource_usage[pid] = proc.memory_percent()
                    self.command_status[pid] = True
            except psutil.NoSuchProcess:
                pass

    def handle_backoff(self, command: str):
        """Handle back-off mechanisms for failed commands."""
        try:
            if self.retry_count[command] >= 3:
                self.logger.warning(f"Command {command} has reached maximum retries")
            else:
                retry_delay = 10 * (self.retry_count[command] + 1)
                self.logger.info(f"Retrying command {command} in {retry_delay} seconds")
                time.sleep(retry_delay)
                self.retry_count[command] += 1
        except KeyError:
            pass

    def cleanup(self):
        """Clean up resources and exit the process."""
        for proc in psutil.process_iter():
            if "python" in proc.name():
                self.logger.info(f"Terminating process {proc.pid}")
                proc.terminate()
        self.logger.info("Cleaning up resources and exiting")
        sys.exit()

if __name__ == "__main__":
    executor = CommandExecutor()
    while True:
        try:
            executor.update_resources()
            for pid in list(executor.command_status):
                if not executor.command_status[pid]:
                    executor.logger.info(f"Command {pid} has completed")
                    del executor.resource_usage[pid]
                    del executor.command_status[pid]
            for command in executor.command_queue:
                if not any(cmd in executor.command_status for cmd in executor.command_status):
                    executor.execute_commands()
        except Exception as e:
            executor.logger.error(f"Error executing commands: {e}")
