// Set up a route to handle shell command execution requests
app.post('/execute', (req, res) => {
  // Parse the request body and extract the shell command
  const command = req.body.command;

  // Start a child process to execute the shell command
  const child = childProcess.exec(command, (error, stdout, stderr) => {
    if (error) {
      res.status(500).send('Error executing command');
      return;
    }

    // Send the output of the shell command back to the client as JSON
    const result = {
      output: stdout,
      error: stderr
    };
    res.json(result);
  });

  // Set up a timeout mechanism for long-running processes
  child.on('exit', (code) => {
    if (code !== 0) {
      res.status(500).send('Error executing command');
    }
  });
});

// Start the server and listen for incoming requests
