// Helper function to check if key is valid
bool isValidKey(const void *key) {
    // Check if key is a valid pointer and its length is 32 bytes (AES-256)
    return key != NULL && strlen((const char *)key) == 32;
}

// Helper function to check if IV is valid
bool isValidIV(const void *iv) {
    // Check if IV is a valid pointer and its length is 16 bytes (AES-128)
    return iv != NULL && strlen((const char *)iv) == 16;
}

// Encrypt data using AES-CBC
void encryptData(const void *input, size_t length, const void *key, const void *iv, unsigned char *output, size_t *outputLength) {
    // Check if input and output pointers are valid
    if (input == NULL || output == NULL || !isValidKey(key) || !isValidIV(iv)) {
        return;
    }

    // Create an EVP context for encryption
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return;
    }

    // Set the key and IV length
    int keyLength = strlen((const char *)key);
    int ivLength = strlen((const char *)iv);

    // Initialize the encryption context
    EVP_EncryptInit(ctx, EVP_aes_256_cbc(), (unsigned char *)key, (unsigned char *)iv);

    // Process the input data in chunks
    int chunkSize = 1024;
    while (length > 0) {
        // Calculate the number of bytes to process in this iteration
        int numBytes = length < chunkSize ? length : chunkSize;

        // Encrypt the data chunk
        EVP_EncryptUpdate(ctx, output, &numBytes, input, numBytes);

        // Update the pointers and remaining length
        input += numBytes;
        length -= numBytes;
    }

    // Finalize the encryption
    EVP_EncryptFinal(ctx, output, &numBytes);

    // Set the output length
    *outputLength = numBytes;

    // Free the context
    EVP_CIPHER_CTX_free(ctx);
}

// Decrypt data using AES-CBC
void decryptData(const void *input, size_t length, const void *key, const void *iv, unsigned char *output, size_t *outputLength) {
    // Check if input and output pointers are valid
    if (input == NULL || output == NULL || !isValidKey(key) || !isValidIV(iv)) {
        return;
    }

    // Create an EVP context for decryption
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return;
    }

    // Set the key and IV length
    int keyLength = strlen((const char *)key);
    int ivLength = strlen((const char *)iv);

    // Initialize the decryption context
    EVP_DecryptInit(ctx, EVP_aes_256_cbc(), (unsigned char *)key, (unsigned char *)iv);

    // Process the input data in chunks
    int chunkSize = 1024;
    while (length > 0) {
        // Calculate the number of bytes to process in this iteration
        int numBytes = length < chunkSize ? length : chunkSize;

        // Decrypt the data chunk
        EVP_DecryptUpdate(ctx, output, &numBytes, input, numBytes);

        // Update the pointers and remaining length
        input += numBytes;
        length -= numBytes;
    }

    // Finalize the decryption
    EVP_DecryptFinal(ctx, output, &numBytes);

    // Set the output length
    *outputLength = numBytes;

    // Free the context
    EVP_CIPHER_CTX_free(ctx);
}
