            printf("Unsupported key length for encryption algorithm %s: %d\n", algorithm, key_length);
            return 0;
        } else if (iv_length != DEFAULT_IV_LENGTH && iv_length != 16 && iv_length != 32 && iv_length != 48 && iv_length != 64) {
            printf("Unsupported IV length for encryption algorithm %s: %d\n", algorithm, iv_length);
            return 0;
        } else {
            return 1;
        }
    } else {
