    if (strcmp(DEFAULT_ENCRYPTION_ALGORITHM, algorithm) == 0 || strcmp("AES-256-CBC", algorithm) == 0 || strcmp("AES-192-CBC", algorithm) == 0 || strcmp("AES-128-CBC", algorithm) == 0) {
