}

// Helper function to encrypt a message using the specified key and IV lengths
int encrypt_message(const char *message, const char *key, int key_length, const char *iv, int iv_length) {
    // Check if the input parameters are valid
    if (!message || !key || !iv) {
        return 0;
    }

    // Initialize the encryption algorithm and generate a random salt
    EVP_CIPHER_CTX *ctx = NULL;
    unsigned char salt[32];
    RAND_bytes(salt, sizeof(salt));

    // Set the cipher and key length
    int cipher = EVP_aes_256_cbc();
    int keylen = 32;

    // Create a new encryption context
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return 0;
    }

    // Initialize the encryption operation
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    // Encrypt the message using the random salt as the prefix
    int msglen = strlen(message);
    unsigned char *cryptmsg = (unsigned char *)malloc(msglen + 16);
    memcpy(cryptmsg, salt, sizeof(salt));
    if (EVP_EncryptUpdate(ctx, cryptmsg + sizeof(salt), &msglen, message, strlen(message)) <= 0) {
        free(cryptmsg);
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }
    msglen += sizeof(salt);

    // Generate a MAC using the encryption context and the random salt
    unsigned char *mac = (unsigned char *)malloc(16);
    if (EVP_EncryptFinal_ex(ctx, mac, &maclen) <= 0) {
        free(cryptmsg);
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    // Combine the encrypted message and MAC into a single output buffer
    int outlen = msglen + maclen;
    unsigned char *encrypted = (unsigned char *)malloc(outlen);
    memcpy(encrypted, cryptmsg, msglen);
    memcpy(encrypted + msglen, mac, maclen);

    // Clean up and return the encrypted message
    free(cryptmsg);
    EVP_CIPHER_CTX_free(ctx);
    return encrypted;
}

// Helper function to decrypt a message using the specified key and IV lengths
int decrypt_message(const char *encrypted, const char *key, int key_length, const char *iv, int iv_length) {
    // Check if the input parameters are valid
    if (!encrypted || !key || !iv) {
        return 0;
    }

    // Initialize the decryption algorithm and generate a random salt
    EVP_CIPHER_CTX *ctx = NULL;
    unsigned char salt[32];
    memcpy(salt, encrypted, sizeof(salt));

    // Set the cipher and key length
    int cipher = EVP_aes_256_cbc();
    int keylen = 32;

    // Create a new decryption context
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return 0;
    }

    // Initialize the decryption operation
    if (EVP_DecryptInit_ex(ctx, cipher, NULL, key, iv) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    // Decrypt the message using the random salt as the prefix
    int msglen = strlen(encrypted) - sizeof(salt);
    unsigned char *message = (unsigned char *)malloc(msglen);
    if (EVP_DecryptUpdate(ctx, message, &msglen, encrypted + sizeof(salt), strlen(encrypted) - sizeof(salt)) <= 0) {
        free(message);
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    // Generate a MAC using the decryption context and the random salt
    unsigned char *mac = (unsigned char *)malloc(16);
    if (EVP_DecryptFinal_ex(ctx, mac, &maclen) <= 0) {
        free(message);
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    // Combine the decrypted message and MAC into a single output buffer
    int outlen = msglen + maclen;
    unsigned char *decrypted = (unsigned char *)malloc(outlen);
    memcpy(decrypted, message, msglen);
    memcpy(decrypted + msglen, mac, maclen);

    // Clean up and return the decrypted message
    free(message);
    EVP_CIPHER_CTX_free(ctx);
    return decrypted;
}

int main() {
    const char *key = "my_secret_key";
    int key_length = strlen(key);

    // Encrypt a message using the specified key and IV lengths
    const char *message = "Hello, World!";
    int iv_length = 16;
    unsigned char *encrypted = encrypt_message(message, key, key_length, NULL, iv_length);

    // Print the encrypted message
    printf("Encrypted Message: %s\n", encrypted);

    // Decrypt the encrypted message using the specified key and IV lengths
    unsigned char *decrypted = decrypt_message(encrypted, key, key_length, NULL, iv_length);

    // Print the decrypted message
    printf("Decrypted Message: %s\n", decrypted);

    return 0;
}']

