package com.example.encryption;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.Base64;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import org.apache.commons.codec.binary.Hex;

public class EncryptionService {
    private static final String CIPHER_ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final String KEY_ALGORITHM = "AES";
    private static final int KEY_SIZE = 256;
    private static final int ITERATIONS = 1000;
    private static final int HASH_ITERATIONS = 1000;
    private static final String SEPARATOR = ":";

    private SecretKeySpec secretKey;
    private Cipher cipher;

    public EncryptionService() {
        this.secretKey = generateSecretKey();
        this.cipher = getCipherInstance();
    }

    public String encrypt(String plaintext) throws NoSuchAlgorithmException, InvalidKeyException, IOException {
        byte[] ciphertext = cipher.doFinal(plaintext.getBytes(StandardCharsets.UTF_8));
        return Base64.getEncoder().encodeToString(ciphertext);
    }

    public String decrypt(String ciphertext) throws NoSuchAlgorithmException, InvalidKeyException, IOException {
        byte[] plaintext = cipher.doFinal(Base64.getDecoder().decode(ciphertext));
        return new String(plaintext, StandardCharsets.UTF_8);
    }

    private SecretKeySpec generateSecretKey() {
        SecureRandom random = new SecureRandom();
        byte[] keyBytes = new byte[KEY_SIZE / 8];
        random.nextBytes(keyBytes);
        return new SecretKeySpec(keyBytes, KEY_ALGORITHM);
    }

    private Cipher getCipherInstance() throws NoSuchAlgorithmException {
        Cipher cipher = Cipher.getInstance(CIPHER_ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        return cipher;
    }
}
```
