struct ConfigList {
    struct Config configs[MAX_CONFIGS];
    int numConfigs;
    pthread_mutex_t mutex;
};

void addConfig(struct ConfigList *configList, char *id, char *logLevel) {
    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&configList->mutex);

    // Check if the configuration already exists in the list
    for (int i = 0; i < configList->numConfigs; i++) {
        if (strcmp(id, configList->configs[i].id) == 0) {
            // Update the log level if it already exists in the list
            strcpy(configList->configs[i].logLevel, logLevel);
            goto unlock;
        }
    }

    // Add a new configuration to the end of the list
    configList->configs[configList->numConfigs].id = id;
    strcpy(configList->configs[configList->numConfigs].logLevel, logLevel);
    configList->numConfigs++;

unlock:
    // Unlock the list to allow other threads to modify it safely
    pthread_mutex_unlock(&configList->mutex);
}

void removeConfig(struct ConfigList *configList, char *id) {
    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&configList->mutex);

    // Find the configuration index in the list
    int configIndex = -1;
    for (int i = 0; i < configList->numConfigs; i++) {
        if (strcmp(id, configList->configs[i].id) == 0) {
            configIndex = i;
            break;
        }
    }

    // Remove the configuration from the list
    if (configIndex >= 0) {
        for (int i = configIndex + 1; i < configList->numConfigs; i++) {
            configList->configs[i - 1] = configList->configs[i];
        }
        configList->numConfigs--;
    }

    // Unlock the list to allow other threads to modify it safely
    pthread_mutex_unlock(&configList->mutex);
}

char *getLogLevel(struct ConfigList *configList, char *id) {
    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&configList->mutex);

    // Find the configuration in the list
    int configIndex = -1;
    for (int i = 0; i < configList->numConfigs; i++) {
        if (strcmp(id, configList->configs[i].id) == 0) {
            configIndex = i;
            break;
        }
    }

    // Return the log level of the configuration
    char *logLevel = NULL;
    if (configIndex >= 0) {
        logLevel = configList->configs[configIndex].logLevel;
    }

    // Unlock the list to allow other threads to modify it safely
    pthread_mutex_unlock(&configList->mutex);

    return logLevel;
}

int main() {
    struct ConfigList configList = {{{"config1", "info"}, {"config2", "debug"}, {"config3", "warn"}}, 3};

    // Add a new configuration to the list
    addConfig(&configList, "new-config", "error");

    // Remove an existing configuration from the list
    removeConfig(&configList, "config2");

    // Get the log level of a configuration in the list
    char *logLevel = getLogLevel(&configList, "config1");
    printf("The log level of config1 is %s\n", logLevel);
}
```

This implementation uses a `struct Config` to store each configuration entry with an ID and a log level. The `struct ConfigList` contains an array of `struct Config` elements, along with a mutex for thread safety and a counter for the number of configurations in the list.

The `addConfig()` function adds a new configuration to the list by locking the mutex, checking if the configuration already exists in the list, updating the log level if it does, or adding a new element to the end of the list. The function then unlocks the mutex.

The `removeConfig()` function removes an existing configuration from the list by locking the mutex, finding the index of the configuration in the list, and removing the configuration from the list if it exists. The function then unlocks the mutex.

The `getLogLevel()` function gets the log level of a configuration in the list by locking the mutex, finding the index of the configuration in the list, and returning its log level if it exists. The function then unlocks the mutex.

In the main function, we add a new configuration to the list, remove an existing configuration from the list, and get the log level of a configuration in the list using the `addConfig()`, `removeConfig()`, and `getLogLevel()` functions respectively.']

