    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);
    curl_easy_setopt(curl, CURLOPT_LOW_SPEED_TIME, 30L);
    curl_easy_setopt(curl, CURLOPT_LOW_SPEED_LIMIT, 10L);

    CURLcode res;
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "cURL error: %s\n", curl_easy_strerror(res));
        return -1;
    }

    // Extract metadata from HTTP headers
    const char *content_type = NULL;
    size_t content_length = 0;
    const char *thumbnail = NULL;
    if (curl_easy_getinfo(curl, CURLINFO_CONTENT_TYPE, &content_type) != CURLE_OK ||
        curl_easy_getinfo(curl, CURLINFO_CONTENT_LENGTH_DOWNLOAD, &content_length) != CURLE_OK ||
        curl_easy_getinfo(curl, CURLINFO_EASY_SSL_VERIFYRESULT, &thumbnail) != CURLE_OK) {
        fprintf(stderr, "Failed to get HTTP headers\n");
        return -1;
    }

    // Parse metadata and check for errors
    int width = 0;
    int height = 0;
    char *mime_type = NULL;
    unsigned char *thumbnail_data = NULL;
    if (sscanf(content_type, "image/%d", &width) != 1 || sscanf(content_type, "image/%d", &height) != 1 ||
        !(mime_type = strdup(content_type)) || !(thumbnail_data = strdup(thumbnail))) {
        fprintf(stderr, "Failed to parse metadata\n");
        return -1;
    }

    // Set output parameters
    metadata->width = width;
    metadata->height = height;
    metadata->mime_type = mime_type;
    metadata->thumbnail = thumbnail_data;

    curl_easy_cleanup(curl);
    return 0;
}

// Function to resize an image using libjpeg-turbo
int resizeImageJpegTurbo(const char *input, const char *output, int width, int height) {
    struct jpeg_decompress_struct cinfo;
    struct jpeg_compress_struct cinfo_comp;
    JSAMPARRAY buffer;
    FILE *infile = NULL;
    FILE *outfile = NULL;
    JDIMENSION row_stride;
    int row_stride_width;
    int row_stride_height;
    int ret = 0;

    // Open input and output files
    infile = fopen(input, "rb");
    if (!infile) {
        fprintf(stderr, "Failed to open input file\n");
        return -1;
    }
    outfile = fopen(output, "wb");
    if (!outfile) {
        fprintf(stderr, "Failed to create output file\n");
        fclose(infile);
        return -1;
    }

    // Set up decompression structure
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);
    jpeg_stdio_src(&cinfo, infile);
    (void)jpeg_read_header(&cinfo, TRUE);
    row_stride = cinfo.image_width * cinfo.input_components;
    row_stride_width = cinfo.image_width;
    row_stride_height = cinfo.image_height;

    // Set up compression structure
    cinfo_comp.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo_comp);
    jpeg_stdio_dest(&cinfo_comp, outfile);
    (void)jpeg_set_defaults(&cinfo_comp);
    cinfo_comp.image_width = width;
    cinfo_comp.image_height = height;
    cinfo_comp.input_components = 3;
    jpeg_set_quality(&cinfo_comp, 90, TRUE);
    (void)jpeg_start_compress(&cinfo_comp, TRUE);

    // Resize image by decompressing input into temporary buffer and then compressing it to output
    int i;
    for (i = 0; i < cinfo.image_height; ++i) {
        if (jpeg_read_scanlines(&cinfo, &buffer[0], row_stride) != 1) {
            fprintf(stderr, "Failed to read scanline\n");
            ret = -1;
            break;
        }
        if (jpeg_write_scanlines(&cinfo_comp, &buffer[0], width) != width) {
            fprintf(stderr, "Failed to write scanline\n");
            ret = -1;
            break;
        }
    }

    // Clean up decompression and compression structures
    jpeg_destroy_decompress(&cinfo);
    jpeg_destroy_compress(&cinfo_comp);

    fclose(infile);
    fclose(outfile);
    return ret;
}

// Function to resize an image using libpng
int resizeImagePng(const char *input, const char *output, int width, int height) {
    png_structp png = NULL;
    png_infop info = NULL;
    FILE *infile = NULL;
    FILE *outfile = NULL;
    png_bytep row_pointers[height];
    png_bytep data = NULL;
    png_uint_32 width_orig = 0;
    png_uint_32 height_orig = 0;
    int ret = 0;

    // Open input and output files
    infile = fopen(input, "rb");
    if (!infile) {
        fprintf(stderr, "Failed to open input file\n");
        return -1;
    }
    outfile = fopen(output, "wb");
    if (!outfile) {
        fprintf(stderr, "Failed to create output file\n");
        fclose(infile);
        return -1;
    }

    // Set up PNG structures
    png = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (!png) {
        fprintf(stderr, "Failed to initialize read struct\n");
        ret = -1;
        goto cleanup;
    }
    info = png_create_info_struct(png);
    if (!info) {
        fprintf(stderr, "Failed to initialize write struct\n");
        ret = -1;
        goto cleanup;
    }

    // Initialize PNG read and write structures
    png_init_io(png, infile);
    png_set_sig_bytes(png, 8);
    png_read_info(png, info);
    width_orig = png_get_image_width(png, info);
    height_orig = png_get_image_height(png, info);
    png_init_io(png, outfile);

    // Allocate memory for data and row pointers
    int bytes_per_pixel = png_get_rowbytes(png, info) / width_orig;
    if (bytes_per_pixel != 3 && bytes_per_pixel != 4) {
        fprintf(stderr, "Unexpected number of bytes per pixel: %d\n", bytes_per_pixel);
        ret = -1;
        goto cleanup;
    }
    data = malloc(png_get_rowbytes(png, info) * height_orig);
    if (!data) {
        fprintf(stderr, "Failed to allocate memory for image data\n");
        ret = -1;
        goto cleanup;
    }
    row_pointers[0] = data;
    for (int i = 1; i < height_orig; ++i) {
        row_pointers[i] = row_pointers[i - 1] + png_get_rowbytes(png, info);
    }

    // Read and resize image data
    int y;
    for (y = 0; y < height_orig && !ret; ++y) {
        ret = png_read_rows(png, &row_pointers[y], NULL, height_orig - y);
    }
    if (ret) {
        fprintf(stderr, "Failed to read scanlines\n");
        goto cleanup;
    }
    for (int i = 0; i < height && !ret; ++i) {
        ret = png_write_rows(png, &row_pointers[i * height / width], (height - i * height / width));
    }

cleanup:
    // Clean up PNG structures and allocated memory
    if (data) free(data);
    if (info) png_free_data(png, info, PNG_FREE_ALL, -1);
    if (png) png_destroy_read_struct(&png, NULL, NULL);
    fclose(infile);
    fclose(outfile);
    return ret;
}
