// define the message structure for LTE RRC messages
typedef struct {
  uint32_t msg_type;    // message type identifier
  uint8_t *msg_data;   // pointer to message data payload
  size_t msg_size;     // length of message data payload
} rrc_message_t;

// define a message queue for holding messages temporarily before processing
typedef struct {
  int max_size;        // maximum number of messages in the queue
  int current_size;    // current number of messages in the queue
  rrc_message_t *messages;   // array of messages
} message_queue_t;

// define a function to initialize the message queue
void init_message_queue(message_queue_t *queue) {
  // allocate memory for the message queue
  queue->max_size = 1024;    // set maximum number of messages in the queue
  queue->current_size = 0;   // initialize current size to zero
  queue->messages = malloc(sizeof(rrc_message_t) * queue->max_size);
  if (queue->messages == NULL) {
    printf("Error: failed to allocate memory for message queue\n");
    return -1;
  }
  // initialize each message in the queue to zero
  for (int i = 0; i < queue->max_size; i++) {
    queue->messages[i].msg_type = 0;
    queue->messages[i].msg_data = NULL;
    queue->messages[i].msg_size = 0;
  }
}

// define a function to enqueue a message into the message queue
int enqueue_message(message_queue_t *queue, rrc_message_t message) {
  // check if there is space in the queue for another message
  if (queue->current_size >= queue->max_size) {
    printf("Error: message queue is full\n");
    return -1;
  }
  // add the new message to the end of the queue
  queue->messages[queue->current_size] = message;
  queue->current_size++;
}

// define a function to dequeue a message from the message queue
rrc_message_t dequeue_message(message_queue_t *queue) {
  // check if there are any messages in the queue
  if (queue->current_size == 0) {
    printf("Error: message queue is empty\n");
    return -1;
  }
  // remove and return the first message from the queue
  rrc_message_t message = queue->messages[0];
  queue->messages[0] = queue->messages[queue->current_size - 1];
  queue->current_size--;
}

