// Define a generic data model for sensor data
struct SensorData {
    std::string type;   // Sensor type identifier (e.g., "temperature", "acceleration")
    double value;      // Sensor value (e.g., temperature in Celsius, acceleration vector)
    double timestamp;  // Timestamp for the data point (e.g., Unix epoch time)
};

// Define a data structure to store sensor data streams
struct DataStream {
    std::string name;   // Stream identifier (e.g., "sensor1", "sensor2")
    std::queue<SensorData> queue;  // Queue for storing incoming data points
};

// Define a map to store data streams by their names
using DataStreamMap = std::unordered_map<std::string, std::shared_ptr<DataStream>>;

class SensorDataManager {
public:
    // Constructor to initialize the data manager
    SensorDataManager() : mutex_(std::mutex()), cond_(std::condition_variable()) {}

    // Add a new sensor data stream to the map
    void addStream(const std::string& name) {
        auto stream = std::make_shared<DataStream>();
        stream->name = name;
        streams_.emplace(name, stream);
    }

    // Remove an existing sensor data stream from the map
    void removeStream(const std::string& name) {
        if (streams_.count(name)) {
            auto it = streams_.find(name);
            streams_.erase(it);
        }
    }

    // Get a reference to an existing sensor data stream by its name
    std::shared_ptr<DataStream> getStream(const std::string& name) {
        return streams_.at(name);
    }

    // Put a new sensor data point into the corresponding stream
    void putDataPoint(const SensorData& data) {
        if (streams_.count(data.type)) {
            auto stream = getStream(data.type);
            std::unique_lock<std::mutex> lock(mutex_);
            while (stream->queue.size() >= MAX_QUEUE_SIZE) {
                cond_.wait(lock);  // Block if the queue is full
            }
            stream->queue.push(data);
            cond_.notify_all();
        } else {
            std::cout << "Data point for non-existent sensor type: " << data.type << std::endl;
        }
    }

    // Get the next available sensor data point from a stream
    SensorData getNextDataPoint(const std::string& name) {
        if (streams_.count(name)) {
            auto stream = getStream(name);
            std::unique_lock<std::mutex> lock(mutex_);
            while (stream->queue.empty()) {
                cond_.wait(lock);  // Block if the queue is empty
            }
            SensorData data = stream->queue.front();
            stream->queue.pop();
            return data;
        } else {
            std::cout << "Requested data point for non-existent sensor type: " << name << std::endl;
            return {};
        }
    }

private:
    // Maximum size of the queue for each stream
    static constexpr int MAX_QUEUE_SIZE = 1000;

    // Mutex and condition variable to synchronize access to streams
    std::mutex mutex_;
    std::condition_variable cond_;

    // Map to store data streams by their names
    DataStreamMap streams_;
};
