  // Derive key and IV from password and salt
  unsigned char key[32], iv[96];
  deriveKey(password, "SALT");

  // Load key and IV into AES-256-GCM
  EVP_CIPHER_CTX *ctx;
  if (!(ctx = EVP_CIPHER_CTX_new())) {
    return 0;
  }
  EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv);

  // Error handling for encryption/decryption failures
  int plaintext_len;
  if (!EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, ciphertext, strlen(ciphertext))) {
    EVP_CIPHER_CTX_free(ctx);
    return 0;
  }
  if (!EVP_DecryptFinal_ex(ctx, plaintext + plaintext_len, &plaintext_len)) {
    EVP_CIPHER_CTX_free(ctx);
