  struct encryption_context *encryption_ctx;
  FILE *file;
};

void init_encryption_context(struct encryption_context *ctx, const EVP_CIPHER *cipher, const EVP_MD *digest) {
  ctx->cipher = cipher;
  ctx->digest = digest;
  ctx->eckey = NULL;
  ctx->rsakey = NULL;
  ctx->key_bio = BIO_new(BIO_s_mem());
  if (ctx->key_bio == NULL) {
    // Handle error
  }
}

void free_encryption_context(struct encryption_context *ctx) {
  BIO_free_all(ctx->key_bio);
}

void init_file_context(struct file_context *ctx, const char *filename, struct encryption_context *encryption_ctx) {
  ctx->filename = filename;
  ctx->encryption_ctx = encryption_ctx;
  ctx->file = fopen(filename, "r");
}

void free_file_context(struct file_context *ctx) {
  if (ctx->file != NULL) {
    fclose(ctx->file);
  }
}

int encrypt_file(const char *filename, const EVP_CIPHER *cipher, const EVP_MD *digest, const EC_KEY *eckey, RSA *rsakey) {
  // Initialize encryption context
  struct encryption_context ctx;
  init_encryption_context(&ctx, cipher, digest);

  // Initialize file context
  struct file_context fctx;
  init_file_context(&fctx, filename, &ctx);

  // Encrypt file and write to output file
  FILE *out = fopen("output.enc", "w");
  if (out == NULL) {
    // Handle error
  }

  int chunk_size = 1024;
  char buffer[chunk_size];
  size_t len;
  unsigned char *outbuf;

  while ((len = fread(buffer, 1, chunk_size, fctx.file)) > 0) {
    outbuf = EVP_EncryptUpdate(fctx.encryption_ctx->cipher, &buffer[0], len);
    if (outbuf == NULL) {
      // Handle error
    }
    fwrite(outbuf, 1, len, out);
  }

  free_file_context(&fctx);

  // Calculate and write checksum
  unsigned char *checksum = EVP_DigestUpdate(fctx.encryption_ctx->digest, "Hello World");
  if (checksum == NULL) {
    // Handle error
  }
  fwrite(checksum, 1, SHA256_DIGEST_LENGTH, out);

  // Clean up
  free_encryption_context(&ctx);
  fclose(out);
}
