class SensorData {
public:
    // Constructor to initialize the sensor data object
    SensorData(std::string sensorType, std::vector<double>& data) : sensorType_(sensorType), data_(data) {}

    // Getter methods for accessing sensor type and data
    const std::string& getSensorType() { return sensorType_; }
    const std::vector<double>& getData() { return data_; }

private:
    // Sensor type string (e.g., "temperature", "humidity")
    std::string sensorType_;

    // Vector of double values representing the sensor data
    std::vector<double> data_;
};

class SensorDataManager {
public:
    // Constructor to initialize the sensor data manager object
    SensorDataManager() {}

    // Method to add a new sensor data stream to the manager
    void addSensorData(const std::string& sensorType, const std::vector<double>& data) {
        std::lock_guard<std::mutex> lock(dataMutex_);
        sensorData_.push_back(SensorData(sensorType, data));
    }

    // Method to process the added sensor data streams in a separate thread
    void processSensorData() {
        while (true) {
            std::unique_lock<std::mutex> lock(dataMutex_);
            if (!sensorData_.empty()) {
                SensorData data = sensorData_.front();
                // Process the data here
                sensorData_.pop_front();
            } else {
                break;
            }
        }
    }

private:
    // Mutex to synchronize access to the sensor data vector
    std::mutex dataMutex_;

    // Vector of SensorData objects representing the added sensor data streams
    std::vector<SensorData> sensorData_;
};
