Here is a sample implementation of the modular C++ application that processes large, heterogeneous log files from various sources in near-real-time:
```c
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

// Log entry structure
struct LogEntry {
  std::string message;
  std::string source;
  int timestamp;
};

// JSON schema for log entries
const std::string schema = "{\"type\":\"object\", \"properties\": {\"message\": { \"type\": \"string\" }, \"source\": { \"type\": \"string\" }, \"timestamp\": { \"type\": \"integer\" }}}";

// Parser class to parse log entries from a given file and apply JSON schema
class LogParser {
 public:
  LogParser(const std::string& file_path, const std::string& schema) : file_path_(file_path), schema_(schema) {}

  // Parse log entries from the input file and return a vector of parsed entries
  std::vector<LogEntry> parse() {
    std::ifstream in(file_path_);
    if (!in.is_open()) {
      throw std::runtime_error("Failed to open input file");
    }

    // Use the JSON schema to validate and transform log entries
    std::vector<LogEntry> parsed_entries;
    while (true) {
      std::string line;
      if (!std::getline(in, line)) {
        break;
      }

      // Parse log entry from the current line
      LogEntry entry = parse_entry(line);

      // Add the parsed entry to the vector of parsed entries
      parsed_entries.push_back(entry);
    }

    return parsed_entries;
  }

 private:
  // Parse a single log entry from a given line and apply JSON schema
  LogEntry parse_entry(const std::string& line) {
    // Use the JSON schema to validate and transform the log entry
    auto json = nlohmann::json::parse(line);
    if (!json.is_object()) {
      throw std::runtime_error("Invalid JSON object");
    }

    // Apply field renaming, value normalization, and selective data retention
    LogEntry entry;
    entry.message = json["message"].get<std::string>();
    entry.source = json["source"].get<std::string>();
    entry.timestamp = json["timestamp"].get<int>();
    return entry;
  }

  // Input file path and JSON schema for log entries
  std::string file_path_;
  std::string schema_;
};

// Asynchronous I/O operations class to handle high throughput and low latency in processing log entries
class AsyncIoOperations {
 public:
  AsyncIoOperations() {}

  // Enqueue a new asynchronous I/O operation for reading from the input file
  void enqueue_read(const std::string& file_path) {
    std::ifstream in(file_path);
    if (!in.is_open()) {
      throw std::runtime_error("Failed to open input file");
    }

    // Create a new thread to perform the asynchronous read operation
    auto* thread = new std::thread([this, &in]() {
      while (true) {
        std::string line;
        if (!std::getline(in, line)) {
          break;
        }

        // Enqueue the read line for processing
        this->enqueue_read_line(line);
      }
    });
  }

  // Enqueue a new asynchronous I/O operation for writing to the output file
  void enqueue_write(const std::string& file_path) {
    std::ofstream out(file_path, std::ios::out | std::ios::binary);
    if (!out.is_open()) {
      throw std::runtime_error("Failed to open output file");
    }

    // Create a new thread to perform the asynchronous write operation
    auto* thread = new std::thread([this, &out]() {
      while (true) {
        // Dequeue the next line for writing and write it to the output file
        this->dequeue_write_line(out);
      }
    });
  }

  // Enqueue a new asynchronous I/O operation for processing log entries using the given parser class
  void enqueue_parser(const std::string& file_path, const std::string& schema) {
    auto* parser = new LogParser(file_path, schema);
    this->parsers_.push_back(parser);

    // Create a new thread to perform the asynchronous parse operation
    auto* thread = new std::thread([this, parser]() {
      while (true) {
        // Dequeue the next line for parsing and pass it to the parser class
        this->dequeue_parse_line(parser);
      }
    });
  }

 private:
  // Enqueue a new read line for processing
  void enqueue_read_line(const std::string& line) {
    // Lock the mutex to prevent concurrent access to the queue
    std::lock_guard<std::mutex> lock(this->mutex_);

    this->read_queue_.push(line);
  }

  // Dequeue the next read line for processing and return it
  std::string dequeue_read_line() {
    // Lock the mutex to prevent concurrent access to the queue
    std::lock_guard<std::mutex> lock(this->mutex_);

    if (this->read_queue_.empty()) {
      return "";
    }

    auto line = this->read_queue_.front();
    this->read_queue_.pop();
    return line;
  }

  // Enqueue a new parse line for processing
  void enqueue_parse_line(LogParser* parser, const std::string& line) {
    // Lock the mutex to prevent concurrent access to the queue
    std::lock_guard<std::mutex> lock(this->mutex_);

    this->parse_queue_.push({parser, line});
  }

  // Dequeue the next parse line for processing and return it
  std::pair<LogParser*, std::string> dequeue_parse_line() {
    // Lock the mutex to prevent concurrent access to the queue
    std::lock_guard<std::mutex> lock(this->mutex_);

    if (this->parse_queue_.empty()) {
      return {};
    }

    auto entry = this->parse_queue_.front();
    this->parse_queue_.pop();
    return entry;
  }

  // Enqueue a new write line for processing
  void enqueue_write_line(const std::string& line) {
    // Lock the mutex to prevent concurrent access to the queue
    std::lock_guard<std::mutex> lock(this->mutex_);

    this->write_queue_.push(line);
  }

  // Dequeue the next write line for processing and return it
  std::string dequeue_write_line() {
    // Lock the mutex to prevent concurrent access to the queue
    std::lock_guard<std::mutex> lock(this->mutex_);

    if (this->write_queue_.empty()) {
      return "";
    }

    auto line = this->write_queue_.front();
    this->write_queue_.pop();
    return line;
  }

  // Vector of parser classes for processing log entries
  std::vector<LogParser*> parsers_;

  // Read queue for storing read lines for processing
  std::queue<std::string> read_queue_;

  // Parse queue for storing parse lines for processing
  std::queue<std::pair<LogParser*, std::string>> parse_queue_;

  // Write queue for storing write lines for processing
  std::queue<std::string> write_queue_;

  // Mutex for preventing concurrent access to the queues
  std::mutex mutex_;
};

int main() {
  AsyncIoOperations operations;

  // Enqueue read, parse, and write operations for processing log entries from an input file and writing the results to an output file
  operations.enqueue_read("input.log");
  operations.enqueue_parser("input.log", "schema.json");
  operations.enqueue_write("output.log");

  return 0;
}']

