Here's a sample implementation of the highly performant and scalable Sandesh client in C++ that efficiently manages concurrent GET and POST requests to a cluster of web servers:
```c++
#include <iostream>
#include <vector>
#include <string>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

// Define the request types
enum RequestType { GET, POST };

// Define the request struct
struct Request {
  // The type of the request (GET or POST)
  RequestType type;

  // The URL of the request
  std::string url;

  // The body of the request (if applicable)
  std::string body;
};

// Define the response struct
struct Response {
  // The status code of the response
  int status_code;

  // The body of the response
  std::string body;
};

// Define the request manager class
class RequestManager {
public:
  // Constructor
  RequestManager(const std::vector<std::string>& servers) : servers_(servers) {}

  // Function to add a new request to the queue
  void AddRequest(const Request& request);

  // Function to get the next available server
  const std::string GetNextServer();

  // Function to handle a response from a server
  void HandleResponse(const Response& response);

private:
  // The list of servers in the cluster
  std::vector<std::string> servers_;

  // The queue of requests
  std::queue<Request> request_queue_;

  // The current server being used
  std::string current_server_;

  // The mutex to protect the request queue and current server
  std::mutex mutex_;

  // The condition variable to signal when a response is available
  std::condition_variable cv_;
};

// Function to add a new request to the queue
void RequestManager::AddRequest(const Request& request) {
  std::lock_guard<std::mutex> lock(mutex_);
  request_queue_.push(request);
}

// Function to get the next available server
const std::string RequestManager::GetNextServer() {
  std::lock_guard<std::mutex> lock(mutex_);

  // Check if there are any servers available
  if (servers_.empty()) {
    return "";
  }

  // Get the next server from the list of servers
  const auto& next_server = servers_.front();
  servers_.pop_front();
  return next_server;
}

