Here is a sample code for the logging framework you described:
```c++
#include <iostream>
#include <fstream>
#include <sstream>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <queue>
#include <vector>
#include <string>

// Logger class that handles the logging operations
class Logger {
public:
    // Constructor to initialize the logger with a configuration file
    Logger(const std::string& config_file) : config_file_(config_file) {
        parse_config();
        init_logging_outputs();
    }

    // Destructor to close the logging outputs
    ~Logger() {
        for (auto& output : logging_outputs_) {
            output->close();
        }
    }

    // Log function that takes in a log message and its severity level
    void log(const std::string& message, int severity) {
        // Lock the mutex to prevent concurrent access to the logging outputs
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if the message should be logged based on its severity level and configuration
        bool should_log = check_severity(severity) && check_configuration();

        // Log the message to all enabled logging outputs
        for (auto& output : logging_outputs_) {
            if (should_log) {
                output->write(message);
            }
        }
    }

private:
    // Configuration file path
    std::string config_file_;

    // Mutex to prevent concurrent access to the logging outputs
    std::mutex mutex_;

    // Condition variable to signal when a log message is available
    std::condition_variable cond_;

    // Queue of log messages waiting to be processed
    std::queue<std::string> log_queue_;

    // Vector of logging outputs, each with its own configuration and buffer size
    std::vector<std::unique_ptr<LoggingOutput>> logging_outputs_;

    // Parse the configuration file and initialize the logging outputs
    void init_logging_outputs() {
        // Load the configuration from the file
        auto config = parse_config();

        // Initialize the logging outputs based on the configuration
        for (auto& output : config.getOutputs()) {
            logging_outputs_.emplace_back(new LoggingOutput(output));
        }
    }

    // Check if a log message should be logged based on its severity level and configuration
    bool check_severity(int severity) {
        return (severity >= config.getMinSeverityLevel()) && (severity <= config.getMaxSeverityLevel());
    }

    // Check if the logging outputs should be enabled based on the configuration
    bool check_configuration() {
        for (auto& output : logging_outputs_) {
            if (!output->isEnabled()) {
                return false;
            }
        }
        return true;
    }
};

// Logging output class that handles the actual logging operations to a file or console
class LoggingOutput {
public:
    // Constructor to initialize the logging output with its configuration and buffer size
    LoggingOutput(const std::string& config) : config_(config), buffer_size_(0) {
        parse_config();
    }

    // Write a log message to the output, synchronized by the mutex
    void write(const std::string& message) {
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if the buffer is full and needs to be flushed before adding new messages
        if (buffer_size_ >= config_.getBufferSize()) {
            flush();
        }

        // Add the log message to the buffer
        log_buffer_.emplace_back(message);

        // Increment the buffer size and signal that a log message is available
        ++buffer_size_;
        cond_.notify_all();
    }

    // Close the logging output and flush any remaining messages
    void close() {
        std::lock_guard<std::mutex> lock(mutex_);
        flush();
        buffer_.close();
    }

private:
    // Mutex to prevent concurrent access to the log buffer
    std::mutex mutex_;

    // Condition variable to signal when a log message is available for processing
    std::condition_variable cond_;

    // Buffer of log messages waiting to be processed
    std::queue<std::string> log_buffer_;

    // Size of the buffer in bytes
    size_t buffer_size_;

    // Configuration for the logging output
    LoggingOutputConfig config_;

    // Parse the configuration file and initialize the logging output
    void parse_config() {
        // Load the configuration from the file
        auto config = parse_config();

        // Initialize the buffer size based on the configuration
        buffer_size_ = 0;
    }

    // Flush any remaining messages in the buffer to the output
    void flush() {
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if there are any messages waiting to be processed
        while (!log_buffer_.empty()) {
            auto& message = log_buffer_.front();

            // Write the message to the output, synchronized by the mutex
            buffer_.write(message.c_str(), message.length());

            // Remove the message from the buffer and decrement the buffer size
            log_buffer_.pop_front();
            --buffer_size_;
        }
    }
};
```
This code provides a basic implementation of a logging framework in C++ that supports multiple output destinations, asynchronous logging, and configurability via a JSON-based configuration file. The `Logger` class is responsible for handling the logging operations and maintaining the list of enabled logging outputs. Each `LoggingOutput` instance handles the actual logging operations to a file or console based on its own configuration and buffer size.

The `init_logging_outputs()` function initializes the logging outputs based on the configuration file, while the `check_severity()` and `check_configuration()` functions check if a log message should be logged based on its severity level and whether any enabled logging outputs are available, respectively. The `write()` function writes a log message to the output, synchronized by the mutex, while the `close()` function closes the logging output and flushes any remaining messages in the buffer.

This is just one example of how you could implement a logging framework in C++, and there are many ways to customize and extend this code depending on your specific requirements.']

