using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Azure.Storage.Blobs;
using Google.Cloud.Storage.V1;
using Amazon.S3.Model;

namespace FileCompressionLibrary
{
    public class CompressionUtility
    {
        private readonly ILogger _logger;
        private readonly CloudStorageProvider _cloudStorageProvider;
        private readonly string _filePath;

        public CompressionUtility(ILogger logger, CloudStorageProvider cloudStorageProvider, string filePath)
        {
            _logger = logger;
            _cloudStorageProvider = cloudStorageProvider;
            _filePath = filePath;
        }

        public async Task<string> CompressFileAsync(CompressionAlgorithm algorithm, CancellationToken cancellationToken = default)
        {
            // Determine the appropriate compression algorithm based on the input argument
            if (algorithm == CompressionAlgorithm.Gzip)
            {
                return await GzipCompressFileAsync(_filePath, cancellationToken);
            }
            else if (algorithm == CompressionAlgorithm.Deflate)
            {
                return await DeflateCompressFileAsync(_filePath, cancellationToken);
            }
            else if (algorithm == CompressionAlgorithm.Brotli)
            {
                return await BrotliCompressFileAsync(_filePath, cancellationToken);
            }

            throw new ArgumentException("Invalid compression algorithm", nameof(algorithm));
        }

        public async Task<string> DecompressFileAsync(CancellationToken cancellationToken = default)
        {
            // Determine the appropriate decompression algorithm based on the input file extension
            string fileExtension = Path.GetExtension(_filePath);
            if (fileExtension == ".gz")
            {
                return await GzipDecompressFileAsync(_filePath, cancellationToken);
            }
            else if (fileExtension == ".zip")
            {
                return await ZipDecompressFileAsync(_filePath, cancellationToken);
            }
            else if (fileExtension == ".tar")
            {
                return await TarDecompressFileAsync(_filePath, cancellationToken);
            }

            throw new ArgumentException("Invalid file extension", nameof(fileExtension));
        }

        private async Task<string> GzipCompressFileAsync(string sourceFilePath, CancellationToken cancellationToken)
        {
            // Compress the source file using Gzip algorithm and return the compressed file path
            string destinationFilePath = sourceFilePath + ".gz";

            using var sourceStream = new FileStream(sourceFilePath, FileMode.Open);
            using var destinationStream = new FileStream(destinationFilePath, FileMode.Create);

            await GzipCompressAsync(sourceStream, destinationStream, cancellationToken);

            return destinationFilePath;
        }

        private async Task<string> DeflateCompressFileAsync(string sourceFilePath, CancellationToken cancellationToken)
        {
            // Compress the source file using Deflate algorithm and return the compressed file path
            string destinationFilePath = sourceFilePath + ".zz";

            using var sourceStream = new FileStream(sourceFilePath, FileMode.Open);
            using var destinationStream = new FileStream(destinationFilePath, FileMode.Create);

            await DeflateCompressAsync(sourceStream, destinationStream, cancellationToken);

            return destinationFilePath;
        }

        private async Task<string> BrotliCompressFileAsync(string sourceFilePath, CancellationToken cancellationToken)
        {
            // Compress the source file using Brotli algorithm and return the compressed file path
            string destinationFilePath = sourceFilePath + ".br";

            using var sourceStream = new FileStream(sourceFilePath, FileMode.Open);
            using var destinationStream = new FileStream(destinationFilePath, FileMode.Create);

            await BrotliCompressAsync(sourceStream, destinationStream, cancellationToken);

            return destinationFilePath;
        }

        private async Task GzipDecompressFileAsync(string sourceFilePath, CancellationToken cancellationToken)
        {
            // Decompress the source file using Gzip algorithm and write to the destination file path
            string destinationFilePath = sourceFilePath.Replace(".gz", "");

            using var sourceStream = new FileStream(sourceFilePath, FileMode.Open);
            using var destinationStream = new FileStream(destinationFilePath, FileMode.Create);

            await GzipDecompressAsync(sourceStream, destinationStream, cancellationToken);
        }

        private async Task ZipDecompressFileAsync(string sourceFilePath, CancellationToken cancellationToken)
        {
            // Decompress the source file using Zip algorithm and write to the destination file path
            string destinationFilePath = sourceFilePath.Replace(".zip", "");

            using var sourceStream = new FileStream(sourceFilePath, FileMode.Open);
            using var destinationStream = new FileStream(destinationFilePath, FileMode.Create);

            await ZipDecompressAsync(sourceStream, destinationStream, cancellationToken);
        }

        private async Task TarDecompressFileAsync(string sourceFilePath, CancellationToken cancellationToken)
        {
            // Decompress the source file using Tar algorithm and write to the destination file path
            string destinationFilePath = sourceFilePath.Replace(".tar", "");

            using var sourceStream = new FileStream(sourceFilePath, FileMode.Open);
            using var destinationStream = new FileStream(destinationFilePath, FileMode.Create);

            await TarDecompressAsync(sourceStream, destinationStream, cancellationToken);
        }
    }
}
