// ResourceManager.java
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class ResourceManager {
    private final Map<String, Integer> resourceMap = new ConcurrentHashMap<>();
    private final ApiService apiService;

    public ResourceManager(ApiService apiService) {
        this.apiService = apiService;
    }

    public int getResourceCount(String resourceId) {
        return resourceMap.getOrDefault(resourceId, 0);
    }

    public void updateResourceCount(String resourceId, int count) {
        resourceMap.put(resourceId, Math.max(count, 0));
    }

    public boolean requestResources(String clientId, String resourceId, int count) {
        if (!apiService.isAvailable()) {
            return false; // API service is unavailable, retry later
        }

        int currentCount = getResourceCount(resourceId);
        if (currentCount < count) {
            return false; // Insufficient resources available
        }

        updateResourceCount(resourceId, currentCount - count);
        apiService.requestResources(clientId, resourceId, count);
        return true;
    }

    public void releaseResources(String clientId, String resourceId, int count) {
        if (!apiService.isAvailable()) {
            return; // API service is unavailable, retry later
        }

        updateResourceCount(resourceId, getResourceCount(resourceId) + count);
        apiService.releaseResources(clientId, resourceId, count);
    }
}
