    }

    public CompletableFuture<Void> requestResources(String clientId, String resourceId, int count) {
        // Retry logic with exponential backoff and fallback to local cache
        return restTemplate.postForObjectAsync(apiUrl + "/resources", new Request(clientId, resourceId, count), Void.class);
    }

    public CompletableFuture<Void> releaseResources(String clientId, String resourceId, int count) {
        // Retry logic with exponential backoff and fallback to local cache
        return restTemplate.postForObjectAsync(apiUrl + "/resources", new Request(clientId, resourceId, -count), Void.class);
    }
}
