Here is an example of a distributed state loader that addresses the challenges outlined in the programming task:
```
import json
from collections import defaultdict
from threading import Thread
from time import sleep

class StateLoader:
    def __init__(self):
        self.data = defaultdict(lambda: defaultdict(list))
        self.locks = {}
        self.external_data_sources = [
            DatabaseDataSource(),
            RESTAPIDataSource(),
            MessageQueueDataSource()
        ]

    def load_state(self):
        for source in self.external_data_sources:
            try:
                data = source.get_data()
                for key, value in data.items():
                    self.data[key].append(value)
            except Exception as e:
                print("Error loading state from {}".format(source))

    def get_state(self):
        return self.data

    def set_state(self, key, value):
        with self.locks[key]:
            self.data[key] = value

    def delete_state(self, key):
        del self.data[key]

class DatabaseDataSource:
    def __init__(self):
        self.connection = None

    def get_data(self):
        with self.connection as cursor:
            cursor.execute("SELECT * FROM states")
            return cursor.fetchall()

class RESTAPIDataSource:
    def __init__(self):
        self.session = requests.Session()

    def get_data(self):
        response = self.session.get("https://api.example.com/states")
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception("Error retrieving state data from REST API")

class MessageQueueDataSource:
    def __init__(self):
        self.connection = None

    def get_data(self):
        with self.connection as consumer:
            message = consumer.receive()
            if message is not None:
                return json.loads(message)
            else:
                raise Exception("Error retrieving state data from message queue")
