const winston = require('winston');
const logger = createLogger({
  level: 'info',
  format: winston.format.json(),
});

// Define the middleware function for handling incoming requests
app.use((req, res, next) => {
  // Log the request at the info level
  logger.info(JSON.stringify(req));
  next();
});

// Set up the S3 client and API endpoint
