import { getExternalMetadata } from 'external-data-api';
import { fetchNodeData } from 'database-api';
import { logError, logWarning, logInfo } from 'logging-utils';

const processNode = async (node: any): Promise<any> => {
  try {
    // Fetch additional metadata from external APIs
    const externalMetadata = await getExternalMetadata(node.id);
    Object.assign(node, externalMetadata);

    // Fetch related data from other services
    const relatedData = await fetchNodeData(node.relatedId);
    node.relatedData = relatedData;

    return node;
  } catch (error) {
    logError(`Failed to process node ${node.id}: ${error}`);
    return null;
  }
};

const processNodes = async (nodes: any[]): Promise<any[]> => {
  const processedNodes = [];
  for (let i = 0; i < nodes.length; i++) {
    const node = await processNode(nodes[i]);
    if (node) {
      processedNodes.push(node);
    }
  }
  return processedNodes;
};

const handleError = async (error: any): Promise<void> => {
  logWarning(`Encountered error in processing nodes: ${error}`);
  // Handle partial failures gracefully
  const failedNodes = [];
  for (let i = 0; i < nodes.length; i++) {
    if (!processedNodes[i]) {
      failedNodes.push(nodes[i]);
    }
  }
  logInfo(`Processing of ${failedNodes.length} nodes failed`);
};

const processHierarchicalData = async (data: any): Promise<any> => {
  try {
    // Process nodes concurrently to optimize performance
    const processedNodes = await processNodes(data.nodes);
    return processedNodes;
  } catch (error) {
    handleError(error);
    return null;
  }
};
```
This code uses a combination of TypeScript and JavaScript syntax to define a function that processes a hierarchical data model, such as a CMS content tree, for efficient consumption by a front-end framework. The function integrates with external data sources using the `getExternalMetadata` function from an external library, fetches related data from other services using the `fetchNodeData` function from a database or microservice, and manages dependencies between nodes. It also includes error handling and edge case detection to ensure that the function can handle partial failures gracefully.

