Designing a scalable, serverless architecture for processing high-velocity geospatial data streams in near-real-time is a complex task that requires careful consideration of several factors. Here's an example code block that illustrates one possible design for this use case:
```scss
const AWS = require('aws-sdk');
const geo = require('geolib');
const { DynamoDB } = AWS;

// Set up a DynamoDB table for storing geospatial data
const GEO_DATA_TABLE = 'GeoDataTable';
const dynamodb = new DynamoDB({ region: 'us-east-1' });

async function processGeoData(data) {
  // Extract geospatial information from the incoming data
  const location = geo.point(data.latitude, data.longitude);
  const radius = geo.radiansToMiles(data.radius);

  // Query the DynamoDB table for nearby locations
  const queryParams = {
    TableName: GEO_DATA_TABLE,
    KeyConditionExpression: '#location BETWEEN :min AND :max',
    ExpressionAttributeNames: {
      '#location': 'location',
    },
    ExpressionAttributeValues: {
      ':min': geo.radiansToMiles(location - radius),
      ':max': geo.radiansToMiles(location + radius),
    },
  };
  const queryResults = await dynamodb.query(queryParams).promise();

  // Handle the results of the query
  if (queryResults.Items && queryResults.Items.length > 0) {
    console.log(`Found ${queryResults.Items.length} nearby locations`);
    return queryResults.Items;
  } else {
    console.log('No nearby locations found');
    return null;
  }
}

// Set up an API endpoint for processing geospatial data streams
const apiGateway = new AWS.APIGateway();
apiGateway.post('/process-geo-data', async (event) => {
  const data = JSON.parse(event.body);
  return processGeoData(data);
});
```
