<?php

namespace ClinicStatusUpdater;

class Service {
    private $dbConnectionPool;
    private $apiConnections;
    private $networkLatencyMap;
    private $responseTimeMap;
    private $lastUpdateTimes;

    public function __construct() {
        $this->dbConnectionPool = new DatabaseConnectionPool();
        $this->apiConnections = [];
        $this->networkLatencyMap = [];
        $this->responseTimeMap = [];
        $this->lastUpdateTimes = [];
    }

    public function updateClinicStatus($clinicId, $status) {
        $apiConnection = $this->getApiConnectionForClinic($clinicId);
        $response = $apiConnection->updateClinicStatus($clinicId, $status);

        if ($response === true) {
            // Update last update time
            $this->lastUpdateTimes[$clinicId] = time();

            // Update database
            $this->dbConnectionPool->updateClinicStatus($clinicId, $status);
        } else {
            // If the response is false, it means there was an error updating the clinic status
            // We can try to update the clinic status again using a different API connection
            // This will help us ensure that we don't lose any updates due to network issues
            $this->updateClinicStatus($clinicId, $status, true);
        }
    }

    public function getApiConnectionForClinic($clinicId) {
        // Get the API connection with the lowest average response time for this clinic
        $minResponseTime = PHP_INT_MAX;
        foreach ($this->apiConnections as $apiConnection) {
            if ($apiConnection->getClinicId() === $clinicId) {
                if ($apiConnection->getAverageResponseTime() < $minResponseTime) {
                    $minResponseTime = $apiConnection->getAverageResponseTime();
                }
            }
        }

        // Get the API connection with the lowest average network latency for this clinic
        $minLatency = PHP_INT_MAX;
        foreach ($this->networkLatencyMap[$clinicId] as $latency) {
            if ($latency < $minLatency) {
                $minLatency = $latency;
            }
        }

        // Get the API connection with the lowest average response time and network latency for this clinic
        foreach ($this->apiConnections as $apiConnection) {
            if ($apiConnection->getAverageResponseTime() === $minResponseTime && $apiConnection->getAverageLatency() === $minLatency) {
                return $apiConnection;
            }
        }

        // If no API connection is found, create a new one
        return new ApiConnection($clinicId);
    }

    public function updateNetworkLatencyMap($clinicId, $latency) {
        // Add the latency to the network latency map for this clinic
        $this->networkLatencyMap[$clinicId][] = $latency;

        // Remove the oldest latency measurement from the map if it exceeds a certain age
        if (count($this->networkLatencyMap[$clinicId]) > 10) {
            array_shift($this->networkLatencyMap[$clinicId]);
        }
    }

    public function updateResponseTimeMap($clinicId, $responseTime) {
        // Add the response time to the response time map for this clinic
        $this->responseTimeMap[$clinicId][] = $responseTime;

        // Remove the oldest response time measurement from the map if it exceeds a certain age
        if (count($this->responseTimeMap[$clinicId]) > 10) {
            array_shift($this->responseTimeMap[$clinicId]);
        }
    }

    public function getAverageNetworkLatencyForClinic($clinicId) {
        return array_sum($this->networkLatencyMap[$clinicId]) / count($this->networkLatencyMap[$clinicId]);
    }

    public function getAverageResponseTimeForClinic($clinicId) {
        return array_sum($this->responseTimeMap[$clinicId]) / count($this->responseTimeMap[$clinicId]);
    }
}

class DatabaseConnectionPool {
    private $connections;

    public function __construct() {
        $this->connections = [];
    }

    public function updateClinicStatus($clinicId, $status) {
        // Update the clinic status in each database connection
        foreach ($this->connections as $connection) {
            $connection->updateClinicStatus($clinicId, $status);
        }
    }
}

class ApiConnection {
    private $clinicId;
    private $averageResponseTime = 0;
    private $averageLatency = 0;

    public function __construct($clinicId) {
        $this->clinicId = $clinicId;
    }

    public function getClinicId() {
        return $this->clinicId;
    }

    public function updateAverageResponseTime($responseTime) {
        $this->averageResponseTime = ($this->averageResponseTime + $responseTime) / 2;
    }

    public function getAverageResponseTime() {
        return $this->averageResponseTime;
    }

    public function updateAverageLatency($latency) {
        $this->averageLatency = ($this->averageLatency + $latency) / 2;
    }

    public function getAverageLatency() {
        return $this->averageLatency;
    }
}
```

