// structure to hold log data
typedef struct {
    int level;
    char *message;
} LogData;

// thread-safe queue for storing logs
typedef struct {
    pthread_mutex_t lock; // mutex for locking the queue
    pthread_cond_t cond; // condition variable for signaling changes to the queue
    int head; // index of the first log entry in the queue
    int tail; // index of the last log entry in the queue
    int size; // number of logs in the queue
    LogData *logs[]; // array of log entries
} Queue;

// function to create a new log data structure
LogData *create_log_data(int level, const char *message) {
    LogData *log = malloc(sizeof(LogData));
    log->level = level;
    log->message = strdup(message);
    return log;
}

// function to append a log message to the queue
void enqueue_log(Queue *q, int level, const char *message) {
    pthread_mutex_lock(&q->lock);
    while (q->size >= q->capacity) { // wait for space in the queue
        pthread_cond_wait(&q->cond, &q->lock);
    }
    LogData *log = create_log_data(level, message);
    int index = (q->tail + 1) % q->capacity;
    q->logs[index] = log;
    q->size++;
    pthread_cond_signal(&q->cond); // signal that there is new data in the queue
    pthread_mutex_unlock(&q->lock);
}

// function to remove a log message from the queue
LogData *dequeue_log(Queue *q) {
    pthread_mutex_lock(&q->lock);
    while (q->size <= 0) { // wait for data in the queue
        pthread_cond_wait(&q->cond, &q->lock);
    }
    LogData *log = q->logs[q->head];
    q->head = (q->head + 1) % q->capacity;
    q->size--;
    pthread_mutex_unlock(&q->lock);
    return log;
}

// function to check if a log message is present in the queue
int is_logged(Queue *q, const char *message) {
    int found = 0;
    pthread_mutex_lock(&q->lock);
    for (int i = q->head; i != q->tail && !found; i = (i + 1) % q->capacity) {
        if (strcmp(q->logs[i]->message, message) == 0) {
            found = 1;
        }
    }
    pthread_mutex_unlock(&q->lock);
    return found;
}

// function to flush the queue and write logs to a file
void flush_queue(Queue *q, FILE *file) {
    pthread_mutex_lock(&q->lock);
    while (q->size > 0) { // wait for data in the queue
        pthread_cond_wait(&q->cond, &q->lock);
    }
    fprintf(file, "Logs:\n");
    int count = 1;
    for (int i = q->head; i != q->tail; i = (i + 1) % q->capacity) {
