        fprintf(file, "%d: %s\n", count++, log->message);
    }
    pthread_mutex_unlock(&q->lock);
}

// function to compress a log message using LZ77 algorithm
void compress_log(char *message) {
    int size = strlen(message);
    char compressed[size]; // buffer for the compressed data
    size_t destLen = sizeof(compressed); // size of the destination buffer
    int status = LZ77_encode(message, size, compressed, &destLen); // encode the message
    if (status == Z_OK) { // check if compression succeeded
        strcpy(message, compressed); // overwrite the original message with the compressed one
    }
}

// function to validate and sanitize a log message for injection attacks
void validate_log(char *message) {
    int size = strlen(message);
    char buffer[size]; // buffer for the sanitized data
    memset(buffer, 0, sizeof(buffer));
    int index = 0;
    for (int i = 0; i < size; i++) {
        char ch = message[i];
        if (ch == '%' || ch == '\\') { // check for injection attacks
            index++; // skip the current character
        } else if (ch >= 0 && ch <= 127) { // validate that the character is printable
            buffer[index] = ch;
            index++;
        } else { // replace non-printable characters with spaces
            buffer[index++] = ' ';
        }
    }
    strcpy(message, buffer); // overwrite the original message with the sanitized one
}

