    }
    fprintf(f, "%s\n", buffer); // write the log message to the file
    fclose(f);
}

// function to append a log message to a queue and optionally flush it to a file
void append_log_to_queue(const char *file, const char *message) {
    Queue q = {0}; // create an empty queue
    int capacity = 100; // set the capacity of the queue
    pthread_mutex_init(&q.lock, NULL); // initialize the mutex for the queue
    pthread_cond_init(&q.cond, NULL); // initialize the condition variable for the queue
