class FieldParser {
private:
    const vector<string>& fields_;

public:
    FieldParser(const vector<string>& fields) : fields_(fields) {}

    bool parse() {
        // Check if the last three fields are numeric
        for (int i = 0; i < fields_.size() - 3; ++i) {
            try {
                stod(fields_[i]);
            } catch (const std::exception& e) {
                return false;
            }
        }
        // Replace the last field with its average if numeric, otherwise retain original value
        for (int i = 0; i < fields_.size() - 3; ++i) {
            try {
                fields_[i] = to_string(stod(fields_[i]));
            } catch (const std::exception& e) {
                // Do nothing, retain original value
            }
        }
        return true;
    }
};

class FileProcessor {
