        return true;
    }
};

class FileProcessorThread {
private:
    const string& filename_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool ready_ = false;
    bool failed_ = false;

public:
    FileProcessorThread(const string& filename) : filename_(filename) {}

    void process() {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return ready_; });
        if (failed_) {
            // Handle failed file
            return;
        }
        FileProcessor processor(filename_);
        if (!processor.process()) {
            failed_ = true;
        }
    }

    void setReady() {
        std::unique_lock<std::mutex> lock(mutex_);
        ready_ = true;
        cv_.notify_all();
    }
};

class FileQueue {
private:
    std::vector<FileProcessorThread*> threads_;
    std::deque<string> queue_;
    std::atomic_bool stop_ = false;

public:
    FileQueue() : threads_(4) {}

    void push(const string& filename) {
        queue_.push_back(filename);
        cv_.notify_all();
    }

    bool pop(string& filename) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (queue_.empty() && !stop_) {
            cv_.wait(lock);
        }
        if (!stop_ && queue_.size()) {
            filename = queue_.front();
            queue_.pop_front();
            return true;
        } else {
            return false;
        }
    }
};

int main() {
    // Create FileQueue and FileProcessorThreads
    FileQueue queue;
    vector<FileProcessorThread*> threads;
    for (size_t i = 0; i < 4; ++i) {
        threads.push_back(new FileProcessorThread(""));
    }

    // Start FileProcessorThreads
    for (auto thread : threads) {
        thread->start();
    }

    // Read files from the REST API and push them to the FileQueue
