        string filename = readFileFromRESTAPI();
        queue.push(filename);
    }

    // Wait for all threads to finish processing files
    for (auto thread : threads) {
        thread->setReady();
    }
    for (auto thread : threads) {
        thread->join();
    }

    return 0;
}
