int readImageFile(const char* filename, ImageFormat format, struct ImageMetadata* metadata) {
    // Check if the file exists and is readable
    FILE* file = fopen(filename, "r");
    if (!file) {
        return -1;
    }

    // Read the image header to determine the number of samples per pixel
    uint8_t numSamplesPerPixel;
    switch (format) {
        case TIFF:
            numSamplesPerPixel = 3;
            break;
        case JPEG:
            numSamplesPerPixel = EXTRA_SAMPLES + 1;
            break;
        case PNG:
            numSamplesPerPixel = EXTRA_SAMPLES + 2;
            break;
    }

    // Read the image data and extract metadata
    uint32_t width, height;
    uint8_t bitsPerSample, extraSamplesPerPixel;
    for (int i = 0; i < numSamplesPerPixel; i++) {
        if (fread(&width, sizeof(uint32_t), 1, file) != 1 || fread(&height, sizeof(uint32_t), 1, file) != 1) {
            return -1;
        }
    }
    for (int i = 0; i < numSamplesPerPixel; i++) {
        if (fread(&bitsPerSample, sizeof(uint8_t), 1, file) != 1 || fread(&extraSamplesPerPixel, sizeof(uint8_t), 1, file) != 1) {
            return -1;
        }
    }

    // Store the metadata in the struct
    metadata->width = width;
    metadata->height = height;
    metadata->bitsPerSample = bitsPerSample;
    metadata->extraSamplesPerPixel = extraSamplesPerPixel;

    fclose(file);
    return 0;
}

