        private const int INITIAL_BACKOFF_MILLISECONDS = 100;

        // Implement a centralized logging service like ELK Stack or Azure Monitor for handling exceptions and critical operations
        private static readonly Logger _logger = new Logger();

        public static byte[] Encrypt(string keyId, string plaintext)
        {
            // Retrieve the key from the KMS using dependency injection and caching
            byte[] key = GetKeyFromKms(keyId);

            // Generate a random IV for this encryption operation
            byte[] iv = CreateRandomIv();

            // Encrypt the plaintext using AES-CBC
            var encryptor = new AesCbcEncryptor(key, iv);
            return encryptor.TransformFinalBlock(Encoding.UTF8.GetBytes(plaintext), 0, plaintext.Length);
        }

        public static string Decrypt(string keyId, byte[] ciphertext)
        {
            // Retrieve the key from the KMS using dependency injection and caching
            byte[] key = GetKeyFromKms(keyId);

            // Generate a random IV for this decryption operation
            byte[] iv = CreateRandomIv();

            // Decrypt the ciphertext using AES-CBC
            var decryptor = new AesCbcDecryptor(key, iv);
            return Encoding.UTF8.GetString(decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length));
        }

        private static byte[] GetKeyFromKms(string keyId)
        {
            // Retrieve the key from the KMS using dependency injection and caching
            if (_keyCache.TryGetValue(keyId, out byte[] key))
            {
                return key;
            }
            else
            {
                try
                {
                    // Interact with the KMS to retrieve the key
                    var kmsClient = new KeyManagementService();
                    key = kmsClient.GetKey(keyId);

                    // Cache the retrieved key for future use
                    _keyCache[keyId] = key;
                }
                catch (Exception ex)
                {
                    _logger.Error("Failed to retrieve key from KMS", ex);
                    throw new EncryptionException("Failed to retrieve key from KMS", ex);
                }
            }
        }

        private static byte[] CreateRandomIv()
        {
            // Generate a random IV using the default IV as a fallback
            var iv = new byte[16];
            if (RNGCryptoServiceProvider.Create().GetBytes(iv) == false)
            {
                return DEFAULT_IV;
            }
            else
            {
                return iv;
            }
        }
    }
}
```
