// mod.rs
use std::{collections::HashMap, sync::Arc};
use log::{info, warn};
use tokio::sync::RwLock;
use crate::directory_service::DirectoryService;

pub struct SymlinkManager {
    directory_service: Arc<DirectoryService>,
    symlinks: HashMap<String, String>, // key: link path, value: target path
    lock: RwLock<()>,
}

impl SymlinkManager {
    pub fn new(directory_service: Arc<DirectoryService>) -> Self {
        Self {
            directory_service,
            symlinks: HashMap::new(),
            lock: RwLock::new(()),
        }
    }

    pub async fn create_symlink(&self, link_path: &str, target_path: &str) -> Result<(), SymlinkError> {
        let mut lock = self.lock.write().await;
        if self.symlinks.contains_key(link_path) {
            return Err(SymlinkError::LinkExists);
        }
        match self.directory_service.create_symbolic_link(link_path, target_path).await {
            Ok(_) => {
                self.symlinks.insert(link_path.to_string(), target_path.to_string());
                Ok(())
            }
            Err(e) => Err(SymlinkError::from(e)),
        }
    }

    pub async fn remove_symlink(&self, link_path: &str) -> Result<(), SymlinkError> {
        let mut lock = self.lock.write().await;
        if !self.symlinks.contains_key(link_path) {
            return Err(SymlinkError::LinkNotFound);
        }
        match self.directory_service.delete_symbolic_link(link_path).await {
            Ok(_) => {
                self.symlinks.remove(link_path);
                Ok(())
            }
            Err(e) => Err(SymlinkError::from(e)),
        }
    }

    pub async fn update_symlink(&self, link_path: &str, target_path: &str) -> Result<(), SymlinkError> {
        let mut lock = self.lock.write().await;
        if !self.symlinks.contains_key(link_path) {
            return Err(SymlinkError::LinkNotFound);
        }
        match self.directory_service.update_symbolic_link(link_path, target_path).await {
            Ok(_) => {
                self.symlinks.insert(link_path.to_string(), target_path.to_string());
                Ok(())
            }
            Err(e) => Err(SymlinkError::from(e)),
        }
    }
}
