// directory_service.rs
use std::{collections::HashMap, sync::Arc};
use log::{info, warn};
use tokio::sync::RwLock;

pub struct DirectoryService {
    directories: HashMap<String, String>, // key: dir path, value: target path
    lock: RwLock<()>,
}

impl DirectoryService {
    pub fn new() -> Self {
        Self {
            directories: HashMap::new(),
            lock: RwLock::new(()),
        }
    }

    pub async fn create_directory(&self, dir_path: &str) -> Result<(), DirectoryError> {
        let mut lock = self.lock.write().await;
        if self.directories.contains_key(dir_path) {
            return Err(DirectoryError::DirExists);
        }
        match fs::create_dir(dir_path).await {
            Ok(_) => {
                self.directories.insert(dir_path.to_string(), "".to_string());
                Ok(())
            }
            Err(e) => Err(DirectoryError::from(e)),
        }
    }

    pub async fn delete_directory(&self, dir_path: &str) -> Result<(), DirectoryError> {
        let mut lock = self.lock.write().await;
        if !self.directories.contains_key(dir_path) {
            return Err(DirectoryError::DirNotFound);
        }
        match fs::remove_dir(dir_path).await {
            Ok(_) => {
                self.directories.remove(dir_path);
                Ok(())
            }
            Err(e) => Err(DirectoryError::from(e)),
        }
    }

    pub async fn create_symbolic_link(&self, link_path: &str, target_path: &str) -> Result<(), SymbolicLinkError> {
        let mut lock = self.lock.write().await;
        if !self.directories.contains_key(target_path) {
            return Err(SymbolicLinkError::TargetNotFound);
        }
        match fs::create_symlink(link_path, target_path).await {
            Ok(_) => {
                self.directories.insert(link_path.to_string(), "".to_string());
                Ok(())
            }
            Err(e) => Err(SymbolicLinkError::from(e)),
        }
    }

    pub async fn delete_symbolic_link(&self, link_path: &str) -> Result<(), SymbolicLinkError> {
        let mut lock = self.lock.write().await;
        if !self.directories.contains_key(link_path) {
            return Err(SymbolicLinkError::LinkNotFound);
        }
        match fs::remove_symlink(link_path).await {
            Ok(_) => {
                self.directories.remove(link_path);
                Ok(())
            }
            Err(e) => Err(SymbolicLinkError::from(e)),
        }
    }

    pub async fn update_symbolic_link(&self, link_path: &str, target_path: &str) -> Result<(), SymbolicLinkError> {
        let mut lock = self.lock.write().await;
        if !self.directories.contains_key(target_path) {
