from typing import Dict, Any
from dataclasses import dataclass
from secrets_manager import SecretsManager

# Define the configuration structure
@dataclass
class Config:
    key1: str = None
    key2: str = None
    key3: int = None

# Define the secrets manager class
class SecretsManager:
    def __init__(self):
        self.secrets = {}

    def add_secret(self, name: str, value: Any) -> None:
        self.secrets[name] = value

    def get_secret(self, name: str) -> Any:
        return self.secrets.get(name)

# Define the configuration manager class
class ConfigManager:
    def __init__(self):
        self.configs = {}
        self.lock = threading.Lock()

    def get_config(self, name: str) -> Config:
        with self.lock:
            if name not in self.configs:
                config = self._load_config(name)
                self.configs[name] = config
            return self.configs[name]

    def update_config(self, name: str, data: Dict[str, Any]) -> None:
        with self.lock:
            config = self._load_config(name)
            for key, value in data.items():
                setattr(config, key, value)
            self._save_config(config)

    def _load_config(self, name: str) -> Config:
        secrets_manager = SecretsManager()
        config_data = {}
        with open(f'{name}.json', 'r') as f:
            config_data = json.load(f)
        for key, value in config_data.items():
            if key in secrets_manager.secrets:
                setattr(config, key, value)
        return Config(**config_data)

    def _save_config(self, config: Config) -> None:
        with open(f'{name}.json', 'w') as f:
            json.dump(config.__dict__, f, indent=4)

# Example usage
config_manager = ConfigManager()
config = config_manager.get_config('my-config')
print(config)
```
This code defines a `Config` dataclass to represent the configuration structure, a `SecretsManager` class for managing secrets, and a `ConfigManager` class that loads, updates, and saves configurations. The `ConfigManager` class is designed to be thread-safe by using a lock object to prevent concurrent access to the configuration cache.

The `get_config` method retrieves a configuration from the cache or loads it from disk if necessary. The `update_config` method updates a configuration and saves it to disk. The `_load_config` method loads a configuration from disk and sets secrets in the secrets manager, while the `_save_config` method saves a configuration to disk.

The code also includes a sample usage example for retrieving a configuration using the `ConfigManager`."]

