// Forward declarations for NMP_MessageType and NMP_Message
class NMP_Message;
struct NMP_MessageType;

// Define the set of message types supported by the library
enum class NMP_MessageType {
    CONFIGURATION,
    STATUS_REPORT,
    ERROR_NOTIFICATION
};

// Define a payload structure for each message type
struct NMP_ConfigurationPayload {
    // Add configuration-specific fields here...
};

struct NMP_StatusReportPayload {
    // Add status report-specific fields here...
};

struct NMP_ErrorNotificationPayload {
    // Add error notification-specific fields here...
};

// Define a message structure that encapsulates the payload and its type
class NMP_Message {
public:
    // Constructor for creating a new message with a specific type
    NMP_Message(NMP_MessageType type, std::unique_ptr<void> payload) : type_(type), payload_(std::move(payload)) {}

    // Getters for the message's type and payload
    NMP_MessageType getType() const { return type_; }
    void* getPayload() const { return payload_.get(); }

private:
    // The message's type and payload
    NMP_MessageType type_;
    std::unique_ptr<void> payload_;
};

// Define a map of message types to their corresponding payload structures
static const std::map<NMP_MessageType, std::type_info*> messageTypeMap = {
    { NMP_MessageType::CONFIGURATION, &NMP_ConfigurationPayload::class },
    { NMP_MessageType::STATUS_REPORT, &NMP_StatusReportPayload::class },
    { NMP_MessageType::ERROR_NOTIFICATION, &NMP_ErrorNotificationPayload::class }
};

// Define a set of message types that are currently supported by the library
static const std::set<NMP_MessageType> supportedMessageTypes = {
    NMP_MessageType::CONFIGURATION,
    NMP_MessageType::STATUS_REPORT,
    NMP_MessageType::ERROR_NOTIFICATION
};

// Define a container for storing and managing the messages
class NMP_MessageStore {
public:
    // Constructor that initializes the message store with an empty set of messages
    NMP_MessageStore() : messages_() {}

    // Add a new message to the message store
    void add(NMP_Message&& message) {
        // Check if the message type is supported by the library
        if (supportedMessageTypes.count(message.getType()) == 0) {
            throw std::invalid_argument("Unsupported message type");
        }

        // Create a copy of the message's payload and store it in the map
        void* payload = new char[sizeof(void*)];
        memcpy(payload, message.getPayload(), sizeof(void*));
        messages_[message.getType()].push_back(payload);
    }

    // Retrieve a message from the message store based on its type and index
    NMP_Message& get(NMP_MessageType type, size_t index) {
        // Check if the message type is supported by the library
        if (supportedMessageTypes.count(type) == 0) {
            throw std::invalid_argument("Unsupported message type");
        }

        // Return the message at the specified index in the map
        return *reinterpret_cast<NMP_Message*>(messages_[type][index]);
    }

private:
    // The set of messages stored in the message store, organized by their types
    std::map<NMP_MessageType, std::vector<void*>> messages_;
};
