// NetworkManager.cpp
#include "NetworkManager.h"
#include <iostream>
#include <fstream>
#include <sstream>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <linux/if_ether.h>

// Configuration file paths
const std::string kNetworkConfigFilePath = "/etc/network/interfaces";
const std::string kRoutingTableFilePath = "/etc/iproute2/rtables";
const std::string kSecurityPoliciesFilePath = "/etc/iptables/policies.conf";

// Network interface configuration
std::map<std::string, NetworkInterfaceConfig> gNetworkInterfaces;

void NetworkManager::start() {
    // Load network interfaces from configuration file
    std::ifstream ifs(kNetworkConfigFilePath);
    if (!ifs) {
        std::cerr << "Failed to open network config file: " << kNetworkConfigFilePath << std::endl;
        return;
    }

    for (std::string line; std::getline(ifs, line); ) {
        // Skip empty lines and comments
        if (line.empty() || line[0] == '#') continue;

        // Split the line into tokens using ":" as a delimiter
        std::istringstream iss(line);
        std::vector<std::string> tokens{std::istream_iterator<std::string>(iss), {}};

        if (tokens.size() < 2) continue;

        // Construct the network interface configuration struct
        NetworkInterfaceConfig config;
        config.ipAddress = tokens[1];
        config.subnetMask = tokens[3];
        config.gateway = tokens[5];
        gNetworkInterfaces[tokens[0]] = config;
    }
}

void NetworkManager::stop() {
    // Save network interfaces to configuration file
    std::ofstream ofs(kNetworkConfigFilePath, std::ios::trunc);
    if (!ofs) {
        std::cerr << "Failed to open network config file: " << kNetworkConfigFilePath << std::endl;
        return;
    }

    for (const auto& [interfaceName, config] : gNetworkInterfaces) {
        ofs << interfaceName << ": " << config.ipAddress << ":" << config.subnetMask << ":" << config.gateway << std::endl;
    }
}

void NetworkManager::configureInterface(const std::string& interfaceName, const NetworkInterfaceConfig& config) {
    // Update network interfaces map
    gNetworkInterfaces[interfaceName] = config;

    // Apply configuration changes to the operating system
    updateRoutingTable(interfaceName, config.dnsServers);
    updateSecurityPolicies(interfaceName, config.securityPolicies);
}

