    g_memPool.size = size;
}

// Allocate memory from the memory pool
void* mempoolAlloc(size_t size) {
    void* ptr = NULL;
    if (g_memPool.size - g_memPool.head > size) {
        ptr = g_memPool.head;
        g_memPool.head += size;
        g_memPool.size -= size;
