import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;

public class IoTDataProcessor {
  private static final int MAX_CONCURRENT_PROCESSORS = 10;
  private static final int MIN_PROCESSING_THREADS = 2;
  private static final int MAX_PROCESSING_THREADS = 5;

  private ExecutorService executor;
  private List<IoTDevice> devices;
  private IoTDataStore dataStore;
  private IoTAnalytics analytics;

  public IoTDataProcessor(List<IoTDevice> devices, IoTDataStore dataStore, IoTAnalytics analytics) {
    this.devices = devices;
    this.dataStore = dataStore;
    this.analytics = analytics;

    executor = Executors.newFixedThreadPool(MAX_CONCURRENT_PROCESSORS);
  }

  public void processData() {
    List<IoTDevice> activeDevices = devices.stream().filter(device -> device.isConnected()).collect(Collectors.toList());
    List<IoTDeviceData> deviceData = activeDevices.stream().map(device -> device.getLatestData()).collect(Collectors.toList());

    executor.submit(() -> {
      try {
        dataStore.saveData(deviceData);
      } catch (IOException e) {
        logError("Error saving data to data store", e);
      }
    });

    executor.submit(() -> {
      try {
        analytics.processData(deviceData);
      } catch (IOException e) {
        logError("Error processing data for analytics", e);
      }
    });
  }

  private void logError(String message, Exception e) {
    // Log the error and notify a human operator if necessary
  }
}
