char* processString(const char* input) {
    if (input == NULL || strlen(input) > 1024) {
        // Handle invalid input
        return NULL;
    }

    char* output = malloc(strlen(input) + 1);
    if (output == NULL) {
        // Handle failed memory allocation
        return NULL;
    }

    strcpy(output, input);

    bool exceededLimit = false;
    if (strlen(input) > 1024) {
        exceededLimit = true;
        output[1023] = '\0';
    } else {
        output[strlen(input)] = '/';
    }

    // Log warning if string exceeds limit
    if (exceededLimit) {
        fprintf(stderr, "Warning: input string exceeds 1024 bytes\n");
    }

    return output;
}
