  }
}

// Function to derive a key from a password and salt using PBKDF2
void pbkdf2_derive_key(const char* passwd, const unsigned char* salt, int salt_len, unsigned char* key, int key_len) {
  if (PKCS5_PBKDF2_HMAC_SHA1(passwd, strlen(passwd), salt, salt_len, ITERATIONS, key_len, key) <= 0) {
    ERR_print_errors_fp(stderr);
    abort();
  }
}

// Function to encrypt data using AES-256-GCM
void aes_encrypt(const unsigned char* plaintext, int plaintext_len, const unsigned char* key, unsigned char* ciphertext) {
  if (EVP_EncryptInit_ex(ciphertext, EVP_aes_256_gcm(), NULL, key, NULL) <= 0) {
    ERR_print_errors_fp(stderr);
    abort();
  }
}

// Function to decrypt data using AES-256-GCM
void aes_decrypt(const unsigned char* ciphertext, int ciphertext_len, const unsigned char* key, unsigned char* plaintext) {
  if (EVP_DecryptInit_ex(ciphertext, EVP_aes_256_gcm(), NULL, key, NULL) <= 0) {
    ERR_print_errors_fp(stderr);
    abort();
