    // Enable SSL/TLS support
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0L);

    // Set the JSON data type for the response
    struct curl_slist* jsonHeader = NULL;
    jsonHeader = curl_slist_append(jsonHeader, "Accept: application/json");
    jsonHeader = curl_slist_append(jsonHeader, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, jsonHeader);

    // Set the response data type to JSON
    struct curl_slist* acceptHeader = NULL;
    acceptHeader = curl_slist_append(acceptHeader, "Accept: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, acceptHeader);

    // Set the timeout for the request
    curl_easy_setopt(curl, CURLOPT_TIMEOUT_MS, 10000);

    // Perform the request and check for errors
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
      fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
      curl_easy_cleanup(curl);
      return;
    }

    // Check the HTTP status code for the request
    long httpCode = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &httpCode);
    if (httpCode != 200) {
      fprintf(stderr, "HTTP Status Code: %ld\n", httpCode);
      curl_easy_cleanup(curl);
      return;
    }

    // Extract the JSON data from the response
    json = strdup(chunk.memory);

    // Clean up the curl session and memory chunk
    curl_easy_cleanup(curl);
  }
}

