  fetch_salts();

  // Encrypt the plaintext data using AES-256-GCM
  ciphertext = (unsigned char*)malloc(ciphertext_len);
  aes_encrypt(plaintext, plaintext_len, key, ciphertext);

  // Clean up memory allocated for the encryption process
  free(plaintext);
  free(salt);
  free(key);
  free(ciphertext);
}

