class DataModel {
 public:
  // Define a map of instruments to their respective data structures
  std::map<std::string, TransactionData> instrumentData;

  // Define a method for adding new transactions to the data structure
  void addTransaction(const TransactionData& transaction) {
    instrumentData[transaction.instrument].push_back(transaction);
  }

  // Define a method for retrieving transactions from the data structure
  std::vector<TransactionData> getTransactions(std::string instrument) {
    return instrumentData[instrument];
  }
};

// Define a real-time processing pipeline for transaction data
class ProcessingPipeline {
 public:
  // Define a constructor that initializes the processing pipeline with a given input source and output sink
  ProcessingPipeline(std::istream& in, std::ostream& out) : in_(in), out_(out) {}

  // Define a method for processing transactions in real-time
  void processTransactions() {
    while (true) {
      TransactionData transaction;
      in_ >> transaction.instrument >> transaction.price >> transaction.quantity;
      if (!in_.eof()) {
        addTransaction(transaction);
        out_ << "Processed transaction: " << transaction.instrument << ", price: " << transaction.price << ", quantity: " << transaction.quantity << std::endl;
      } else {
        break;
      }
    }
  }

  // Define a method for adding new transactions to the processing pipeline
  void addTransaction(const TransactionData& transaction) {
    out_ << "Received transaction: " << transaction.instrument << ", price: " << transaction.price << ", quantity: " << transaction.quantity << std::endl;
    transactions_.push_back(transaction);
  }

 private:
  // Define a vector of transactions for storing and processing real-time data
  std::vector<TransactionData> transactions_;

  // Define an input stream for reading new transactions from an external source
  std::istream& in_;

  // Define an output stream for writing processed transactions to an external sink
  std::ostream& out_;
