import java.util.concurrent.*;
import com.google.common.util.concurrent.*;

public class NotificationSystem {
    private static final int NUM_THREADS = 10; // number of threads for handling notifications
    private static final long RETRY_INTERVAL = 60000L; // retry interval in milliseconds
    private static final int MAX_RETRIES = 3; // maximum number of retries before failing a notification

    private ExecutorService executor; // thread pool for handling notifications
    private Map<String, Notification> notifications; // map of notifications by ID
    private List<NotificationListener> listeners; // list of notification listeners

    public NotificationSystem() {
        executor = new ThreadPoolExecutor(NUM_THREADS, NUM_THREADS, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<>());
        notifications = new ConcurrentHashMap<>();
        listeners = new CopyOnWriteArrayList<>();
    }

    public void addNotificationListener(NotificationListener listener) {
        listeners.add(listener);
    }

    public void removeNotificationListener(NotificationListener listener) {
        listeners.remove(listener);
    }

    public void sendNotification(String id, String message) {
        Notification notification = new Notification(id, message);
        notifications.put(id, notification);
        executor.execute(() -> handleNotification(notification));
    }

    private void handleNotification(Notification notification) {
        // handle the notification with retries and fallback strategies
        for (int i = 0; i < MAX_RETRIES; i++) {
            try {
                sendToAllListeners(notification);
                return;
            } catch (IOException e) {
                System.out.println("Notification failed: " + notification.getId());
                long retryInterval = RETRY_INTERVAL * Math.max(1, i + 1);
                try {
                    Thread.sleep(retryInterval);
                } catch (InterruptedException ex) {
                    // ignore and continue
                }
            }
        }
        System.out.println("Notification failed: " + notification.getId());
    }

    private void sendToAllListeners(Notification notification) throws IOException {
        for (NotificationListener listener : listeners) {
            listener.onNotification(notification);
        }
    }

    public static class Notification {
        private String id;
        private String message;

        public Notification(String id, String message) {
            this.id = id;
            this.message = message;
        }

        public String getId() {
            return id;
        }

        public void setId(String id) {
            this.id = id;
        }

        public String getMessage() {
            return message;
        }

        public void setMessage(String message) {
            this.message = message;
        }
    }

    public interface NotificationListener {
        void onNotification(Notification notification);
    }
}
```
