```
import os
from concurrent.futures import ThreadPoolExecutor
import time
from typing import List

class MessageBroker:
    def __init__(self):
        self.message_queue = []
        self.clients = {}
        self.executor = ThreadPoolExecutor(max_workers=2)

    def publish(self, message: str, client_id: int):
        if client_id in self.clients:
            self.message_queue.append((client_id, message))
            self.executor.submit(self._process_messages)
        else:
            print("Client with ID {} does not exist.".format(client_id))

    def subscribe(self, client_id: int):
        if client_id in self.clients:
            return "Client with ID {} already exists.".format(client_id)
        else:
            self.clients[client_id] = []
            print("Client with ID {} has been added.".format(client_id))

    def unsubscribe(self, client_id: int):
        if client_id in self.clients:
            del self.clients[client_id]
            print("Client with ID {} has been removed.".format(client_id))
        else:
            return "Client with ID {} does not exist.".format(client_id)

    def _process_messages(self):
        while len(self.message_queue) > 0:
            client_id, message = self.message_queue[0]
            if client_id in self.clients:
                self.clients[client_id].append(message)
                del self.message_queue[0]
            else:
                print("Client with ID {} does not exist.".format(client_id))

    def get_messages(self, client_id: int) -> List[str]:
        if client_id in self.clients:
            return self.clients[client_id]
        else:
            print("Client with ID {} does not exist.".format(client_id))
