#include <errno.h>
#include <pthread.h>
#include <stdbool.h>
#include "plugin_manager.h"

/* Plugin structure */
struct plugin {
    void* handle;
    char* name;
    char* version;
    char* config;
};

/* Plugin manager object */
static struct plugin_manager {
    /* List of loaded plugins */
    struct plugin** plugins;
    /* Number of plugins in the list */
    int num_plugins;
    /* Mutex for synchronizing access to the plugin list */
    pthread_mutex_t mutex;
} manager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

/* Load a plugin from disk and add it to the list of loaded plugins */
void load_plugin(const char* path) {
    struct plugin* plugin = NULL;

    /* Check if the plugin is already loaded */
    pthread_mutex_lock(&manager.mutex);
    for (int i = 0; i < manager.num_plugins; i++) {
        if (!strcmp(path, manager.plugins[i]->name)) {
            plugin = manager.plugins[i];
            break;
        }
    }
    pthread_mutex_unlock(&manager.mutex);

    /* If the plugin is not already loaded, load it and add it to the list */
    if (!plugin) {
        plugin = (struct plugin*)malloc(sizeof(struct plugin));
        plugin->handle = dlopen(path, RTLD_LAZY | RTLD_LOCAL);
        plugin->name = strdup(path);
        plugin->version = strdup("1.0");
        plugin->config = NULL;

        pthread_mutex_lock(&manager.mutex);
        manager.plugins = realloc(manager.plugins, sizeof(struct plugin*) * (manager.num_plugins + 1));
        manager.plugins[manager.num_plugins++] = plugin;
        pthread_mutex_unlock(&manager.mutex);
    }
}

/* Unload a plugin from memory and remove it from the list of loaded plugins */
void unload_plugin(const char* name) {
    struct plugin* plugin = NULL;

    /* Check if the plugin is already loaded */
    pthread_mutex_lock(&manager.mutex);
    for (int i = 0; i < manager.num_plugins; i++) {
        if (!strcmp(name, manager.plugins[i]->name)) {
            plugin = manager.plugins[i];
            break;
        }
    }
    pthread_mutex_unlock(&manager.mutex);

    /* If the plugin is loaded, unload it and remove it from the list */
    if (plugin) {
        dlclose(plugin->handle);

        pthread_mutex_lock(&manager.mutex);
        for (int i = 0; i < manager.num_plugins; i++) {
            if (plugin == manager.plugins[i]) {
                manager.plugins[i] = NULL;
                break;
            }
        }
        pthread_mutex_unlock(&manager.mutex);
    }
}

/* Load a plugin and return its handle */
void* load_plugin(const char* path) {
    void* handle = NULL;

    /* Check if the plugin is already loaded */
    pthread_mutex_lock(&manager.mutex);
    for (int i = 0; i < manager.num_plugins; i++) {
        if (!strcmp(path, manager.plugins[i]->name)) {
            handle = manager.plugins[i]->handle;
            break;
        }
    }
    pthread_mutex_unlock(&manager.mutex);

    /* If the plugin is not already loaded, load it and add it to the list */
    if (!handle) {
        handle = dlopen(path, RTLD_LAZY | RTLD_LOCAL);
        if (handle) {
            struct plugin* plugin = (struct plugin*)malloc(sizeof(struct plugin));
            plugin->handle = handle;
            plugin->name = strdup(path);
            plugin->version = strdup("1.0");
            plugin->config = NULL;

            pthread_mutex_lock(&manager.mutex);
            manager.plugins = realloc(manager.plugins, sizeof(struct plugin*) * (manager.num_plugins + 1));
            manager.plugins[manager.num_plugins++] = plugin;
            pthread_mutex_unlock(&manager.mutex);
        }
    }

    return handle;
}

/* Unload a plugin and release its memory */
void unload_plugin(void* handle) {
    struct plugin* plugin = NULL;

    /* Check if the plugin is already loaded */
    pthread_mutex_lock(&manager.mutex);
    for (int i = 0; i < manager.num_plugins; i++) {
        if (handle == manager.plugins[i]->handle) {
            plugin = manager.plugins[i];
            break;
        }
    }
    pthread_mutex_unlock(&manager.mutex);

    /* If the plugin is loaded, unload it and remove it from the list */
    if (plugin) {
        dlclose(handle);

        pthread_mutex_lock(&manager.mutex);
        for (int i = 0; i < manager.num_plugins; i++) {
            if (plugin == manager.plugins[i]) {
                free(plugin->name);
                free(plugin->version);
                free(plugin->config);
                free(manager.plugins[i]);
                manager.plugins[i] = NULL;
                break;
            }
        }
        pthread_mutex_unlock(&manager.mutex);
    }
}
