#include <openssl/x509.h>
#include <openssl/pkcs7.h>

// Symmetric Encryption (AES)
std::vector<unsigned char> encrypt(const std::string& message, const std::string& key) {
  unsigned char iv[AES_BLOCK_SIZE];
  AES_KEY enc_key;

  // Initialize AES encryption with the given key and initialization vector (iv)
  if(!AES_set_encrypt_key(reinterpret_cast<const unsigned char*>(key.c_str()), 128, &enc_key)) {
    std::cerr << "Failed to set encrypt key: " << ERR_error_string(ERR_get_error(), nullptr) << std::endl;
  }

  // Encrypt the given message with AES
  unsigned char* encrypted = static_cast<unsigned char*>(malloc(AES_BLOCK_SIZE + message.size()));
  memcpy(encrypted, iv, sizeof(iv));
  memcpy(&encrypted[sizeof(iv)], message.c_str(), message.size());
  AES_ctr128_encrypt(encrypted, encrypted, message.size() + sizeof(iv), &enc_key, iv, &num);

  // Return the encrypted message as a vector of unsigned chars
  std::vector<unsigned char> result(encrypted, encrypted + AES_BLOCK_SIZE + message.size());
  free(encrypted);
  return result;
}

// Asymmetric Encryption (RSA)
std::vector<unsigned char> encrypt(const std::string& message, const std::string& public_key) {
  RSA* rsa = PEM_read_RSAPublicKey(public_key.c_str(), nullptr, nullptr, nullptr);
  if(!rsa) {
    std::cerr << "Failed to read public key: " << ERR_error_string(ERR_get_error(), nullptr) << std::endl;
  }

  unsigned char* encrypted = static_cast<unsigned char*>(malloc(RSA_size(rsa)));
  int len = RSA_public_encrypt(message.size(), reinterpret_cast<const unsigned char*>(message.c_str()), encrypted, rsa, RSA_PKCS1_PADDING);
  if (len < 0) {
    std::cerr << "Failed to encrypt message: " << ERR_error_string(ERR_get_error(), nullptr) << std::endl;
  }

  // Return the encrypted message as a vector of unsigned chars
  std::vector<unsigned char> result(encrypted, encrypted + len);
  free(encrypted);
  return result;
}

// Symmetric Decryption (AES)
std::string decrypt(const std::vector<unsigned char>& message, const std::string& key) {
  unsigned char iv[AES_BLOCK_SIZE];
  AES_KEY enc_key;

  // Initialize AES encryption with the given key and initialization vector (iv)
  if(!AES_set_decrypt_key(reinterpret_cast<const unsigned char*>(key.c_str()), 128, &enc_key)) {
    std::cerr << "Failed to set decrypt key: " << ERR_error_string(ERR_get_error(), nullptr) << std::endl;
  }

  // Decrypt the given message with AES
  unsigned char* decrypted = static_cast<unsigned char*>(malloc(message.size() - sizeof(iv)));
  memcpy(decrypted, &message[sizeof(iv)], message.size() - sizeof(iv));
  AES_ctr128_encrypt(decrypted, decrypted, message.size() - sizeof(iv), &enc_key, iv, &num);

  // Return the decrypted message as a string
  std::string result = reinterpret_cast<char*>(decrypted);
  free(decrypted);
  return result;
}

// Asymmetric Decryption (RSA)
std::string decrypt(const std::vector<unsigned char>& message, const std::string& private_key) {
  RSA* rsa = PEM_read_RSAPrivateKey(private_key.c_str(), nullptr, nullptr, nullptr);
  if(!rsa) {
    std::cerr << "Failed to read private key: " << ERR_error_string(ERR_get_error(), nullptr) << std::endl;
  }

  unsigned char* decrypted = static_cast<unsigned char*>(malloc(RSA_size(rsa)));
  int len = RSA_private_decrypt(message.size(), reinterpret_cast<const unsigned char*>(message.c_str()), decrypted, rsa, RSA_PKCS1_PADDING);
  if (len < 0) {
    std::cerr << "Failed to decrypt message: " << ERR_error_string(ERR_get_error(), nullptr) << std::endl;
  }

  // Return the decrypted message as a string
  std::string result = reinterpret_cast<char*>(decrypted);
  free(decrypted);
  return result;
}
