import os
import sys
import time
import json
import threading
import logging
from typing import List, Dict, Set

class CommandLineTool:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.config_service = None
        self.file_paths = []
        self.worker_threads = []
        self.file_count = 0
        self.line_count = 0
        self.processing_start_time = time.time()
        self.config_lock = threading.Lock()
        self.line_count_lock = threading.Lock()

    def configure(self, config_service=None):
        self.logger.info("Configuring command-line tool")
        if config_service:
            self.config_service = config_service
            self.file_paths = self.retrieve_file_paths()
            self.logger.info(f"Retrieved {len(self.file_paths)} file paths from configuration service")
        else:
            self.logger.warning("No configuration service provided, falling back to command-line arguments")
            self.file_paths = sys.argv[1:]

    def retrieve_file_paths(self):
        try:
            response = self.config_service.get_file_paths()
            if response and "data" in response:
                return response["data"]
        except Exception as e:
            self.logger.error("Failed to retrieve file paths from configuration service", exc_info=True)
        return sys.argv[1:]

    def start(self):
        if not self.file_paths:
            self.logger.warning("No files specified, exiting")
            return
        self.configure()
        for file in self.file_paths:
            thread = threading.Thread(target=self.process_file, args=(file,))
            self.worker_threads.append(thread)
            thread.start()
        for thread in self.worker_threads:
            thread.join()

    def process_file(self, file):
        try:
            with open(file, "r") as f:
                for line in f:
                    self.process_line(line)
        except Exception as e:
            self.logger.error(f"Error processing file {file}", exc_info=True)

    def process_line(self, line):
        try:
            with self.config_lock:
                config = json.loads(line)
            if not config or "data" not in config:
                self.logger.warning("Skipping empty configuration")
                return
            data = config["data"]
            if not isinstance(data, Dict):
                self.logger.error("Invalid data type for configuration")
                return
            self.process_data(data)
        except Exception as e:
            self.logger.error(f"Error processing line {line}", exc_info=True)

    def process_data(self, data):
        try:
            with self.line_count_lock:
                self.file_count += 1
                self.line_count += len(data)
            self.logger.debug(f"Processed {len(data)} lines from file {self.file_count}")
        except Exception as e:
            self.logger.error(f"Error processing data", exc_info=True)

    def log_state(self):
        try:
            with self.config_lock:
                config = json.dumps(self.config_service.get_current_config())
            if not config or "data" not in config:
                self.logger.warning("Skipping empty configuration")
                return
            data = config["data"]
            if not isinstance(data, Dict):
                self.logger.error("Invalid data type for configuration")
                return
            self.process_data(data)
        except Exception as e:
            self.logger.error(f"Error logging state", exc_info=True)

    def shutdown(self):
        self.logger.warning("Shutting down command-line tool")
        for thread in self.worker_threads:
            thread.join()
        self.logger.info(f"Processed {self.file_count} files and {self.line_count} lines")
```']

