    // DNS-based service discovery with fallback mechanisms
    int ret = dns_sd_query(&service->name, &service->ip, &service->port);
    if (ret == -1) {
        free(service);
        return NULL;
    }

    // Round-robin or weighted load-balancing strategy for multiple service instances
