public class PokemonService {
  private final String POKEAPI_URL = "https://pokeapi.co/api/v2";
  private final int MAX_CONCURRENT_REQUESTS = 10;
  private final Map<String, Pokemon> cache = new HashMap<>();

  public Response getPokemon(String name) {
    // Check if the Pokemon is in the cache
    if (cache.containsKey(name)) {
      return cache.get(name);
    }

    // Make an API request to fetch the Pokemon data
    JSONObject pokemonData = makeAPIRequest(POKEAPI_URL + "/pokemon/" + name);

    // Handle any errors that may have occurred during the request
    if (pokemonData == null) {
      return new Response("Error fetching data for " + name, 500);
    }

    // Extract the relevant information from the API response
    String type = pokemonData.getString("type");
    int strength = pokemonData.getInt("strength");
    int weakness = pokemonData.getInt("weakness");
    int resistance = pokemonData.getInt("resistance");

    // Create a new Pokemon object with the extracted data
    Pokemon pokemon = new Pokemon(name, type, strength, weakness, resistance);

    // Add the Pokemon to the cache for future requests
    cache.put(name, pokemon);

    return new Response(pokemon.toJSON(), 200);
  }

  private JSONObject makeAPIRequest(String url) {
    // Implement rate limiting and circuit breakers to prevent API overload
    if (rateLimitExceeded()) {
      try {
        Thread.sleep(500);
      } catch (InterruptedException e) {
        e.printStackTrace();
      }
    }

    // Make the API request and handle any errors that may have occurred
    JSONObject response = null;
    try {
      URL pokemonURL = new URL(url);
      HttpURLConnection connection = (HttpURLConnection) pokemonURL.openConnection();
      connection.setRequestMethod("GET");
      connection.connect();

      // Check if the API request was successful
      int status = connection.getResponseCode();
      if (status == 200) {
        response = new JSONObject(connection.getInputStream());
      } else {
        System.out.println("Error fetching data from " + url);
      }
    } catch (MalformedURLException e) {
      e.printStackTrace();
    } catch (IOException e) {
      e.printStackTrace();
    }

    return response;
  }

  private boolean rateLimitExceeded() {
    // Implement a simple rate limiter to prevent API overload
    long currentTime = System.currentTimeMillis();
    if (cache.size() >= MAX_CONCURRENT_REQUESTS || lastRequestTime + RATE_LIMIT_PERIOD < currentTime) {
      return true;
    }
    return false;
  }
}

