class CacheManager {
 public:
  // Constructor
  CacheManager(const std::vector<std::string>& dataCenters, int numShards) : dataCenters_(dataCenters), numShards_(numShards) {}

  // Function to set the value of a cache entry
  void SetValue(const std::string& key, const std::string& value) {
    // Lock the mutex for this key
    std::lock_guard<std::mutex> lock(mutexes_[key]);

    // Check if the cache entry already exists
    auto it = cache_.find(key);
    if (it != cache_.end()) {
      // Update the value of the existing cache entry
      it->second.value = value;
      it->second.isDirty = true;
    } else {
      // Add a new cache entry
      cache_.emplace(key, CacheEntry{key, value, true});
    }
  }

