import json
from collections import deque
import threading
import time

class ConfigurationManager:
    def __init__(self, config_data):
        self.config_data = config_data
        self.thread_pool = []
        self.api_queue = deque()
        self.update_lock = threading.Lock()

    def start(self):
        self.thread_pool.append(threading.Thread(target=self._run))
        self.thread_pool[0].start()

    def _run(self):
        while True:
            with self.update_lock:
                if len(self.api_queue) > 0:
                    api, data = self.api_queue.popleft()
                    try:
                        response = self._send_request(api, data)
                        self._handle_response(api, response)
                    except Exception as e:
                        self._handle_error(api, e)
