import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.function.Consumer;
import javax.sql.DataSource;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.common.TopicPartition;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.task.AsyncTaskExecutor;
import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

@Configuration
public class KafkaConfiguration {
    @Autowired
    private DataSource dataSource;

    @Bean
    public AsyncTaskExecutor asyncTaskExecutor() {
        ThreadPoolTaskExecutor taskExecutor = new ThreadPoolTaskExecutor();
        taskExecutor.setCorePoolSize(10);
        taskExecutor.setMaxPoolSize(20);
        taskExecutor.setQueueCapacity(500);
        return taskExecutor;
    }

    @Bean
    public ConcurrentKafkaListenerContainerFactory<String, String> kafkaListenerContainerFactory() {
        ConcurrentKafkaListenerContainerFactory<String, String> factory = new ConcurrentKafkaListenerContainerFactory<>();
        factory.setConsumerFactory(consumerFactory());
        return factory;
    }

    @Bean
    public KafkaConsumer consumerFactory() {
        Map<String, Object> props = new HashMap<>();
        props.put("bootstrap.servers", "localhost:9092");
        props.put("group.id", "my-consumer");
        props.put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        props.put("value.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        return new KafkaConsumer(props);
    }
}

@Component
public class KafkaMessageHandler {
    @Autowired
    private DataSource dataSource;

    @Transactional
    public void handleKafkaMessage(String message) {
        // Process the message and save to database.
        // ...

        // Save to MySQL database using JDBC.
        try (Connection connection = dataSource.getConnection()) {
            PreparedStatement statement = connection.prepareStatement("INSERT INTO mytable (column1, column2) VALUES (?, ?)");
            statement.setString(1, message);
            statement.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException("Error saving to MySQL database", e);
        }

        // Save to PostgreSQL database using JDBC.
        try (Connection connection = dataSource.getConnection()) {
            PreparedStatement statement = connection.prepareStatement("INSERT INTO mytable (column1, column2) VALUES (?, ?)");
            statement.setString(1, message);
            statement.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException("Error saving to PostgreSQL database", e);
        }

        // Save to MongoDB using MongoTemplate.
        MongoTemplate mongoTemplate = new MongoTemplate(new SimpleMongoClientDatabaseFactory());
        Document document = new Document();
        document.put("column1", message);
        document.put("column2", "value");
        mongoTemplate.insert(document, "mycollection");
    }
}

@Component
public class KafkaMessageProducer {
    @Autowired
    private AsyncTaskExecutor asyncTaskExecutor;

    public void produceKafkaMessage(String message) {
        asyncTaskExecutor.submit(() -> {
            List<PartitionInfo> partitionInfos = new ArrayList<>();
            partitionInfos.add(new PartitionInfo("my-topic", 0, null, null, null));

            KafkaProducer producer = new KafkaProducer<String, String>(partitionInfos);
            producer.send(message);
        });
    }
}
```
This code implements a Kafka message handler that processes messages from a Kafka topic and saves them to a MySQL database using JDBC. The `KafkaMessageHandler` class is annotated with `@Component`, which indicates that it should be registered as a Spring bean in the application context. The `handleKafkaMessage` method is marked with `@Transactional`, which ensures that all database operations within this method are executed atomically and rolled back if any errors occur.

The `produceKafkaMessage` method is responsible for sending messages to the Kafka topic. It uses an `AsyncTaskExecutor` to execute the message production asynchronously, which allows the application to continue processing other tasks while the message is being produced. The `KafkaProducer` class is used to send the message to the Kafka topic.

The `KafkaConfiguration` class configures the Spring application context for Kafka messaging. It sets up a Kafka consumer factory that can create instances of the `KafkaConsumer` class, which is used to consume messages from the Kafka topic. The `ConcurrentKafkaListenerContainerFactory` is configured to use the consumer factory and process messages concurrently using multiple threads.

The `MySQLDatabaseConfiguration` class configures the Spring application context for MySQL database access. It sets up a data source that can be used to obtain connections to the MySQL database, which is used by the `KafkaMessageHandler` class to save messages to the database.

The `PostgreSQLDatabaseConfiguration` class configures the Spring application context for PostgreSQL database access. It sets up a data source that can be used to obtain connections to the PostgreSQL database, which is used by the `KafkaMessageHandler` class to save messages to the database.

The `MongoTemplate` class is used to save documents to the MongoDB collection. The `MongoTemplate` instance is created with a `SimpleMongoClientDatabaseFactory`, which creates instances of `MongoClient` that are used to connect to the MongoDB cluster.

This code uses the `KafkaMessageProducer` and `KafkaMessageHandler` classes to send messages from a Kafka topic to a MySQL database, PostgreSQL database, and MongoDB collection. The producer sends messages asynchronously using an `AsyncTaskExecutor`, which allows the application to continue processing other tasks while the message is being produced. The handler processes the messages concurrently using multiple threads, ensuring that all messages are processed even if some take longer than others.']

