      trigger_error($e->getMessage(), E_USER_WARNING);
      return false;
    }
  }

  // handle update user stats request
  function updateUserStats($userId, $stats) {
    try {
      $this->conn->update("UPDATE statistics SET total_views=?, total_clicks=? WHERE id=$userId", $stats);

      return true;
    } catch (Exception $e) {
      trigger_error($e->getMessage(), E_USER_WARNING);
      return false;
    }
  }

  // handle update trend data request
  function updateTrendData($trendId, $trendData) {
    try {
      $this->conn->update("UPDATE trends SET name=?, description=? WHERE id=$trendId", $trendData);

      return true;
    } catch (Exception $e) {
      trigger_error($e->getMessage(), E_USER_WARNING);
      return false;
    }
  }
}
```
