}

// Function to parse a line in a file and replace the last numeric field with its average
void process_line(const string& line, const vector<string>& fields) {
    bool is_numeric = true;
    try {
        for (int i = 0; i < fields.size(); ++i) {
            if (!is_numeric) {
                break;
            }
            double num = stod(fields[i]);
            is_numeric &= !isnan(num);
        }
    } catch (exception& e) {
        // Handle invalid numeric fields as non-numeric
        is_numeric = false;
    }

    if (!is_numeric) {
        return;
    }

    double average = 0.0;
    for (int i = 1; i < fields.size() - 1; ++i) {
        try {
            double num = stod(fields[i]);
            if (!isnan(num)) {
                average += num;
            } else {
                is_numeric = false;
                break;
            }
        } catch (exception& e) {
            // Handle invalid numeric fields as non-numeric
            is_numeric = false;
            break;
        }
    }

    if (is_numeric && average > 0.0) {
        average /= fields.size() - 1;
