Here is a possible implementation of the modular C library for processing and extracting metadata from diverse image formats:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <assert.h>

#define MAX_IMAGE_FORMATS 16
#define MAX_SAMPLES_PER_PIXEL 4
#define MAX_BITS_PER_SAMPLE 16
#define MIN_LATENCY_MS 50
#define MAX_MEMORY_USAGE_MB 512

typedef struct {
    char* format;
    uint8_t bitsPerSample;
    uint8_t samplesPerPixel;
} imageFormat_t;

// Define the supported image formats
imageFormat_t supportedFormats[MAX_IMAGE_FORMATS] = {
    {"TIFF", MAX_BITS_PER_SAMPLE, MAX_SAMPLES_PER_PIXEL},
    {"JPEG", MAX_BITS_PER_SAMPLE, MAX_SAMPLES_PER_PIXEL},
    {"PNG", MAX_BITS_PER_SAMPLE, MAX_SAMPLES_PER_PIXEL},
};

// Define the buffer size for incoming data
#define BUFFER_SIZE 1024 * 1024

// Define the retry policy for failed operations
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 500

// Define the error codes for the library
#define ERROR_SUCCESS 0
#define ERROR_INVALID_FORMAT -1
#define ERROR_UNSUPPORTED_FORMAT -2
#define ERROR_READ_FAILED -3
#define ERROR_WRITE_FAILED -4
#define ERROR_MEMORY_ALLOCATION_FAILED -5

// Define the logging levels for the library
#define LOGGING_LEVEL_NONE 0
#define LOGGING_LEVEL_ERROR 1
#define LOGGING_LEVEL_WARN 2
#define LOGGING_LEVEL_INFO 3
#define LOGGING_LEVEL_DEBUG 4

// Define the cache eviction policy for recently accessed metadata
#define CACHE_EVICTION_POLICY_LRU 0
#define CACHE_EVICTION_POLICY_LFU 1
#define CACHE_EVICTION_POLICY_FIFO 2

// Define the thread-safety mechanisms for accessing metadata in a multi-threaded environment
#define THREAD_SAFETY_MECHANISM_LOCK 0
#define THREAD_SAFETY_MECHANISM_ATOMIC 1

// Define the configuration parameters for the library
struct config {
    // Logging level
    uint8_t loggingLevel;

    // Buffer size for incoming data
    uint32_t bufferSize;

    // Retry policy for failed operations
    uint8_t retryCount;
    uint32_t retryDelayMs;

    // Cache eviction policy for recently accessed metadata
    uint8_t cacheEvictionPolicy;

    // Thread-safety mechanism for accessing metadata in a multi-threaded environment
    uint8_t threadSafetyMechanism;
};

// Initialize the library with the given configuration parameters
void init(struct config* config) {
    // Set the logging level
    logLevel = config->loggingLevel;

    // Set the buffer size for incoming data
    bufferSize = config->bufferSize;

    // Set the retry policy for failed operations
    retryCount = config->retryCount;
    retryDelayMs = config->retryDelayMs;

    // Set the cache eviction policy for recently accessed metadata
    cacheEvictionPolicy = config->cacheEvictionPolicy;

    // Set the thread-safety mechanism for accessing metadata in a multi-threaded environment
    threadSafetyMechanism = config->threadSafetyMechanism;
}

// Process and extract metadata from an image file
int processImage(const char* path, const char* format) {
    // Check if the image format is supported
    bool isFormatSupported = false;
    for (uint8_t i = 0; i < MAX_IMAGE_FORMATS; i++) {
        if (!strcmp(format, supportedFormats[i].format)) {
            isFormatSupported = true;
            break;
        }
    }

    // Return an error code if the image format is not supported
    if (!isFormatSupported) {
        return ERROR_UNSUPPORTED_FORMAT;
    }

    // Open the image file and read its contents
    FILE* file = fopen(path, "rb");
    if (file == NULL) {
        return ERROR_READ_FAILED;
    }

    // Allocate memory for the image data
    uint32_t width;
    uint32_t height;
    uint8_t* imageData = malloc(bufferSize);
    if (imageData == NULL) {
        return ERROR_MEMORY_ALLOCATION_FAILED;
    }

    // Read the image data from the file
    size_t bytesRead = fread(imageData, 1, bufferSize, file);
    if (bytesRead != bufferSize) {
        return ERROR_READ_FAILED;
    }

    // Close the image file
    fclose(file);

    // Extract metadata from the image data
    uint32_t* widthPtr = &width;
    uint32_t* heightPtr = &height;
    int bytesPerPixel = supportedFormats[format].bitsPerSample / 8 * supportedFormats[format].samplesPerPixel;
    for (uint32_t i = 0; i < bufferSize; i += bytesPerPixel) {
        // Read the width and height of the image from the metadata
        if (!isFormatSupported) {
            return ERROR_UNSUPPORTED_FORMAT;
        }

        // Extract metadata from the image data
        uint32_t* imageMetadata = (uint32_t*)imageData;
        *widthPtr = imageMetadata->width;
        *heightPtr = imageMetadata->height;
    }

    return ERROR_NONE;
}

// Write metadata to an image file
int writeImage(const char* path, const char* format) {
    // Check if the image format is supported
    bool isFormatSupported = false;
    for (uint8_t i = 0; i < MAX_IMAGE_FORMATS; i++) {
        if (!strcmp(format, supportedFormats[i].format)) {
            isFormatSupported = true;
            break;
        }
    }

    // Return an error code if the image format is not supported
    if (!isFormatSupported) {
        return ERROR_UNSUPPORTED_FORMAT;
    }

    // Open the image file and read its contents
    FILE* file = fopen(path, "rb");
    if (file == NULL) {
        return ERROR_READ_FAILED;
    }

    // Allocate memory for the image data
    uint32_t width;
    uint32_t height;
    uint8_t* imageData = malloc(bufferSize);
    if (imageData == NULL) {
        return ERROR_MEMORY_ALLOCATION_FAILED;
    }

    // Read the image data from the file
    size_t bytesRead = fread(imageData, 1, bufferSize, file);
    if (bytesRead != bufferSize) {
        return ERROR_READ_FAILED;
    }

    // Close the image file
    fclose(file);

    // Extract metadata from the image data
    uint32_t* widthPtr = &width;
    uint32_t* heightPtr = &height;
    int bytesPerPixel = supportedFormats[format].bitsPerSample / 8 * supportedFormats[format].samplesPerPixel;
    for (uint32_t i = 0; i < bufferSize; i += bytesPerPixel) {
        // Read the width and height of the image from the metadata
        if (!isFormatSupported) {
            return ERROR_UNSUPPORTED_FORMAT;
        }

        // Extract metadata from the image data
        uint32_t* imageMetadata = (uint32_t*)imageData;
        *widthPtr = imageMetadata->width;
        *heightPtr = imageMetadata->height;
    }

    return ERROR_NONE;
}
