Here's an example of how you can implement the requirements for the encryption library using Java:
```
import java.security.SecureRandom;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;

public class EncryptionLibrary {
    private static final String AES_ALGORITHM = "AES";
    private static final String CAMELLIA_ALGORITHM = "Camellia";
    private static final String MD5_ALGORITHM = "MD5";
    private static final String SHA1_ALGORITHM = "SHA-1";
    private static final String SHA256_ALGORITHM = "SHA-256";
    private static final String SHA512_ALGORITHM = "SHA-512";
    private static final String ECDSA_ALGORITHM = "ECDSA";

    private static final int AES_KEY_LENGTH = 128;
    private static final int CAMELLIA_KEY_LENGTH = 192;
    private static final int ECDSA_CURVE = P_256;

    private ExecutorService executorService;
    private SecureRandom secureRandom;

    public EncryptionLibrary() {
        this.executorService = Executors.newFixedThreadPool(10);
        this.secureRandom = new SecureRandom();
    }

    public void encrypt(byte[] plaintext, String algorithm) throws Exception {
        Cipher cipher = getCipherInstance(algorithm);
        byte[] iv = secureRandom.generateSeed(cipher.getBlockSize());
        IvParameterSpec ivParams = new IvParameterSpec(iv);

        SecretKeySpec keySpec = getSecretKeySpec(algorithm, AES_KEY_LENGTH);

        cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivParams);

        byte[] ciphertext = cipher.doFinal(plaintext);

        System.out.println("Encrypted text: " + toHexString(ciphertext));
    }

    public void decrypt(byte[] ciphertext, String algorithm) throws Exception {
        Cipher cipher = getCipherInstance(algorithm);
        byte[] iv = secureRandom.generateSeed(cipher.getBlockSize());
        IvParameterSpec ivParams = new IvParameterSpec(iv);

        SecretKeySpec keySpec = getSecretKeySpec(algorithm, AES_KEY_LENGTH);

        cipher.init(Cipher.DECRYPT_MODE, keySpec, ivParams);

        byte[] plaintext = cipher.doFinal(ciphertext);

        System.out.println("Decrypted text: " + new String(plaintext));
    }

    private Cipher getCipherInstance(String algorithm) throws Exception {
        switch (algorithm) {
            case AES_ALGORITHM:
                return Cipher.getInstance("AES/CTR/NoPadding");
            case CAMELLIA_ALGORITHM:
                return Cipher.getInstance("Camellia/ECB/NoPadding");
            case MD5_ALGORITHM:
                return Cipher.getInstance("MD5");
            case SHA1_ALGORITHM:
                return Cipher.getInstance("SHA-1");
            case SHA256_ALGORITHM:
                return Cipher.getInstance("SHA-256");
            case SHA512_ALGORITHM:
                return Cipher.getInstance("SHA-512");
            case ECDSA_ALGORITHM:
                return Cipher.getInstance("ECDSA");
            default:
                throw new Exception("Unsupported algorithm: " + algorithm);
        }
    }

    private SecretKeySpec getSecretKeySpec(String algorithm, int keyLength) throws Exception {
        switch (algorithm) {
            case AES_ALGORITHM:
            case CAMELLIA_ALGORITHM:
                return new SecretKeySpec(secureRandom.generateSeed(keyLength), "AES");
            case ECDSA_ALGORITHM:
                return new SecretKeySpec(secureRandom.generateSeed(128), "ECDSA");
            default:
                throw new Exception("Unsupported algorithm: " + algorithm);
        }
    }

    private String toHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bytes.length; i++) {
            sb.append(String.format("%02x", bytes[i]));
        }
        return sb.toString();
    }
}
