int encryptFileCBC_PKCS7(const char *filename, const unsigned char *key) {
    FILE *fp; // File pointer for reading the input file
    int size; // Size of the input file in bytes
    unsigned char buffer[KEY_SIZE]; // Buffer for reading from the file
    AES_KEY aesKey; // AES key structure
    EVP_CIPHER_CTX *ctx; // Cipher context for encryption
    int encryptedSize; // Size of the encrypted data in bytes
    unsigned char iv[IV_SIZE]; // Initialization vector (IV)
    unsigned char *encryptedData; // Encrypted data buffer

    // Open the input file for reading
    fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error opening file: %s\n", filename);
        return -1;
    }

    // Get the size of the input file in bytes
    fseek(fp, 0, SEEK_END);
    size = ftell(fp);
    rewind(fp);

    // Allocate a buffer for reading from the file
    encryptedData = malloc(size + AES_BLOCK_SIZE);
    if (encryptedData == NULL) {
        printf("Error allocating memory for encrypted data\n");
        fclose(fp);
        return -1;
    }

    // Initialize the AES key and encryption context
    if (AES_set_encrypt_key(key, KEY_SIZE * 8, &aesKey) != 1) {
        printf("Error setting AES encryption key: %s\n", ERR_error_string(ERR_get_error(), NULL));
        free(encryptedData);
        fclose(fp);
        return -1;
    }
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error creating encryption context\n");
        AES_clear_key(&aesKey);
        free(encryptedData);
        fclose(fp);
        return -1;
    }

    // Generate a random IV and write it to the beginning of the output file
    if (!RAND_bytes(iv, sizeof(iv))) {
        printf("Error generating initialization vector: %s\n", ERR_error_string(ERR_get_error(), NULL));
        EVP_CIPHER_CTX_free(ctx);
        AES_clear_key(&aesKey);
        free(encryptedData);
        fclose(fp);
        return -1;
    }
    if (fwrite(iv, sizeof(iv), 1, stdout) != 1) {
        printf("Error writing initialization vector to file: %s\n", ERR_error_string(ERR_get_error(), NULL));
        EVP_CIPHER_CTX_free(ctx);
        AES_clear_key(&aesKey);
        free(encryptedData);
        fclose(fp);
        return -1;
    }

    // Encrypt the input file and store the encrypted data in the buffer
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        printf("Error initializing AES encryption: %s\n", ERR_error_string(ERR_get_error(), NULL));
        EVP_CIPHER_CTX_free(ctx);
        AES_clear_key(&aesKey);
        free(encryptedData);
        fclose(fp);
        return -1;
    }
    if (!EVP_EncryptUpdate(ctx, encryptedData, &size, buffer, size)) {
        printf("Error encrypting data: %s\n", ERR_error_string(ERR_get_error(), NULL));
        EVP_CIPHER_CTX_free(ctx);
        AES_clear_key(&aesKey);
        free(encryptedData);
        fclose(fp);
        return -1;
    }
    if (!EVP_EncryptFinal_ex(ctx, encryptedData + size, &size)) {
        printf("Error finalizing AES encryption: %s\n", ERR_error_string(ERR_get_error(), NULL));
        EVP_CIPHER_CTX_free(ctx);
        AES_clear_key(&aesKey);
        free(encryptedData);
        fclose(fp);
        return -1;
    }
    encryptedSize = size + IV_SIZE;

    // Close the input file and write the encrypted data to the output file
    fclose(fp);
    if (fwrite(encryptedData, sizeof(unsigned char), encryptedSize, stdout) != encryptedSize) {
        printf("Error writing encrypted data to file: %s\n", ERR_error_string(ERR_get_error(), NULL));
        EVP_CIPHER_CTX_free(ctx);
        AES_clear_key(&aesKey);
        free(encryptedData);
        return -1;
    }

    // Free resources and return success
    EVP_CIPHER_CTX_free(ctx);
    AES_clear_key(&aesKey);
    free(encryptedData);
    return 0;
}

// Function to decrypt a file using the AES-256 algorithm with CBC mode and PKCS#7 padding
int decryptFileCBC_PKCS7(const char *filename, const unsigned char *key) {
    FILE *fp; // File pointer for reading the input file
    int size; // Size of the input file in bytes
    unsigned char buffer[KEY_SIZE]; // Buffer for reading from the file
    AES_KEY aesKey; // AES key structure
    EVP_CIPHER_CTX *ctx; // Cipher context for decryption
    int decryptedSize; // Size of the decrypted data in bytes
    unsigned char iv[IV_SIZE]; // Initialization vector (IV)
    unsigned char *decryptedData; // Decrypted data buffer

