    if (fp == NULL) {
        printf("Error opening file: %s\n", filename);
        return -1;
    }

    // Get the size of the input file in bytes
    fseek(fp, 0, SEEK_END);
    size = ftell(fp);
    rewind(fp);

    // Allocate a buffer for reading from the file
    decryptedData = malloc(size + AES_BLOCK_SIZE);
    if (decryptedData == NULL) {
        printf("Error allocating memory for encrypted data\n");
        fclose(fp);
        return -1;
    }

    // Read the initialization vector from the input file
    if (fread(iv, sizeof(unsigned char), IV_SIZE, fp) != IV_SIZE) {
        printf("Error reading initialization vector from file: %s\n", ERR_error_string(ERR_get_error(), NULL));
        free(decryptedData);
        fclose(fp);
        return -1;
    }

    // Decrypt the input file and store the decrypted data in the buffer
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        printf("Error initializing AES decryption: %s\n", ERR_error_string(ERR_get_error(), NULL));
        free(decryptedData);
        fclose(fp);
        return -1;
    }
    if (!EVP_DecryptUpdate(ctx, decryptedData, &size, buffer, size)) {
        printf("Error decrypting data: %s\n", ERR_error_string(ERR_get_error(), NULL));
        free(decryptedData);
        fclose(fp);
        return -1;
    }
    if (!EVP_DecryptFinal_ex(ctx, decryptedData + size, &size)) {
        printf("Error finalizing AES decryption: %s\n", ERR_error_string(ERR_get_error(), NULL));
        free(decryptedData);
        fclose(fp);
        return -1;
    }
    decryptedSize = size + IV_SIZE;

    // Close the input file and write the decrypted data to the output file
    fclose(fp);
    if (fwrite(decryptedData, sizeof(unsigned char), decryptedSize, stdout) != decryptedSize) {
        printf("Error writing decrypted data to file: %s\n", ERR_error_string(ERR_get_error(), NULL));
        free(decryptedData);
        return -1;
    }

    // Free resources and return success
    free(decryptedData);
