  std::vector<DataTransformationConfig> transforms;                            // Configurations of data transformations
  std::vector<OutputDestinationConfig> destinations;                           // Configurations of output destinations
  std::mutex sourcesMutex, transformsMutex, destinationsMutex;                // Mutexes for accessing the instances of data sources and output destinations
  std::condition_variable dataCondition;                                       // Condition variable to signal when new data is available
