    transforms = config.transforms;
    destinations = config.destinations;
    sourcesMutex = std::mutex();
    transformsMutex = std::mutex();
    destinationsMutex = std::mutex();
    dataCondition = std::condition_variable();
    processingData = false;
    errorMessage = "";
  }

  // Method to start the processing of data
  void startProcessing() {
    if (processingThread.joinable()) {
      return;
    }

    // Create a thread for processing the data in parallel
    processingThread = std::thread([this]() {
      while (true) {
        // Lock the mutex to access the instance variables
        std::unique_lock<std::mutex> lck(sourcesMutex);

        // Wait for new data to be available
