    public class EncryptionHelper
    {
        private readonly IConfiguration _configuration;
        private readonly string _key;
        private readonly string _iv;

        public EncryptionHelper(IConfiguration configuration)
        {
            _configuration = configuration;
            _key = _configuration["Key"];
            _iv = _configuration["IV"];
        }

        public string Encrypt(string plainText)
        {
            using var encryptor = Aes.Create();
            encryptor.KeySize = 256;
            encryptor.BlockSize = 128;
            encryptor.Mode = CipherMode.CBC;
            encryptor.Padding = PaddingMode.PKCS7;
            encryptor.Key = Encoding.UTF8.GetBytes(_key);
            encryptor.IV = Encoding.UTF8.GetBytes(_iv);

            var cipherText = new byte[encryptor.OutputBlockSize];
            using (var msEncrypt = new MemoryStream(cipherText))
            {
                using (var csEncrypt = new CryptoStream(msEncrypt, encryptor.CreateEncryptor(), CryptoStreamMode.Write))
                {
                    var plainBytes = Encoding.UTF8.GetBytes(plainText);
                    csEncrypt.Write(plainBytes, 0, plainBytes.Length);
                }
            }

            return Convert.ToBase64String(cipherText);
        }

        public string Decrypt(string cipherText)
        {
            using var encryptor = Aes.Create();
            encryptor.KeySize = 256;
            encryptor.BlockSize = 128;
            encryptor.Mode = CipherMode.CBC;
            encryptor.Padding = PaddingMode.PKCS7;
            encryptor.Key = Encoding.UTF8.GetBytes(_key);
            encryptor.IV = Encoding.UTF8.GetBytes(_iv);

            var plainText = new byte[encryptor.OutputBlockSize];
            using (var msDecrypt = new MemoryStream(cipherText))
            {
                using (var csDecrypt = new CryptoStream(msDecrypt, encryptor.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    var cipherBytes = new byte[encryptor.OutputBlockSize];
                    csDecrypt.Read(cipherBytes, 0, cipherBytes.Length);
                    plainText = Encoding.UTF8.GetString(cipherBytes);
                }
            }

            return plainText;
        }
    }
}
