import logging
from collections import defaultdict

class LogAggregator:
    def __init__(self):
        self.log_format_map = defaultdict(list)
        self.logs = []

    def collectLogs(self, logs):
        for log in logs:
            if not isinstance(log, dict):
                try:
                    log = json.loads(log)
                except ValueError as e:
                    logging.warning("Could not parse log message: {}".format(e))
                    continue
            self.logs.append(log)
        return self.aggregateLogs()

    def aggregateLogs(self):
        aggregated_data = defaultdict(list)
        for log in self.logs:
            if log['type'] not in self.log_format_map:
                continue
            for field, value in log[self.log_format_map[log['type']]].items():
                aggregated_data[field].append(value)
        return aggregated_data
```
