#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/evp.h>

#define PBKDF2_ITERATIONS 2048
#define SHA256_HASH_SIZE 32
#define IV_SIZE 96
#define KEY_SIZE 32
#define MAX_IV_GENERATION_ATTEMPTS 10

struct EncryptionContext {
    AES_KEY aesKey;
    unsigned char iv[IV_SIZE];
};

void initEncryptionContext(struct EncryptionContext *context) {
    context->aesKey = AES_KEY_INITIALIZER;
}

int generateKeyDerivationParameters(const unsigned char *password, size_t passwordLen, const unsigned char *salt, size_t saltLen, const unsigned char *pepper, size_t pepperLen, struct EncryptionContext *context) {
    // PBKDF2 key derivation function
    AES_KEY *key = &context->aesKey;

    if (password == NULL || passwordLen == 0) {
        return -1;
    }

    if (salt == NULL || saltLen == 0) {
        return -2;
    }

    if (pepper == NULL && pepperLen != 0) {
        return -3;
    }

    unsigned char *derivedKey = malloc(SHA256_HASH_SIZE);
    memset(derivedKey, 0, SHA256_HASH_SIZE);

    for (int i = 0; i < MAX_IV_GENERATION_ATTEMPTS; i++) {
        // Perform PBKDF2 with SHA-256 PRF and at least 2048 iterations to ensure security
        int err = PKCS5_PBKDF2_HMAC(password, passwordLen, salt, saltLen, pepper, pepperLen, PBKDF2_ITERATIONS, EVP_sha256(), SHA256_HASH_SIZE, derivedKey);
        if (err == 0) {
            break;
        } else if (i >= MAX_IV_GENERATION_ATTEMPTS - 1) {
            free(derivedKey);
            return err;
        }
    }

    // Initialize AES key with derived key
    memset(key->key, 0, KEY_SIZE);
    memcpy(key->key, derivedKey, SHA256_HASH_SIZE);
    memset(derivedKey, 0, SHA256_HASH_SIZE);

    // Generate IV using the same salt and pepper as above
    RAND_bytes(context->iv, IV_SIZE);

    free(derivedKey);
    return 0;
}

int generateIV(const unsigned char *salt, size_t saltLen, const unsigned char *pepper, size_t pepperLen, struct EncryptionContext *context) {
    // Use the same PBKDF2-based key derivation function as above to generate an IV
    return generateKeyDerivationParameters(NULL, 0, salt, saltLen, pepper, pepperLen, context);
}

int encryptData(const unsigned char *data, size_t dataLen, const struct EncryptionContext *context, unsigned char **encryptedData) {
    // Use the AES-256-GCM encryption algorithm with a generated IV and key
    EVP_CIPHER_CTX *ctx = NULL;
    int len = 0;

    if (data == NULL || dataLen == 0 || context == NULL) {
        return -1;
    }

    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return -2;
    }

    int err = EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, context->key, context->iv);
    if (err == 0) {
        goto error;
    }

    unsigned char *encryptedDataPtr = malloc(dataLen + AES_BLOCK_SIZE);
    memset(encryptedDataPtr, 0, dataLen + AES_BLOCK_SIZE);

    err = EVP_EncryptUpdate(ctx, encryptedDataPtr, &len, data, (int)dataLen);
    if (err == 0 || len != dataLen + AES_BLOCK_SIZE) {
        goto error;
    }

    *encryptedData = encryptedDataPtr;
    return len;

error:
    free(encryptedDataPtr);
    EVP_CIPHER_CTX_free(ctx);
    return -3;
}

int decryptData(const unsigned char *encryptedData, size_t encryptedDataLen, const struct EncryptionContext *context, unsigned char **decryptedData) {
    // Use the AES-256-GCM decryption algorithm with a generated IV and key
    EVP_CIPHER_CTX *ctx = NULL;
    int len = 0;

    if (encryptedData == NULL || encryptedDataLen == 0 || context == NULL) {
        return -1;
    }

    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return -2;
    }

    int err = EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, context->key, context->iv);
    if (err == 0) {
        goto error;
    }

    unsigned char *decryptedDataPtr = malloc(encryptedDataLen - AES_BLOCK_SIZE);
    memset(decryptedDataPtr, 0, encryptedDataLen - AES_BLOCK_SIZE);

    err = EVP_DecryptUpdate(ctx, decryptedDataPtr, &len, encryptedData, (int)encryptedDataLen);
    if (err == 0 || len != encryptedDataLen - AES_BLOCK_SIZE) {
        goto error;
    }

    *decryptedData = decryptedDataPtr;
    return len;

error:
    free(decryptedDataPtr);
    EVP_CIPHER_CTX_free(ctx);
    return -3;
}

int generateSalt(unsigned char **salt) {
    // Generate a salt using the RAND_bytes function from OpenSSL
    int len = 0;

    if (salt == NULL) {
        return -1;
    }

    *salt = malloc(32);
    memset(*salt, 0, 32);

    RAND_bytes((unsigned char *)*salt, len);

    return len;
}

int generatePepper(unsigned char **pepper) {
    // Generate a pepper using the RAND_bytes function from OpenSSL
    int len = 0;

    if (pepper == NULL) {
        return -1;
    }

    *pepper = malloc(32);
    memset(*pepper, 0, 32);

    RAND_bytes((unsigned char *)*pepper, len);

    return len;
}

int main() {
    // Test the encryption and decryption functions with a test message
    unsigned char *testMsg = "Hello, World!";
    size_t msgLen = strlen(testMsg);

    struct EncryptionContext context;
    generateIV(NULL, 0, NULL, 0, &context);
    generateSalt(NULL);
    generatePepper(NULL);

    unsigned char *encryptedData = NULL;
    encryptData(testMsg, msgLen, &context, &encryptedData);

    unsigned char *decryptedData = NULL;
    decryptData(encryptedData, msgLen + AES_BLOCK_SIZE, &context, &decryptedData);

    printf("Encrypted message: %s\n", encryptedData);
    printf("Decrypted message: %s\n", decryptedData);

    free(encryptedData);
    free(decryptedData);
}
```
