        usage = current_usages[tenant["id"]]["usage"] + allocated_storage
        if usage < storage_quotas[tenant["id"]]:
            try:
                # Call the external billing API to validate the additional cost of allocation
                response = requests.post(f"https://billing-api.com/cost?tenant={tenant['id']}&usage={usage}")
                if response.status_code == 200:
                    cost = json.loads(response.text)["cost"]
            except requests.exceptions.RequestException as e:
