void *process_messages(void *args) {
    while (1) {
        sem_wait(&sem);
        if (num_messages == 0) {
            break;
        }
        char* message = &messages[num_messages - 1];
        char key[KEY_LENGTH];
        // Encrypt the message using a random key
        encrypt(message, key);
        // Decrypt the message using the same key
        decrypt(message, key);
        // Print the decrypted message to stdout
        printf("%s\n", message);
        // Remove the processed message from the array
        memmove(&messages[0], &messages[1], (num_messages - 1) * sizeof(message_t));
        num_messages--;
        sem_post(&sem);
    }
    return NULL;
}

// Main function for processing messages in a loop
void process_messages_loop() {
    while (1) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);
        // Check if there are any messages to process
        if (num_messages > 0) {
            // Create a new thread for processing messages
            pthread_create(&process_messages, NULL, &process_messages, NULL);
            sem_wait(&sem);
        } else {
            // Release the lock on the mutex
            pthread_mutex_unlock(&mutex);
            // Wait for 1 second before checking again
            sleep(1);
        }
    }
}

int main() {
    // Initialize the semaphore
    sem_init(&sem, 0, 0);
    // Create a new thread for processing messages in a loop
    pthread_create(&process_messages, NULL, &process_messages_loop, NULL);
    // Start consuming messages from the message broker and storing them in an array
    while (1) {
        char* message = malloc(MESSAGE_SIZE);
        // Consume a message from the message broker
        strncpy(message, "Some message", MESSAGE_SIZE);
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);
        // Add the message to the array of messages
        if (num_messages < MAX_MESSAGES) {
            memmove(&messages[num_messages], message, MESSAGE_SIZE);
            num_messages++;
        } else {
            // Release the lock on the mutex
            pthread_mutex_unlock(&mutex);
            // Wait for 1 second before checking again
            sleep(1);
        }
    }
    return 0;
}
