    }

    // Determine the size of the file in bytes and allocate memory for its contents
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);
    char *data = (char *)malloc(file_size);
    if (data == NULL) {
        log_message("Error: could not allocate memory for file contents\n");
        return -1;
    }

    // Read the entire contents of the file into the data buffer
    size_t bytes_read = fread(data, sizeof(char), file_size, file);
    if (bytes_read != file_size) {
        log_message("Error: could not read entire file\n");
        return -1;
    }

    // Encrypt the data using the specified algorithm
    char *encrypted_data = encrypt(data, file_size, algorithm);
    if (encrypted_data == NULL) {
        log_message("Error: could not encrypt data\n");
        return -1;
    }

    // Write the encrypted data to the storage system
    size_t bytes_written = fwrite(encrypted_data, sizeof(char), file_size, file);
    if (bytes_written != file_size) {
        log_message("Error: could not write entire file\n");
        return -1;
    }

    // Update the metadata for the encrypted file
    update_file_metadata(file_name, file_size, ftell(file));

    // Release resources and return success
    free(data);
    fclose(file);
    return 0;
}

// Decrypt a file using the specified encryption algorithm
int decrypt_file(const char *file_name, const char *algorithm) {
    // Check if the file exists and is readable
    FILE *file = fopen(file_name, "rb");
    if (file == NULL) {
        log_message("Error: could not open file for reading\n");
        return -1;
    }

    // Determine the size of the file in bytes and allocate memory for its contents
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);
    char *data = (char *)malloc(file_size);
    if (data == NULL) {
        log_message("Error: could not allocate memory for file contents\n");
        return -1;
    }

    // Read the entire contents of the file into the data buffer
    size_t bytes_read = fread(data, sizeof(char), file_size, file);
    if (bytes_read != file_size) {
        log_message("Error: could not read entire file\n");
        return -1;
    }

    // Decrypt the data using the specified algorithm
    char *decrypted_data = decrypt(data, file_size, algorithm);
    if (decrypted_data == NULL) {
        log_message("Error: could not decrypt data\n");
        return -1;
    }

    // Write the decrypted data to the storage system
    size_t bytes_written = fwrite(decrypted_data, sizeof(char), file_size, file);
    if (bytes_written != file_size) {
        log_message("Error: could not write entire file\n");
        return -1;
    }

    // Update the metadata for the decrypted file
    update_file_metadata(file_name, file_size, ftell(file));

    // Release resources and return success
    free(data);
    fclose(file);
    return 0;
}

// Update the metadata for a file in the storage system
int update_file_metadata(const char *file_name, long file_size, long offset) {
