    }

    // Determine the size of the metadata in bytes and allocate memory for its contents
    fseek(file, 0, SEEK_END);
    long metadata_size = ftell(file) - offset;
    rewind(file);
    char *metadata = (char *)malloc(metadata_size);
    if (metadata == NULL) {
        log_message("Error: could not allocate memory for file metadata\n");
        return -1;
    }

    // Read the entire contents of the metadata into the buffer
    size_t bytes_read = fread(metadata, sizeof(char), metadata_size, file);
