// Command-line utility for efficient line count processing with dynamic file path retrieval from external configuration service
package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"net/http"
	"os"
	"sync"
	"time"
)

const (
	// Default configuration service URL
	defaultConfigServiceURL = "https://example.com/config"
	// Default file path for input text files
	defaultInputFilePath = "/path/to/input/files"
	// Default output format for line counts
	defaultOutputFormat = "json"
)

var (
	inputFiles    []string // List of input text files to process
	outputFormat  string   // Output format for line counts (e.g., JSON, CSV, ...)
	configService *ConfigServiceClient // Client for external configuration service
)

type ConfigServiceClient struct {
	url      string        // URL for the external configuration service
	client   *http.Client  // HTTP client for communication with the service
	cache    map[string][]byte // Cache for frequently accessed file paths
	mux      sync.RWMutex // Mux for synchronizing access to the cache
}

func (c *ConfigServiceClient) GetFilePaths(fileNames []string) ([]string, error) {
	// Call the external configuration service for file paths
	var filePaths []string
	for _, fileName := range fileNames {
		filePaths = append(filePaths, c.cache[fileName])
	}
	return filePaths, nil
}

func (c *ConfigServiceClient) GetFileContents(filePaths []string) ([]byte, error) {
	// Call the external configuration service for file contents
	var content []byte
	for _, filePath := range filePaths {
		content = append(content, c.cache[filePath])
	}
	return content, nil
}

func (c *ConfigServiceClient) CacheFileContents(filePaths []string) error {
	// Update the cache with new file contents
	for _, filePath := range filePaths {
		c.cache[filePath] = c.client.Get(fmt.Sprintf("%s/%s", c.url, filePath)).Body()
	}
	return nil
}

func (c *ConfigServiceClient) HealthCheck() error {
	// Perform a health check on the external configuration service
	if _, err := http.Head(c.url); err != nil {
		log.Printf("[ERROR] Failed to perform health check on config service: %v\n", err)
		return err
	}
	return nil
}

func main() {
	// Parse command-line arguments
	flag.StringVar(&configService.url, "config-service-url", defaultConfigServiceURL, "External configuration service URL")
	flag.StringVar(&outputFormat, "output-format", defaultOutputFormat, "Output format for line counts (e.g., JSON, CSV, ...)")
	flag.Parse()

	// Initialize the external configuration service client
	configService = &ConfigServiceClient{url: configServiceURL, client: http.DefaultClient}

	// Retrieve file paths from the external configuration service
	filePaths := []string{}
	if err := configService.GetFilePaths(inputFiles, &filePaths); err != nil {
		log.Printf("[ERROR] Failed to retrieve file paths: %v\n", err)
	}

	// Cache frequently accessed file contents
	cacheFileContents(&filePaths)

	// Process the input files concurrently for efficient line count processing
	var wg sync.WaitGroup // Group for waiting on goroutines to complete
	for _, file := range inputFiles {
		wg.Add(1)
		go func(file string) {
			defer wg.Done()
			processFile(file, outputFormat)
		}(file)
	}
	wg.Wait()
}

func processFile(file string, format string) error {
	// Open the input file for reading
	f, err := os.Open(file)
	if err != nil {
		log.Printf("[ERROR] Failed to open file %s: %v\n", file, err)
		return err
	}
	defer f.Close()

	// Create a buffer for reading the input file
	var buf bytes.Buffer

	// Write line counts to the buffer
	writer := bufio.NewWriter(&buf)
	count := 0
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		count++
	}
	if err := scanner.Err(); err != nil {
		log.Printf("[ERROR] Failed to read file %s: %v\n", file, err)
		return err
	}

	// Marshal the line count into a JSON object
	countBytes, err := json.Marshal(map[string]int{"count": count})
	if err != nil {
		log.Printf("[ERROR] Failed to marshal line count: %v\n", err)
		return err
	}

	// Write the JSON object to the buffer
	if _, err := writer.Write(countBytes); err != nil {
		log.Printf("[ERROR] Failed to write line count to buffer: %v\n", err)
		return err
	}

	// Flush the buffer and close the output file
	writer.Flush()
	f.Close()

	// Print the processed file to STDOUT
	fmt.Println(buf.String())

	return nil
}

func cacheFileContents(filePaths []string) error {
	// Update the cache with new file contents
	for _, filePath := range filePaths {
		c.cache[filePath] = c.client.Get(fmt.Sprintf("%s/%s", c.url, filePath)).Body()
	}
	return nil
}

func healthCheck() error {
	// Perform a health check on the external configuration service
	if _, err := http.Head(c.url); err != nil {
		log.Printf("[ERROR] Failed to perform health check on config service: %v\n", err)
		return err
	}
	return nil
}
