    return 0;
}

// Function to merge two Config structures into one
int config_merge(struct Config *config1, struct Config *config2) {
    // Check if the given Config structures are valid
    if (!config1 || !config2) {
        printf("Error: Invalid Config structure\n");
        return -1;
    }

    // Merge the hostname field
    if (config1->hostname && config2->hostname) {
        free(config1->hostname);
        config1->hostname = strdup(config2->hostname);
    } else if (config2->hostname) {
        config1->hostname = strdup(config2->hostname);
    }

    // Merge the port field
    if (config1->port && config2->port) {
        free(config1->port);
        config1->port = atoi(config2->port);
    } else if (config2->port) {
        config1->port = atoi(config2->port);
    }

    // Merge the use_ssl field
    if (config1->use_ssl && config2->use_ssl) {
        free(config1->use_ssl);
        config1->use_ssl = json_object_get_boolean(config2->use_ssl);
    } else if (config2->use_ssl) {
        config1->use_ssl = json_object_get_boolean(config2->use_ssl);
    }

    // Merge the username field
    if (config1->username && config2->username) {
        free(config1->username);
        config1->username = strdup(config2->username);
    } else if (config2->username) {
        config1->username = strdup(config2->username);
    }

    // Merge the password field
    if (config1->password && config2->password) {
        free(config1->password);
        config1->password = strdup(config2->password);
    } else if (config2->password) {
        config1->password = strdup(config2->password);
    }

    return 0;
}

// Main function
int main() {
    // Create two Config structures
    struct Config *config1 = malloc(sizeof(struct Config));
    struct Config *config2 = malloc(sizeof(struct Config));

    // Load configuration from file, environment variable, or API endpoint
    config_load("file.conf", config1);
    config_load_env("CONFIG_ENV", config2);
    config_load_api("https://example.com/config", config3);

    // Merge the Config structures
    config_merge(config1, config2);
    config_merge(config1, config3);

    return 0;
}
```

This program creates three `Config` structures, one for each way of loading configuration. It then merges these configurations together using the `config_merge()` function. The resulting merged configuration is printed to the console.

