#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <unordered_map>
#include <atomic>
#include <chrono>

using namespace std;

// Define a structure to represent the data sources
struct DataSource {
  string name;
  vector<string> fields;
  int updateFrequency;
  bool active;
};

// Define a class to manage the data sources
class DataManager {
 private:
  // A map of data sources by their names
  unordered_map<string, DataSource> dataSources;

  // A vector of active data sources
  vector<DataSource> activeDataSources;

  // A mutex to protect the data sources
  mutex dataSourcesMutex;

  // A condition variable to signal when a data source is added or removed
  condition_variable dataSourceChangedCV;

  // A flag to indicate that the data source changed
  atomic<bool> dataSourceChanged{false};

 public:
  // Constructor
  DataManager() {}

  // Add a new data source
  void addDataSource(const string& name, const vector<string>& fields, int updateFrequency) {
    unique_lock<mutex> lock(dataSourcesMutex);
    dataSources[name] = {name, fields, updateFrequency, true};
    activeDataSources.push_back(dataSources[name]);
    dataSourceChangedCV.notify_all();
  }

  // Remove a data source
  void removeDataSource(const string& name) {
    unique_lock<mutex> lock(dataSourcesMutex);
    auto it = find_if(activeDataSources.begin(), activeDataSources.end(), [name](const DataSource& ds) {
      return ds.name == name;
    });
    if (it != activeDataSources.end()) {
      (*it).active = false;
      dataSourceChangedCV.notify_all();
    }
  }

  // Get the list of active data sources
  vector<DataSource> getActiveDataSources() {
    unique_lock<mutex> lock(dataSourcesMutex);
    return activeDataSources;
  }

  // Wait for a change in the data source set
  void waitForDataSourceChange() {
    unique_lock<mutex> lock(dataSourcesMutex);
    while (!dataSourceChanged) {
      dataSourceChangedCV.wait(lock);
    }
    dataSourceChanged = false;
  }
};

// Define a class to process the data streams in real-time
class DataProcessor {
 private:
  // A vector of threads for processing the data streams
  vector<thread> threadPool;

  // A map of data sources by their names
  unordered_map<string, DataSource> dataSources;

  // A mutex to protect the data sources
  mutex dataSourcesMutex;

  // A condition variable to signal when a data source is added or removed
  condition_variable dataSourceChangedCV;

  // A flag to indicate that the data source changed
  atomic<bool> dataSourceChanged{false};

 public:
  // Constructor
  DataProcessor(const vector<DataSource>& dataSources) : dataSources(dataSources) {}

  // Start processing the data streams
  void startProcessing() {
    for (auto& ds : dataSources) {
      threadPool.push_back(thread([this, ds] {
        while (true) {
          unique_lock<mutex> lock(dataSourcesMutex);
          waitForDataSourceChange();
          if (!ds.active) break;
          // Process the data stream here
          ...
        }
      }));
    }
  }

  // Stop processing the data streams
  void stopProcessing() {
    for (auto& t : threadPool) {
      t.join();
    }
  }

 private:
  // Wait for a change in the data source set
  void waitForDataSourceChange() {
    unique_lock<mutex> lock(dataSourcesMutex);
    while (!dataSourceChanged) {
      dataSourceChangedCV.wait(lock);
    }
    dataSourceChanged = false;
  }
};

int main() {
  // Create a data manager to manage the data sources
  DataManager dataManager;

  // Add some data sources
  dataManager.addDataSource("source1", {"field1", "field2"}, 10);
  dataManager.addDataSource("source2", {"field3", "field4"}, 5);
  dataManager.addDataSource("source3", {"field5", "field6"}, 100);

  // Create a data processor to process the data streams in real-time
  DataProcessor dataProcessor(dataManager.getActiveDataSources());

  // Start processing the data streams
  dataProcessor.startProcessing();

  // Wait for a few seconds to allow the threads to start
  this_thread::sleep_for(chrono::seconds(5));

  // Remove some data sources
  dataManager.removeDataSource("source2");
  dataManager.removeDataSource("source3");

  // Wait for a few seconds to allow the threads to stop
  this_thread::sleep_for(chrono::seconds(5));

  // Stop processing the data streams
  dataProcessor.stopProcessing();

  return 0;
}
```
This code uses a `DataManager` class to manage the data sources, including adding and removing them dynamically, and a `DataProcessor` class to process the data streams in real-time using multiple threads. The `DataManager` class uses a vector of threads for processing the data streams, which is created using the `std::thread` class from the C++ standard library.

The `DataManager` class also uses a condition variable to signal when a change has occurred in the data source set. This allows the `DataProcessor` class to wait for a change in the data source set and then start or stop processing the data streams accordingly.

The `main()` function creates an instance of the `DataManager` class, adds some data sources to it, and then creates an instance of the `DataProcessor` class using the active data sources from the `DataManager`. It then starts processing the data streams in real-time using the `startProcessing()` method of the `DataProcessor`, waits for a few seconds to allow the threads to start, removes some data sources, and then stops processing the data streams using the `stopProcessing()` method.']

