using namespace std;

class StateMachine {
public:
    enum class State {
        INIT,
        ACTIVE,
        PAUSED,
        FINISHED
    };

    StateMachine() : state_(State::INIT) {}

    void run() {
        while (true) {
            switch (state_) {
                case State::INIT:
                    cout << "Initializing..." << endl;
                    break;
                case State::ACTIVE:
                    cout << "Running..." << endl;
                    break;
                case State::PAUSED:
                    cout << "Paused." << endl;
                    break;
                case State::FINISHED:
                    cout << "Finished." << endl;
                    return;
            }
        }
    }

    void pause() { state_ = State::PAUSED; }

    void resume() { state_ = State::ACTIVE; }

private:
    State state_;
};

int main() {
    StateMachine sm;
    sm.run();

    sm.pause();
    cout << "Pausing for 5 seconds..." << endl;
    this_thread::sleep_for(chrono::seconds(5));
    sm.resume();

    sm.finish();
    cout << "Finished." << endl;
    return 0;
}
```
In this code, we define a `StateMachine` class that has four states: `INIT`, `ACTIVE`, `PAUSED`, and `FINISHED`. We also provide methods to transition between these states (`pause()`, `resume()`, and `finish()`). In the `main()` function, we create an instance of the `StateMachine` class and call its `run()` method. This will loop indefinitely, printing a message indicating the current state at each iteration.

