      logger.error("Failed to store market data", e);
    }
  }

  public MarketData retrieveMarketData(String id) {
    try {
      // Retrieve the processed market data from the storage layer
      return storageLayer.retrieve(id);
    } catch (StorageException e) {
      logger.error("Failed to retrieve market data", e);
    }
