// Memory pool for NFAPI CRC indication PDUs
typedef struct {
    size_t count;
    nfapi_crc_indication_pdu_t* pdu;
} nfapi_crc_indication_pool_t;

// Mutex for protecting the memory pool
static pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the memory pool with a given number of elements
void nfapi_crc_indication_pool_init(nfapi_crc_indication_pool_t* pool, size_t count) {
    pool->count = count;
    pool->pdu = (nfapi_crc_indication_pdu_t*)malloc(sizeof(nfapi_crc_indication_pdu_t) * count);
}

// Populate a NFAPI CRC indication PDU with a valid RX UE information tag, RNTI, and CRCFLAG
bool nfapi_crc_indication_populate(nfapi_crc_indication_pool_t* pool, size_t index, config_service* config) {
    // Acquire lock for protecting the memory pool
    pthread_mutex_lock(&mem_lock);

    nfapi_crc_indication_pdu_t* pdu = &pool->pdu[index];
    bool success = false;

    // Retrieve configuration parameters from external service
    int num_pdus = config->get_int("num_pdus");
    int seed = config->get_int("seed");

    if (num_pdus > 0 && seed > 0) {
        pdu->rx_ue_information_tag = num_pdus;
        pdu->rnti = rand() % num_pdus;
        pdu->crc_indication_rel8_tag = rand() % 256;
        pdu->crcflag = (rand() % 2) ? true : false;
        success = true;
    } else {
        // Fallback: use default values if configuration retrieval fails
        pdu->rx_ue_information_tag = 100;
        pdu->rnti = 100;
        pdu->crc_indication_rel8_tag = 256;
        pdu->crcflag = true;
        success = false;
    }

    // Release lock for protecting the memory pool
    pthread_mutex_unlock(&mem_lock);

    return success;
}

// Clean up and free resources associated with a given NFAPI CRC indication PDU
void nfapi_crc_indication_free(nfapi_crc_indication_pool_t* pool, size_t index) {
    // Acquire lock for protecting the memory pool
    pthread_mutex_lock(&mem_lock);

    nfapi_crc_indication_pdu_t* pdu = &pool->pdu[index];
    free(pdu);

    // Release lock for protecting the memory pool
    pthread_mutex_unlock(&mem_lock);
}
