import { fetch } from 'node-fetch';
import { JSON } from 'json.js';

interface ContentNode {
  id: string;
  title: string;
  content: string;
  children?: ContentNode[];
}

interface ExternalAPIResponse {
  status: number;
  data: any;
}

class ContentService {
  private readonly apiUrls = [
    'https://api1.example.com',
    'https://api2.example.com',
    // ...
  ];

  async fetchContent(id: string): Promise<ContentNode> {
    const externalAPIResponses: ExternalAPIResponse[] = await this.fetchDataFromExternalAPIs(id);

    const data = externalAPIResponses.reduce((acc, curr) => {
      if (curr.status === 200) {
        acc.data.push(curr.data);
      } else {
        console.error(`Failed to fetch content for ID ${id} from API ${curr.url}`);
      }
      return acc;
    }, { data: [] });

    if (data.length === 0) {
      throw new Error(`No content found for ID ${id}.`);
    }

    const contentNode = this.convertToContentNode(data);
    return contentNode;
  }

  private fetchDataFromExternalAPIs(id: string): Promise<ExternalAPIResponse[]> {
    return this.apiUrls.map((url) => fetch(`${url}/content/${id}`))
      .then((response) => response.json())
      .catch((error) => {
        console.error(`Failed to fetch content for ID ${id} from API ${url}: ${error}`);
        return null;
      });
  }

  private convertToContentNode(data: any[]): ContentNode {
    const rootNode = data[0];
    if (!rootNode) {
      throw new Error(`No content found for ID ${id}.`);
    }

    const nodesMap = new Map<string, ContentNode>();
    const childrenNodes = [];

    // Recursively build the tree structure.
    function buildTree(node: any): ContentNode {
      if (nodesMap.has(node.id)) {
        return nodesMap.get(node.id);
      }

      const contentNode = {
        id: node.id,
        title: node.title,
        content: node.content,
        children: [],
      };

      if (node.children) {
        for (const child of node.children) {
          const childNode = buildTree(child);
          if (childNode) {
            contentNode.children.push(childNode);
          }
        }
      }

      nodesMap.set(node.id, contentNode);
      return contentNode;
    }

    const rootContentNode = buildTree(rootNode);
    for (const node of nodes) {
      childrenNodes.push(buildTree(node));
    }

    return rootContentNode;
  }
}
```
