from typing import Dict, List
import json

class APIGateway:
    def __init__(self):
        self.service_map = {}  # dictionary of service endpoints and their corresponding microservices
        self.request_queue = []  # list of pending requests to be processed
        self.lock = Lock()  # lock for synchronizing access to the request queue
        self.error_handlers = {}  # dictionary of error handlers for different error codes
        self.retry_strategy = {}  # strategy for handling retries on failed requests

    def add_service(self, service_name: str, service_url: str):
        """Add a new microservice to the gateway."""
        self.service_map[service_name] = service_url

    def remove_service(self, service_name: str):
        """Remove a microservice from the gateway."""
        del self.service_map[service_name]

    def route_request(self, request: requests.Request) -> Dict[str, any]:
        """Route a request to the appropriate microservice based on its method and URL."""
        service = request.method + ":" + request.url
        if service in self.service_map:
            return self._process_request(self.service_map[service], request)
        else:
            raise Exception("Service not found")

    def _process_request(self, service_url: str, request: requests.Request) -> Dict[str, any]:
        """Process a request by sending it to the corresponding microservice."""
        response = None
        try:
            response = requests.post(service_url, data=json.dumps(request.data))
        except Exception as e:
            print(f"Error processing request {request.url} with method {request.method}: {e}")
            return self._handle_error(response)
        else:
            return response.json()

    def _handle_error(self, response: requests.Response) -> Dict[str, any]:
        """Handle an error response by calling the appropriate error handler."""
        if response is None or "error" not in response.json():
            return {"error": "Unknown error"}
        else:
            error_code = response.json()["error"]["code"]
            if error_code in self.error_handlers:
                return self.error_handlers[error_code](response)
            else:
                return {"error": f"Error code {error_code} not handled"}

    def set_error_handler(self, error_code: int, handler: Callable[[requests.Response], Dict[str, any]]):
        """Set an error handler for a specific error code."""
        self.error_handlers[error_code] = handler

    def get_service_list(self) -> List[str]:
        """Get the list of services registered with the gateway."""
        return list(self.service_map.keys())

    def _process_request_async(self, service_url: str, request: requests.Request) -> requests.Response:
        """Process a request asynchronously by sending it to the corresponding microservice."""
        response = None
        try:
            response = requests.post(service_url, data=json.dumps(request.data))
        except Exception as e:
            print(f"Error processing request {request.url} with method {request.method}: {e}")
            return self._handle_error(response)
        else:
            return response

    def process_request_batch(self, requests: List[requests.Request]) -> List[Dict[str, any]]:
        """Process a batch of requests in parallel."""
        with ThreadPoolExecutor() as executor:
            results = executor.map(self._process_request_async, self.service_map.values(), requests)
            return [r.json() for r in results]

    def set_retry_strategy(self, strategy: Callable[[requests.Response], bool]):
        """Set a retry strategy based on the response of a failed request."""
        self.retry_strategy = strategy

    def _should_retry(self, response: requests.Response) -> bool:
        """Determine whether to retry a failed request based on its response code and the configured retry strategy."""
        if self.retry_strategy is not None:
            return self.retry_strategy(response)
        else:
            return False

    def _retry_request(self, service_url: str, request: requests.Request) -> Dict[str, any]:
        """Retry a failed request by sending it to the corresponding microservice."""
        response = None
        while self._should_retry(response):
            try:
                response = requests.post(service_url, data=json.dumps(request.data))
            except Exception as e:
                print(f"Error processing request {request.url} with method {request.method}: {e}")
                return self._handle_error(response)
        else:
            return response.json()

    def process_request(self, request: requests.Request) -> Dict[str, any]:
        """Process a single request by routing it to the appropriate microservice."""
        service = request.method + ":" + request.url
        if service in self.service_map:
            response = self._process_request(self.service_map[service], request)
            if response is not None and response["error"] is not None:
                return self._retry_request(self.service_map[service], request)
            else:
                return response
        else:
            raise Exception("Service not found")

