# Implement a circuit breaker pattern to protect against API failures
class CircuitBreaker:
    def __init__(self):
        self._open = False
        self._failed_requests = 0

    def call(self, func):
        if self._open:
            raise Exception("Circuit breaker is open")
        else:
            try:
                return func()
            except Exception as e:
                # Increment the failed request count and check if the circuit should be opened
                self._failed_requests += 1
                if self._failed_requests >= 5:
                    self._open = True
                    raise Exception("Circuit breaker is open")
                else:
                    # Raise the exception for handling by the calling function
                    raise e

