function filterComment(comment) {
  const author = comment.author;
  const content = comment.content;
  const timestamp = comment.timestamp;

  // Discard comments older than 90 days
  if (Date.now() - new Date(timestamp).getTime() > 1000 * 60 * 60 * 24 * 90) {
    return false;
  }

  // Sanitize content by removing URLs, email addresses, and offensive language
  const sanitizedContent = sanitize(content, {
    allowedTags: whitelist,
    allowedAttributes: whitelist,
  });

  // Optimize for performance while ensuring robust handling of unexpected input patterns
