            std::string response = http_get(database_url_, node);

            // Parse the JSON response into a map of device configurations
            std::map<std::string, DeviceConfig> configs;
            parse_json(response, configs);

            // Add the parsed configurations to the local cache
            for (const auto& entry : configs) {
                configurations_.emplace(entry.first, entry.second);
            }
        }
    }

    // Validate device configurations against a set of flexible validation rules
    void validateConfigurations() {
        for (const auto& entry : configurations_) {
            const auto& config = entry.second;

            // Perform custom validation checks based on the configuration parameters
            if (config.device_name == "") {
                std::cerr << "Device name is empty" << std::endl;
            } else if (config.device_ip == "") {
                std::cerr << "Device IP address is empty" << std::endl;
