// Define a struct to represent a file processing task
struct FileProcessingTask {
    std::string filename;
    bool isValid;
};

// Define a struct to represent a line of text in the file
struct TextLine {
    std::string contents;
    int numericField1;
    int numericField2;
    double averageNumericField1And2;
};

// Define a class to handle file receipt and validation
class FileReceiver {
private:
    // Use a queue to hold incoming files until they are processed
    std::queue<FileProcessingTask> fileQueue;
    // Use a mutex to protect the file queue from concurrent access
    std::mutex fileQueueMutex;
    // Use a condition variable to signal when a new file is available
    std::condition_variable fileAvailableCondition;
public:
    void receiveFile(const FileProcessingTask& task) {
        // Lock the mutex and push the file onto the queue
        std::lock_guard<std::mutex> lock(fileQueueMutex);
        fileQueue.push(task);
        // Notify any waiting threads that a new file is available
        fileAvailableCondition.notify_one();
    }

    bool getNextFile(FileProcessingTask& task) {
        // Lock the mutex and wait for a new file to become available
        std::unique_lock<std::mutex> lock(fileQueueMutex);
        while (fileQueue.empty()) {
            fileAvailableCondition.wait(lock);
        }
        task = fileQueue.front();
        fileQueue.pop();
        return true;
    }
};

// Define a class to handle file validation and line processing
class ValidationEngine {
private:
    // Use a mutex to protect the file validation method from concurrent access
    std::mutex fileValidationMutex;
public:
    bool validateFile(const FileProcessingTask& task) {
        // Lock the mutex and perform file validation
        std::lock_guard<std::mutex> lock(fileValidationMutex);
        if (task.filename.empty()) {
            return false;
        }
        std::ifstream inFile(task.filename, std::ios::binary);
        if (!inFile.is_open()) {
            return false;
        }
        // Check file size, date range, and MIME type
        std::string mimeType = getMimeType(task.filename);
        if (mimeType != "text/plain") {
            return false;
        }
        std::chrono::time_point<std::chrono::system_clock> startTime = std::chrono::system_clock::now();
        std::chrono::time_point<std::chrono::system_clock> endTime = startTime + std::chrono::seconds(10);
        while (inFile.good() && inFile.peek() != EOF && std::chrono::system_clock::now() < endTime) {
            std::string line;
            getline(inFile, line);
            if (!isValidLine(line)) {
                return false;
            }
        }
        inFile.close();
        // Return true if the file is valid
        return true;
    }

    bool isValidLine(const std::string& line) {
        // Check for missing or malformed data
        if (line.empty() || !isNumeric(line)) {
            return false;
        }
        // Replace the last numeric field with its average if the preceding two fields are numeric
        int numericField1 = std::stoi(line);
        int numericField2 = std::stoi(line.substr(numericField1.length()));
        if (isNumeric(numericField1) && isNumeric(numericField2)) {
            line.replace(line.length() - numericField2.length(), numericField2.length(), std::to_string(average(numericField1, numericField2)));
        }
        // Return true if the line is valid
        return true;
    }

    bool average(int a, int b) {
        return (a + b) / 2;
    }

    bool isNumeric(const std::string& str) {
        try {
            std::stoi(str);
            return true;
        } catch (std::invalid_argument& e) {
            return false;
        }
    }
};

