namespace AESCBCLibrary
{
    using System;
    using System.Security.Cryptography;
    using System.Threading.Tasks;

    public class AESCBCEncryptionDecryption
    {
        private readonly IKeyManagementService _keyManagementService;
        private readonly RedisCache _redisCache;
        private readonly ILogger _logger;

        public AESCBCEncryptionDecryption(IKeyManagementService keyManagementService, RedisCache redisCache, ILogger logger)
        {
            _keyManagementService = keyManagementService;
            _redisCache = redisCache;
            _logger = logger;
        }

        public async Task<string> EncryptAsync(string plainText, string keyId)
        {
            // Retrieve the encryption key from the KMS using dependency injection.
            var key = await _keyManagementService.GetEncryptionKeyAsync(keyId);

            // Generate a random initialization vector (IV) for each encryption operation.
            var iv = CryptographicBuffer.GenerateRandom(16);

            // Create an AES-CBC encryptor using the key and IV.
            var aesEncryptor = new SymmetricKeyAlgorithmProvider(SymmetricAlgorithmNames.AesCbc, key).CreateSymmetricKeyAlgorithm(_keyManagementService.GetEncryptionKeySizeInBits());

            // Encrypt the plain text using the encryptor and return the encrypted data as a string.
            var encryptedData = await Task.Run(() => aesEncryptor.EncryptAsync(CryptographicBuffer.ConvertStringToBinary(plainText, BinaryStringEncoding.Utf8), iv));

            // Cache the IV and encrypted data in Redis for 24 hours to prevent re-encryption of plain text.
            _redisCache.Add("IV", iv);
            _redisCache.Add("EncryptedData", encryptedData);

            return CryptographicBuffer.EncodeToBase64String(encryptedData);
        }

        public async Task<string> DecryptAsync(string encryptedText, string keyId)
        {
            // Retrieve the encryption key from the KMS using dependency injection.
            var key = await _keyManagementService.GetEncryptionKeyAsync(keyId);

            // Retrieve the cached IV and encrypted data from Redis.
            var iv = _redisCache.Get("IV");
            var encryptedData = _redisCache.Get("EncryptedData");

            // Create an AES-CBC decryptor using the key and IV.
            var aesDecryptor = new SymmetricKeyAlgorithmProvider(SymmetricAlgorithmNames.AesCbc, key).CreateSymmetricKeyAlgorithm(_keyManagementService.GetEncryptionKeySizeInBits());

            // Decrypt the encrypted data using the decryptor and return the plain text as a string.
            var plainText = await Task.Run(() => aesDecryptor.DecryptAsync(CryptographicBuffer.DecodeFromBase64String(encryptedData), iv));

            return CryptographicBuffer.ConvertBinaryToString(BinaryStringEncoding.Utf8, plainText);
        }
    }
}

namespace AESCBCLibrary.KeyManagement
{
    using System;
    using System.Security.Cryptography;
    using System.Threading.Tasks;

    public class KeyManagementService : IKeyManagementService
    {
        private readonly RedisCache _redisCache;
        private readonly ILogger _logger;

        public KeyManagementService(RedisCache redisCache, ILogger logger)
        {
            _redisCache = redisCache;
            _logger = logger;
        }

        public async Task<string> GetEncryptionKeyAsync(string keyId)
        {
            // Retrieve the encryption key from Redis cache.
            var key = _redisCache.Get("EncryptionKey");

            if (key == null)
            {
                // If no key is found, retrieve it from the KMS and cache it in Redis for 24 hours.
                key = await GetEncryptionKeyFromKMSAsync(keyId);
                _redisCache.Add("EncryptionKey", key);
            }

            return key;
        }

        private async Task<string> GetEncryptionKeyFromKMSAsync(string keyId)
        {
            // Implement a retry mechanism with exponential backoff for transient errors.
            var attempts = 0;
            while (attempts < 3)
            {
                try
                {
                    return await _keyManagementService.GetEncryptionKeyAsync(keyId);
                }
                catch (Exception e) when (e is NetworkConnectionException || e is UnauthorizedAccessException)
                {
                    attempts++;
                    await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, attempts)));
                }
            }

            return null;
        }
    }
}

namespace AESCBCLibrary.RedisCache
{
    using System.Collections.Generic;
    using System.Linq;

    public class RedisCache : IRedisCache
    {
        private readonly Dictionary<string, object> _cache = new();

        public void Add(string key, object value)
        {
            _cache[key] = value;
        }

        public object Get(string key)
        {
            return _cache.GetValueOrDefault(key);
        }
    }
}

namespace AESCBCLibrary.Logging
{
    using System;

    public class Logger : ILogger
    {
        private readonly LogLevel _logLevel;
        private readonly Action<string, Exception> _loggerAction;

        public Logger(LogLevel logLevel, Action<string, Exception> loggerAction)
        {
            _logLevel = logLevel;
            _loggerAction = loggerAction;
        }

        public void Log(Exception ex)
        {
            if (ex == null || _logLevel < LogLevel.Error) return;
            _loggerAction($"{ex.Message}", ex);
        }

        public void Log(string message, Exception ex = null)
        {
            if (_logLevel < LogLevel.Information) return;
            _loggerAction(message, ex);
        }
    }
}']

