import org.apache.flink.api.common.functions.*;
import org.apache.flink.streaming.api.datastream.*;
import org.apache.flink.streaming.api.environment.*;
import org.apache.flink.streaming.connectors.kafka.*;

public class EnrichEvents {
    public static void main(String[] args) throws Exception {
        // Set up the streaming environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setStreamTimeCharacteristic(TimeCharacteristic.EventTime);

        // Set up the Kafka consumer and producer
        FlinkKafkaConsumer<String> kafkaConsumer = new FlinkKafkaConsumer<>(
            "topic", new SimpleStringSchema(), env.getConfig());
        FlinkKafkaProducer<String> kafkaProducer = new FlinkKafkaProducer<>(
            "output-topic", new SimpleStringSchema(), env.getConfig());

        // Set up the data stream and pipeline
        DataStream<String> inputStream = env.addSource(kafkaConsumer);
        DataStream<EnrichedEvent> outputStream = inputStream
            .flatMap(new EnrichEvents())
            .assignTimestampsAndWatermarks(
                new AscendingTimestampExtractor<EnrichedEvent>() {
                    @Override
                    public long extractAscendingTimestamp(EnrichedEvent element) {
                        return element.getTimestamp();
                    }
                });

        // Write the output to Kafka
        outputStream.addSink(kafkaProducer);

        // Execute the pipeline
        env.execute("Enrich Events");
    }

    public static class EnrichEvents extends RichFlatMapFunction<String, EnrichedEvent> {
