  },

  // Function to send notifications from the queue
  sendNotifications() {
    const notificationsToSend = this.queue.slice(0, 100); // Send up to 100 notifications at a time
    for (const notification of notificationsToSend) {
      const messagingPlatform = this.messagingPlatforms[notification.platform];
      if (!messagingPlatform) {
