        // If an error occurs, retry the message with exponential backoff
        const retryCount = notification.retryCount || 0;
        if (retryCount < 3) {
          notification.retryCount = retryCount + 1;
          this.addNotification(notification);
        } else {
          console.error(`Retry limit reached for message to ${notification.recipient}`);
        }
      }
