        self.storage_providers = storage_providers
        self.cache = dict()
        self.cache_size = cache_size
        self.fallback_strategy = None

    def get(self, key: str) -> Optional[any]:
        # Check if the key is in the local cache
        if key in self.cache:
            return self.cache[key]

        # Check if there are any available storage providers
        if len(self.storage_providers) == 0:
            return None

        # Get the first available storage provider and fetch the value from it
        provider = self.storage_providers[0]
        value = provider.get(key)

        # If the value is not found, try the next available provider
        if value is None:
            for i in range(1, len(self.storage_providers)):
                provider = self.storage_providers[i]
                value = provider.get(key)
                if value is not None:
                    break

        # If the value is still not found, use the fallback strategy
        if value is None and self.fallback_strategy is not None:
            value = self.fallback_strategy(key)

        # Update the local cache with the new value
        self.cache[key] = value

        return value

    def set(self, key: str, value: any):
