    def get(self, key):
        try:
            return self.redis_client.get(key)
        except ConnectionError as e:
            # implement error handling mechanism
            pass

    def set(self, key, value):
        try:
            return self.redis_client.set(key, value)
        except ConnectionError as e:
            # implement error handling mechanism
            pass

    def get_and_set(self, key, value, ex=None):
        try:
            return self.redis_client.get_and_set(key, value, ex=ex)
        except ConnectionError as e:
            # implement error handling mechanism
            pass

    def del(self, key):
        try:
            return self.redis_client.del(key)
        except ConnectionError as e:
            # implement error handling mechanism
            pass
