import hashlib
from concurrent.futures import ThreadPoolExecutor
from time import sleep

class FileHasher:
    def __init__(self, file_path, hash_algorithm='md5'):
        self.file_path = file_path
        self.hash_algorithm = hash_algorithm
        self.logger = logging.getLogger(__name__)

    def calculate_hash(self):
        try:
            with open(self.file_path, 'rb') as f:
                hasher = getattr(hashlib, self.hash_algorithm)()
                while True:
                    data = f.read(8192)
                    if not data:
                        break
                    hasher.update(data)
                return hasher.hexdigest()
        except (OSError, IOError):
            self.logger.error('Error reading file %s', self.file_path, exc_info=True)
            return None

class FileVerifier:
    def __init__(self, file_path, expected_hash, hash_algorithm='md5'):
        self.file_path = file_path
        self.expected_hash = expected_hash
        self.hash_algorithm = hash_algorithm
        self.logger = logging.getLogger(__name__)

    def verify(self):
        try:
            with open(self.file_path, 'rb') as f:
                hasher = getattr(hashlib, self.hash_algorithm)()
                while True:
                    data = f.read(8192)
                    if not data:
                        break
                    hasher.update(data)
                actual_hash = hasher.hexdigest()
                return actual_hash == self.expected_hash
        except (OSError, IOError):
            self.logger.error('Error reading file %s', self.file_path, exc_info=True)
            return False

class FileHashService:
    def __init__(self, storage_system):
        self.storage_system = storage_system
        self.logger = logging.getLogger(__name__)

