import os
import hashlib
from concurrent.futures import ThreadPoolExecutor
from logging import getLogger, basicConfig

logger = getLogger(__name__)

class HashService:
    def __init__(self):
        self.executor = ThreadPoolExecutor()

    def calculate_hash(self, file_path):
        with open(file_path, 'rb') as f:
            return hashlib.md5(f.read()).hexdigest()

    def verify_hash(self, file_path, expected_hash):
        actual_hash = self.calculate_hash(file_path)
        if actual_hash == expected_hash:
            logger.info(f'Hash verification successful for {file_path}.')
            return True
        else:
            logger.error(f'Hash verification failed for {file_path}. Expected hash: {expected_hash}, Actual hash: {actual_hash}')
            return False

    def calculate_and_verify_hash(self, file_path, expected_hash):
        try:
            if self.verify_hash(file_path, expected_hash):
                logger.info(f'Hash calculation and verification successful for {file_path}.')
                return True
            else:
                raise ValueError('Hash verification failed.')
        except Exception as e:
            logger.error(f'Failed to calculate and verify hash for {file_path}. Error: {e}')
            return False

    def calculate_hashes_concurrently(self, file_paths):
        futures = []
        for file_path in file_paths:
            future = self.executor.submit(self.calculate_hash, file_path)
            futures.append(future)

        hashes = []
        for future in futures:
            try:
                hash = future.result()
                hashes.append(hash)
            except Exception as e:
                logger.error(f'Failed to calculate hash for {file_path}. Error: {e}')

        return hashes

    def verify_hashes_concurrently(self, file_paths, expected_hashes):
        futures = []
        for file_path, expected_hash in zip(file_paths, expected_hashes):
            future = self.executor.submit(self.verify_hash, file_path, expected_hash)
            futures.append(future)

        verified = []
        for future in futures:
            try:
                verified.append(future.result())
            except Exception as e:
                logger.error(f'Failed to verify hash for {file_path}. Error: {e}')

        return all(verified)

    def calculate_and_verify_hashes_concurrently(self, file_paths, expected_hashes):
        try:
            if self.verify_hashes_concurrently(file_paths, expected_hashes):
                logger.info(f'Hash calculation and verification successful for {file_paths}.')
                return True
            else:
                raise ValueError('Hash verification failed.')
        except Exception as e:
            logger.error(f'Failed to calculate and verify hashes concurrently for {file_paths}. Error: {e}')
            return False
