// Define a structure to represent an LTE RRC message type and its data payload
typedef struct {
  char* name;
  void* data;
} LTE_RRC_CU_MessageType;

// Define a hash table to map between message types and their versions
#define MESSAGE_TYPE_VERSION_MAP_SIZE 1024
typedef struct {
  char* name;
  int version;
} MessageTypeVersionMap;

// Define a dynamic array to store the collection of LTE RRC message types
#define MAX_MESSAGE_TYPES 1000
typedef struct {
  LTE_RRC_CU_MessageType* messages[MAX_MESSAGE_TYPES];
} MessageCollection;

// Define a thread-safe data structure to manage the collection of message types
#define MESSAGE_COLLECTION_LOCK(name) pthread_mutex_t name = PTHREAD_MUTEX_INITIALIZER;
#define MESSAGE_COLLECTION_UNLOCK(name) pthread_mutex_unlock(&name);

// Define a function to initialize the message collection
void initializeMessageCollection() {
  // Allocate memory for the message collection and set its size
  MessageCollection* collection = (MessageCollection*)malloc(sizeof(MessageCollection));
  collection->size = 0;

  // Initialize the hash table to map between message types and their versions
  MessageTypeVersionMap version_map[MESSAGE_TYPE_VERSION_MAP_SIZE];
  for (int i = 0; i < MESSAGE_TYPE_VERSION_MAP_SIZE; i++) {
    version_map[i].name = NULL;
    version_map[i].version = 0;
  }

  // Initialize the mutex to manage concurrent access to the message collection
  MESSAGE_COLLECTION_LOCK(mutex);
}

// Define a function to add a new message type to the collection
void addMessageType(char* name, int version) {
  // Check if the message type already exists in the hash table
  bool found = false;
  for (int i = 0; i < MESSAGE_TYPE_VERSION_MAP_SIZE; i++) {
    if (strcmp(version_map[i].name, name) == 0) {
      // If the message type exists, update its version
      version_map[i].version = version;
      found = true;
      break;
    }
  }

  // If the message type does not exist, add it to the hash table and the collection
  if (!found) {
    MessageTypeVersionMap* new_message = (MessageTypeVersionMap*)malloc(sizeof(MessageTypeVersionMap));
    new_message->name = name;
    new_message->version = version;

    // Add the new message type to the collection and the hash table
    MESSAGE_COLLECTION_LOCK(mutex);
    if (collection->size < MAX_MESSAGE_TYPES) {
      LTE_RRC_CU_MessageType* new_message_type = (LTE_RRC_CU_MessageType*)malloc(sizeof(LTE_RRC_CU_MessageType));
      new_message_type->name = name;
      new_message_type->data = NULL;
      collection->messages[collection->size++] = new_message_type;
    } else {
      printf("Maximum number of message types reached\n");
    }
    MESSAGE_COLLECTION_UNLOCK(mutex);
  }
}

// Define a function to release a message type from the collection
void removeMessageType(char* name) {
  // Check if the message type exists in the hash table
  bool found = false;
  for (int i = 0; i < MESSAGE_TYPE_VERSION_MAP_SIZE; i++) {
    if (strcmp(version_map[i].name, name) == 0) {
      // If the message type exists, remove it from the hash table and the collection
      version_map[i].name = NULL;
      version_map[i].version = 0;
      found = true;
      break;
    }
  }

  // If the message type does not exist, print an error message
  if (!found) {
    printf("Message type %s does not exist\n", name);
  } else {
    MESSAGE_COLLECTION_LOCK(mutex);
    for (int i = 0; i < collection->size; i++) {
      if (strcmp(collection->messages[i]->name, name) == 0) {
        free(collection->messages[i]);
        collection->size--;
        break;
      }
    }
    MESSAGE_COLLECTION_UNLOCK(mutex);
  }
}

// Define a function to retrieve a message type from the collection by name and version
void getMessageType(char* name, int version) {
  // Check if the message type exists in the hash table
  bool found = false;
  for (int i = 0; i < MESSAGE_TYPE_VERSION_MAP_SIZE; i++) {
    if (strcmp(version_map[i].name, name) == 0 && version_map[i].version == version) {
      found = true;
      break;
    }
  }

  // If the message type does not exist or has a different version, print an error message
  if (!found || version != version_map[i].version) {
    printf("Message type %s with version %d does not exist\n", name, version);
  } else {
    MESSAGE_COLLECTION_LOCK(mutex);
    for (int i = 0; i < collection->size; i++) {
      if (strcmp(collection->messages[i]->name, name) == 0 && collection->messages[i]->version == version) {
        // Return the message type and its data payload
        printf("Message type %s with version %d found\n", name, version);
        MESSAGE_COLLECTION_UNLOCK(mutex);
      }
    }
  }
}

// Define a function to update a message type in the collection by name and version
void updateMessageType(char* name, int version) {
  // Check if the message type exists in the hash table
  bool found = false;
  for (int i = 0; i < MESSAGE_TYPE_VERSION_MAP_SIZE; i++) {
    if (strcmp(version_map[i].name, name) == 0 && version_map[i].version == version) {
      found = true;
      break;
    }
  }

  // If the message type does not exist or has a different version, print an error message
  if (!found || version != version_map[i].version) {
    printf("Message type %s with version %d does not exist\n", name, version);
  } else {
    MESSAGE_COLLECTION_LOCK(mutex);
    for (int i = 0; i < collection->size; i++) {
      if (strcmp(collection->messages[i]->name, name) == 0 && collection->messages[i]->version == version) {
        // Update the message type and its data payload
        printf("Message type %s with version %d updated\n", name, version);
        MESSAGE_COLLECTION_UNLOCK(mutex);
      }
    }
  }
}

// Define a function to release all message types from the collection
void clearCollection() {
  // Release all message types and their data payloads
  for (int i = 0; i < collection->size; i++) {
    free(collection->messages[i]);
  }
  collection->size = 0;
}

// Define a function to release all resources allocated by the library
void shutdownLibrary() {
  // Release all message types and their data payloads
  clearCollection();

  // Release the mutex used to manage concurrent access to the message collection
  MESSAGE_COLLECTION_UNLOCK(mutex);

  // Release the memory allocated for the hash table
  free(version_map);
}
