    std::unique_lock<std::mutex> lock(db_mtx);
    // Wait until the database is ready or a timeout occurs
    cv.wait(lock, []{ return db_ready.load(); });
}

// Function to retrieve UE information from the database
std::vector<NFAPI_CRC_INDICATION_PDU_T> get_ue_info() {
    // Lock the mutex to ensure that only one thread accesses the database at a time
    std::unique_lock<std::mutex> lock(db_mtx);
    // Wait for the database to be ready
    wait_for_db();
    // Query the database for UE information
    auto ue_info = db_interface->get_ue_info();
    // Create a vector of NFAPI_CRC_INDICATION_PDU_T structures based on the query results
    std::vector<NFAPI_CRC_INDICATION_PDU_T> crc_indications;
    for (auto &ue : ue_info) {
        // Extract the RNTI and UE category from the database entry
        uint16_t rnti = std::get<0>(ue);
        uint8_t ue_category = std::get<1>(ue);
        // Compute the CRC indication for this UE
        int8_t crc_indication = compute_crc_indication(rnti, ue_category);
        // Add the CRC indication to the vector of NFAPI_CRC_INDICATION_PDU_T structures
        crc_indications.push_back({rnti, ue_category, crc_indication});
    }
    return crc_indications;
}

// Function to compute the CRC indication for a given UE
int8_t compute_crc_indication(uint16_t rnti, uint8_t ue_category) {
    // Compute the CRC indication based on the RNTI and UE category
    return rnti % 2 == 0 ? ue_category : -ue_category;
}

// Function to generate a list of NFAPI_CRC_INDICATION_PDU_T structures for a given number of UEs
std::vector<NFAPI_CRC_INDICATION_PDU_T> create_crc_indications_list(size_t num_ues) {
    // Create an empty vector to store the CRC indications
    std::vector<NFAPI_CRC_INDICATION_PDU_T> crc_indications;
    // Iterate over the number of UEs and retrieve the corresponding UE information from the database
    for (size_t i = 0; i < num_ues; ++i) {
        auto ue_info = get_ue_info();
        if (!ue_info.empty()) {
            // Add the CRC indications for this UE to the vector of NFAPI_CRC_INDICATION_PDU_T structures
            crc_indications.insert(crc_indications.end(), ue_info.begin(), ue_info.end());
        }
    }
    return crc_indications;
}
