    LTE_PHY_RRC_UE_CONTEXT *data; // Array of LTE_PHY_RRC_UE_CONTEXT structures
} UEContextArray;

// Function to initialize a new UE context and add it to the dynamic array
int addNewUEContext(UEContextArray *array, uint16_t UE_ID, RRC_STATE rrc_state, PHY_TRANSPORT_CHANNEL_CONFIG phy_transport_config) {
    // Check if there is enough capacity in the array to add a new element
    if (array->num_elements >= array->capacity) {
        return -1;
    }

    // Allocate memory for the new UE context structure
    LTE_PHY_RRC_UE_CONTEXT *new_context = malloc(sizeof(LTE_PHY_RRC_UE_CONTEXT));
    if (new_context == NULL) {
        return -2;
    }

    // Initialize the new UE context structure
    new_context->UE_ID = UE_ID;
    new_context->rrc_state = rrc_state;
    new_context->phy_transport_config = phy_transport_config;

    // Add the new UE context to the array
    array->data[array->num_elements++] = new_context;

    return 0;
}

// Function to remove an existing UE context from the dynamic array
int removeUEContext(UEContextArray *array, uint16_t UE_ID) {
    // Find the index of the UE context in the array
    int index = -1;
    for (int i = 0; i < array->num_elements; i++) {
        if (array->data[i]->UE_ID == UE_ID) {
            index = i;
            break;
        }
    }

    // Check if the UE context was found in the array
    if (index < 0) {
        return -1;
    }

    // Remove the UE context from the array
    LTE_PHY_RRC_UE_CONTEXT *removed_context = array->data[index];
    array->num_elements--;

    // Shift all elements after the removed element to fill the gap
    for (int i = index; i < array->num_elements; i++) {
        array->data[i] = array->data[i + 1];
    }

    // Free memory used by the removed UE context structure
    free(removed_context);

    return 0;
}

