            response = requests.post(url, json=data)
            if response.status_code == 200:
                return True
            else:
                print(f"Received {response.status_code} status code from API")
                return False
        except ConnectionError as e:
            print("Connection error:", e)
            time.sleep(2**retries)  # exponential backoff with retries
        except Timeout as e:
            print("Timeout error:", e)
            time.sleep(2**retries)  # exponential backoff with retries

    # Send validated metrics to REST service and store in InfluxDB using thread pools
    num_requests = len(validated_metrics) if max_concurrent_requests > len(validated_metrics) else max_concurrent_requests
    with ThreadPoolExecutor(max_workers=num_requests) as executor:
        for metric in validated_metrics:
            url = "https://api.example.com/metrics"
            data = {
                "device_id": metric["device_id"],
                "timestamp": metric["timestamp"],
                "metric_name": metric["metric_name"],
                "value": metric["value"]
            }
            future = executor.submit(send_request, url, data)
            try:
                future.result(timeout=api_timeout)  # timeout management
            except TimeoutError as e:
                print("API request timed out")
            except Exception as e:
                print("Error sending API request:", e)

    # Handle potential connection failures, timeouts, and rate limiting from external services
    if num_requests > 0:
        try:
            influxdb = InfluxDBClient(url="http://localhost:8086", token="my-token", org="my-org")
            for metric in validated_metrics:
                point = {
                    "measurement": "iot_device_metrics",
                    "tags": {
                        "device_id": metric["device_id"]
                    },
                    "fields": {
                        "metric_name": metric["metric_name"],
                        "value": float(metric["value"])
                    }
                }
                try:
                    influxdb.write_api().write(bucket="my-bucket", record=point)
                except ApiException as e:
                    print("Error storing metric in InfluxDB:", e)
        except ConnectionError as e:
            print("InfluxDB connection error:", e)
