// Encryption Service

package com.example.encryption;

import java.util.Map;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import org.apache.commons.io.IOUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class EncryptionService {
  private static final Logger LOGGER = LoggerFactory.getLogger(EncryptionService.class);

  private Map<String, SecretKeySpec> keyMap;
  private Map<String, Cipher> cipherMap;

  public EncryptionService() {
    this.keyMap = new HashMap<>();
    this.cipherMap = new HashMap<>();
  }

  public void init(Map<String, String> keyConfig) {
    // Initialize secret keys and ciphers from configuration map
    for (String keyName : keyConfig.keySet()) {
      SecretKeySpec key = new SecretKeySpec(IOUtils.toByteArray(keyConfig.get(keyName)), "AES");
      Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
      cipher.init(Cipher.ENCRYPT_MODE, key);
      this.keyMap.put(keyName, key);
      this.cipherMap.put(keyName, cipher);
    }
  }

  public byte[] encrypt(String keyName, String plaintext) throws Exception {
    // Encrypt input using specified secret key and cipher
    SecretKeySpec key = this.keyMap.get(keyName);
    Cipher cipher = this.cipherMap.get(keyName);
    if (key == null || cipher == null) {
      throw new IllegalArgumentException("No matching secret key and cipher found");
    }
    IvParameterSpec ivSpec = new IvParameterSpec(new byte[16]);
    return cipher.doFinal(plaintext.getBytes());
  }

  public String decrypt(String keyName, byte[] ciphertext) throws Exception {
    // Decrypt input using specified secret key and cipher
    SecretKeySpec key = this.keyMap.get(keyName);
    Cipher cipher = this.cipherMap.get(keyName);
    if (key == null || cipher == null) {
      throw new IllegalArgumentException("No matching secret key and cipher found");
    }
    IvParameterSpec ivSpec = new IvParameterSpec(new byte[16]);
    return new String(cipher.doFinal(ciphertext));
  }
}
