import os
from pathlib import Path
import requests
from concurrent.futures import ThreadPoolExecutor

class CloudSyncer:
    def __init__(self, local_path, cloud_services):
        self.local_path = local_path
        self.cloud_services = cloud_services
        self.versioning_enabled = False

    def sync(self):
        # Initialize versioning if enabled
        if self.versioning_enabled:
            self.initialize_versioning()

        # Sync files and directories with cloud services
        for service in self.cloud_services:
            for file in os.listdir(self.local_path):
                local_file = os.path.join(self.local_path, file)
                if os.path.isfile(local_file):
                    self.sync_file(service, local_file)
                else:
                    self.sync_directory(service, local_file)

    def sync_file(self, service, local_file):
        # Get file metadata from cloud service
        try:
            metadata = service.get_file_metadata(local_file)
        except requests.exceptions.RequestException:
            return

        # Check if file is updated locally
        if os.path.getmtime(local_file) > metadata['last_modified']:
            # Update cloud service with local changes
            try:
                service.upload_file(local_file, metadata['etag'])
            except requests.exceptions.RequestException as e:
                print(f"Error uploading file to {service}: {e}")

    def sync_directory(self, service, local_directory):
        # Get directory metadata from cloud service
        try:
            metadata = service.get_directory_metadata(local_directory)
        except requests.exceptions.RequestException:
            return

        # Check if directory is updated locally
        if os.path.getmtime(local_directory) > metadata['last_modified']:
            # Update cloud service with local changes
            try:
                service.upload_directory(local_directory, metadata['etag'])
            except requests.exceptions.RequestException as e:
                print(f"Error uploading directory to {service}: {e}")

    def initialize_versioning(self):
        # Initialize versioning for local files and directories
        for service in self.cloud_services:
            for file in os.listdir(self.local_path):
                local_file = os.path.join(self.local_path, file)
                if os.path.isfile(local_file):
                    self.initialize_versioning_for_file(service, local_file)
                else:
                    self.initialize_versioning_for_directory(service, local_file)

    def initialize_versioning_for_file(self, service, local_file):
        # Get file metadata from cloud service
        try:
            metadata = service.get_file_metadata(local_file)
        except requests.exceptions.RequestException:
            return

        # Initialize versioning for file
        self.versioning_enabled[service][local_file] = True
        self.file_versions[service][local_file] = {
            'version': 1,
            'etag': metadata['etag']
        }

    def initialize_versioning_for_directory(self, service, local_directory):
        # Get directory metadata from cloud service
        try:
            metadata = service.get_directory_metadata(local_directory)
        except requests.exceptions.RequestException:
            return

        # Initialize versioning for directory
        self.versioning_enabled[service][local_directory] = True
        self.directory_versions[service][local_directory] = {
            'version': 1,
            'etag': metadata['etag']
        }

    def get_file_metadata(self, service, file):
        # Get file metadata from cloud service
        try:
            response = requests.get(f'{service.base_url}/files/{file}', headers=service.headers)
            if response.status_code == 200:
                return response.json()['metadata']
            else:
                raise Exception(response.text)
        except requests.exceptions.RequestException as e:
            print(f"Error getting file metadata from {service}: {e}")

    def get_directory_metadata(self, service, directory):
        # Get directory metadata from cloud service
        try:
            response = requests.get(f'{service.base_url}/directories/{directory}', headers=service.headers)
            if response.status_code == 200:
                return response.json()['metadata']
            else:
                raise Exception(response.text)
        except requests.exceptions.RequestException as e:
            print(f"Error getting directory metadata from {service}: {e}")

    def upload_file(self, service, local_file):
        # Upload file to cloud service
        try:
            with open(local_file, 'rb') as f:
                response = requests.put(f'{service.base_url}/files/{local_file}', data=f, headers=service.headers)
            if response.status_code == 201:
                return True
            else:
                raise Exception(response.text)
        except requests.exceptions.RequestException as e:
            print(f"Error uploading file to {service}: {e}")

    def upload_directory(self, service, local_directory):
        # Upload directory to cloud service
        try:
            for file in os.listdir(local_directory):
                with open(os.path.join(local_directory, file), 'rb') as f:
                    response = requests.put(f'{service.base_url}/files/{file}', data=f, headers=service.headers)
                if response.status_code == 201:
                    return True
                else:
                    raise Exception(response.text)
        except requests.exceptions.RequestException as e:
            print(f"Error uploading directory to {service}: {e}")
