struct rrc_message_queue *create_rrc_message_queue() {
    struct rrc_message_queue *queue = malloc(sizeof(struct rrc_message_queue));
    queue->size = 0;
    return queue;
}

void destroy_rrc_message_queue(struct rrc_message_queue *queue) {
    free(queue);
}

int enqueue_rrc_message(struct rrc_message_queue *queue, struct rrc_message message) {
    if (queue->size == 100) {
        return -1; // Queue is full
    }
    queue->messages[queue->size++] = malloc(sizeof(struct rrc_message));
    memcpy(queue->messages[queue->size-1], &message, sizeof(struct rrc_message));
    return 0;
}

int dequeue_rrc_message(struct rrc_message_queue *queue) {
    if (queue->size == 0) {
        return -1; // Queue is empty
    }
    free(queue->messages[queue->size-1]);
    queue->size--;
    return 0;
}

struct rrc_message *peek_rrc_message(struct rrc_message_queue *queue) {
    if (queue->size == 0) {
        return NULL; // Queue is empty
    }
    return queue->messages[queue->size-1];
}

