#include <semaphore.h>
#include "nfapi_crc_indication_pdu_t.h"

#define MAX_UE 1000000000
#define MEMORY_SIZE (sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_UE)
#define LOCK_SIZE (sizeof(pthread_mutex_t) * MAX_UE)
#define SEMAPHORE_SIZE (sizeof(sem_t) * MAX_UE)

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t* lock;
    sem_t* semaphore;
} UEInfo;

UEInfo ueInfo[MAX_UE];
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
sem_t memory_semaphore = SEMAPHORE_INITIALIZER;

void initializeUEInfo(int index, int rnti) {
    ueInfo[index].data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memset(ueInfo[index].data, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ueInfo[index].lock = (pthread_mutex_t*) malloc(LOCK_SIZE);
    pthread_mutex_init(ueInfo[index].lock, NULL, 0);
    ueInfo[index].semaphore = (sem_t*) malloc(SEMAPHORE_SIZE);
    sem_init(ueInfo[index].semaphore, 0, 1);
    ueInfo[index].data->rnti = rnti;
}

void deinitializeUEInfo(int index) {
    free(ueInfo[index].data);
    free(ueInfo[index].lock);
    sem_destroy(ueInfo[index].semaphore);
}

void initializeMemory() {
    int i;
    for (i = 0; i < MAX_UE; i++) {
        ueInfo[i] = NULL;
    }
    pthread_mutex_init(&memory_lock, NULL, 0);
    sem_init(&memory_semaphore, 0, 1);
}

void deinitializeMemory() {
    int i;
    for (i = 0; i < MAX_UE; i++) {
        if (ueInfo[i] != NULL) {
            deinitializeUEInfo(i);
        }
    }
    pthread_mutex_destroy(&memory_lock);
    sem_destroy(&memory_semaphore);
}

void* initializeUEs() {
    int i;
    for (i = 0; i < MAX_UE; i++) {
        if (ueInfo[i] == NULL) {
            initializeUEInfo(i, i);
        }
    }
    return NULL;
}

void* deinitializeUEs() {
    int i;
    for (i = 0; i < MAX_UE; i++) {
        if (ueInfo[i] != NULL) {
            deinitializeUEInfo(i);
        }
    }
    return NULL;
}

void* handleCRCIndication(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    int i;
    for (i = 0; i < MAX_UE; i++) {
        if (pdu->rnti == ueInfo[i].data->rnti) {
            pthread_mutex_lock(ueInfo[i].lock);
            sem_wait(ueInfo[i].semaphore);
            memcpy(ueInfo[i].data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            sem_post(ueInfo[i].semaphore);
            pthread_mutex_unlock(ueInfo[i].lock);
        }
    }
    return NULL;
}
