// Registry Management //

#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <memory>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>

using namespace std;

class TaskRegistry {
private:
    map<string, unique_ptr<Task>> tasks_;
    mutex task_map_lock_;
    condition_variable cv_;
    vector<shared_ptr<Task>> running_tasks_;
    shared_ptr<Task> current_task_;

public:
    TaskRegistry() { }

    void register_task(const string& name, unique_ptr<Task> task) {
        lock_guard<mutex> guard(task_map_lock_);
        tasks_.emplace(name, move(task));
    }

    void execute_task(const string& name) {
        lock_guard<mutex> guard(task_map_lock_);
        current_task_ = tasks_[name]->clone();
        running_tasks_.push_back(current_task_);
        cv_.notify_one();
    }

    void deregister_task(const string& name) {
        lock_guard<mutex> guard(task_map_lock_);
        tasks_.erase(name);
    }

    void run() {
        unique_lock<mutex> lock(task_map_lock_);
        while (running_tasks_.empty()) {
            cv_.wait(lock);
        }
        current_task_->run();
        running_tasks_.pop_back();
    }
};

