// Define a task queue with asynchronous job execution
struct TaskQueue {
  vector<Task*> tasks;
  mutex lock = {};

  // Function to add a new task to the queue
  void enqueue(Task& task) {
    lock_guard<mutex> lk(lock);
    tasks.push_back(&task);
  }

  // Function to remove and execute a task from the queue
  Task* dequeue() {
    lock_guard<mutex> lk(lock);
    if (tasks.empty()) return nullptr;
    Task* task = tasks[0];
    tasks.erase(tasks.begin());
    return task;
  }
};

