  mutex lock = {};

  // Function to transition a task from one state to another
  void transition(Task& task, TaskState from, TaskState to) {
    lock_guard<mutex> lk(lock);
    if (tasks_by_state.find(task.get_name()) == tasks_by_state.end()) return;
    Task* task = tasks_by_state[task.get_name()];
    if (task->get_state() != from) return;
    task->set_state(to);
  }
};

