// Protocol Adapter for IoT Sensor Data
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <stdbool.h>

// Define constants for protocol and data format
#define PROTOCOL_TYPE 1 // MQTT, HTTP, WebSocket, etc.
#define DATA_FORMAT 2 // JSON, XML, CSV, etc.

// Define structs for device data and sensor readings
struct DeviceData {
    char* deviceId;
    char* deviceType;
};
struct SensorReading {
    float temperature;
    float humidity;
};

// Function to connect to a specific protocol and data format
int connectToProtocol(char* protocol, char* dataFormat) {
    // Check if the protocol and data format are supported
    if (strcmp(protocol, "MQTT") && strcmp(dataFormat, "JSON")) {
        return -1;
    }

    // Initialize socket connection
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Error creating socket");
        exit(EXIT_FAILURE);
    }

    // Define address and port for connection
    struct sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(PORT_NUMBER);
    inet_pton(AF_INET, "localhost", &serverAddress.sin_addr);

    // Connect to the protocol and data format
    if (connect(sock, (struct sockaddr*)&serverAddress, sizeof(serverAddress)) < 0) {
        perror("Error connecting");
        exit(EXIT_FAILURE);
    }

    return sock;
}

// Function to disconnect from a specific protocol and data format
void disconnectFromProtocol(int sock, char* protocol, char* dataFormat) {
    // Check if the socket is valid and the protocol and data format are supported
    if (sock < 0 || strcmp(protocol, "MQTT") && strcmp(dataFormat, "JSON")) {
        return;
    }

    // Close the socket connection
    close(sock);
}

// Function to read sensor data from a specific protocol and data format
struct SensorReading* readSensorData(int sock, char* protocol, char* dataFormat) {
    // Check if the socket is valid and the protocol and data format are supported
    if (sock < 0 || strcmp(protocol, "MQTT") && strcmp(dataFormat, "JSON")) {
        return NULL;
    }

    // Define buffer for receiving data from the protocol and data format
    char* buffer = malloc(1024);
    int readBytes = recv(sock, buffer, 1024, 0);
    if (readBytes < 0) {
        perror("Error reading from socket");
        return NULL;
    }

    // Parse the received data and extract the sensor reading
    struct SensorReading* reading = parseSensorData(buffer, protocol, dataFormat);
    if (reading == NULL) {
        fprintf(stderr, "Error parsing sensor data\n");
        return NULL;
    }

    return reading;
}

// Function to parse sensor data from a specific protocol and data format
struct SensorReading* parseSensorData(char* data, char* protocol, char* dataFormat) {
    // Check if the protocol and data format are supported
    if (strcmp(protocol, "MQTT") && strcmp(dataFormat, "JSON")) {
        return NULL;
    }

    // Define structs for device data and sensor readings
    struct DeviceData* deviceData = malloc(sizeof(struct DeviceData));
    struct SensorReading* reading = malloc(sizeof(struct SensorReading));

    // Parse the received data and extract the device ID and type
    char* jsonBuffer = strdup(data);
    cJSON* jsonRoot = cJSON_Parse(jsonBuffer);
    if (jsonRoot == NULL) {
        fprintf(stderr, "Error parsing JSON\n");
        return NULL;
    }

    deviceData->deviceId = cJSON_GetObjectItemCaseSensitive(jsonRoot, "deviceId")->valuestring;
    deviceData->deviceType = cJSON_GetObjectItemCaseSensitive(jsonRoot, "deviceType")->valuestring;

    // Parse the received data and extract the sensor reading
    float temperature = cJSON_GetObjectItemCaseSensitive(jsonRoot, "temperature")->valueint;
    float humidity = cJSON_GetObjectItemCaseSensitive(jsonRoot, "humidity")->valuedouble;

    // Free memory and return the sensor reading
    free(deviceData);
    free(reading);
    return malloc(sizeof(struct SensorReading));
}
```
