        crc_queue.push_back(CRCIndication{crc_indications[i].rnti, RxUEInfo{crc_indications[i].rx_ue_info.cell_id, crc_indications[i].rx_ue_info.pci, crc_indications[i].rx_ue_info.crc_flag}});
