            unsigned short RNTI = (*pdu_list)[num_processed].RNTI;

            // Get CRC_INDICATION_REL8_TAG from PDU list
            unsigned char CRC_INDICATION_REL8_TAG[4] = (*pdu_list)[num_processed].CRC_INDICATION_REL8_TAG;

            // Get CRCFLAG from PDU list
