                CRC_value = get_crc_value(RX_UE_INFORMATION_TAG, RNTI);
            }

            // Create new NFAPI_CRC_INDICATION_PDU_T structure and populate it with CRC value
            NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(&new_pdu->RX_UE_INFORMATION_TAG, RX_UE_INFORMATION_TAG, 2);
            new_pdu->RNTI = RNTI;
            memcpy(&new_pdu->CRC_INDICATION_REL8_TAG, CRC_INDICATION_REL8_TAG, 4);
            new_pdu->CRCFLAG = CRCFLAG;
            if (CRCFLAG) {
                new_pdu->CRC_value = CRC_value;
            }

            // Add new PDU to list
            *pdu_list = realloc(*pdu_list, (*num_pdus + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(&(*pdu_list)[*num_pdus], new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            (*num_pdus)++;

            // Increment number of processed PDUs and number of locks
            num_processed++;
            num_locks++;
        }

        // Release mutex after processing and populating list of NFAPI_CRC_INDICATION_PDU_T structures
        pthread_mutex_unlock(&mutex);
    }
}
