#define MAX_MESSAGES 1024 // maximum number of messages in the array

typedef enum {
    LTE_DL_CCCH_MSG_TYPE_1,
    LTE_DL_CCCH_MSG_TYPE_2,
    LTE_DL_CCCH_MSG_TYPE_3
} nas_msg_type_t;

typedef struct {
    uint8_t *nas_pdu; // pointer to NAS PDU data
    size_t nas_pdu_len; // length of NAS PDU data
    uint8_t rrc_cause; // RRC cause code for the message
} nas_msg_t;

typedef struct {
    pthread_mutex_t mutex; // mutex for thread-safe access to the array
    size_t size; // current number of messages in the array
    nas_msg_t *messages[MAX_MESSAGES]; // array of NAS messages
} nas_msg_array_t;

void initialize_nas_msg_array(nas_msg_array_t *arr) {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&arr->mutex, &attr);
    arr->size = 0;
}

void destroy_nas_msg_array(nas_msg_array_t *arr) {
    for (int i = 0; i < arr->size; i++) {
        free(arr->messages[i]->nas_pdu);
        free(arr->messages[i]);
    }
    pthread_mutex_destroy(&arr->mutex);
}

void nas_msg_array_add(nas_msg_array_t *arr, uint8_t *nas_pdu, size_t nas_pdu_len, uint8_t rrc_cause) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size == MAX_MESSAGES) {
        pthread_mutex_unlock(&arr->mutex);
        return; // maximum number of messages reached, cannot add new message
    }
    nas_msg_t *new_msg = malloc(sizeof(nas_msg_t));
    if (!new_msg) {
        pthread_mutex_unlock(&arr->mutex);
        return; // failed to allocate memory for new message
    }
    new_msg->nas_pdu = nas_pdu;
    new_msg->nas_pdu_len = nas_pdu_len;
    new_msg->rrc_cause = rrc_cause;
    arr->messages[arr->size++] = new_msg;
    pthread_mutex_unlock(&arr->mutex);
}

void nas_msg_array_update(nas_msg_array_t *arr, int index, uint8_t rrc_cause) {
    if (index < 0 || index >= arr->size) {
        return; // invalid index, cannot update message
    }
    pthread_mutex_lock(&arr->mutex);
    arr->messages[index]->rrc_cause = rrc_cause;
    pthread_mutex_unlock(&arr->mutex);
}

void nas_msg_array_remove(nas_msg_array_t *arr, int index) {
    if (index < 0 || index >= arr->size) {
        return; // invalid index, cannot remove message
    }
    pthread_mutex_lock(&arr->mutex);
    nas_msg_t *removed_msg = arr->messages[index];
    free(removed_msg->nas_pdu);
    free(removed_msg);
    for (int i = index + 1; i < arr->size - 1; i++) {
        arr->messages[i - 1] = arr->messages[i];
    }
    arr->size--;
    pthread_mutex_unlock(&arr->mutex);
}
