import os
import hashlib
from concurrent.futures import ProcessPoolExecutor
from datetime import datetime
from enum import Enum

class HashType(Enum):
    MD5 = 1
    SHA256 = 2
    CUSTOM = 3

class HashCalculator:
    def __init__(self, hash_type: HashType, worker_count: int):
        self.hash_type = hash_type
        self.worker_count = worker_count
        self.executor = ProcessPoolExecutor(max_workers=worker_count)

    def calculate_hash(self, file_path: str) -> str:
        with open(file_path, "rb") as f:
            if self.hash_type == HashType.MD5:
                return hashlib.md5(f.read()).hexdigest()
            elif self.hash_type == HashType.SHA256:
                return hashlib.sha256(f.read()).hexdigest()
            else:
                raise NotImplementedError("Unsupported hash type")

    def calculate_file_hashes(self, file_paths: list) -> dict:
        futures = []
        for path in file_paths:
            futures.append(self.executor.submit(self.calculate_hash, path))

        hashes = {}
        for future in futures:
            try:
                hashes[future.result()] = future.exception()
            except Exception as e:
                hashes[future.result()] = e

        return hashes

    def monitor_hashes(self, file_paths: list) -> None:
        for path in file_paths:
            start_time = datetime.now()
            hash = self.calculate_hash(path)
            end_time = datetime.now()
            print(f"Hash calculation for {path} completed in {end_time - start_time}.")

    def monitor_and_report_errors(self, file_paths: list) -> None:
        error_log = {}
        for path in file_paths:
            try:
                self.monitor_hashes([path])
            except Exception as e:
                error_log[path] = e
        print("Error log:\n")
        for path, err in error_log.items():
            print(f"{path}: {err}")
