using namespace std;

class DynamicHttpCache {
private:
    // Define the HTTP request PDU structure
    struct HTTP_REQUEST_PDU_T {
        string method;
        string url;
        vector<string> headers;
        string body;
    };

    // Define the cache entry structure
    struct CacheEntry {
        HTTP_REQUEST_PDU_T request;
        bool inUse;
        chrono::time_point<chrono::system_clock> lastAccessTime;
    };

    // Define the eviction strategy
    enum EvictionStrategy {
        LRU = 0,
        Random = 1
    };

    // Define the cache size
    const int MAX_CACHE_SIZE = 5 * 1024 * 1024;

    // Define the maximum number of threads
    const int MAX_THREADS = 8;

    // Define the eviction strategy
    EvictionStrategy evictionStrategy = LRU;

    // Define the cache map
    unordered_map<string, CacheEntry> cacheMap;

    // Define the mutex for protecting the cache map
    mutex cacheLock;

    // Define the condition variable for waiting on threads
    condition_variable threadWait;

    // Define the number of threads in use
    int numThreads = 0;

    // Define the next thread to be used
    int nextThread = 0;

public:
    // Constructor
    DynamicHttpCache() { }

    // Destructor
    ~DynamicHttpCache() { }

    // Put a request in the cache
    void put(HTTP_REQUEST_PDU_T& request) {
        unique_lock<mutex> lock(cacheLock);

        // Check if the cache is full
        if (cacheMap.size() >= MAX_CACHE_SIZE) {
            // Evict an entry from the cache
            evict();
        }

        // Create a new cache entry
        CacheEntry* newEntry = new CacheEntry;
        newEntry->request = request;
        newEntry->inUse = true;
        newEntry->lastAccessTime = chrono::system_clock::now();

        // Add the entry to the cache map
        cacheMap.insert({newEntry->request.url, *newEntry});
    }

    // Get a request from the cache
    HTTP_REQUEST_PDU_T* get(string url) {
        unique_lock<mutex> lock(cacheLock);

        // Check if the cache contains the requested URL
        auto it = cacheMap.find(url);
        if (it == cacheMap.end()) {
            return NULL;
        }

        // Mark the entry as in use
        it->second.inUse = true;

        // Update the last access time
        it->second.lastAccessTime = chrono::system_clock::now();

        // Return a copy of the request
        return new HTTP_REQUEST_PDU_T(it->second.request);
    }

    // Evict an entry from the cache
    void evict() {
        unique_lock<mutex> lock(cacheLock);

        // Check if there are any entries in the cache
        if (cacheMap.empty()) {
            return;
        }

        // Determine which strategy to use for eviction
        switch (evictionStrategy) {
            case LRU:
                // Evict the least recently used entry
                auto it = cacheMap.begin();
                while (it != cacheMap.end() && it->second.inUse) {
                    ++it;
                }
                if (it == cacheMap.end()) {
                    return;
                }
                cacheMap.erase(it);
                break;
            case Random:
                // Evict a random entry
                auto it = cacheMap.begin();
                advance(it, rand() % cacheMap.size());
                while (it != cacheMap.end() && it->second.inUse) {
                    ++it;
                }
                if (it == cacheMap.end()) {
                    return;
                }
                cacheMap.erase(it);
                break;
        }
    }

    // Get the current size of the cache
    int getSize() {
        unique_lock<mutex> lock(cacheLock);
        return cacheMap.size();
    }

    // Set the eviction strategy
    void setEvictionStrategy(int strategy) {
        unique_lock<mutex> lock(cacheLock);
        evictionStrategy = (strategy == LRU) ? LRU : Random;
    }
};
