    collection->message_types = NULL;
    collection->num_message_types = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void add_LTE_RRC_CU_MessageType(LTE_RRC_CU_MessageCollection *collection, const char *name, uint16_t version) {
