            free(collection->message_types[i].name);
            memmove(&collection->message_types[i], &collection->message_types[i + 1], (collection->num_message_types - i - 1) * sizeof(LTE_RRC_CU_MessageType));
            collection->num_message_types--;
            break;
        }
    }
}

void set_LTE_RRC_CU_MessageData(LTE_RRC_CU_MessageCollection *collection, const char *name, uint16_t version, void *data, size_t size) {
