    for (i = 0; i < collection->num_message_types; i++) {
        if (strcmp(collection->message_types[i].name, name) == 0 &&
                collection->message_types[i].version == version) {
            free(collection->message_types[i].data);
            collection->message_types[i].data = data;
            collection->message_types[i].size = size;
            return;
        }
    }
}

void *get_LTE_RRC_CU_MessageData(LTE_RRC_CU_MessageCollection *collection, const char *name, uint16_t version) {
