        if (strcmp(collection->message_types[i].name, name) == 0 &&
                collection->message_types[i].version == version) {
            return collection->message_types[i].data;
        }
    }
    return NULL;
}

void release_LTE_RRC_CU_MessageCollection(LTE_RRC_CU_MessageCollection *collection) {
    size_t i;
    for (i = 0; i < collection->num_message_types; i++) {
        free(collection->message_types[i].name);
        if (collection->message_types[i].data != NULL) {
