#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <assert.h>

// Config struct to store configuration data
typedef struct {
    char* name;
    char* value;
} config_t;

// Configuration list struct to store multiple configurations
typedef struct {
    int count;
    config_t** configs;
} config_list_t;

// Schema for validating configurations against
static const char* schema = "{\"type\": \"object\",\"properties\": {\"name\": {\"type\": \"string\"}, \"value\": {\"type\": \"string\"}}}";

// Function to validate a configuration against the schema
bool validate_config(const config_t* config) {
    // Use JSON schema library to validate config against schema
    return json_schema_validate(config, schema);
}

// Function to add a new configuration to the list
void add_config(config_list_t* list, const char* name, const char* value) {
    // Create a new config struct and initialize it with the provided values
    config_t* config = malloc(sizeof(config_t));
    config->name = strdup(name);
    config->value = strdup(value);

    // Add the new config to the list of configurations
    if (list->count == 0) {
        list->configs = malloc(sizeof(config_t*));
    } else {
        list->configs = realloc(list->configs, (list->count + 1) * sizeof(config_t*));
    }

    list->configs[list->count++] = config;
}

// Function to remove a configuration from the list by name
void remove_config(config_list_t* list, const char* name) {
    // Find the index of the configuration to be removed
    int index = -1;
    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->configs[i]->name, name) == 0) {
            index = i;
            break;
        }
    }

    // Remove the configuration from the list
    if (index != -1) {
        for (int i = index; i < list->count - 1; i++) {
            list->configs[i] = list->configs[i + 1];
        }

        free(list->configs[--list->count]);
    }
}

// Function to update a configuration in the list by name
void update_config(config_list_t* list, const char* name, const char* value) {
    // Find the index of the configuration to be updated
    int index = -1;
    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->configs[i]->name, name) == 0) {
            index = i;
            break;
        }
    }

    // Update the configuration in the list
    if (index != -1) {
        free(list->configs[index]->value);
        list->configs[index]->value = strdup(value);
    } else {
        add_config(list, name, value);
    }
}

// Function to get a configuration from the list by name
const char* get_config(config_list_t* list, const char* name) {
    // Find the index of the configuration to be retrieved
    int index = -1;
    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->configs[i]->name, name) == 0) {
            index = i;
            break;
        }
    }

    // Return the configuration value or NULL if not found
    return index != -1 ? list->configs[index]->value : NULL;
}

// Function to initialize a new configuration list
void init_config_list(config_list_t* list) {
    list->count = 0;
    list->configs = malloc(sizeof(config_t*) * 16);
}

// Function to destroy an existing configuration list
void destroy_config_list(config_list_t* list) {
    for (int i = 0; i < list->count; i++) {
