    pool->buffer_size = size;
    pthread_mutex_init(&pool->mutex, NULL);
}

// Define a function for allocating memory from the pool
void* allocate_memory(MemoryPool* pool, size_t size) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&pool->mutex);
    void* mem = (uint8_t*)malloc(size);
    if (mem == NULL) {
        // Log an error message and exit the function if memory allocation fails
        fprintf(stderr, "Error: Out of memory\n");
