    @Bean
    public CaffeineCache caffeineCache() {
        CaffeineCache cache = new CaffeineCache("pokemon-cache");
        cache.setCaffeine(Caffeine.newBuilder().expireAfterWrite(5, TimeUnit.MINUTES));
        return cache;
    }

    @Bean
    public Resilience4jCircuitBreakerFactory resilience4jCircuitBreakerFactory() {
        return new Resilience4jCircuitBreakerFactory();
    }

    @Bean
    public RateLimiter rateLimiter() {
        return new TokenBucketRateLimiter(5, 10);
    }

    @Bean
    public HttpSecurity httpSecurity() throws Exception {
        return new HttpSecurity(new HttpsConfigurer(), new AuthConfigurer());
    }

    @Bean
    public ThreadPoolTaskExecutor threadPoolTaskExecutor() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(10);
        executor.setMaxPoolSize(20);
        executor.setQueueCapacity(500);
        executor.setRejectedExecutionHandler(new ThreadPoolExecutor.CallerRunsPolicy());
        return executor;
    }
}
```

