public class EventStreamProcessor {
  private final String messageBroker; // e.g., Kafka or RabbitMQ
  private final int bufferSize; // e.g., 10,000 messages
  private final Map<String, MessageBuffer> buffers = new ConcurrentHashMap<>();

  public EventStreamProcessor(String messageBroker, int bufferSize) {
    this.messageBroker = messageBroker;
    this.bufferSize = bufferSize;
  }

  public void processEvent(String eventId, String eventData) {
    MessageBuffer buffer = getOrCreateBuffer(eventId);
    buffer.addMessage(eventData);
  }

  private MessageBuffer getOrCreateBuffer(String eventId) {
    return buffers.computeIfAbsent(eventId, id -> new MessageBuffer(id, bufferSize));
  }

  public void consumeMessages() {
    for (MessageBuffer buffer : buffers.values()) {
      consumeBuffer(buffer);
    }
  }

  private void consumeBuffer(MessageBuffer buffer) {
    // Implement your backpressure mechanism here, e.g., using a semaphore to limit the number of messages being processed simultaneously
    int numMessages = buffer.size();
    for (int i = 0; i < numMessages; i++) {
      String eventData = buffer.removeMessage(i);
      // Process the message here, e.g., by sending it to an external service or storing it in a database
    }
  }
}

class MessageBuffer {
  private final String id;
  private final int size;
  private final List<String> messages = new ArrayList<>();

  public MessageBuffer(String id, int size) {
    this.id = id;
    this.size = size;
  }

  public void addMessage(String message) {
    if (messages.size() >= size) {
      throw new IllegalStateException("Buffer is full");
    }
    messages.add(message);
  }

  public String removeMessage(int index) {
    return messages.remove(index);
  }

  public int size() {
    return messages.size();
  }
}
