import json
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime
from typing import Dict, List, Any

class MessageBroker:
    def __init__(self):
        self.producers = set()
        self.consumers = dict()
        self.messages = list()
        self.executor = ThreadPoolExecutor(max_workers=10)

    def add_producer(self, producer: Any) -> None:
        self.producers.add(producer)

    def remove_producer(self, producer: Any) -> None:
        self.producers.remove(producer)

    def add_consumer(self, consumer: Any) -> None:
        self.consumers[consumer] = list()

    def remove_consumer(self, consumer: Any) -> None:
        del self.consumers[consumer]

    def send_message(self, message: Dict[str, str]) -> None:
        self.messages.append(message)
        self.executor.submit(self.process_messages)

    def process_messages(self) -> None:
        for consumer in self.consumers:
            messages = self.consumers[consumer]
            while len(messages) > 0:
                message = messages.pop(0)
                consumer.process_message(message)

    def handle_producer_error(self, producer: Any, error: Exception) -> None:
        self.producers.remove(producer)
        if len(self.producers) == 0:
            raise RuntimeError("No producers available.") from error

    def handle_consumer_error(self, consumer: Any, error: Exception) -> None:
        self.consumers[consumer].clear()

class ProducerService:
    def __init__(self):
        self.message_broker = MessageBroker()

    def send_message(self, message: Dict[str, str]) -> None:
        try:
            self.message_broker.send_message(message)
        except RuntimeError as error:
            if "No producers available." in str(error):
                self.message_broker.add_producer(self)
                self.message_broker.send_message(message)

    def handle_error(self, error: Exception) -> None:
        self.message_broker.handle_producer_error(self, error)

class ConsumerService:
    def __init__(self):
        self.message_broker = MessageBroker()
        self.message_broker.add_consumer(self)

    def process_message(self, message: Dict[str, str]) -> None:
        pass # implement message processing logic here

    def handle_error(self, error: Exception) -> None:
        self.message_broker.handle_consumer_error(self, error)
```
