// activity_list.hpp
#include <forward_list>
#include <string>
#include <unordered_set>
#include <chrono>
#include <mutex>
#include <thread>

class ActivityList {
public:
    // constructor
    explicit ActivityList(const std::string& data_source,
                          const Comparator& comparator = DefaultComparator());

    // add activity to the list
    void addActivity(const std::string& activity);

    // fetch updates from external data source and append them to the list
    void updateList();

    // return a copy of the activity list
    std::forward_list<std::string> getActivities() const;

private:
    // data members
    std::string m_data_source;
    std::mutex m_mutex;
    std::chrono::steady_clock::time_point m_last_update;
    std::unordered_set<std::string> m_unique_activities;
    std::forward_list<std::string> m_activity_list;

    // comparator for sorting and comparing strings
    Comparator m_comparator;

    // function to update the activity list from external data source
    void fetchUpdates();
};

// default comparator for strings
struct DefaultComparator {
    bool operator()(const std::string& s1, const std::string& s2) const {
        return s1 < s2;
    }
};

// implementation of ActivityList class methods
ActivityList::ActivityList(const std::string& data_source,
                           const Comparator& comparator)
    : m_data_source(data_source), m_last_update(std::chrono::steady_clock::now()),
      m_comparator(comparator) {}

void ActivityList::addActivity(const std::string& activity) {
    // lock the mutex to prevent concurrent updates
    std::lock_guard<std::mutex> lock(m_mutex);

    // check if the activity already exists in the list
    if (m_unique_activities.find(activity) == m_unique_activities.end()) {
        // add the activity to the unique activities set and the activity list
        m_unique_activities.insert(activity);
        m_activity_list.push_front(activity);
    }
}

void ActivityList::updateList() {
    // lock the mutex to prevent concurrent updates
    std::lock_guard<std::mutex> lock(m_mutex);

    // fetch updates from external data source and append them to the list
    fetchUpdates();
}

std::forward_list<std::string> ActivityList::getActivities() const {
    return m_activity_list;
}

void ActivityList::fetchUpdates() {
    // check if it's time for an update
    auto now = std::chrono::steady_clock::now();
    if (std::chrono::duration_cast<std::chrono::seconds>(now - m_last_update).count() < 60) {
        // not enough time has passed since the last update, return
        return;
    }

    // fetch updates from external data source
    std::vector<std::string> new_activities = fetchUpdatesFromDataSource();

    // lock the mutex to prevent concurrent updates
    std::lock_guard<std::mutex> lock(m_mutex);

    // update the activity list with the new activities
    for (const auto& activity : new_activities) {
        if (m_unique_activities.find(activity) == m_unique_activities.end()) {
            // add the activity to the unique activities set and the activity list
            m_unique_activities.insert(activity);
            m_activity_list.push_front(activity);
        }
    }

    // update the last update time
    m_last_update = now;
}

std::vector<std::string> ActivityList::fetchUpdatesFromDataSource() {
    // fetch updates from external data source using m_data_source
    std::vector<std::string> new_activities;
    // parse the response and extract the activities
    return new_activities;
}

// unit tests for ActivityList class
#include <gtest/gtest.h>

TEST(ActivityListTest, AddActivity) {
    ActivityList list("data_source");
    std::string activity = "activity1";
    list.addActivity(activity);
    EXPECT_EQ(list.getActivities().front(), activity);
}

TEST(ActivityListTest, UpdateList) {
    ActivityList list("data_source");
    list.updateList();
    EXPECT_TRUE(!list.getActivities().empty());
}

TEST(ActivityListTest, GetActivities) {
    ActivityList list("data_source");
    std::string activity = "activity1";
    list.addActivity(activity);
    auto activities = list.getActivities();
    EXPECT_EQ(activities.front(), activity);
}

