namespace Logging {
    class Logger {
    public:
        enum class Level { DEBUG, INFO, WARNING, ERROR, CRITICAL };
        static const char* GetLevelString(Level level) {
            switch (level) {
                case Level::DEBUG: return "DEBUG";
                case Level::INFO: return "INFO";
                case Level::WARNING: return "WARNING";
                case Level::ERROR: return "ERROR";
                case Level::CRITICAL: return "CRITICAL";
            }
        }
    private:
        std::string _logFilePath;
        std::ofstream _fileStream;
        std::mutex _fileMutex;
        std::atomic<Level> _defaultLogLevel;
        std::unordered_map<std::thread::id, Level> _threadLogLevels;
        std::condition_variable _cv;
        std::mutex _cvMutex;
        std::vector<std::unique_ptr<std::ofstream>> _asyncFileStreams;
        std::unordered_map<Level, std::string> _levelToConsoleOutputMap;

        void InitAsyncFiles() {
            // Initialize the async file streams with the default log level and output destination
            for (int i = 0; i < _asyncFileStreams.size(); ++i) {
                _asyncFileStreams[i] = std::make_unique<std::ofstream>();
                _asyncFileStreams[i]->open(_logFilePath, std::ios::out | std::ios::app);
            }
        }

        void Log(Level level, const char* message) {
            // Acquire the file mutex to write to the log file
            std::unique_lock<std::mutex> lock(_fileMutex);
            _fileStream << GetLevelString(level) << ": " << message << std::endl;
        }

        void AsyncLog(Level level, const char* message) {
            // Acquire the async file stream mutex to write to one of the async file streams
            std::unique_lock<std::mutex> lock(_asyncFileStreams[i]->get_mutex());
            _asyncFileStreams[i] << GetLevelString(level) << ": " << message << std::endl;
        }

        void ConsoleLog(Level level, const char* message) {
            // Acquire the console mutex to write to stdout/stderr
            std::lock_guard<std::mutex> lock(_cvMutex);
            std::cout << GetLevelString(level) << ": " << message << std::endl;
        }

    public:
        Logger(const char* logFilePath, Level defaultLogLevel = Level::INFO, int numAsyncFiles = 0) : _logFilePath(logFilePath), _defaultLogLevel(defaultLogLevel) {
            // Initialize the async file streams and console output map with the given configuration
            for (int i = 0; i < numAsyncFiles; ++i) {
                _asyncFileStreams.emplace_back(new std::ofstream());
                _asyncFileStreams[i]->open(_logFilePath, std::ios::out | std::ios::app);
            }
            for (int i = 0; i < static_cast<int>(Level::NUM_LEVELS); ++i) {
                _levelToConsoleOutputMap.emplace(static_cast<Level>(i), "");
            }
        }

        void SetDefaultLogLevel(Level level) {
            // Acquire the log mutex and set the default log level
            std::unique_lock<std::mutex> lock(_fileMutex);
            _defaultLogLevel = level;
        }

        Level GetDefaultLogLevel() const {
            // Acquire the log mutex and return the current default log level
            std::unique_lock<std::mutex> lock(_fileMutex);
            return _defaultLogLevel;
        }

        void SetThreadLogLevel(Level level) {
            // Acquire the log mutex and set the thread-local log level
            std::unique_lock<std::mutex> lock(_fileMutex);
            _threadLogLevels[std::this_thread::get_id()] = level;
        }

        Level GetThreadLogLevel() const {
            // Acquire the log mutex and return the current thread-local log level
            std::unique_lock<std::mutex> lock(_fileMutex);
            auto it = _threadLogLevels.find(std::this_thread::get_id());
            if (it != _threadLogLevels.end()) {
                return it->second;
            } else {
                return Level::INFO;
            }
        }

        void LogMessage(const char* message) const {
            // Acquire the log mutex and write to the file stream, console output, or both
            std::unique_lock<std::mutex> lock(_fileMutex);
            if (_defaultLogLevel >= Level::DEBUG || _threadLogLevels.find(std::this_thread::get_id()) != _threadLogLevels.end()) {
                Log(_defaultLogLevel, message);
                ConsoleLog(_defaultLogLevel, message);
            }
        }

        void AsyncLogMessage(const char* message) const {
            // Acquire the log mutex and write to one of the async file streams or console output
            std::unique_lock<std::mutex> lock(_fileMutex);
            if (_defaultLogLevel >= Level::DEBUG || _threadLogLevels.find(std::this_thread::get_id()) != _threadLogLevels.end()) {
                AsyncLog(_defaultLogLevel, message);
                ConsoleLog(_defaultLogLevel, message);
            }
        }

        void SubmitToRemoteServer(const char* message) const {
            // Acquire the log mutex and use an external logging API to submit the log message to a remote server
            std::unique_lock<std::mutex> lock(_fileMutex);
            if (_defaultLogLevel >= Level::DEBUG || _threadLogLevels.find(std::this_thread::get_id()) != _threadLogLevels.end()) {
                // Use an external logging API to submit the log message to a remote server
                // Example:
                //   extern void SubmitLogToRemoteServer(const char* message);
                //   SubmitLogToRemoteServer(message);
            }
        }
    };
}']

