const bookNamePatterns = [
  // Old Testament books
  /^Genesis$/,
  /^Exodus$/,
  /^Leviticus$/,
  /^Numbers$/,
  /^Deuteronomy$/,
  /^Joshua$/,
  /^Judges$/,
  /^Ruth$/,
  /^1 Samuel$/,
  /^2 Samuel$/,
  /^1 Kings$/,
  /^2 Kings$/,
  /^1 Chronicles$/,
  /^2 Chronicles$/,
  /^Ezra$/,
  /^Nehemiah$/,
  /^Esther$/,
  /^Job$/,
  /^Psalms$/,
  /^Proverbs$/,
  /^Ecclesiastes$/,
  /^Song of Solomon$/,
  /^Isaiah$/,
  /^Jeremiah$/,
  /^Lamentations$/,
  /^Ezekiel$/,
  /^Daniel$/,
  /^Hosea$/,
  /^Joel$/,
  /^Amos$/,
  /^Obadiah$/,
  /^Jonah$/,
  /^Micah$/,
  /^Nahum$/,
  /^Habakkuk$/,
  /^Zephaniah$/,
  /^Haggai$/,
  /^Zechariah$/,
  /^Malachi$/,
];

// Define metadata types and relevance levels
const metadata = {
  narrative: ['primary', 'secondary'],
  poetry: ['primary', 'secondary'],
  historicalContext: ['primary', 'secondary'],
};

// Define a function to match book names using regex patterns
function matchBookName(text) {
  for (const pattern of bookNamePatterns) {
    if (pattern.test(text)) return true;
  }
  return false;
}

// Define a function to validate book names against the external API
async function validateBookName(name) {
  const headers = apiHeaders;
  const body = JSON.stringify({ name });
  try {
    const response = await axios.post(apiUrl, body, headers);
    return response.data.valid;
  } catch (error) {
    console.log(`Error validating book name: ${name}`);
    throw error;
  }
}

// Define a function to process a single document and extract references to Old Testament books
async function processDocument(document, callback) {
  const $ = cheerio.load(document);
  let references = [];

  // Match book names in the document using regex patterns
  $('span').each((i, element) => {
    if (matchBookName($(element).text())) {
      references.push({
        name: $(element).text(),
        sectionType: 'narrative',
      });
    }
  });

  // Validate book names against the external API and count occurrences
  const validReferences = await Promise.all(references.map((reference) => validateBookName(reference.name)));
  const counts = validReferences.reduce((counts, isValid) => {
    if (isValid) {
      counts[reference.name] = (counts[reference.name] || 0) + 1;
    }
    return counts;
  }, {});

  // Filter out tertiary sections and count occurrences of each book name across primary and secondary sections
  const sectionCounts = {};
  $('section').each((i, element) => {
    if (metadata[$(element).attr('type')].includes($(element).attr('relevance'))) {
      $(element).find('span').each((j, childElement) => {
        const bookName = $(childElement).text();
        if (counts[bookName]) {
          sectionCounts[bookName] = (sectionCounts[bookName] || 0) + 1;
        }
      });
    }
  });

  // Maintain a distributed cache to minimize repeated API calls for validation
  const cachedBookNames = [];
  Object.keys(counts).forEach((bookName) => {
    if (validateBookName(bookName)) {
      cachedBookNames.push({ bookName, count: counts[bookName] });
    }
  });
  cache.put('cachedBookNames', cachedBookNames);

  // Implement a robust error handling mechanism to manage unexpected input formats, missing metadata, and API call failures
  if (references.length === 0) {
    console.log(`No references found in document`);
    return callback(null, { references: [], counts });
  } else if (!document.metadata || !document.metadata.type || !metadata[document.metadata.type].includes(document.metadata.relevance)) {
    console.log(`Invalid metadata format or relevance level`);
    return callback(null, { references: [], counts });
  } else if (cachedBookNames.length === 0) {
    console.log(`No valid book names found in cache`);
    return callback(null, { references: [], counts });
  } else {
    return callback(null, { references, counts });
  }
}

// Define a function to process multiple documents simultaneously and ensure the service can handle peak loads without degradation
async function processDocuments(documents) {
  const documentResults = [];
  for (const document of documents) {
    try {
      const result = await processDocument(document);
      documentResults.push({
        document,
        result,
      });
    } catch (error) {
      console.log(`Error processing document: ${document}`);
    }
  }
  return documentResults;
}

// Export the processDocument and processDocuments functions as a module
module.exports = {
  processDocument,
  processDocuments,
};
```
This implementation uses Node.js's built-in `async` library for asynchronous operations and `cheerio` for parsing HTML documents. It also uses an external API to validate book names against a canonical list and caches the results in memory using the `memory-cache` module. The service implements robust error handling mechanisms to manage unexpected input formats, missing metadata, and API call failures, as well as optimizations for performance and scalability."]

