from typing import List, Dict, Union
from requests import get, post
from cachecontrol import CacheControl
from cachecontrol.caches.file_cache import FileCache
from pyformance import metrics
from pyformance.registry import CollectorRegistry

class ScriptLoader:
    def __init__(self, script_service: str = "https://script-management-service.com"):
        self.script_service = script_service
        self.cache = FileCache(".cache")
        self.script_mapping = {}

    def load_scripts(self, roles: List[str], device_types: List[str], locations: List[str]):
        """Loads the appropriate scripts for the given user based on their roles, device types, and geographic locations."""
        # Calculate the script hashes based on the provided information
        script_hashes = []
        for role in roles:
            for device_type in device_types:
                for location in locations:
                    script_hashes.append(self._calculate_script_hash(role, device_type, location))

        # Check if the scripts are already cached
        loaded_scripts = self.cache.get_many(script_hashes)
        if len(loaded_scripts) == len(script_hashes):
            return loaded_scripts

        # Fetch and cache the missing scripts
        for script_hash in set(script_hashes) - set(loaded_scripts):
            script = self._fetch_script(script_hash)
            if script:
                self.cache.set(script_hash, script)
                loaded_scripts.append(script)

        return loaded_scripts

    def _calculate_script_hash(self, role, device_type, location):
        """Calculates a unique hash for the given script based on its content."""
        # Calculate the SHA-256 hash of the script content
        script_content = self._fetch_script_content(role, device_type, location)
        if not script_content:
            return None
        else:
            return hashlib.sha256(script_content).hexdigest()

    def _fetch_script(self, script_hash):
        """Fetches the script with the given hash from the script management service."""
        # Create a new cache entry if necessary
        if not self.cache.get(script_hash):
            self.cache.set(script_hash, "")

        # Retrieve the script content from the cache
        script_content = self.cache.get(script_hash)
        if not script_content:
            return None

        # Parse the script and extract its content
        try:
            script = json.loads(script_content)
        except ValueError:
            return None
        else:
            return script["content"]

    def _fetch_script_content(self, role, device_type, location):
        """Fetches the content of the script for the given user based on their roles, device types, and geographic locations."""
        # Construct the URL for the script management service
        url = f"{self.script_service}/scripts?role={role}&device_type={device_type}&location={location}"

        # Fetch the script content from the service
        response = get(url, timeout=10)
        if not response or response.status_code != 200:
            return None
        else:
            return response.content

    def _fetch_script_from_cache(self, script_hash):
        """Fetches the script with the given hash from the cache."""
        # Check if the script is cached
        if self.cache.get(script_hash):
            return self.cache.get(script_hash)
        else:
            return None

    def _fetch_script_from_service(self, script_hash):
        """Fetches the script with the given hash from the script management service."""
        # Construct the URL for the script management service
        url = f"{self.script_service}/scripts?hash={script_hash}"

        # Fetch the script content from the service
        response = get(url, timeout=10)
        if not response or response.status_code != 200:
            return None
        else:
            return response.content

    def _cache_script(self, script_hash, script_content):
        """Caches the given script content with the given hash."""
        # Set the cache entry for the script hash
        self.cache.set(script_hash, script_content)

    def _invalidate_cache(self, script_hash):
        """Invalidates the cache entry for the given script hash."""
        # Delete the cache entry for the script hash
        self.cache.delete(script_hash)
