                                .filter(t -> t.getTransactionId().equals(transactionId))
                                .forEach(t -> t.setRiskClassification(""));
                        } else if (anomalyType.equalsIgnoreCase("unknown")) {
                            // Ignore the transaction for now, may be handled later based on other rules
