                            throw new IllegalArgumentException("Invalid anomaly type: " + anomalyType);
                        }
                    }
                } else {
                    throw new IllegalArgumentException("Received alert with empty transaction ID or session ID");
                }
            } else {
                throw new IllegalArgumentException("Received alert with invalid format: " + alert);
            }
        } else {
            throw new IllegalArgumentException("Received null or empty alert");
        }
    }

    private Session getSession(String sessionId, long timestamp) {
        // Get the current session from cache or create a new one if it doesn't exist
        return sessionsBySessionId.computeIfAbsent(sessionId, k -> new Session(sessionId, timestamp));
    }

    private void scheduleSessionExpiry(String sessionId, int duration) {
        // Schedule the session to expire after a certain time
        TimerTask task = new TimerTask() {
            @Override
            public void run() {
                sessionsBySessionId.remove(sessionId);
            }
        };
        Timer timer = new Timer();
        timer.schedule(task, duration * 1000L); // Convert seconds to milliseconds
    }

