    PacketProcessor(int maxQueueSize = 1000, int minProcessingDelay = 100) {
        this->maxQueueSize = maxQueueSize;
        this->minProcessingDelay = minProcessingDelay;
        this->queue = new std::list<Packet>();
    }

    // Destructor
