        // Calculate packet relevance score based on associated metadata
        double relevanceScore = calculateRelevanceScore(packet.metadata);

        // Check if packet is eligible for processing
        bool isEligibleForProcessing = (packet.timestamp + 60) > std::time(nullptr);

        // Check if queue is full and needs to be flushed
        bool shouldFlushQueue = this->queue->size() >= this->maxQueueSize;

        // Add packet to the queue
        this->queue->push_back(packet);

        // Check if there are other packets in the queue that can be processed
        for (auto it = this->queue->begin(); it != this->queue->end(); ++it) {
            Packet& currentPacket = *it;

            // Check if packet is eligible for processing
            if (!currentPacket.processed && currentPacket.timestamp + 60 > std::time(nullptr)) {
                // Calculate cumulative bandwidth usage over the last 60 seconds
                double cumulativeBandwidthUsage = calculateCumulativeBandwidthUsage(currentPacket);

                // Check if packet is eligible for processing based on cumulative bandwidth usage
                bool isEligibleForProcessing = (cumulativeBandwidthUsage / 60) < this->maxQueueSize;

                // Check if the current packet has a higher priority than the other packets in the queue
                bool hasHigherPriorityThanOtherPackets = currentPacket.priority > this->queue->back().priority;

                // Check if the current packet has a lower age than the other packets in the queue
                bool hasLowerAgeThanOtherPackets = currentPacket.timestamp < this->queue->back().timestamp;

                // Check if the current packet should be processed based on its relevance score and eligibility for processing
                if (isEligibleForProcessing && isEligibleForProcessing && hasHigherPriorityThanOtherPackets && hasLowerAgeThanOtherPackets) {
                    // Process the current packet
                    processPacket(currentPacket);

                    // Mark the current packet as processed
                    currentPacket.processed = true;
                }
            }
        }

        // Check if the queue should be flushed
        if (shouldFlushQueue) {
            // Flush the queue
            flushQueue();
        }
    }

