        for (auto it = this->queue->begin(); it != this->queue->end(); ++it) {
            Packet& currentPacket = *it;

            // Check if the current packet should be processed based on its relevance score and eligibility for processing
            if (!currentPacket.processed && currentPacket.timestamp + 60 > std::time(nullptr)) {
                // Process the current packet
