using namespace std;

int main() {
    // Declare variables
    string input_file = "input.txt";
    vector<string> lines;
    int num_lines = 0;
    bool is_error = false;

    // Open the file and read each line into a vector
    ifstream file(input_file);
    if (file.is_open()) {
        string line;
        while (getline(file, line)) {
            lines.push_back(line);
        }
        num_lines = lines.size();
    } else {
        cout << "Error opening file: " << input_file << endl;
        is_error = true;
    }

    // Check for errors and close the file
    if (is_error) {
        file.close();
        return 1;
    } else {
        file.close();
    }

    // Print the number of lines in the file
    cout << "Number of lines in the file: " << num_lines << endl;

    // Process each line in the vector and perform operations as needed
    for (int i = 0; i < num_lines; i++) {
        string line = lines[i];
        // Perform operations on the line, such as parsing or transforming data
    }

    return 0;
}
