class Schema {
public:
    virtual ~Schema() = default;

    // validate the given data against this schema
    virtual bool validate(const std::string& data) const = 0;
};

class OAuth2Token {
public:
    virtual ~OAuth2Token() = default;

    // get the access token for the given resource and scope
    virtual std::string getAccessToken(const std::string& resource, const std::string& scope) = 0;
};

class SchemaLoader {
public:
    static std::unique_ptr<Schema> loadSchema(const std::string& schemaUrl);
};

// a cache for loaded schemas
class SchemaCache : public std::map<std::string, std::shared_ptr<Schema>> {
public:
    // add a new schema to the cache
    void addSchema(const std::string& schemaUrl, const std::shared_ptr<Schema>& schema);

    // get an existing schema from the cache
    std::shared_ptr<Schema> getSchema(const std::string& schemaUrl);
};

// a cache for OAuth2 tokens
class TokenCache : public std::map<std::string, std::unique_ptr<OAuth2Token>> {
public:
    // add a new token to the cache
    void addToken(const std::string& resource, const std::string& scope, const std::unique_ptr<OAuth2Token>& token);

    // get an existing token from the cache
    std::unique_ptr<OAuth2Token> getToken(const std::string& resource, const std::string& scope);
};

class SchemaValidator {
public:
    // validate the given data against the given schema
    bool validate(const std::string& schemaUrl, const std::string& data) const;

private:
    // the cache for loaded schemas
    SchemaCache schemaCache_;

    // the cache for OAuth2 tokens
    TokenCache tokenCache_;
};

std::unique_ptr<Schema> SchemaLoader::loadSchema(const std::string& schemaUrl) {
    auto schema = std::make_unique<Schema>();
    // load the schema from the given URL
    // ...
    return schema;
}

void SchemaCache::addSchema(const std::string& schemaUrl, const std::shared_ptr<Schema>& schema) {
    (*this)[schemaUrl] = schema;
}

std::shared_ptr<Schema> SchemaCache::getSchema(const std::string& schemaUrl) {
    auto it = this->find(schemaUrl);
    if (it != this->end()) {
        return it->second;
    } else {
        // load the schema from the given URL and add it to the cache
        auto schema = SchemaLoader::loadSchema(schemaUrl);
        this->addSchema(schemaUrl, schema);
        return schema;
    }
}

void TokenCache::addToken(const std::string& resource, const std::string& scope, const std::unique_ptr<OAuth2Token>& token) {
    (*this)[resource + ":" + scope] = token;
}

std::unique_ptr<OAuth2Token> TokenCache::getToken(const std::string& resource, const std::string& scope) {
    auto it = this->find(resource + ":" + scope);
    if (it != this->end()) {
        return it->second;
    } else {
        // get the access token for the given resource and scope from the OAuth2 server
        // ...
        return std::unique_ptr<OAuth2Token>(new OAuth2Token());
    }
}

bool SchemaValidator::validate(const std::string& schemaUrl, const std::string& data) const {
    auto schema = schemaCache_.getSchema(schemaUrl);
    if (schema == nullptr) {
        throw std::invalid_argument("Invalid schema URL: " + schemaUrl);
    }
    return schema->validate(data);
}
```
