                    return false;

                var client = _clients[config.Url];
                var request = new HttpRequestMessage(new HttpMethod(config.Method), config.Url);

                foreach (var header in config.Headers)
                {
                    request.Headers.Add(header.Key, header.Value.ToString());
                }

                foreach (var param in config.QueryParams)
                {
                    request.RequestUri = new UriBuilder(request.RequestUri).SetQueryParam(param.Key, param.Value.ToString()).Uri;
                }

                var response = await client.SendAsync(request);
                if (response.StatusCode != HttpStatusCode.OK)
                    return false;
            }

            return true;
        }

