            if (matchedEndpoints.Count == 0)
                return false;

            var response = await GetResponse(request, matchedEndpoints[0]);
            if (response != null)
            {
                var client = _clients[matchedEndpoints[0].Url];
                var resp = new HttpResponseMessage()
                {
                    StatusCode = response.StatusCode,
                    Content = new StringContent(response.Body, Encoding.UTF8, "application/json")
                };
                foreach (var header in response.Headers)
                {
                    resp.Headers.Add(header.Key, header.Value.ToString());
                }
                return true;
            }

            return false;
        }

        public async Task<EndpointResponse> GetResponse(HttpRequestMessage request, EndpointConfig config)
        {
            var client = _clients[config.Url];
            var requestUri = new UriBuilder(request.RequestUri).SetQueryParam(config.QueryParams[0].Key, config.QueryParams[0].Value.ToString()).Uri;
            var resp = await client.SendAsync(request);
            if (resp.StatusCode == HttpStatusCode.OK)
                return new EndpointResponse()
                {
                    StatusCode = resp.StatusCode,
                    ContentType = resp.Content.Headers.ContentType.MediaType,
                    Body = await resp.Content.ReadAsStringAsync()
                };
            else
                return null;
        }
    }
}']

