```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

// Define the structure for storing the RRC message data
struct rrc_message {
    char *msg;  // Pointer to the RRC message data
    size_t length;  // Length of the RRC message data
};

// Define the structure for storing the RRC message metadata
struct rrc_metadata {
    char *name;  // Name of the RRC message type
    size_t length;  // Length of the RRC message data
    int version;  // Version of the RRC message type
};

// Define the structure for storing the collection of RRC messages
struct rrc_message_collection {
    struct rrc_message *messages;  // Array of pointers to RRC messages
    size_t num_messages;  // Number of RRC messages in the collection
    size_t max_messages;  // Maximum number of RRC messages that can be stored in the collection
};

// Define the function for adding a new RRC message to the collection
void add_rrc_message(struct rrc_message_collection *collection, char *msg, size_t length) {
    // Check if there is enough space in the collection to store the new message
    if (collection->num_messages == collection->max_messages) {
        // Reallocate memory for the collection to accommodate the new message
        struct rrc_message *new_messages = realloc(collection->messages, sizeof(struct rrc_message) * (collection->max_messages + 1));
        if (new_messages == NULL) {
            // Reallocation failed; return an error
            printf("Error: could not add new RRC message to collection\n");
            return;
        }
        collection->messages = new_messages;
        collection->max_messages++;
    }

    // Add the new RRC message to the collection
    collection->messages[collection->num_messages].msg = malloc(length);
    if (collection->messages[collection->num_messages].msg == NULL) {
        // Memory allocation failed; return an error
        printf("Error: could not allocate memory for new RRC message\n");
        return;
    }
    memcpy(collection->messages[collection->num_messages].msg, msg, length);
    collection->messages[collection->num_messages].length = length;
    collection->num_messages++;
}

// Define the function for retrieving an RRC message from the collection
struct rrc_message *get_rrc_message(struct rrc_message_collection *collection, size_t index) {
    // Check if the specified index is out of range
    if (index >= collection->num_messages) {
        printf("Error: requested RRC message index %zu is out of range\n", index);
        return NULL;
    }

    // Return the RRC message at the specified index
    return &collection->messages[index];
}

// Define the function for removing an RRC message from the collection
void remove_rrc_message(struct rrc_message_collection *collection, size_t index) {
    // Check if the specified index is out of range
    if (index >= collection->num_messages) {
        printf("Error: requested RRC message index %zu is out of range\n", index);
        return;
    }

    // Remove the RRC message at the specified index from the collection
    struct rrc_message *msg = &collection->messages[index];
    free(msg->msg);
    memmove(&collection->messages[index], &collection->messages[index + 1], (collection->num_messages - index - 1) * sizeof(struct rrc_message));
    collection->num_messages--;
}

// Define the function for iterating over all RRC messages in the collection
void iterate_rrc_messages(struct rrc_message_collection *collection, void (*callback)(struct rrc_message *)) {
    // Iterate over all RRC messages in the collection and call the specified callback function for each message
    for (size_t i = 0; i < collection->num_messages; i++) {
        struct rrc_message *msg = &collection->messages[i];
        callback(msg);
    }
}
```
