} MessageData;

// Define the message queue to hold the messages
struct MessageQueue {
  pthread_mutex_t mutex;
  pthread_cond_t cond;
  int capacity;
  int size;
  MessageMetadata* metadata;
  MessageData* data;
};

// Initialize the message queue with a given capacity
void initializeMessageQueue(struct MessageQueue* q, int capacity) {
  // Initialize the mutex and condition variable for the queue
  pthread_mutex_init(&q->mutex, NULL);
  pthread_cond_init(&q->cond, NULL);

  // Set the capacity of the queue
  q->capacity = capacity;

  // Initialize the size of the queue to zero
  q->size = 0;

  // Allocate memory for the metadata and data arrays
  q->metadata = malloc(sizeof(MessageMetadata) * capacity);
  q->data = malloc(sizeof(MessageData) * capacity);
}

// Deinitialize the message queue
void deinitializeMessageQueue(struct MessageQueue* q) {
  // Free the memory allocated for the metadata and data arrays
  free(q->metadata);
  free(q->data);

  // Destroy the mutex and condition variable for the queue
  pthread_mutex_destroy(&q->mutex);
  pthread_cond_destroy(&q->cond);
}

// Enqueue a new message to the queue
void enqueueMessage(struct MessageQueue* q, char* type, uint16_t length) {
  // Lock the mutex for the queue
  pthread_mutex_lock(&q->mutex);

  // Check if the queue is full
  if (q->size == q->capacity) {
    // If the queue is full, wait until there is space available
    while (q->size == q->capacity) {
      pthread_cond_wait(&q->cond, &q->mutex);
    }
  }

  // Add the new message to the end of the queue
  q->metadata[q->size].type = type;
  q->metadata[q->size].length = length;
  q->data[q->size].data = malloc(sizeof(char) * length);
  q->data[q->size].size = length;
  q->size++;

  // Signal the condition variable to indicate that there is space available in the queue
  pthread_cond_signal(&q->cond);

  // Unlock the mutex for the queue
  pthread_mutex_unlock(&q->mutex);
}

// Dequeue a message from the queue
void dequeueMessage(struct MessageQueue* q, char** type, uint16_t* length) {
  // Lock the mutex for the queue
  pthread_mutex_lock(&q->mutex);

  // Check if there are any messages in the queue
  if (q->size == 0) {
    // If there are no messages in the queue, wait until there is a message available
    while (q->size == 0) {
      pthread_cond_wait(&q->cond, &q->mutex);
    }
  }

  // Get the first message from the queue
  *type = q->metadata[0].type;
  *length = q->metadata[0].length;

  // Remove the first message from the queue
  for (int i = 1; i < q->size; i++) {
    q->metadata[i - 1].type = q->metadata[i].type;
    q->metadata[i - 1].length = q->metadata[i].length;
    q->data[i - 1].data = q->data[i].data;
    q->data[i - 1].size = q->data[i].size;
  }
  q->size--;

  // Signal the condition variable to indicate that there is space available in the queue
  pthread_cond_signal(&q->cond);

  // Unlock the mutex for the queue
  pthread_mutex_unlock(&q->mutex);
}
