// Structure to represent a message queue entry
struct message_queue_entry {
    char *payload;
    size_t payload_size;
};

// Function to create a new message queue
void init_message_queue() {
    // Allocate memory for the message queue
    struct message_queue_entry *messages = (struct message_queue_entry *)malloc(MAX_MESSAGES * sizeof(struct message_queue_entry));
    if (!messages) {
        perror("Failed to allocate memory for message queue");
        exit(1);
    }

    // Initialize the message queue with NULL payloads
    for (int i = 0; i < MAX_MESSAGES; i++) {
        messages[i].payload = NULL;
        messages[i].payload_size = 0;
    }

    // Create a semaphore to synchronize access to the message queue
    int sem_id = sem_open("message_queue_sem", O_CREAT, 0644, MAX_MESSAGES);
    if (sem_id < 0) {
        perror("Failed to create semaphore");
        exit(1);
    }
}

// Function to add a new message to the queue
void enqueue_message(const char *payload, size_t payload_size) {
    // Check if the message queue is full
    struct message_queue_entry *messages = (struct message_queue_entry *)sem_wait(MAX_MESSAGES);
    if (!messages) {
        perror("Failed to wait on semaphore");
        exit(1);
    }

    // Allocate memory for the new payload
    char *new_payload = (char *)malloc(payload_size + 1);
    if (!new_payload) {
        perror("Failed to allocate memory for new payload");
        exit(1);
    }

    // Copy the payload into the new allocation
    memcpy(new_payload, payload, payload_size);
    new_payload[payload_size] = '\0';

    // Add the new payload to the message queue
    messages->payload = new_payload;
    messages->payload_size = payload_size;

    // Increment the semaphore value to indicate that there is a new entry in the queue
    if (sem_post(MAX_MESSAGES) < 0) {
        perror("Failed to post semaphore");
        exit(1);
    }
}

// Function to remove and return the next message from the queue
struct message_queue_entry dequeue_message() {
    // Wait on the semaphore to ensure that there is an entry in the queue
    struct message_queue_entry *messages = (struct message_queue_entry *)sem_wait(MAX_MESSAGES);
    if (!messages) {
        perror("Failed to wait on semaphore");
        exit(1);
    }

    // Get the next message from the queue
    struct message_queue_entry new_message;
    new_message.payload = messages[0].payload;
    new_message.payload_size = messages[0].payload_size;

    // Shift all remaining messages down one index
    for (int i = 1; i < MAX_MESSAGES - 1; i++) {
        messages[i-1] = messages[i];
    }

    // Remove the last entry from the queue
    messages[MAX_MESSAGES - 1].payload = NULL;
    messages[MAX_MESSAGES - 1].payload_size = 0;

    // Increment the semaphore value to indicate that there is one less entry in the queue
    if (sem_post(MAX_MESSAGES) < 0) {
        perror("Failed to post semaphore");
        exit(1);
    }

    return new_message;
}

// Function to read a message from a file descriptor
struct message_queue_entry read_message(int fd) {
    // Read the payload size from the file descriptor
    uint32_t payload_size = 0;
    if (read(fd, &payload_size, sizeof(uint32_t)) < 0) {
        perror("Failed to read message payload size");
        exit(1);
    }

    // Allocate memory for the payload
    char *payload = (char *)malloc(payload_size + 1);
    if (!payload) {
        perror("Failed to allocate memory for message payload");
        exit(1);
    }

    // Read the payload from the file descriptor
    if (read(fd, payload, payload_size) < 0) {
        perror("Failed to read message payload");
        exit(1);
    }

    // Add the new message to the queue
    enqueue_message(payload, payload_size);
}

// Function to write a message to a file descriptor
void write_message(int fd, const char *payload, size_t payload_size) {
    // Write the payload size to the file descriptor
    if (write(fd, &payload_size, sizeof(uint32_t)) < 0) {
        perror("Failed to write message payload size");
        exit(1);
    }

    // Write the payload to the file descriptor
    if (write(fd, payload, payload_size) < 0) {
        perror("Failed to write message payload");
        exit(1);
    }
}

int main() {
    init();

    // Open a file descriptor for reading and writing
    int fd = open("message_queue.txt", O_RDWR | O_CREAT, 0644);
    if (fd < 0) {
        perror("Failed to open file descriptor");
        exit(1);
    }

    // Read a message from the file descriptor and add it to the queue
    read_message(fd);

    // Remove and return the next message from the queue
    struct message_queue_entry message = dequeue_message();

    // Write the message back to the file descriptor
    write_message(fd, message.payload, message.payload_size);

    return 0;
}
```

In this example, we have defined a `struct` called `message_queue_entry` that contains two fields: `payload`, which is a pointer to the actual message payload, and `payload_size`, which is an integer representing the size of the payload. We have also defined a function called `init()` that initializes the message queue by creating a semaphore with a value of 0.

We have then implemented three functions: `enqueue_message()`, `dequeue_message()`, and `read_message()`. The `enqueue_message()` function takes in a payload and its size, allocates memory for it, adds it to the end of the queue, and increments the semaphore value to indicate that there is a new entry in the queue. The `dequeue_message()` function waits on the semaphore to ensure that there is an entry in the queue, removes and returns the next message from the queue, and decrements the semaphore value to indicate that there is one less entry in the queue. The `read_message()` function reads a payload size from a file descriptor, allocates memory for the payload, reads the payload from the file descriptor, adds the new message to the queue, and increments the semaphore value to indicate that there is a new entry in the queue.

The `write_message()` function takes in an integer file descriptor, a pointer to the message payload, and its size, writes the payload size to the file descriptor, writes the payload to the file descriptor, and increments the semaphore value to indicate that there is a new entry in the queue.

The `main()` function first initializes the message queue by creating a semaphore with a value of 0, opens a file descriptor for reading and writing to a file called "message_queue.txt", reads a message from the file descriptor and adds it to the queue, removes and returns the next message from the queue, writes the message back to the file descriptor, and closes the file descriptor.

