import logging
from typing import List, Dict
from urllib.parse import quote_plus

import requests

logger = logging.getLogger(__name__)

class SecureStringProcessor:
    def __init__(self, api_key: str):
        self.api_key = api_key
        self.headers = {"Authorization": f"Bearer {api_key}"}
        self.encryption_algo = "AES-256-CBC"

    def encrypt(self, plaintext: str) -> str:
        """Encrypts the given plaintext using the external encryption service API."""
        try:
            params = {"key": self.api_key}
            data = {
                "plaintext": plaintext,
                "encryptionAlgo": self.encryption_algo,
            }
            response = requests.post(
                "https://example.com/encrypt", headers=self.headers, params=params, json=data
            )
            if response.status_code == 200:
                encrypted_data = response.json()["encryptedData"]
                return encrypted_data
            else:
                logger.error(f"Error during encryption: {response.text}")
                raise Exception("Encryption failed")
        except requests.RequestException as e:
            logger.exception(e)
            raise e

    def decrypt(self, ciphertext: str) -> str:
        """Decrypts the given ciphertext using the external encryption service API."""
        try:
            params = {"key": self.api_key}
            data = {
                "ciphertext": ciphertext,
                "encryptionAlgo": self.encryption_algo,
            }
            response = requests.post(
                "https://example.com/decrypt", headers=self.headers, params=params, json=data
            )
            if response.status_code == 200:
                plaintext = response.json()["plaintext"]
                return plaintext
            else:
                logger.error(f"Error during decryption: {response.text}")
                raise Exception("Decryption failed")
        except requests.RequestException as e:
            logger.exception(e)
            raise e

    def process_strings(self, strings: List[str]) -> Dict[str, str]:
        """Processes a list of strings and returns a dictionary of encrypted/decrypted strings."""
        processed_strings = {}
        for string in strings:
            if self.encryption_algo == "AES-256-CBC":
                processed_strings[string] = self.encrypt(string)
            else:
                raise ValueError("Unsupported encryption algorithm")
        return processed_strings
```
