#include "message_handler.h"

// Global variables
const char* config_file = "/etc/message_handler.conf";
int config_interval = 600; // 10 minutes

// Struct to hold configuration data
struct Config {
    int version;
    char* api_url;
    char* client_id;
    char* client_secret;
};

// Function to read and parse the config file
void load_config() {
    struct Config config = {};
    json_object *json, *version, *api_url, *client_id, *client_secret;

    // Load configuration from file
    FILE* fp = fopen(config_file, "r");
    if (fp == NULL) {
        perror("Failed to open config file");
        exit(1);
    }
    json = json_object_from_file(config_file);
    version = json_object_get_object(json, "version");
    api_url = json_object_get_string(json, "api_url");
    client_id = json_object_get_string(json, "client_id");
    client_secret = json_object_get_string(json, "client_secret");
    fclose(fp);

    // Check if all required fields are present
    if (version == NULL || api_url == NULL || client_id == NULL || client_secret == NULL) {
        perror("Invalid config file format");
        exit(1);
    }

    // Set the global configuration variables
    config.version = json_object_get_int(version);
    config.api_url = strdup(json_object_get_string(api_url));
    config.client_id = strdup(json_object_get_string(client_id));
    config.client_secret = strdup(json_object_get_string(client_secret));
}

// Function to fetch updated message definitions from the RESTful API
void update_messages() {
    struct Config* config = load_config();
    char* url = (char*) malloc(strlen(config->api_url) + 10);
    sprintf(url, "%s/messages?version=%d", config->api_url, config->version);

    CURL* curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_HTTPAUTH, CURLAUTH_BASIC);
        curl_easy_setopt(curl, CURLOPT_USERPWD, config->client_id . ":". config->client_secret);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_perform(curl);
        curl_easy_cleanup(curl);
    }
}

// Function to handle incoming LTE RRC messages
void message_handler(char* message) {
    struct Config* config = load_config();
    json_object *json, *version, *type, *payload;

    // Parse the JSON message
    json = json_tokener_parse(message);
    version = json_object_get_object(json, "version");
    type = json_object_get_string(json, "type");
    payload = json_object_get_string(json, "payload");

    // Check if the message is valid and has a known version
    if (version == NULL || !json_object_is_number(version)) {
        printf("Invalid message format\n");
        return;
    }

    // Update the message definitions if necessary
    int current_version = json_object_get_int(version);
    if (current_version > config->version) {
        update_messages();
        config->version = current_version;
    }

    // Handle the message based on its type
    switch (json_object_get_string(type)) {
        case "MESSAGE1":
            // Handle message 1
            break;
        case "MESSAGE2":
            // Handle message 2
            break;
        default:
            printf("Unknown message type\n");
    }
}

// Callback function for the curl library
size_t write_callback(void* contents, size_t size, size_t nmemb, void** userp) {
    // Save the response to a temporary buffer
    size_t realsize = size * nmemb;
    char* tmp = (char*) malloc(realsize + 1);
    memcpy(tmp, contents, realsize);
    tmp[realsize] = '\0';

    // Parse the JSON response and update the message definitions
    json_object *json = json_tokener_parse(tmp);
    if (json != NULL) {
        json_object_get_object(json, "messages");
        free(tmp);
        return realsize;
    } else {
        printf("Invalid response from API\n");
        return -1;
    }
}
