using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;
using MyLibrary.Encryption;

namespace MyLibrary
{
    public class AesCbcEncryption : IEncryption
    {
        private readonly ILogger<AesCbcEncryption> _logger;
        private readonly byte[] _key;
        private readonly byte[] _iv;

        public AesCbcEncryption(IKeyManager keyManager, IVectorProvider vectorProvider)
        {
            _logger = LoggerFactory.CreateLogger<AesCbcEncryption>();
            _key = keyManager.GetKey();
            _iv = vectorProvider.GetVector();
        }

        public string Encrypt(string plainText)
        {
            try
            {
                using (var aesAlg = new AesManaged())
                {
                    aesAlg.KeySize = 256;
                    aesAlg.BlockSize = 128;
                    aesAlg.Mode = CipherMode.CBC;
                    aesAlg.Padding = PaddingMode.PKCS7;
                    aesAlg.FeedbackSize = 128;
                    var encryptor = aesAlg.CreateEncryptor(_key, _iv);
                    var memoryStream = new MemoryStream();
                    using (var cryptoStream = new CryptoStream(memoryStream, encryptor, CryptoStreamMode.Write))
                    {
                        using (var streamWriter = new StreamWriter(cryptoStream))
                        {
                            streamWriter.Write(plainText);
                        }
                        var cipherTextBytes = memoryStream.ToArray();
                        return Convert.ToBase64String(cipherTextBytes);
                    }
                }
            }
            catch (Exception e)
            {
                _logger.LogError("Encryption failed: " + e.Message);
                throw;
            }
        }

        public string Decrypt(string cipherText)
        {
            try
            {
                using (var aesAlg = new AesManaged())
                {
                    aesAlg.KeySize = 256;
                    aesAlg.BlockSize = 128;
                    aesAlg.Mode = CipherMode.CBC;
                    aesAlg.Padding = PaddingMode.PKCS7;
                    aesAlg.FeedbackSize = 128;
                    var decryptor = aesAlg.CreateDecryptor(_key, _iv);
                    var memoryStream = new MemoryStream(Convert.FromBase64String(cipherText));
                    using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                    {
                        using (var streamReader = new StreamReader(cryptoStream))
                        {
                            return streamReader.ReadToEnd();
                        }
                    }
                }
            }
            catch (Exception e)
            {
                _logger.LogError("Decryption failed: " + e.Message);
                throw;
            }
        }
    }
}
