// Modular, scalable, and secure C# library for managing JWT-based authentication and authorization
using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.IdentityModel.Tokens;
using Newtonsoft.Json.Linq;
using Redis;
using RedisClient;
using RedisClient.Models;

namespace JwtAuthLib
{
    public class AuthManager : IAuthManager
    {
        private readonly IServiceProvider _serviceProvider;
        private readonly RedisClientOptions _redisOptions;
        private readonly TokenValidationParameters _tokenValidationParams;

        // DI constructor
        public AuthManager(IServiceProvider serviceProvider, RedisClientOptions redisOptions, TokenValidationParameters tokenValidationParams)
        {
            _serviceProvider = serviceProvider;
            _redisOptions = redisOptions;
            _tokenValidationParams = tokenValidationParams;
        }

        // Function to issue a JWT access token for the specified user and client
        public async Task<string> IssueAccessTokenAsync(string userId, string clientId)
        {
            // Use dependency injection to get an instance of the RedisClient
            var redisClient = _serviceProvider.GetService<RedisClient>();

            // Generate a new JWT access token for the specified user and client
            var jwtToken = await CreateAccessTokenAsync(userId, clientId);

            // Add the access token to the Redis cache
            await redisClient.SetAsync("access_token:" + userId + "-" + clientId, jwtToken);

            return jwtToken;
        }

        // Function to validate a JWT access token and retrieve the associated user ID and client ID
        public async Task<(string UserId, string ClientId)> ValidateAccessTokenAsync(string jwtToken)
        {
            try
            {
                // Use dependency injection to get an instance of the RedisClient
                var redisClient = _serviceProvider.GetService<RedisClient>();

                // Retrieve the access token from the Redis cache
                var accessToken = await redisClient.GetAsync("access_token:" + jwtToken);

                // Validate the access token using Microsoft's TokenValidationParameters
                var claimsPrincipal = TokenValidator.ValidateToken(jwtToken, _tokenValidationParams);

                // Retrieve the user ID and client ID from the JWT access token
                var userId = claimsPrincipal.FindFirst("sub").Value;
                var clientId = claimsPrincipal.FindFirst("aud").Value;

                return (userId, clientId);
            }
            catch (Exception ex)
            {
                Console.WriteLine(ex.Message);
                throw;
            }
        }

        // Function to invalidate a JWT access token and delete it from the Redis cache
        public async Task InvalidateAccessTokenAsync(string jwtToken)
        {
            try
            {
                // Use dependency injection to get an instance of the RedisClient
                var redisClient = _serviceProvider.GetService<RedisClient>();

                // Retrieve the access token from the Redis cache
                var accessToken = await redisClient.GetAsync("access_token:" + jwtToken);

                // Invalidate the access token and delete it from the Redis cache
                await redisClient.DelAsync("access_token:" + jwtToken);
            }
            catch (Exception ex)
            {
                Console.WriteLine(ex.Message);
                throw;
            }
        }

        // Function to generate a new JWT access token for the specified user and client
        private async Task<string> CreateAccessTokenAsync(string userId, string clientId)
        {
            try
            {
                // Use dependency injection to get an instance of the RedisClient
                var redisClient = _serviceProvider.GetService<RedisClient>();

                // Generate a new JWT access token for the specified user and client
                var jwtToken = await TokenGenerator.GenerateAccessTokenAsync(userId, clientId);

                return jwtToken;
            }
            catch (Exception ex)
            {
                Console.WriteLine(ex.Message);
                throw;
            }
        }
    }
}
