class TCPPacket {
 public:
  // constructor and destructor
  TCPPacket(const std::string& type, const std::vector<unsigned char>& data) : type_(type), data_(data) {}
  ~TCPPacket() = default;

  // accessors
  const std::string& getType() const { return type_; }
  const std::vector<unsigned char>& getData() const { return data_; }

 private:
  std::string type_;
  std::vector<unsigned char> data_;
};

class TCPPacketManager {
 public:
  // constructor and destructor
  TCPPacketManager() {}
  ~TCPPacketManager() = default;

  // methods for managing packets
  void addPacket(const std::string& type, const std::vector<unsigned char>& data) {
    std::lock_guard<std::mutex> lock(packets_mutex_);
    packets_.emplace_back(type, data);
  }

  void removePacket(const std::string& type) {
    std::lock_guard<std::mutex> lock(packets_mutex_);
    for (auto it = packets_.begin(); it != packets_.end(); ++it) {
      if ((*it).getType() == type) {
        packets_.erase(it);
        break;
      }
    }
  }

  void clearPackets() {
    std::lock_guard<std::mutex> lock(packets_mutex_);
    packets_.clear();
  }

  bool hasPacket(const std::string& type) const {
    std::lock_guard<std::mutex> lock(packets_mutex_);
    for (auto it = packets_.begin(); it != packets_.end(); ++it) {
      if ((*it).getType() == type) {
        return true;
      }
    }
    return false;
  }

  std::vector<TCPPacket> getAllPackets(const std::string& type = "") const {
    std::lock_guard<std::mutex> lock(packets_mutex_);
    if (type.empty()) {
      return packets_;
    } else {
      std::vector<TCPPacket> filtered_packets;
      for (auto packet : packets_) {
        if (packet.getType() == type) {
          filtered_packets.push_back(packet);
        }
      }
      return filtered_packets;
    }
  }

 private:
  std::vector<TCPPacket> packets_;
  mutable std::mutex packets_mutex_;
};

