  int port_;
};

class TLSManager {
 public:
  // constructor and destructor
  TLSManager() {}
  ~TLSManager() = default;

  // methods for managing TLS sessions
  void addSession(const std::string& id, const std::vector<unsigned char>& session_data) {
    std::lock_guard<std::mutex> lock(sessions_mutex_);
    sessions_.emplace(id, session_data);
  }

  void removeSession(const std::string& id) {
    std::lock_guard<std::mutex> lock(sessions_mutex_);
    sessions_.erase(id);
  }

  bool hasSession(const std::string& id) const {
    std::lock_guard<std::mutex> lock(sessions_mutex_);
    return sessions_.find(id) != sessions_.end();
  }

  std::vector<unsigned char> getSessionData(const std::string& id) const {
    std::lock_guard<std::mutex> lock(sessions_mutex_);
    return sessions_.at(id);
  }

