    if (!isConnected()) {
      connect();
    }
    // serialize the packet and send it over the connection
  }

  void receivePacket(TCPPacket& packet) {
    if (!isConnected()) {
      disconnect();
    }
    // deserialize a packet from the connection
  }

 private:
