  ~TLSClient() = default;

  // methods for establishing a TLS session with a server
  void connect(const std::string& ip, const int port) {
    connection_ = TCPConnection(ip, port);
    connection_.connect();
    tls_session_ = TLSManager().addSession("some_id", "some_data");
  }

  void disconnect() {
    if (connection_) {
      connection_.disconnect();
    }
    if (tls_session_) {
      TLSManager().removeSession(tls_session_);
    }
  }

  bool isConnected() const {
    return connection_ && connection_.isConnected();
  }

  // methods for sending and receiving packets
  void sendPacket(const std::string& type, const std::vector<unsigned char>& data) {
    if (connection_) {
      TCPPacket packet(type, data);
      sendPacket(packet);
    }
  }

  void sendPacket(const TCPPacket& packet) {
    // encrypt the packet using the TLS session
  }

  void receivePacket(TCPPacket& packet) {
    if (connection_) {
      connection_.receivePacket(packet);
    }
    // decrypt the packet using the TLS session
  }

 private:
  TCPConnection connection_;
  std::string tls_session_;
};
