// Custom thread-safe hash table for caching message definitions
typedef struct {
    void** buckets;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} my_hash_table;

my_hash_table* my_create_hash_table(size_t initial_capacity) {
    my_hash_table *table = (my_hash_table*) malloc(sizeof(my_hash_table));
    table->buckets = (void**) malloc(initial_capacity * sizeof(void*));
    memset(table->buckets, 0, initial_capacity);
    table->size = 0;
    table->capacity = initial_capacity;
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

void my_destroy_hash_table(my_hash_table* table) {
    free(table->buckets);
    pthread_mutex_destroy(&table->mutex);
    free(table);
}

void my_put(my_hash_table* table, void* key, void* value) {
    pthread_mutex_lock(&table->mutex);
    if (table->size == table->capacity) {
        size_t new_capacity = table->capacity * 2;
        void** new_buckets = (void**) malloc(new_capacity * sizeof(void*));
        memcpy(new_buckets, table->buckets, table->capacity);
        free(table->buckets);
        table->buckets = new_buckets;
        table->capacity = new_capacity;
    }
    size_t index = hash(key) % table->capacity;
    while (table->buckets[index] != NULL) {
        index = (index + 1) % table->capacity;
    }
    table->buckets[index] = value;
    table->size++;
    pthread_mutex_unlock(&table->mutex);
}

void* my_get(my_hash_table* table, void* key) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash(key) % table->capacity;
    while (index != 0 && table->buckets[index] == NULL) {
        index = (index + 1) % table->capacity;
    }
    void* value = table->buckets[index];
    pthread_mutex_unlock(&table->mutex);
    return value;
}

