    amqp_connection_state_t conn = amqp_new_connection();
    if (conn == NULL) {
        fprintf(stderr, "Failed to establish connection to RabbitMQ\n");
        return 1;
    }

    amqp_channel_open(conn);
    amqp_queue_declare(conn, amqp_cstring_bytes("my_queue"), AMQP_QUEUE_PASSIVE | AMQP_QUEUE_DURABLE);
    amqp_basic_consume(conn, amqp_cstring_bytes("my_queue"), amqp_empty_bytes, 0, 1, 0, 0, amqp_empty_table);

    // Set up the cache for message definitions
    my_hash_table* table = my_create_hash_table(1024);

    // Fetch message definitions from the RESTful API and populate the cache
    char url[512];
    sprintf(url, "http://example.com/api/v1/messages?limit=1024");
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to fetch message definitions from the RESTful API\n");
        return 1;
    }

    // Process messages in real-time
    while (true) {
        amqp_frame_t frame = amqp_consume_frame(conn);
        if (frame.frame_type == AMQP_FRAME_METHOD && frame.payload.method.id == AMQP_BASIC_DELIVER_METHOD) {
            // Parse the incoming message and perform necessary actions
            size_t body_size = frame.payload.basic.body_size;
            void* msg = my_slab_alloc(sizeof(char) * (body_size + 1));
            memcpy(msg, frame.payload.basic.body, body_size);
            ((char*) msg)[body_size] = '\0';

            // Look up the message definition in the cache
            void* def = my_get(table, (void*) msg);
            if (def != NULL) {
                // Perform actions based on the message definition
                // ...
            } else {
                // Fetch the message definition from the RESTful API and add it to the cache
                char url[512];
                sprintf(url, "http://example.com/api/v1/messages/%s", (char*) msg);
                res = curl_easy_perform(curl);
                if (res != CURLE_OK) {
                    fprintf(stderr, "Failed to fetch message definition for message %s\n", (char*) msg);
                    return 1;
                }
                def = my_slab_alloc(sizeof(struct message));
                parse_message(def, frame.payload.basic.body, body_size);
                my_put(table, (void*) msg, def);
            }
        }
    }

    // Clean up resources
    amqp_destroy_connection(conn);
    curl_easy_cleanup(curl);
    my_destroy_hash_table(table);
}
