from threading import Lock

class LineCounter:
    def __init__(self):
        self.lock = Lock()
        self.total_lines = 0

    def count_lines(self, file_path):
        with open(file_path, 'r') as f:
            for line in f:
                with self.lock:
                    self.total_lines += 1

    def get_total_lines(self):
        return self.total_lines

class LineCounterService:
    def __init__(self, file_paths):
        self.file_paths = file_paths
        self.line_counter = LineCounter()

    def count_lines(self):
        with ThreadPoolExecutor(max_workers=5) as executor:
            futures = []
            for file_path in self.file_paths:
                future = executor.submit(self.line_counter.count_lines, file_path)
                futures.append(future)
            for future in futures:
                try:
                    result = future.result()
                except Exception as e:
                    print('Error counting lines:', e)
        return self.line_counter.get_total_lines()

class LineCounterCLI:
    def __init__(self, file_paths=None):
        if not file_paths:
            file_paths = sys.argv[1:]
        self.file_paths = file_paths
        self.line_counter_service = LineCounterService(file_paths)

    def run(self):
        total_lines = self.line_counter_service.count_lines()
