use std::collections::HashMap;
use std::net::TcpStream;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;
use std::io::Read;
use std::io::Write;
use std::result::Result;

pub struct DistributedKeyValueStore {
    servers: Vec<String>,
    clients: HashMap<String, TcpStream>,
    cache: HashMap<String, String>,
}

impl DistributedKeyValueStore {
    pub fn new(servers: Vec<String>) -> Self {
        let mut clients = HashMap::new();
        for server in servers.iter() {
            clients.insert(server.to_string(), TcpStream::connect(*server).unwrap());
        }

        DistributedKeyValueStore {
            servers,
            clients,
            cache: HashMap::new(),
        }
    }

    pub fn get(&mut self, key: &str) -> Result<String, String> {
        if let Some(value) = self.cache.get(key) {
            return Ok(value.to_string());
        }

        let mut client = match self.clients.remove(key) {
            Some(client) => client,
            None => self.connect(key)?,
        };

        client.write(format!("GET {}", key).as_bytes()).unwrap();
        client.flush().unwrap();

        let mut buf = String::new();
        client.read_to_string(&mut buf).unwrap();

        self.cache.insert(key.to_string(), buf);

        Ok(buf)
    }

    pub fn set(&mut self, key: &str, value: &str) -> Result<String, String> {
        let mut client = match self.clients.remove(key) {
            Some(client) => client,
            None => self.connect(key)?,
        };

        client.write(format!("SET {} {}", key, value).as_bytes()).unwrap();
        client.flush().unwrap();

        Ok("Ok".to_string())
    }

    pub fn connect(&mut self, server: &str) -> Result<TcpStream, String> {
        let mut clients = Arc::new(Mutex::new(self.clients.clone()));
        let client = TcpStream::connect(*server).unwrap();

        thread::spawn(move || {
            loop {
                match client.read_to_string(&mut buf) {
                    Ok(_) => {},
                    Err(e) => println!("Error while reading from client: {}", e),
                }
            }
        });

        clients.lock().unwrap().insert(server.to_string(), client);

        Ok(client)
    }
}
