```
#include <iostream>
#include <vector>
#include <string>
#include <cstdlib>
#include <algorithm>
#include <utility>
#include <unordered_map>

// Define a data structure to hold sensor readings
struct SensorReading {
  std::string id;
  double value;
};

// Define a data structure to hold pipeline configuration
struct PipelineConfig {
  std::vector<std::pair<std::string, int>> filters; // List of filters and their positions in the pipeline
  std::unordered_map<std::string, std::string> aggregates; // Map of aggregate functions and their corresponding field names
};

// Define a data structure to hold pipeline state
struct PipelineState {
  std::vector<SensorReading> readings; // Current set of sensor readings
  std::unordered_map<std::string, double> aggregates; // Aggregate values for each field
};

// Define a function to ingest sensor data and apply filters and aggregates
void processData(const PipelineConfig &config, const std::vector<SensorReading> &readings) {
  // Create a copy of the current pipeline state
  PipelineState state = config.pipeline;

  // Apply filters to the sensor readings
  for (int i = 0; i < config.filters.size(); ++i) {
    const auto &filter = config.filters[i];
    if (filter.first == "average") {
      state.readings = average(state.readings);
    } else if (filter.first == "minimum") {
      state.readings = minimum(state.readings);
    } else if (filter.first == "maximum") {
      state.readings = maximum(state.readings);
    }
  }

  // Update the pipeline state with the filtered readings
  config.pipeline.readings = state.readings;

  // Apply aggregates to the filtered readings
  for (const auto &aggregate : config.aggregates) {
    const std::string &fieldName = aggregate.first;
    const std::string &aggregateFunction = aggregate.second;
    if (aggregateFunction == "average") {
      state.aggregates[fieldName] = average(state.readings, fieldName);
    } else if (aggregateFunction == "minimum") {
      state.aggregates[fieldName] = minimum(state.readings, fieldName);
    } else if (aggregateFunction == "maximum") {
      state.aggregates[fieldName] = maximum(state.readings, fieldName);
    }
  }

  // Update the pipeline state with the aggregated values
  config.pipeline.aggregates = state.aggregates;
}

// Define a function to handle errors and recover from failures
void errorHandler(const PipelineConfig &config, const std::string &errorMessage) {
  // Log the error message
  std::cout << "Error: " << errorMessage << std::endl;

  // Try to recover from the error by retrying the failed operation
  if (errorMessage == "Network connection lost") {
    processData(config, config.pipeline.readings);
  } else if (errorMessage == "Aggregate function not supported") {
    const auto &aggregate = config.aggregates[0];
    std::cout << "Error: Aggregate function \"" << aggregate.first << "\" not supported." << std::endl;
  }
}

int main() {
  // Define a pipeline configuration with filters and aggregates
  PipelineConfig config = {
    {"filters": [{"average", 0}, {"minimum", 1}, {"maximum", 2}]},
    {"aggregates": [{"average", "temperature"}, {"minimum", "pressure"}]}
  };

  // Define a list of sensor readings to process
  std::vector<SensorReading> readings = {
    {"sensor1", 20.5},
    {"sensor2", 18.3},
    {"sensor3", 19.7}
  };

  // Process the sensor readings and apply filters and aggregates
  processData(config, readings);

  // Print the processed data to the console
  std::cout << "Filtered readings: ";
  for (const auto &reading : config.pipeline.readings) {
    std::cout << reading.id << ": " << reading.value << ", ";
  }
  std::cout << std::endl;

  std::cout << "Aggregated values: ";
  for (const auto &aggregate : config.pipeline.aggregates) {
    std::cout << aggregate.first << ": " << aggregate.second << ", ";
  }
  std::cout << std::endl;

  return 0;
}
```
This code defines a `PipelineConfig` data structure to hold pipeline configuration, and a `PipelineState` data structure to hold pipeline state. The `processData()` function takes a `PipelineConfig` object and a list of sensor readings as input, and applies filters and aggregates defined in the configuration to the readings. The `errorHandler()` function is called when an error occurs during processing, allowing for error handling and recovery.

The code also defines a `main()` function that demonstrates how to use the pipeline configuration and processing functions. It creates a list of sensor readings and applies filters and aggregates defined in the configuration to the readings using the `processData()` function. The processed data is then printed to the console.']

