// Use shared_ptr and unique_ptr instead of raw pointers to manage memory safely.
using namespace std;

class PaymentProcessor {
  public:
    virtual void processPayment(const string& request) = 0;
};

class InventorySystem {
  public:
    virtual int checkInventory(const string& itemName) = 0;
};

class AnalyticsTool {
  public:
    virtual void trackEvent(const string& eventName, const map<string, string>& eventData) = 0;
};

class RequestContext {
  private:
    shared_ptr<PaymentProcessor> paymentProcessor_;
    shared_ptr<InventorySystem> inventorySystem_;
    shared_ptr<AnalyticsTool> analyticsTool_;
    atomic<bool> completed_{false};
    mutex mu_;
    condition_variable cv_;

  public:
    RequestContext(const string& request, const shared_ptr<PaymentProcessor>& paymentProcessor,
                   const shared_ptr<InventorySystem>& inventorySystem,
                   const shared_ptr<AnalyticsTool>& analyticsTool) {
      paymentProcessor_ = paymentProcessor;
      inventorySystem_ = inventorySystem;
      analyticsTool_ = analyticsTool;
    }

  public:
    void processPayment() {
      // Process the payment using the PaymentProcessor.
      paymentProcessor_->processPayment(request_);
    }

    int checkInventory(const string& itemName) {
      // Check the inventory using the InventorySystem.
      return inventorySystem_->checkInventory(itemName);
    }

    void trackEvent(const string& eventName, const map<string, string>& eventData) {
      // Track the event using the AnalyticsTool.
      analyticsTool_->trackEvent(eventName, eventData);
    }

  private:
    bool isCompleted() {
      std::lock_guard<std::mutex> lk(mu_);
      return completed_;
    }

    void setCompleted() {
      std::unique_lock<std::mutex> ulk(mu_);
      completed_ = true;
      cv_.notify_one();
    }

    bool waitForCompletion(const std::chrono::milliseconds& timeout) {
      std::unique_lock<std::mutex> ulk(mu_);
      return cv_.wait_for(ulk, timeout, [this]() { return isCompleted(); });
    }
};

class RequestHandler {
  private:
    shared_ptr<RequestContext> context_;
    atomic<bool> completed_{false};
    mutex mu_;
    condition_variable cv_;

  public:
    RequestHandler(const shared_ptr<RequestContext>& context) : context_(context) {}

  public:
    void handleRequest() {
      // Process the request using the RequestContext.
      processPayment();
      checkInventory("example-item");
      trackEvent("purchase", {{ "itemName", "example-item" }, {"amount", "100" } });
      setCompleted();
    }

  private:
    bool isCompleted() {
      std::lock_guard<std::mutex> lk(mu_);
      return completed_;
    }

    void setCompleted() {
      std::unique_lock<std::mutex> ulk(mu_);
      completed_ = true;
      cv_.notify_one();
    }

    bool waitForCompletion(const std::chrono::milliseconds& timeout) {
      std::unique_lock<std::mutex> ulk(mu_);
      return cv_.wait_for(ulk, timeout, [this]() { return isCompleted(); });
    }
};

class RequestManager {
  private:
    shared_ptr<RequestContext> context_;
    atomic<bool> completed_{false};
    mutex mu_;
    condition_variable cv_;

  public:
    RequestManager(const shared_ptr<RequestContext>& context) : context_(context) {}

  public:
    void handleRequest() {
      // Handle the request using the RequestHandler.
      RequestHandler handler(context_);
      handler.handleRequest();
      setCompleted();
    }

  private:
    bool isCompleted() {
      std::lock_guard<std::mutex> lk(mu_);
      return completed_;
    }

