      std::unique_lock<std::mutex> ulk(mu_);
      return cv_.wait_for(ulk, timeout, [this]() { return isCompleted(); });
    }
};

class RequestRouter {
  private:
    shared_ptr<RequestContext> context_;
    atomic<bool> completed_{false};
    mutex mu_;
    condition_variable cv_;

  public:
    RequestRouter(const shared_ptr<RequestContext>& context) : context_(context) {}

  public:
    void routeRequest() {
      // Route the request to the appropriate handler.
      if (context_->isCompleted()) {
        return;
      }
      RequestManager manager(context_);
      manager.handleRequest();
      setCompleted();
    }

  private:
    bool isCompleted() {
      std::lock_guard<std::mutex> lk(mu_);
      return completed_;
    }

    void setCompleted() {
      std::unique_lock<std::mutex> ulk(mu_);
      completed_ = true;
      cv_.notify_one();
    }

    bool waitForCompletion(const std::chrono::milliseconds& timeout) {
      std::unique_lock<std::mutex> ulk(mu_);
      return cv_.wait_for(ulk, timeout, [this]() { return isCompleted(); });
    }
};

class RequestProcessor {
  private:
    shared_ptr<RequestContext> context_;
    atomic<bool> completed_{false};
    mutex mu_;
    condition_variable cv_;

  public:
    RequestProcessor(const shared_ptr<RequestContext>& context) : context_(context) {}

  public:
    void processRequest() {
      // Process the request using the RequestRouter.
      if (context_->isCompleted()) {
        return;
      }
      RequestRouter router(context_);
      router.routeRequest();
      setCompleted();
    }

  private:
    bool isCompleted() {
      std::lock_guard<std::mutex> lk(mu_);
      return completed_;
    }

    void setCompleted() {
      std::unique_lock<std::mutex> ulk(mu_);
      completed_ = true;
      cv_.notify_one();
    }

    bool waitForCompletion(const std::chrono::milliseconds& timeout) {
      std::unique_lock<std::mutex> ulk(mu_);
      return cv_.wait_for(ulk, timeout, [this]() { return isCompleted(); });
    }
};
