namespace EncryptionService
{
    public class KeyManager
    {
        private static readonly Dictionary<string, string> _keyCache = new Dictionary<string, string>();
        private static readonly object _lock = new object();
        private const int MAX_KEYS = 10; // maximum number of keys to cache

        public static async Task<string> GetKeyAsync(string keyId)
        {
            if (_keyCache.ContainsKey(keyId))
            {
                return _keyCache[keyId];
            }

            string key = await CallKmsApiAsync(keyId);
            lock (_lock)
            {
                _keyCache.Add(keyId, key);
                if (_keyCache.Count > MAX_KEYS)
                {
                    _keyCache.Remove(_keyCache.First().Key);
                }
            }

            return key;
        }

        private static async Task<string> CallKmsApiAsync(string keyId)
        {
            try
            {
                HttpClient client = new HttpClient();
                string url = $"https://kms.example.com/key/{keyId}";
                HttpResponseMessage response = await client.GetAsync(url);
                response.EnsureSuccessStatusCode();
                string responseBody = await response.Content.ReadAsStringAsync();
                return JsonConvert.DeserializeObject<string>(responseBody);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error getting key from KMS: {ex}");
                throw;
            }
        }
    }

    public class EncryptionService
    {
        private readonly Random _random = new Random();
        private readonly Dictionary<string, string> _ivCache = new Dictionary<string, string>();
        private static readonly object _lock = new object();
        private const int MAX_IVS = 10; // maximum number of IVs to cache

        public async Task<byte[]> EncryptAsync(string keyId, byte[] plaintext)
        {
            string key = await KeyManager.GetKeyAsync(keyId);
            if (key == null)
            {
                throw new Exception("Invalid key ID.");
            }

            string iv = GetIv();
            using (Aes aes = Aes.Create())
            {
                aes.Mode = CipherMode.CBC;
                aes.KeySize = 256;
                aes.BlockSize = 128;
                aes.Key = Encoding.UTF8.GetBytes(key);
                aes.IV = Encoding.UTF8.GetBytes(iv);

                using (MemoryStream ms = new MemoryStream())
                {
                    using (CryptoStream cs = new CryptoStream(ms, aes.CreateEncryptor(), CryptoStreamMode.Write))
                    {
                        await cs.WriteAsync(plaintext, 0, plaintext.Length);
                    }
                    return ms.ToArray();
                }
            }
        }

        public async Task<byte[]> DecryptAsync(string keyId, byte[] ciphertext)
        {
            string key = await KeyManager.GetKeyAsync(keyId);
            if (key == null)
            {
                throw new Exception("Invalid key ID.");
            }

            string iv = GetIv();
            using (Aes aes = Aes.Create())
            {
                aes.Mode = CipherMode.CBC;
                aes.KeySize = 256;
                aes.BlockSize = 128;
                aes.Key = Encoding.UTF8.GetBytes(key);
                aes.IV = Encoding.UTF8.GetBytes(iv);

                using (MemoryStream ms = new MemoryStream())
                {
                    using (CryptoStream cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Write))
                    {
                        await cs.WriteAsync(ciphertext, 0, ciphertext.Length);
                    }
                    return ms.ToArray();
                }
            }
        }

        private string GetIv()
        {
            string iv;
            lock (_lock)
            {
                if (_ivCache.Count > 0)
                {
                    iv = _ivCache[_ivCache.First().Key];
                    _ivCache.Remove(_ivCache.First().Key);
                }
                else
                {
                    byte[] ivBytes = new byte[16];
                    _random.NextBytes(ivBytes);
                    iv = Convert.ToBase64String(ivBytes);
                }
            }
            return iv;
        }
    }
}
