        for esp in self.event_streaming_platforms:
            threading.Thread(target=self._process_esp, args=(esp,)).start()
        for mqs in self.message_queuing_services:
            threading.Thread(target=self._process_mqs, args=(mqs,)).start()
        for nss in self.third_party_notification_systems:
            threading.Thread(target=self._process_nss, args=(nss,)).start()

    def stop(self):
        self.executor.shutdown(wait=True)

    def _process_esp(self, esp):
        while True:
            event = esp.receive()
            if not event:
