#include <sqlite3.h>
#include <stdatomic.h>

// Custom memory pool allocator
struct MemoryPool {
    size_t blockSize;
    size_t numBlocks;
    void** blocks;
};

// Initialize custom memory pool
static void initMemoryPool(struct MemoryPool* pool, size_t blockSize) {
    pool->blockSize = blockSize;
    pool->numBlocks = 0;
    pool->blocks = NULL;
}

// Allocate memory from custom memory pool
void* allocFromPool(struct MemoryPool* pool, size_t size) {
    void* ptr = NULL;
    if (pool->numBlocks > 0 && size <= pool->blockSize) {
        // Search for a suitable block in the pool
        for (int i = 0; i < pool->numBlocks; i++) {
            if (pool->blocks[i] != NULL && pool->blocks[i]->size >= size) {
                ptr = pool->blocks[i];
                break;
            }
        }
    }

    // If no suitable block found, allocate a new one
    if (ptr == NULL) {
        void* newBlock = malloc(blockSize);
        if (newBlock != NULL) {
            pool->numBlocks++;
            pool->blocks = realloc(pool->blocks, pool->numBlocks * sizeof(void*));
            pool->blocks[pool->numBlocks - 1] = newBlock;
            ptr = newBlock;
        }
    }

    return ptr;
}

// Release memory back to custom memory pool
void releaseToPool(struct MemoryPool* pool, void* ptr) {
    if (ptr != NULL) {
        // Find the block in the pool that corresponds to the given pointer
        for (int i = 0; i < pool->numBlocks; i++) {
            if (pool->blocks[i] == ptr) {
                free(ptr);
                pool->blocks[i] = NULL;
                return;
            }
        }
    }
}

// Custom thread-safe functions
static void* allocateThreadSafe(void* args) {
    struct MemoryPool* pool = (struct MemoryPool*)args;
    size_t blockSize = pool->blockSize;

    // Allocate memory from the pool
    void* ptr = allocFromPool(pool, blockSize);

    return ptr;
}

static void releaseThreadSafe(void* args) {
    struct MemoryPool* pool = (struct MemoryPool*)args;
    size_t blockSize = pool->blockSize;

    // Release memory back to the pool
    releaseToPool(pool, ptr);
}

