    if (url != NULL && method != NULL && body != NULL) {
        // Receive response from the given URL using the specified method and body
        rc = receive_http_response(url, method, body);
        if (rc != 0) {
            printf("Error receiving HTTP response: %s\n", strerror(errno));
        }
