                api2.makeRequest(accessToken, transactionId);
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Error processing payment", e);
                throw new RuntimeException("Error processing payment", e);
            }
        } else {
            LOGGER.warning("Invalid transaction: " + transactionId);
            throw new IllegalArgumentException("Invalid transaction: " + transactionId);
        }
    }

    private boolean isValidTransaction(String transactionId) {
        // Check if the transaction exists in the cache
        if (cacheManager.contains(transactionId)) {
            return true;
        } else {
            // Check with third-party API 1 and 2 to confirm the transaction exists
            for (String api : THIRD_PARTY_APIS) {
                ThirdPartyApi api = new ThirdPartyApi(api);
                if (!api.containsTransaction(transactionId)) {
                    return false;
                }
            }
        }
        return true;
    }

    private static class OAuth2Client {
        private static final String[] GRANT_TYPES = {"client_credentials", "password"};

        public OAuth2Client(String[] grantTypes) {
            // Initialize the OAuth 2.0 client with the preferred grant types
