import org.slf4j.LoggerFactory;
import org.slf4j.Logger;

// Imports for external APIs
import com.google.cloud.vision.v1.AnnotateImageRequest;
import com.google.cloud.vision.v1.AnnotateImageResponse;
import com.google.cloud.vision.v1.BatchAnnotateImagesRequest;
import com.google.cloud.vision.v1.BatchAnnotateImagesResponse;
import com.google.cloud.vision.v1.Feature;
import com.google.cloud.vision.v1.Image;
import com.google.cloud.vision.v1.ImageAnnotatorClient;
import com.google.cloud.vision.v1.OutputConfig;
import com.google.cloud.vision.v1.Page;
import com.google.cloud.vision.v1.TextAnnotation;
import com.google.protobuf.ByteString;

public class ImageProcessingService {
  private static final Logger logger = LoggerFactory.getLogger(ImageProcessingService.class);

  // Thread pool for handling requests concurrently
  private ExecutorService executorService = Executors.newFixedThreadPool(10);

  // Instance of the image annotator client for interacting with external APIs
  private ImageAnnotatorClient annotator;

  // Flag to indicate whether the service is running in a multi-tenant environment
  private boolean multiTenant;

  public ImageProcessingService(boolean multiTenant) {
    this.multiTenant = multiTenant;
    if (!this.multiTenant) {
      logger.info("Running in single-tenant mode");
    } else {
      logger.info("Running in multi-tenant mode");
    }
  }

  public void processImages(List<File> images, String tenantId) throws Exception {
    // Create a list of image objects for the API request
    List<Image> imageList = images.stream().map(image -> Image.newBuilder().setContent(ByteString.copyFrom(image)).build()).collect(Collectors.toList());

    // Set up the annotation request with the list of images and relevant features
    AnnotateImageRequest request = AnnotateImageRequest.newBuilder()
      .addFeatures(Feature.newBuilder().setType("DOCUMENT_TEXT_DETECTION").build())
      .addFeatures(Feature.newBuilder().setType("SAFE_SEARCH_DETECTION").build())
      .addFeatures(Feature.newBuilder().setType("LABEL_DETECTION").build())
      .addFeatures(Feature.newBuilder().setType("LOGO_DETECTION").build())
      .addFeatures(Feature.newBuilder().setType("OBJECT_LOCALIZATION").build())
      .addFeatures(Feature.newBuilder().setType("TEXT_DETECTION").build())
      .setImage(imageList)
      .build();

    // Set up the batch annotation request with the annotation request and output configuration
    BatchAnnotateImagesRequest batchRequest = BatchAnnotateImagesRequest.newBuilder()
      .addRequests(request)
      .setOutputConfig(OutputConfig.newBuilder().setGcsDestination(GcsDestination.newBuilder()).build())
      .build();

    // Send the annotation request to the external API and retrieve the response
    BatchAnnotateImagesResponse batchResponse = annotator.batchAnnotateImages(batchRequest);

    // Process the response for each image
    for (int i = 0; i < images.size(); i++) {
      AnnotateImageResponse response = batchResponse.getResponses(i);
      processResponse(response, images.get(i), tenantId);
    }
  }

  private void processResponse(AnnotateImageResponse response, File image, String tenantId) {
    // Extract the relevant information from the response
    List<TextAnnotation> text = response.getTextAnnotationsList();
    List<EntityAnnotation> safeSearch = response.getSafeSearchAnnotation().get();
    List<EntityAnnotation> labels = response.getLabelAnnotationsList();
    List<EntityAnnotation> logos = response.getLogoAnnotationsList();
    List<LocalizedObjectAnnotation> objects = response.getLocalizedObjectAnnotationsList();

    // Log the information for debugging purposes
    logger.info("Tenant ID: " + tenantId);
    logger.info("Image name: " + image.getName());
    logger.info("Text annotations: " + text);
    logger.info("Safe search: " + safeSearch);
    logger.info("Labels: " + labels);
    logger.info("Logos: " + logos);
    logger.info("Objects: " + objects);
  }
}
