public class DependencyManager {
    private static final Map<String, String> dependencies = new HashMap<>();

    public static void init() throws Exception {
        // Initialize the dependencies map
        dependencies.put("aws", "com.amazonaws.services.lambda.runtime.LambdaRuntime");
        dependencies.put("gcp", "com.google.cloud.functions.CloudFunction");
        dependencies.put("azure", "com.microsoft.azure.CloudFunction");
    }

    public static void validateDependency(String dependency) throws Exception {
        // Validate the given dependency against the supported cloud providers and their corresponding SDK classes
        if (!dependencies.containsKey(dependency)) {
            throw new IllegalArgumentException("Unsupported dependency: " + dependency);
        }

