['```cpp
// Modular, fault-tolerant C++ library to manage a distributed network of nodes
#include <iostream>
#include <map>
#include <vector>
#include <string>
#include <set>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <atomic>
#include <future>

// Constants for node status and attributes
const int NODE_ID = 0;
const int NODE_LOCATION = 1;
const int NODE_STATUS = 2;

// Node data structure to store information about each node
struct Node {
    int id;
    std::string location;
    std::string status;
};

// Map to store all nodes in the system
std::map<int, Node> nodeRegistry;

// Set to store all active nodes in the system
std::set<int> activeNodes;

// Mutex for protecting concurrent access to the node registry and active nodes set
std::mutex nodeLock;

// Condition variable for notifying changes in active nodes
std::condition_variable activeNodeCV;

// Function to add a new node to the system
void addNode(int id, const std::string& location) {
    // Acquire lock on node registry and active nodes set
    std::unique_lock<std::mutex> lock(nodeLock);

    // Check if node already exists in the system
    if (nodeRegistry.find(id) != nodeRegistry.end()) {
        throw std::runtime_error("Node with ID " + std::to_string(id) + " already exists");
    }

    // Add new node to the registry and active nodes set
    Node newNode = {id, location, "UP"};
    nodeRegistry[id] = newNode;
    activeNodes.insert(id);

    // Release lock on node registry and active nodes set
    lock.unlock();
}

// Function to remove a node from the system
void removeNode(int id) {
    // Acquire lock on node registry and active nodes set
    std::unique_lock<std::mutex> lock(nodeLock);

    // Check if node exists in the system
    auto it = nodeRegistry.find(id);
    if (it == nodeRegistry.end()) {
        throw std::runtime_error("Node with ID " + std::to_string(id) + " does not exist");
    }

    // Remove node from registry and active nodes set
    nodeRegistry.erase(it);
    activeNodes.erase(id);

    // Release lock on node registry and active nodes set
    lock.unlock();
}

// Function to update the status of a node
void updateNodeStatus(int id, const std::string& status) {
    // Acquire lock on node registry and active nodes set
    std::unique_lock<std::mutex> lock(nodeLock);

    // Check if node exists in the system
    auto it = nodeRegistry.find(id);
    if (it == nodeRegistry.end()) {
        throw std::runtime_error("Node with ID " + std::to_string(id) + " does not exist");
    }

    // Update status of node in registry and active nodes set
    it->second.status = status;
    if (status == "UP") {
        activeNodes.insert(id);
    } else {
        activeNodes.erase(id);
    }

    // Release lock on node registry and active nodes set
    lock.unlock();
}

// Function to retrieve the status of a node
std::string getNodeStatus(int id) {
    // Acquire lock on node registry and active nodes set
    std::unique_lock<std::mutex> lock(nodeLock);

    // Check if node exists in the system
    auto it = nodeRegistry.find(id);
    if (it == nodeRegistry.end()) {
        throw std::runtime_error("Node with ID " + std::to_string(id) + " does not exist");
    }

    // Return status of node in registry and active nodes set
    return it->second.status;

    // Release lock on node registry and active nodes set
    lock.unlock();
}

// Function to retrieve all active nodes
std::vector<int> getActiveNodes() {
    // Acquire lock on node registry and active nodes set
    std::unique_lock<std::mutex> lock(nodeLock);

    // Return vector of IDs for all active nodes in the system
    return std::vector<int>(activeNodes.begin(), activeNodes.end());

    // Release lock on node registry and active nodes set
    lock.unlock();
}

// Function to retrieve all nodes in the system
std::map<int, Node> getAllNodes() {
    // Acquire lock on node registry and active nodes set
    std::unique_lock<std::mutex> lock(nodeLock);

    // Return copy of node registry for all nodes in the system
    return nodeRegistry;

    // Release lock on node registry and active nodes set
    lock.unlock();
}

// Function to subscribe to updates about a specific node
void subscribeToNodeUpdates(int id, std::function<void(std::string)> callback) {
    // Acquire lock on node registry and active nodes set
    std::unique_lock<std::mutex> lock(nodeLock);

    // Check if node exists in the system
    auto it = nodeRegistry.find(id);
    if (it == nodeRegistry.end()) {
        throw std::runtime_error("Node with ID " + std::to_string(id) + " does not exist");
    }

    // Create a new subscription for the given callback function and node ID
    auto subscription = [&]() {
        while (true) {
            // Wait for notification of updated status for this node
            activeNodeCV.wait(lock);

            // If the node is still active, notify subscriber with updated status
            if (activeNodes.find(id) != activeNodes.end()) {
                callback(getNodeStatus(id));
            }
        }
    };

    // Create a new thread for the subscription and start it
    std::thread subThread(subscription);
    subThread.detach();

    // Release lock on node registry and active nodes set
    lock.unlock();
}
