Here is an example of a modular C# library for real-time data streaming and processing across multiple cloud platforms:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Nito.AsyncEx;
using Redis;
using StackExchange.Redis;

namespace RealTimeDataStreaming
{
    public class DataStreamer
    {
        private readonly ILogger<DataStreamer> _logger;
        private readonly List<IMessageConsumer> _consumers;
        private readonly Dictionary<string, IMessageProducer> _producers;
        private readonly AsyncLock _lock;

        public DataStreamer(ILogger<DataStreamer> logger)
        {
            _logger = logger;
            _consumers = new List<IMessageConsumer>();
            _producers = new Dictionary<string, IMessageProducer>();
            _lock = new AsyncLock();
        }

        public async Task StartAsync(CancellationToken cancellationToken)
        {
            // Initialize consumers and producers for each cloud platform
            await InitializeConsumersAndProducersAsync(cancellationToken);

            // Subscribe to message broker events
            await SubscribeToMessageBrokerEventsAsync(cancellationToken);

            // Start consuming messages from the broker
            await ConsumeMessagesFromBrokerAsync(cancellationToken);
        }

        private async Task InitializeConsumersAndProducersAsync(CancellationToken cancellationToken)
        {
            _logger.LogInformation("Initializing consumers and producers...");

            // Create a consumer for each cloud platform
            var consumers = new List<IMessageConsumer>
            {
                new AzureEventHubsConsumer(),
                new AWSKinesisConsumer(),
                new GooglePubSubConsumer(),
                new IBMCloudEventsConsumer(),
                new AlibabaCloudMessageServiceConsumer()
            };

            // Create a producer for each cloud platform
            var producers = new Dictionary<string, IMessageProducer>
            {
                ["Azure"] = new AzureEventHubsProducer(),
                ["AWS"] = new AWSKinesisProducer(),
                ["Google"] = new GooglePubSubProducer(),
                ["IBM"] = new IBMCloudEventsProducer(),
                ["Alibaba"] = new AlibabaCloudMessageServiceProducer()
            };

            // Add consumers and producers to the list
            _consumers.AddRange(consumers);
            foreach (var producer in producers)
            {
                _producers[producer.Key] = producer.Value;
            }
        }

        private async Task SubscribeToMessageBrokerEventsAsync(CancellationToken cancellationToken)
        {
            _logger.LogInformation("Subscribing to message broker events...");

            // Subscribe to message broker events for each cloud platform
            foreach (var consumer in _consumers)
            {
                await consumer.SubscribeAsync(cancellationToken);
            }
        }

        private async Task ConsumeMessagesFromBrokerAsync(CancellationToken cancellationToken)
        {
            _logger.LogInformation("Consuming messages from the broker...");

            // Use a lock to ensure thread safety when consuming messages
            using (await _lock.LockAsync())
            {
                while (!cancellationToken.IsCancellationRequested)
                {
                    try
                    {
                        var message = await _consumers[0].ReceiveAsync(cancellationToken);
                        if (message != null)
                        {
                            // Handle the received message
                            await HandleReceivedMessageAsync(message, cancellationToken);
                        }
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError(ex, "Failed to consume message from broker");
                    }
                }
            }
        }

        private async Task HandleReceivedMessageAsync(IMessage message, CancellationToken cancellationToken)
        {
            // Handle the received message based on its type and content
            if (message is AzureEventHubsMessage azureEventHubsMessage)
            {
                await HandleAzureEventHubsMessageAsync(azureEventHubsMessage, cancellationToken);
            }
            else if (message is AWSKinesisMessage awsKinesisMessage)
            {
                await HandleAWSKinesisMessageAsync(awsKinesisMessage, cancellationToken);
            }
            else if (message is GooglePubSubMessage googlePubSubMessage)
            {
                await HandleGooglePubSubMessageAsync(googlePubSubMessage, cancellationToken);
            }
            else if (message is IBMCloudEventsMessage ibmCloudEventsMessage)
            {
                await HandleIBMCloudEventsMessageAsync(ibmCloudEventsMessage, cancellationToken);
            }
            else if (message is AlibabaCloudMessageServiceMessage alibabaCloudMessageServiceMessage)
            {
                await HandleAlibabaCloudMessageServiceMessageAsync(alibabaCloudMessageServiceMessage, cancellationToken);
            }
        }

        private async Task HandleAzureEventHubsMessageAsync(AzureEventHubsMessage message, CancellationToken cancellationToken)
        {
            // Publish the received message to the appropriate producer
            await _producers["Azure"].PublishAsync(message.Body, cancellationToken);
        }

        private async Task HandleAWSKinesisMessageAsync(AWSKinesisMessage message, CancellationToken cancellationToken)
        {
            // Publish the received message to the appropriate producer
            await _producers["AWS"].PublishAsync(message.Body, cancellationToken);
        }

        private async Task HandleGooglePubSubMessageAsync(GooglePubSubMessage message, CancellationToken cancellationToken)
        {
            // Publish the received message to the appropriate producer
            await _producers["Google"].PublishAsync(message.Body, cancellationToken);
        }

        private async Task HandleIBMCloudEventsMessageAsync(IBMCloudEventsMessage message, CancellationToken cancellationToken)
        {
            // Publish the received message to the appropriate producer
            await _producers["IBM"].PublishAsync(message.Body, cancellationToken);
        }

        private async Task HandleAlibabaCloudMessageServiceMessageAsync(AlibabaCloudMessageServiceMessage message, CancellationToken cancellationToken)
        {
            // Publish the received message to the appropriate producer
            await _producers["Alibaba"].PublishAsync(message.Body, cancellationToken);
        }
    }
}
```

This class provides a way for multiple producers and consumers to communicate with each other using an event hub as a communication channel. The `Start()` method is called to start the event hub, which will create the necessary connections and subscriptions between the producers and consumers. The `Stop()` method is called to stop the event hub and close all of the connections and subscriptions.

The `HandleReceivedMessageAsync()` method is where the actual handling of received messages occurs. This method takes a message and does something with it based on its type. For example, if the message is an `AzureEventHubsMessage`, then the method will call the appropriate producer's `PublishAsync()` method to send the message to that producer.

The event hub also provides a way for producers and consumers to be notified when certain events occur, such as when a consumer is successfully connected or disconnected from the event hub. This can be useful for monitoring purposes, or for logging and debugging.']

