// Add a packet to the queue
void PacketProcessor::enqueuePacket(const PacketMetadata& metadata, const std::string& payload) {
    // Lock the mutex to ensure thread safety
    std::lock_guard<std::mutex> lock(queueMutex);

    // Add the packet to the queue
    packetQueue.push(std::make_pair(metadata, payload));

    // Signal that a new packet is available in the queue
    queueCondVar.notify_one();
}

// Dequeue and process packets based on priority and age
void PacketProcessor::dequeueAndProcessPackets() {
    // Initialize variables for tracking packet processing time and memory usage
    auto startTime = std::chrono::high_resolution_clock::now();
    size_t maxMemoryUsage = 0;

    while (true) {
        // Lock the mutex to ensure thread safety
        std::lock_guard<std::mutex> lock(queueMutex);

        // Check if there are any packets available in the queue
        if (packetQueue.empty()) {
            // Wait for a new packet to be added to the queue or until shutdown signal is received
            queueCondVar.wait(lock, [&]() -> bool { return !packetQueue.empty() || shutdownSignal; });
        }

        // Process packets with higher priority first
        while (!packetQueue.empty()) {
            // Get the current packet from the front of the queue
            auto packet = packetQueue.front();
            packetQueue.pop();

            // Check if the packet is eligible for processing based on age and cumulative bandwidth usage
            if (isEligibleForProcessing(packet)) {
                // Process the packet
                processPacket(packet);
            } else {
                // Put the packet back in the queue if it's not eligible for processing
                packetQueue.push(packet);
            }
        }
    }
}

