package com.mediahostingplatformstorage;

import java.io.File;
import java.util.List;
import java.util.Map;

public class MediaHostingPlatformStorageService {
    private final Map<String, File> fileCache = new ConcurrentHashMap<>();
    private final List<String> storageProviders = new ArrayList<>();
    private final List<String> cdnServers = new ArrayList<>();

    public void init() {
        // Initialize the cache and storage providers
        this.fileCache.clear();
        for (String provider : storageProviders) {
            File file = new File(provider);
            fileCache.put(provider, file);
        }

        // Initialize the CDN servers
        for (String cdnServer : cdnServers) {
            File file = new File(cdnServer);
            fileCache.put(cdnServer, file);
        }
    }

    public void uploadFile(String fileName, InputStream inputStream) throws IOException {
        // Check if the file is already in cache
        File cachedFile = this.fileCache.get(fileName);
        if (cachedFile != null) {
            // If the file is already in cache, use it directly
            return;
        }

        // Otherwise, upload the file to all storage providers and CDN servers
        for (String provider : storageProviders) {
            File file = new File(provider);
            file.mkdirs();
            try {
                Files.copy(inputStream, file.toPath(), StandardCopyOption.REPLACE_EXISTING);
            } catch (Exception e) {
                // Handle any errors during the upload process
            }
        }

        for (String cdnServer : cdnServers) {
            File file = new File(cdnServer);
            file.mkdirs();
            try {
                Files.copy(inputStream, file.toPath(), StandardCopyOption.REPLACE_EXISTING);
            } catch (Exception e) {
                // Handle any errors during the upload process
            }
        }
    }

    public InputStream downloadFile(String fileName) throws IOException {
        // Check if the file is already in cache
        File cachedFile = this.fileCache.get(fileName);
        if (cachedFile != null) {
            return new FileInputStream(cachedFile);
        }

        // Otherwise, download the file from all storage providers and CDN servers
        for (String provider : storageProviders) {
            File file = new File(provider);
            if (file.exists()) {
                return new FileInputStream(file);
            }
        }

        for (String cdnServer : cdnServers) {
            File file = new File(cdnServer);
            if (file.exists()) {
                return new FileInputStream(file);
            }
        }

        // If the file is not found in any storage provider or CDN server, throw an exception
        throw new IOException("File not found: " + fileName);
    }

    public void deleteFile(String fileName) throws IOException {
        // Check if the file is already in cache
        File cachedFile = this.fileCache.get(fileName);
        if (cachedFile != null) {
            // If the file is already in cache, delete it directly
            cachedFile.delete();
            return;
        }

        // Otherwise, delete the file from all storage providers and CDN servers
        for (String provider : storageProviders) {
            File file = new File(provider);
            if (file.exists()) {
                file.delete();
            }
        }

        for (String cdnServer : cdnServers) {
            File file = new File(cdnServer);
            if (file.exists()) {
                file.delete();
            }
        }
    }
}
