import org.apache.flink.api.common.state.*;
import org.apache.flink.api.java.tuple.*;
import org.apache.flink.streaming.api.functions.sink.TwoPhaseCommitSinkFunction;
import org.apache.flink.util.function.*;

// Enrich events with metadata from external sources
def enrichEvents(events: DataStream[Event], config: Config): DataStream[EnrichedEvent] = {
  // Initialize a state descriptor for the cache
  val cacheStateDesc: StateDescriptor[String, EventMetadata] = new MapStateDescriptor[String, EventMetadata]("cache", classOf[String], classOf[EventMetadata])

  // Create a caching sink function to store frequently accessed metadata
  val cachingSinkFn = new TwoPhaseCommitSinkFunction[(String, EnrichedEvent), String](new KeySelector[EnrichedEvent] {
    def getKey(enrichedEvent: EnrichedEvent) = enrichedEvent.eventId
  }) {
    override def commit(value: Tuple2[String, EnrichedEvent], context: CommitContext): Unit = {
      // Store the event metadata in the cache for future use
      val (_, enrichedEvent) = value
      cacheStateDesc.getRuntimeContext().getCacheManager().getCache("eventMetadata").put(enrichedEvent.eventId, enrichedEvent.metadata)
    }
  }

  // Join the event stream with the cache to enrich the events
  val enrichedEvents: DataStream[EnrichedEvent] = events.connect()
    .transform("cache", new TwoPhaseCommitSinkFunction[(String, EnrichedEvent), String](new KeySelector[EnrichedEvent] {
      def getKey(enrichedEvent: EnrichedEvent) = enrichedEvent.eventId
    }) {
      override def commit(value: Tuple2[String, EnrichedEvent], context: CommitContext): Unit = {
        // Update the cache with the latest event metadata
        val (_, enrichedEvent) = value
        cacheStateDesc.getRuntimeContext().getCacheManager().getCache("eventMetadata").put(enrichedEvent.eventId, enrichedEvent.metadata)
      }
    }, cachingSinkFn, config.getInteger("cache.size"))
}
```
In this solution, we define a `enrichEvents` method that takes an input data stream of `Event` objects and returns a data stream of `EnrichedEvent` objects, where each enriched event contains additional metadata fields obtained from external sources. We use the `TwoPhaseCommitSinkFunction` to implement a caching mechanism for frequently accessed metadata, which is stored in an Apache Flink cache with a maximum size set by the `cache.size` configuration parameter.

To join the event stream with the cache, we define a `connect()` method that returns a new data stream containing the enriched events. We use the `KeySelector` interface to specify the key for the caching sink function, which is the event ID in this case. The `commit` method of the caching sink function updates the cache with the latest event metadata after each successful commit.

The `enrichEvents` method is carefully crafted to minimize impact on overall pipeline performance while facilitating easy integration with new data sources and sinks. It uses Apache Flink's caching mechanism to store frequently accessed metadata in a separate cache, which is retrieved from the cache during the join operation. This approach ensures that the pipeline remains extensible and performant as new enrichment rules and data sources are introduced.']

