class ProductService {
    private $client;
    private $cache;
    private $redis;
    private $log;
    private $config;

    public function __construct(Client $client, Cache $cache, Redis $redis, Log $log, Config $config) {
        $this->client = $client;
        $this->cache = $cache;
        $this->redis = $redis;
        $this->log = $log;
        $this->config = $config;
    }

    public function createProduct(array $payload) {
        // Validate the payload against a flexible schema
        $schema = new Schema($this->config['product_create_schema']);
        $validator = new Validator($payload, $schema);
        if (!$validator->validate()) {
            throw new InvalidPayloadException($validator->getErrors());
        }

        // Handle transient failures by retrying with exponential backoff
        $retryDelay = 100;
        $maxRetries = 3;
        for ($i=0; $i < $maxRetries; $i++) {
            try {
                $response = $this->client->post('/products', [
                    'headers' => ['Content-Type' => 'application/json'],
                    'body' => json_encode($payload),
                ]);
                break;
            } catch (GuzzleException $e) {
                if ($i == $maxRetries - 1) {
                    throw new RequestFailedException($e->getMessage(), $e->getCode());
                }
                usleep($retryDelay *= 2);
            }
        }

        // Handle rate limits by retrying after the next available time
        if ($response->hasHeader('X-RateLimit-Retry-After')) {
            $retryAfter = (int) $response->getHeaderLine('X-RateLimit-Retry-After');
            sleep($retryAfter);
            return $this->createProduct($payload);
        }

        // Handle errors by throwing an exception
        if ($response->hasError()) {
            throw new RequestFailedException($response->getBody()->getContents());
