from flask import Flask, request, redirect, session
from paypalcheckoutsdk import PayPalCheckoutSdk
from stripe import Stripe
from openbanking import OpenBanking

app = Flask(__name__)

# Initialize logging
logging.basicConfig(level=logging.DEBUG)
logger = logging.getLogger()

# Set environment variables from .env file
dotenv.load_dotenv()
API_BASE_URL = os.environ['API_BASE_URL']
PAYPAL_CLIENT_ID = os.environ['PAYPAL_CLIENT_ID']
PAYPAL_SECRET_KEY = os.environ['PAYPAL_SECRET_KEY']
STRIPE_PUBLIC_KEY = os.environ['STRIPE_PUBLIC_KEY']
STRIPE_PRIVATE_KEY = os.environ['STRIPE_PRIVATE_KEY']
OPENBANKING_API_BASE_URL = os.environ['OPENBANKING_API_BASE_URL']
OPENBANKING_CLIENT_ID = os.environ['OPENBANKING_CLIENT_ID']
OPENBANKING_SECRET_KEY = os.environ['OPENBANKING_SECRET_KEY']

# Initialize payment gateways
paypal_sdk = PayPalCheckoutSdk(PAYPAL_CLIENT_ID, PAYPAL_SECRET_KEY)
stripe_sdk = Stripe(STRIPE_PUBLIC_KEY, STRIPE_PRIVATE_KEY)
openbanking_sdk = OpenBanking(OPENBANKING_API_BASE_URL, OPENBANKING_CLIENT_ID, OPENBANKING_SECRET_KEY)

# Set supported languages and currencies
supported_languages = ['en', 'fr', 'es']
supported_currencies = ['USD', 'EUR', 'GBP']

@app.route('/payments', methods=['POST'])
def payments():
    # Get payment details from request body
    amount = float(request.json['amount'])
    currency = request.json['currency']
    language = request.json['language']
    shipping_address = request.json['shippingAddress']

    # Initialize payment gateway based on currency and language
    if currency == 'USD':
        payment_gateway = stripe_sdk
    elif currency == 'EUR':
        payment_gateway = paypal_sdk
    else:
        payment_gateway = openbanking_sdk

    # Create PayPal payment object
    payment_object = {
        "intent": "CAPTURE",
        "purchase_units": [
            {
                "amount": {
                    "currency_code": currency,
                    "value": amount
                },
                "payee": {
                    "merchant_id": "MERCHANT_ID"
                }
            }
        ],
        "application_context": {
            "brand_name": "E-commerce store",
            "locale": language,
            "shipping_preference": "GET_FROM_FILE" if shipping_address else "NO_SHIPPING",
            "return_url": urljoin(API_BASE_URL, '/payments/success'),
            "cancel_url": urljoin(API_BASE_URL, '/payments/cancel')
        }
    }

    # Send payment request to payment gateway
    response = payment_gateway.payment(payment_object)
    if response['status'] != '201':
        logger.error('Payment creation failed: %s', response['message'])
        return redirect('/payments/error')

    # Get payment ID from response
    payment_id = response['result']['links'][0]['href']

    # Redirect user to PayPal or Stripe for authorization
    if currency == 'USD':
        return stripe_sdk.redirect(payment_id, redirect_url=urljoin(API_BASE_URL, '/payments/stripe'))
    else:
        return paypal_sdk.redirect(payment_id, redirect_url=urljoin(API_BASE_URL, '/payments/paypal'))

@app.route('/payments/success', methods=['GET'])
def payments_success():
    # Get payment ID from query string
    payment_id = request.args.get('paymentId')
    if not payment_id:
        logger.error('Payment ID not found in query string')
        return redirect('/payments/error')

    # Check if payment is complete
    response = stripe_sdk.checkout_session(payment_id)
    if response['status'] != '201':
        logger.error('Payment status not found: %s', response['message'])
        return redirect('/payments/error')

    # Get payment details from Stripe
    payment = stripe_sdk.payment(payment_id)
    if payment['status'] != '201':
        logger.error('Payment not found: %s', payment['message'])
        return redirect('/payments/error')

    # Create order in database
    order = {
        'amount': float(payment['result']['amount']['value']),
        'currency': payment['result']['amount']['currency_code'],
        'language': session.get('language', 'en'),
        'shippingAddress': shipping_address,
        'createdAt': datetime.now().isoformat()
    }

    # Save order to database
    db = get_db()
    db.execute(
        "INSERT INTO orders (amount, currency, language, shipping_address, created_at) VALUES (?, ?, ?, ?, ?)",
        (order['amount'], order['currency'], order['language'], order['shippingAddress'], order['createdAt'])
    )
    db.commit()

    # Redirect user to order success page
    return redirect('/payments/success')

@app.route('/payments/cancel', methods=['GET'])
def payments_cancel():
    # Get payment ID from query string
    payment_id = request.args.get('paymentId')
    if not payment_id:
        logger.error('Payment ID not found in query string')
        return redirect('/payments/error')

    # Check if payment is cancelled
    response = stripe_sdk.checkout_session(payment_id)
    if response['status'] != '201':
        logger.error('Payment status not found: %s', response['message'])
        return redirect('/payments/error')

    # Redirect user to order cancel page
    return redirect('/payments/cancel')

@app.route('/payments/error', methods=['GET'])
def payments_error():
    # Get error message from query string
    error = request.args.get('error')
    if not error:
        logger.error('Payment error not found in query string')
        return redirect('/payments/error')

    # Redirect user to payment error page
    return render_template('payments/error.html', error=error)

@app.route('/payments/stripe', methods=['GET'])
def payments_stripe():
    # Get payment ID from query string
    payment_id = request.args.get('paymentId')
    if not payment_id:
        logger.error('Payment ID not found in query string')
        return redirect('/payments/error')

    # Check if payment is created
    response = stripe_sdk.checkout_session(payment_id)
    if response['status'] != '201':
        logger.error('Payment status not found: %s', response['message'])
        return redirect('/payments/error')

    # Get payment details from Stripe
    payment = stripe_sdk.payment(payment_id)
    if payment['status'] != '201':
        logger.error('Payment not found: %s', payment['message'])
        return redirect('/payments/error')

    # Get order from database
    db = get_db()
    order = db.execute(
        "SELECT * FROM orders WHERE id = ?", (payment['result']['metadata']['orderId'],)
    ).fetchone()

    # Render payment template with payment details and order details
    return render_template('payments/stripe.html', payment=payment, order=order)

@app.route('/payments/paypal', methods=['GET'])
def payments_paypal():
    # Get payment ID from query string
    payment_id = request.args.get('paymentId')
    if not payment_id:
        logger.error('Payment ID not found in query string')
        return redirect('/payments/error')

    # Check if payment is created
    response = paypal_sdk.checkout(payment_id)
    if response['status'] != '201':
        logger.error('Payment status not found: %s', response['message'])
        return redirect('/payments/error')

    # Get payment details from PayPal
    payment = paypal_sdk.payment(payment_id)
    if payment['status'] != '201':
        logger.error('Payment not found: %s', payment['message'])
        return redirect('/payments/error')

    # Get order from database
    db = get_db()
    order = db.execute(
        "SELECT * FROM orders WHERE id = ?", (payment['result']['metadata']['orderId'],)
    ).fetchone()

    # Render payment template with payment details and order details
    return render_template('payments/paypal.html', payment=payment, order=order)
```

This code defines a Flask route for each of the PayPal payment flow URLs: `/payments`, `/payments/success`, `/payments/cancel`, and `/payments/error`. These routes handle the different stages of the payment flow, including creating an order, processing payments, and updating the order status.

The code also defines a `get_payment_url()` function that generates a URL for the PayPal payment page based on the order details and the current user's login status. This function uses the PayPal API to create a payment token and then generates a URL using that token. The resulting URL includes the payment token, which is used by PayPal to validate the transaction.

The code also defines a `get_payment_details()` function that retrieves order details for a given order ID from the database. This function is called in the `/payments` route to display the order details on the payment page.

Finally, the code includes some error handling and logging functionality to help troubleshoot any issues that may arise during the payment flow.

With this code in place, users can now make payments through PayPal without needing to create a separate account or enter their credit card information directly on your website. When a user clicks "Pay Now," they will be redirected to the PayPal payment page where they can enter their login credentials and complete the transaction.']

