// Implement a resilient API gateway for dynamic microservice ecosystems
const express = require('express');
const app = express();
const rateLimit = require('express-rate-limit');
const cache = require('memory-cache');
const logger = require('morgan');
const monitor = require('monitoring-library');

// Assess and document system dependencies and external data sources
app.dependencies = [ /* list of dependencies */ ];
app.dataSources = [ /* list of data sources */ ];

// Implement dynamic routing mechanism for adapting to microservice availability and performance
const router = express.Router();
router.get('/', (req, res) => {
  const serviceName = req.query.service;
  if (!serviceName || !app.dependencies[serviceName]) {
    return res.status(400).json({ message: 'Service not found' });
  }
  const serviceURL = app.dependencies[serviceName];
  const options = {
    url: serviceURL,
    method: req.method,
    headers: req.headers,
    body: req.body,
  };
  return axios(options)
    .then((response) => res.status(200).json({ data: response.data }))
    .catch((error) => {
      console.log(`Error in ${serviceName}:`, error);
      return res.status(500).json({ message: 'Internal server error' });
    });
});

// Implement rate limiting for preventing abuse and accommodating bursts of activity
const limiter = new rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 50, // 50 requests per minute
});
app.use(limiter);

// Optimize caching strategies for reducing latency and load on backend services
const cacheMiddleware = (req, res, next) => {
  const key = `GET ${req.url}`;
  if (!cache.has(key)) {
    return axios({
      url: req.url,
      method: 'GET',
    })
      .then((response) => {
        cache.set(key, response);
        next();
      })
      .catch((error) => {
        console.log(`Error caching ${req.url}:`, error);
        return res.status(500).json({ message: 'Internal server error' });
      });
  } else {
    const cachedResponse = cache.get(key);
    return res.send(cachedResponse);
  }
};
app.use(cacheMiddleware);

// Collaborate with a content delivery network (CDN) provider to cache static assets globally
const cdn = require('cdn-library');
const cdnMiddleware = (req, res, next) => {
  if (!cdn.isCached(req)) {
    return axios({
      url: req.url,
      method: 'GET',
    })
      .then((response) => {
        cdn.cache(req, response);
        next();
      })
      .catch((error) => {
        console.log(`Error caching ${req.url} in CDN:`, error);
        return res.status(500).json({ message: 'Internal server error' });
      });
  } else {
    const cachedResponse = cdn.getCached(req);
    return res.send(cachedResponse);
  }
};
app.use(cdnMiddleware);

// Implement monitoring and logging framework for tracking API performance, errors, and usage patterns
const log = require('log-library');
const monitorMiddleware = (req, res, next) => {
  const startTime = Date.now();
  return next()
    .then(() => {
      const endTime = Date.now();
      const latency = endTime - startTime;
      log.info(`${req.method} ${req.url} ${res.statusCode} ${latency}`);
    })
    .catch((error) => {
      console.log(`Error logging response:`, error);
      return res.status(500).json({ message: 'Internal server error' });
    });
};
app.use(monitorMiddleware);

// Evaluate and select technologies for resource usage optimization while minimizing costs
const costOptimization = require('cost-optimization-library');
const optimizeResourceUtilization = (req, res, next) => {
  const optimizedResourceUtilization = costOptimization.optimize(req);
  return next();
};
app.use(optimizeResourceUtilization);

// Make strategic decisions about technology stack and architectural components
const technologyStack = [ /* list of technologies */ ];
const architectureComponents = {
  router,
  limiter,
  cacheMiddleware,
  cdnMiddleware,
  monitorMiddleware,
  optimizeResourceUtilization,
};

// Start the API gateway
app.listen(3000, () => console.log('API Gateway started on port 3000'));
