#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>
#include <errno.h>

// Define the data structure for each node in the linked list
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct node *next;
} node_t;

// Global variables for managing the linked list
node_t *head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
bool isRunning = true;

// Function to create a new node with randomized CRC data
node_t* newNode(size_t minSize, size_t maxSize) {
    // Allocate memory for the node data
    NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        printf("Error: Failed to allocate memory for node data\n");
        return NULL;
    }

    // Initialize the CRC data in the node
    data->RX_UE_INFORMATION_TAG = rand() % minSize + 1;
    data->RNTI = rand() % maxSize + 1;
    data->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0 ? true : false;

    // Allocate memory for the node itself
    node_t *node = (node_t*) malloc(sizeof(node_t));
    if (!node) {
        printf("Error: Failed to allocate memory for new node\n");
        free(data);
        return NULL;
    }

    // Set the data and next pointers in the node
    node->data = data;
    node->next = head;
    head = node;

    return node;
}

// Function to destroy a node and its associated data
void destroyNode(node_t *node) {
    // Check if the node is not NULL before destroying it
    if (node == NULL) {
        printf("Error: Node is NULL, unable to destroy\n");
        return;
    }

    // Free the data and next pointers in the node
    free(node->data);
    free(node);
}

// Function to allocate a new node with randomized CRC data within the specified range
void *newNodeWithRandomCRC(size_t minSize, size_t maxSize) {
    // Create a new thread-safe lock for protecting the linked list
    pthread_mutex_lock(&mutex);

    // Check if the global variable is set to running
    if (!isRunning) {
        printf("Error: Node allocation failed, system shutting down\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Create a new node with randomized CRC data
    node_t *node = newNode(minSize, maxSize);
    if (node == NULL) {
        printf("Error: Node allocation failed, system shutting down\n");
        isRunning = false;
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Unlock the mutex and return the new node
    pthread_mutex_unlock(&mutex);
    return node;
}

// Function to destroy a node and its associated data within the specified range
void destroyNodeWithRandomCRC(node_t *node) {
    // Create a new thread-safe lock for protecting the linked list
    pthread_mutex_lock(&mutex);

    // Check if the global variable is set to running
    if (!isRunning) {
        printf("Error: Node destruction failed, system shutting down\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Destroy the node and its associated data
    destroyNode(node);

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Function to allocate a new node with randomized CRC data within the specified range
void *newNodeWithRandomCRCAndLogging(size_t minSize, size_t maxSize) {
    // Create a new thread-safe lock for protecting the linked list
    pthread_mutex_lock(&mutex);

    // Check if the global variable is set to running
    if (!isRunning) {
        printf("Error: Node allocation failed, system shutting down\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Create a new node with randomized CRC data
    node_t *node = newNode(minSize, maxSize);
    if (node == NULL) {
        printf("Error: Node allocation failed, system shutting down\n");
        isRunning = false;
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Log the creation of a new node
    printf("New node created with RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
           node->data->RX_UE_INFORMATION_TAG, node->data->RNTI, node->data->CRC_INDICATION_REL8_TAG.CRCFLAG);

    // Unlock the mutex and return the new node
    pthread_mutex_unlock(&mutex);
    return node;
}

// Function to destroy a node and its associated data within the specified range
void destroyNodeWithRandomCRCAndLogging(node_t *node) {
    // Create a new thread-safe lock for protecting the linked list
    pthread_mutex_lock(&mutex);

    // Check if the global variable is set to running
    if (!isRunning) {
        printf("Error: Node destruction failed, system shutting down\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Log the destruction of a node
    printf("Node destroyed with RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
           node->data->RX_UE_INFORMATION_TAG, node->data->RNTI, node->data->CRC_INDICATION_REL8_TAG.CRCFLAG);

    // Destroy the node and its associated data
    destroyNode(node);

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}
