    std::unordered_map<std::string, std::string> headers; // Response headers
    std::vector<uint8_t> body; // Response body
};

// Define a class to manage HTTP requests and responses
class HTTPRequestHandler {
private:
    // Define an atomic counter for request IDs
    static std::atomic<int> idCounter;

    // Define a mutex for protecting concurrent access to the request queue
    static std::mutex requestQueueMutex;

    // Define a condition variable for notifying when new requests are available
