```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Struct for storing network interface configurations
typedef struct {
    char *ip_address; // IP address of the interface
    char *subnet_mask; // Subnet mask of the interface
    char *mac_address; // MAC address of the interface
    char *default_gateway; // Default gateway of the interface
} nic_config_t;

// Struct for storing the list of NICs and their configurations
typedef struct {
    unsigned int num_nics; // Number of NICs in the list
    nic_config_t *nics[1024]; // List of NIC configurations
} nics_list_t;

// Function to add a new NIC to the list of NICs and its configurations
void add_nic(nics_list_t *list, const char *ip_address, const char *subnet_mask, const char *mac_address, const char *default_gateway) {
    // Check if there is enough space in the list to store the new NIC
    if (list->num_nics >= 1024) {
        printf("Error: Maximum number of NICs reached\n");
        return;
    }

    // Allocate memory for the new NIC configuration
    nic_config_t *new_nic = malloc(sizeof(nic_config_t));
    if (new_nic == NULL) {
        printf("Error: Failed to allocate memory for new NIC\n");
        return;
    }

    // Set the IP address, subnet mask, MAC address, and default gateway of the new NIC
    strcpy(new_nic->ip_address, ip_address);
    strcpy(new_nic->subnet_mask, subnet_mask);
    strcpy(new_nic->mac_address, mac_address);
    strcpy(new_nic->default_gateway, default_gateway);

    // Add the new NIC to the list of NICs and its configurations
    list->nics[list->num_nics++] = new_nic;
}

// Function to remove a NIC from the list of NICs and its configurations
void remove_nic(nics_list_t *list, const char *ip_address) {
    // Find the index of the NIC with the given IP address in the list
    int nic_index = -1;
    for (int i = 0; i < list->num_nics; i++) {
        if (strcmp(list->nics[i]->ip_address, ip_address) == 0) {
            nic_index = i;
            break;
        }
    }

    // Check if the NIC was found in the list
    if (nic_index == -1) {
        printf("Error: NIC with IP address %s not found\n", ip_address);
        return;
    }

    // Free the memory allocated for the removed NIC configuration
    free(list->nics[nic_index]);

    // Shift all NIC configurations after the removed NIC to fill the gap
    for (int i = nic_index; i < list->num_nics - 1; i++) {
        list->nics[i] = list->nics[i + 1];
    }

    // Decrement the number of NICs in the list
    list->num_nics--;
}

// Function to update a NIC configuration in the list
void update_nic(nics_list_t *list, const char *ip_address, const char *key, const char *value) {
    // Find the index of the NIC with the given IP address in the list
    int nic_index = -1;
    for (int i = 0; i < list->num_nics; i++) {
        if (strcmp(list->nics[i]->ip_address, ip_address) == 0) {
            nic_index = i;
            break;
        }
    }

    // Check if the NIC was found in the list
    if (nic_index == -1) {
        printf("Error: NIC with IP address %s not found\n", ip_address);
        return;
    }

    // Update the configuration key-value pair of the specified NIC
    if (strcmp(key, "ip") == 0) {
        strcpy(list->nics[nic_index]->ip_address, value);
    } else if (strcmp(key, "subnet_mask") == 0) {
        strcpy(list->nics[nic_index]->subnet_mask, value);
    } else if (strcmp(key, "mac_address") == 0) {
        strcpy(list->nics[nic_index]->mac_address, value);
    } else if (strcmp(key, "default_gateway") == 0) {
        strcpy(list->nics[nic_index]->default_gateway, value);
    } else {
        printf("Error: Invalid configuration key %s\n", key);
        return;
    }
}

// Function to retrieve a NIC configuration from the list
void get_nic(nics_list_t *list, const char *ip_address, nic_config_t *config) {
    // Find the index of the NIC with the given IP address in the list
    int nic_index = -1;
    for (int i = 0; i < list->num_nics; i++) {
        if (strcmp(list->nics[i]->ip_address, ip_address) == 0) {
            nic_index = i;
            break;
        }
    }

    // Check if the NIC was found in the list
    if (nic_index == -1) {
        printf("Error: NIC with IP address %s not found\n", ip_address);
        return;
    }

    // Copy the configuration of the specified NIC to the output parameter
    *config = *(list->nics[nic_index]);
}
