    NO_FAILOVER
};

// Resource utilization metrics
enum Metric {
    CPU_USAGE,
    RAM_USAGE,
    DISK_USAGE,
    NETWORK_INPUT,
    NETWORK_OUTPUT
};

// Deployment configuration
class DeploymentConfig {
public:
    string instanceType;
    int instanceCount;
    ScalingPolicy scalingPolicy;
    LoadBalancingPolicy loadBalancingPolicy;
    FailoverPolicy failoverPolicy;
