    vector<pair<string, string>> appInstances_; // Instances in containerized applications (appID, instanceID)
    map<Metric, int> resourceUtilization_; // Resource utilization metrics
    thread workerThread_; // Worker thread for managing deployments and applications

public:
    Framework() : mtx_(), cv_(), cloudAPIs_(), deployments_(), apps_(), deploymentInstances_(), appInstances_(), resourceUtilization_(), workerThread_(&Framework::worker, this) {}

    // Add a new cloud API instance
    void addCloudAPI(const string& apiName, unique_ptr<CloudAPI>&& api) {
        lock_guard<mutex> lock(mtx_);
        cloudAPIs_.emplace(apiName, move(api));
    }

    // Add a new deployment configuration
    void addDeploymentConfig(const string& deploymentID, const DeploymentConfig& config) {
        lock_guard<mutex> lock(mtx_);
        deployments_.emplace(deploymentID, config);
    }

    // Add a new containerized application configuration
    void addAppConfig(const string& appID, const AppConfig& config) {
        lock_guard<mutex> lock(mtx_);
        apps_.emplace(appID, config);
    }

    // Update deployment instance count
    void updateDeploymentInstanceCount(const string& deploymentID, int count) {
        lock_guard<mutex> lock(mtx_);
        for (auto& instance : deploymentInstances_) {
            if (instance.first == deploymentID) {
                instance.second = count;
            }
        }
    }

    // Update application instance count
    void updateAppInstanceCount(const string& appID, int count) {
        lock_guard<mutex> lock(mtx_);
        for (auto& instance : appInstances_) {
            if (instance.first == appID) {
                instance.second = count;
            }
        }
    }

    // Remove a deployment configuration
    void removeDeploymentConfig(const string& deploymentID) {
        lock_guard<mutex> lock(mtx_);
        deployments_.erase(deploymentID);
    }

    // Remove a containerized application configuration
    void removeAppConfig(const string& appID) {
        lock_guard<mutex> lock(mtx_);
        apps_.erase(appID);
    }

    // Run the worker thread
    void runWorker() {
        unique_lock<mutex> lock(mtx_);
        cv_.wait(lock, [&] { return !deploymentInstances_.empty(); });
        while (!deploymentInstances_.empty()) {
            auto instance = deploymentInstances_.back();
            deploymentInstances_.pop_back();
            auto config = deployments_[instance.first];
            // Scale instances in deployment based on scaling policy
