  int sensorId;
  std::string value;
};

// Sliding window buffer for storing data when the network is down
std::vector<SensorData> slidingWindowBuffer;

// Function to connect to MQTT broker and HTTP server
void Connect() {
  // Create a new MQTT client
  mqttClients.push_back(new MQTTClient());

  // Connect to the MQTT broker
  if (!mqttClients[0]->Connect("localhost", 1883)) {
    std::cerr << "Failed to connect to MQTT broker" << std::endl;
  }

  // Create a new HTTP client
  httpClients.push_back(new httplib::Client());

  // Connect to the HTTP server
  if (!httpClients[0]->Connect("localhost", 80)) {
    std::cerr << "Failed to connect to HTTP server" << std::endl;
  }
}

// Function to disconnect from MQTT broker and HTTP server
void Disconnect() {
  // Disconnect from the MQTT broker
  if (mqttClients[0]->Disconnect()) {
    std::cerr << "Failed to disconnect from MQTT broker" << std::endl;
  }

  // Disconnect from the HTTP server
  if (httpClients[0]->Disconnect()) {
    std::cerr << "Failed to disconnect from HTTP server" << std::endl;
  }
}

// Function to publish sensor data to MQTT broker
void PublishToMQTT(SensorData& data) {
  // Create a new MQTT message
  MQTTMessage* msg = new MQTTMessage();

  // Set the topic and payload of the message
  msg->SetTopic("sensor-data");
  msg->SetPayload(data.value);

  // Publish the message to the MQTT broker
  if (!mqttClients[0]->PublishMessage(msg)) {
    std::cerr << "Failed to publish sensor data to MQTT broker" << std::endl;
  }
}

// Function to send sensor data to HTTP server
void SendToHTTP(SensorData& data) {
  // Create a new HTTP request
  httplib::Request req;

  // Set the URL and method of the request
  req.SetURL("http://localhost/api/sensor-data");
  req.SetMethod(httplib::HTTP_POST);

  // Add the sensor data to the body of the request
  req.SetBody(data.value);

  // Send the request to the HTTP server
  httplib::Client& client = *httpClients[0];
  if (!client.SendRequest(req)) {
    std::cerr << "Failed to send sensor data to HTTP server" << std::endl;
  }
}

// Function to handle incoming MQTT messages
void HandleMQTTMessage(const MQTTPacket* packet) {
  // Check if the message is a valid JSON object
  if (!packet->IsJSONObject()) {
    std::cerr << "Received invalid JSON object from MQTT broker" << std::endl;
    return;
  }

  // Parse the JSON object and extract the sensor data
  json::JSONValue* value = packet->GetJSONValue();
  if (value == nullptr) {
    std::cerr << "Failed to parse JSON object from MQTT broker" << std::endl;
    return;
  }

  // Check if the sensor data is valid
  int sensorId = value->GetInt("sensorId");
  if (sensorId <= 0) {
    std::cerr << "Invalid sensor ID received from MQTT broker" << std::endl;
    return;
  }

  // Add the sensor data to the sliding window buffer
  SensorData data = {sensorId, value->GetString("value")};
  slidingWindowBuffer.push_back(data);
}

// Function to handle incoming HTTP requests
void HandleHTTPRequest(const httplib::Client& client) {
  // Check if the request is a valid JSON object
  json::JSONValue* value = client.GetBody();
  if (value == nullptr) {
    std::cerr << "Failed to parse JSON object from HTTP server" << std::endl;
    return;
  }

  // Check if the sensor data is valid
  int sensorId = value->GetInt("sensorId");
  if (sensorId <= 0) {
    std::cerr << "Invalid sensor ID received from HTTP server" << std::endl;
    return;
  }

  // Add the sensor data to the sliding window buffer
  SensorData data = {sensorId, value->GetString("value")};
  slidingWindowBuffer.push_back(data);
}

// Function to process incoming sensor data
void ProcessSensorData() {
  // Check if there is any data in the sliding window buffer
  if (slidingWindowBuffer.size() == 0) {
    return;
  }

  // Get the oldest data in the sliding window buffer
  SensorData& data = slidingWindowBuffer[0];

  // Check if the data is valid
  if (data.sensorId <= 0) {
    std::cerr << "Invalid sensor data received" << std::endl;
    return;
  }

  // Publish the data to MQTT broker
  PublishToMQTT(data);

  // Send the data to HTTP server
  SendToHTTP(data);

  // Remove the oldest data from the sliding window buffer
  slidingWindowBuffer.erase(slidingWindowBuffer.begin());
}

// Function to handle incoming MQTT messages and incoming HTTP requests
void HandleIncomingData() {
  // Check if there are any incoming MQTT messages or incoming HTTP requests
  if (mqttClients[0]->HasMessage()) {
    const MQTTPacket* packet = mqttClients[0]->ReceiveMessage();
    HandleMQTTMessage(packet);
  } else if (httpClients[0]->HasRequest()) {
    httplib::Client& client = *httpClients[0];
    HandleHTTPRequest(client);
  }
}

// Function to handle outgoing MQTT messages and HTTP requests
void HandleOutgoingData() {
  // Check if there are any outgoing MQTT messages or HTTP requests
  if (mqttClients[0]->HasMessage()) {
    const MQTTPacket* packet = mqttClients[0]->ReceiveMessage();
    PublishToMQTT(packet);
  } else if (httpClients[0]->HasRequest()) {
    httplib::Client& client = *httpClients[0];
    SendToHTTP(client);
  }
}

// Function to handle incoming sensor data and process it
void HandleIncomingSensorData() {
  // Check if there is any incoming sensor data
  if (mqttClients[0]->HasMessage()) {
    const MQTTPacket* packet = mqttClients[0]->ReceiveMessage();
    HandleMQTTMessage(packet);
  } else if (httpClients[0]->HasRequest()) {
    httplib::Client& client = *httpClients[0];
    HandleHTTPRequest(client);
  }

  // Process the incoming sensor data
  ProcessSensorData();
}

int main() {
  // Connect to the MQTT broker and HTTP server
  Connect();

  // Handle incoming sensor data and process it
  while (true) {
    HandleIncomingSensorData();
  }

  // Disconnect from the MQTT broker and HTTP server
  Disconnect();

  return 0;
}
