#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

using namespace std;

class DataBuffer {
public:
    void add(const string& data) {
        unique_lock<mutex> lock(m_mutex);
        m_data.push_back(data);
        m_cv.notify_all();
    }

    void remove(vector<string>& result) {
        unique_lock<mutex> lock(m_mutex);
        while (result.size() < m_batchSize) {
            if (!m_data.empty()) {
                result.push_back(m_data.front());
                m_data.pop_front();
            } else {
                m_cv.wait(lock);
            }
        }
    }

private:
    vector<string> m_data;
    const size_t m_batchSize = 10;
    mutex m_mutex;
    condition_variable m_cv;
};

class Processor {
public:
    void run() {
        while (true) {
            vector<string> data;
            {
                unique_lock<mutex> lock(m_buffer.m_mutex);
                m_buffer.remove(data);
            }
            process(data);
        }
    }

private:
    void process(const vector<string>& data) {
        // Process the data here
        for (const auto& item : data) {
            cout << item << endl;
        }
    }

    DataBuffer m_buffer;
};

int main() {
    vector<string> data = {"apple", "banana", "cherry"};
    Processor processor;
    processor.run();
    return 0;
}']

