// Custom Allocator for Efficient Memory Management
class MemoryAllocator {
    private:
        std::vector<std::pair<void*, size_t>> allocatedMemory;

        void* allocate(size_t size) {
            if (size == 0) return nullptr;
            void* ptr = malloc(size);
            if (ptr != nullptr) {
                allocatedMemory.push_back({ptr, size});
            }
            return ptr;
        }

        void deallocate(void* ptr) {
            for (auto it = allocatedMemory.begin(); it != allocatedMemory.end(); ++it) {
                if (it->first == ptr) {
                    free(ptr);
                    allocatedMemory.erase(it);
                    break;
                }
            }
        }

    public:
        MemoryAllocator() {}
        ~MemoryAllocator() {}

        void* allocate(size_t size, int alignment) {
            if (alignment > 0) return nullptr; // not supported by this allocator
            return allocate(size);
        }

        void deallocate(void* ptr, std::size_t size) {
            deallocate(ptr);
        }
};

// Custom Error Handler and Logger for Troubleshooting and Incident Response
class ErrorHandlerLogger {
    private:
        static const int MAX_ERROR_MESSAGE_LENGTH = 256;
        std::string errorMessage;
        bool isError;

        void reset() {
            errorMessage.clear();
            isError = false;
        }

        void handleError(const std::string& message) {
            if (errorMessage.size() < MAX_ERROR_MESSAGE_LENGTH - 1) {
                errorMessage += "\n" + message;
                isError = true;
            } else {
                errorMessage += "\n[truncated]";
            }
        }

    public:
        ErrorHandlerLogger() {}
        ~ErrorHandlerLogger() {}

        const std::string& getErrorMessage() { return errorMessage; }
        bool hasError() { return isError; }

        void handleError(const char* format, ...) {
            va_list args;
            va_start(args, format);
            vsnprintf(errorMessage.data(), MAX_ERROR_MESSAGE_LENGTH - 1, format, args);
            va_end(args);
        }
};

