// Modular Encryption and Decryption Module

#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/modes.h>

#define AES_BLOCK_SIZE 16

class EncryptionDecryptionModule {
private:
    // OpenSSL EVP Context for encryption and decryption
    EVP_CIPHER_CTX *encryptCtx;
    EVP_CIPHER_CTX *decryptCtx;

    // Key management and session state persistence
    char *sessionKey;
    size_t sessionKeyLen;

public:
    EncryptionDecryptionModule() {
        encryptCtx = EVP_CIPHER_CTX_new();
        decryptCtx = EVP_CIPHER_CTX_new();
        sessionKey = NULL;
        sessionKeyLen = 0;
    }

    ~EncryptionDecryptionModule() {
        if (sessionKey != NULL) {
            OPENSSL_free(sessionKey);
        }
        EVP_CIPHER_CTX_free(encryptCtx);
        EVP_CIPHER_CTX_free(decryptCtx);
    }

    // Encryption functions

    void setEncryptionMode(const char *mode) {
        if (strcmp(mode, "ECB") == 0) {
            EVP_EncryptInit(encryptCtx, EVP_aes_128_ecb(), NULL, NULL);
        } else if (strcmp(mode, "CBC") == 0) {
            EVP_EncryptInit(encryptCtx, EVP_aes_128_cbc(), NULL, NULL);
        } else if (strcmp(mode, "CTR") == 0) {
            EVP_EncryptInit(encryptCtx, EVP_aes_128_ctr(), NULL, NULL);
        } else if (strcmp(mode, "GCM") == 0) {
            EVP_EncryptInit(encryptCtx, EVP_aes_128_gcm(), NULL, NULL);
        } else if (strcmp(mode, "EDE") == 0) {
            EVP_EncryptInit(encryptCtx, EVP_aes_128_ede(), NULL, NULL);
        }
    }

    int encryptData(char *data, size_t dataLen) {
        // Set encryption mode
        setEncryptionMode("ECB");

        // Generate random session key if not already generated
        if (sessionKey == NULL) {
            sessionKeyLen = AES_KEY_LENGTH;
            sessionKey = OPENSSL_malloc(sessionKeyLen);
            RAND_bytes(sessionKey, sessionKeyLen);
        }

        // Encrypt data
        EVP_EncryptInit(encryptCtx, NULL, sessionKey, AES_KEY_LENGTH);
        size_t cipherTextLen = 0;
        int ret = EVP_EncryptUpdate(encryptCtx, NULL, &cipherTextLen, data, dataLen);
        if (ret != 1) {
            return -1;
        }
        char *cipherText = OPENSSL_malloc(cipherTextLen + AES_BLOCK_SIZE);
        ret = EVP_EncryptUpdate(encryptCtx, cipherText, &cipherTextLen, data, dataLen);
        if (ret != 1) {
            return -1;
        }
        OPENSSL_free(cipherText);

        // Return encrypted data
        return cipherTextLen;
    }

    // Decryption functions

    void setDecryptionMode(const char *mode) {
        if (strcmp(mode, "ECB") == 0) {
            EVP_DecryptInit(decryptCtx, EVP_aes_128_ecb(), NULL, NULL);
        } else if (strcmp(mode, "CBC") == 0) {
            EVP_DecryptInit(decryptCtx, EVP_aes_128_cbc(), NULL, NULL);
        } else if (strcmp(mode, "CTR") == 0) {
            EVP_DecryptInit(decryptCtx, EVP_aes_128_ctr(), NULL, NULL);
        } else if (strcmp(mode, "GCM") == 0) {
            EVP_DecryptInit(decryptCtx, EVP_aes_128_gcm(), NULL, NULL);
        } else if (strcmp(mode, "EDE") == 0) {
            EVP_DecryptInit(decryptCtx, EVP_aes_128_ede(), NULL, NULL);
        }
    }

    int decryptData(char *cipherText, size_t cipherTextLen) {
        // Set decryption mode
        setDecryptionMode("ECB");

        // Decrypt data
        EVP_DecryptInit(decryptCtx, NULL, sessionKey, AES_KEY_LENGTH);
        size_t plainTextLen = 0;
        int ret = EVP_DecryptUpdate(decryptCtx, NULL, &plainTextLen, cipherText, cipherTextLen);
        if (ret != 1) {
            return -1;
        }
        char *plainText = OPENSSL_malloc(plainTextLen + AES_BLOCK_SIZE);
        ret = EVP_DecryptUpdate(decryptCtx, plainText, &plainTextLen, cipherText, cipherTextLen);
        if (ret != 1) {
            return -1;
        }
        OPENSSL_free(plainText);

        // Return decrypted data
        return plainTextLen;
    }
};

int main() {
    EncryptionDecryptionModule module;
    char *data = "Hello, World!";
    size_t dataLen = strlen(data);
    char *cipherText = NULL;
    size_t cipherTextLen = 0;

    // Encrypt data using ECB mode
    if (module.encryptData(data, dataLen) < 0) {
        return -1;
    }
    cipherText = OPENSSL_malloc(cipherTextLen + AES_BLOCK_SIZE);

    // Decrypt encrypted data using ECB mode
    if (module.decryptData(cipherText, cipherTextLen) < 0) {
        return -1;
    }

    // Return decrypted data
    return plainTextLen;
}']

