int encrypt(char* input, char* output) {
    // Initialize OpenSSL EVP context
    EVP_CIPHER_CTX *ctx;
    int len;

    // Create encryption context with selected cipher and key
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        printf("Error creating encryption context\n");
        return -1;
    }
    if (EVP_EncryptInit(ctx, EVP_get_cipherbyname("aes-256-cbc"), key, iv) <= 0) {
        printf("Error initializing encryption context\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Encrypt input data and write to output buffer
    len = EVP_EncryptUpdate(ctx, (unsigned char*)output, strlen(input));
    if (len <= 0) {
        printf("Error encrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Write the final block to output buffer
    len = EVP_EncryptFinal(ctx, (unsigned char*)output + strlen(input), &padding);
    if (len <= 0) {
        printf("Error encrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Free the encryption context
    EVP_CIPHER_CTX_free(ctx);

    return len;
}

// Function to decrypt data using EVP
int decrypt(char* input, char* output) {
    // Initialize OpenSSL EVP context
    EVP_CIPHER_CTX *ctx;
    int len;

    // Create decryption context with selected cipher and key
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        printf("Error creating decryption context\n");
        return -1;
    }
    if (EVP_DecryptInit(ctx, EVP_get_cipherbyname("aes-256-cbc"), key, iv) <= 0) {
        printf("Error initializing decryption context\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Decrypt input data and write to output buffer
    len = EVP_DecryptUpdate(ctx, (unsigned char*)output, strlen(input));
    if (len <= 0) {
        printf("Error decrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Write the final block to output buffer
    len = EVP_DecryptFinal(ctx, (unsigned char*)output + strlen(input), &padding);
    if (len <= 0) {
        printf("Error decrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Free the encryption context
    EVP_CIPHER_CTX_free(ctx);

    return len;
}

// Function to handle data encryption at rest and in transit
void encryptData(char* input, char* output) {
    int len = strlen(input);
    // Encrypt the input data using the chosen cipher mode
    encrypt(input, output);
    // Write the encrypted data to the output buffer
    memcpy(output + len, output, strlen(output));
}

// Function to handle data decryption at rest and in transit
void decryptData(char* input, char* output) {
    int len = strlen(input);
    // Decrypt the input data using the chosen cipher mode
    decrypt(input, output);
    // Write the decrypted data to the output buffer
    memcpy(output + len, output, strlen(output));
}

