// LTE_RRC_CU_MessageManager.cpp

#include "LTE_RRC_CU_MessageType.h"
#include "LTE_RRC_CU_MessageManager.h"

LTE_RRC_CU_MessageManager::LTE_RRC_CU_MessageManager() {
    // Initialize the message types and versions maps
    messageTypes = std::map<int, std::vector<LTE_RRC_CU_MessageType>>();
    versionMap = std::map<int, int>();
}

LTE_RRC_CU_MessageManager::~LTE_RRC_CU_MessageManager() {
    // Clean up the message types and versions maps
    messageTypes.clear();
    versionMap.clear();
}

bool LTE_RRC_CU_MessageManager::initialize(std::vector<int> messageTypes, std::vector<int> versionMap) {
    // Check if the input vectors are valid and have the same size
    if (messageTypes.size() != versionMap.size()) {
        return false;
    }

    // Initialize the message types and versions maps with the given values
    this->messageTypes = std::map<int, std::vector<LTE_RRC_CU_MessageType>>();
    this->versionMap = std::map<int, int>();

    for (size_t i = 0; i < messageTypes.size(); ++i) {
        this->messageTypes[messageTypes[i]] = std::vector<LTE_RRC_CU_MessageType>();
        this->versionMap[messageTypes[i]] = versionMap[i];
    }

    return true;
}

void LTE_RRC_CU_MessageManager::addMessageType(int type, void* data) {
    // Check if the message type already exists in the collection
    if (messageTypes.find(type) != messageTypes.end()) {
        return;
    }

    // Create a new message type with its payload and add it to the collection
    LTE_RRC_CU_MessageType newType = LTE_RRC_CU_MessageType();
    newType.type = type;
    newType.data = data;

    messageTypes[type].push_back(newType);
}

void LTE_RRC_CU_MessageManager::removeMessageType(int type) {
    // Check if the message type exists in the collection and remove it
    if (messageTypes.find(type) != messageTypes.end()) {
        messageTypes.erase(type);
        versionMap.erase(type);
    }
}

void* LTE_RRC_CU_MessageManager::getMessageData(int type) {
    // Check if the message type exists in the collection and return its payload
    if (messageTypes.find(type) != messageTypes.end()) {
        return messageTypes[type].back().data;
    } else {
        return NULL;
    }
}

void LTE_RRC_CU_MessageManager::setMessageData(int type, void* data) {
    // Check if the message type exists in the collection and set its payload
    if (messageTypes.find(type) != messageTypes.end()) {
        messageTypes[type].back().data = data;
    }
}

void LTE_RRC_CU_MessageManager::clear() {
    // Clear all message types and their corresponding payloads from the collection
    messageTypes.clear();
    versionMap.clear();
}
