<?php

namespace Microservice;

use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\HttpFoundation\Response;
use Psr\Log\LoggerInterface;
use Doctrine\ORM\EntityManagerInterface;
use Predis\Client;
use GuzzleHttp\Client as HttpClient;
use WebSocket\Connection;

class UserStatisticsService
{
    private $logger;
    private $entityManager;
    private $predis;
    private $httpClient;
    private $connection;

    public function __construct(LoggerInterface $logger, EntityManagerInterface $entityManager, Client $predis, HttpClient $httpClient, Connection $connection)
    {
        $this->logger = $logger;
        $this->entityManager = $entityManager;
        $this->predis = $predis;
        $this->httpClient = $httpClient;
        $this->connection = $connection;
    }

    public function createUser(Request $request)
    {
        // Validate input and create user entity in database
        $user = new User();
        $user->setEmail($request->get('email'));
        $user->setPassword($request->get('password'));
        $this->entityManager->persist($user);
        $this->entityManager->flush();

        // Notify external API for user creation
        $response = $this->httpClient->post('https://external-api.com/users', [
            'json' => [
                'email' => $request->get('email'),
                'password' => $request->get('password')
            ]
        ]);

        // Notify real-time communication platform for user account creation
        $this->connection->send(json_encode([
            'event' => 'user.created',
            'data' => [
                'email' => $request->get('email'),
                'password' => $request->get('password')
            ]
        ]));

        return new Response('User created successfully', 201);
    }

    public function updateUser(Request $request)
    {
        // Validate input and update user entity in database
        $user = $this->entityManager->getRepository(User::class)->find($request->get('id'));
        if (!$user) {
            throw new NotFoundHttpException('User not found');
        }
        $user->setEmail($request->get('email'));
        $user->setPassword($request->get('password'));
        $this->entityManager->persist($user);
        $this->entityManager->flush();

        // Notify external API for user update
        $response = $this->httpClient->put('https://external-api.com/users/' . $request->get('id'), [
            'json' => [
                'email' => $request->get('email'),
                'password' => $request->get('password')
            ]
        ]);

        // Notify real-time communication platform for user account update
        $this->connection->send(json_encode([
            'event' => 'user.updated',
            'data' => [
                'email' => $request->get('email'),
                'password' => $request->get('password')
            ]
        ]));

        return new Response('User updated successfully', 201);
    }

    public function deleteUser(Request $request)
    {
        // Validate input and delete user entity from database
        $user = $this->entityManager->getRepository(User::class)->find($request->get('id'));
        if (!$user) {
            throw new NotFoundHttpException('User not found');
        }
        $this->entityManager->remove($user);
        $this->entityManager->flush();

        // Notify external API for user deletion
        $response = $this->httpClient->delete('https://external-api.com/users/' . $request->get('id'));

        // Notify real-time communication platform for user account deletion
        $this->connection->send(json_encode([
            'event' => 'user.deleted',
            'data' => [
                'email' => $request->get('email'),
                'password' => $request->get('password')
            ]
        ]));

        return new Response('User deleted successfully', 201);
    }

    public function fetchStats(Request $request)
    {
        // Validate input and fetch user statistics from external API
        $response = $this->httpClient->get('https://external-api.com/users/' . $request->get('id') . '/stats');

        // Calculate and return statistics
        $stats = json_decode($response->getBody(), true);
        return new Response(json_encode(['stats' => $stats]));
    }

    public function notifyRealTimeEvents(Request $request)
    {
        // Validate input and fetch real-time event data from external API
        $response = $this->httpClient->get('https://external-api.com/users/' . $request->get('id') . '/events');

        // Handle real-time events
        foreach ($response->json() as $event) {
            switch ($event['type']) {
                case 'user.created':
                    // Notify real-time communication platform for user account creation
                    $this->connection->send(json_encode([
                        'event' => 'user.created',
                        'data' => [
                            'email' => $event['data']['email'],
                            'password' => $event['data']['password']
                        ]
                    ]));
                    break;
                case 'user.updated':
                    // Notify real-time communication platform for user account update
                    $this->connection->send(json_encode([
                        'event' => 'user.updated',
                        'data' => [
                            'email' => $event['data']['email'],
                            'password' => $event['data']['password']
                        ]
                    ]));
                    break;
                case 'user.deleted':
                    // Notify real-time communication platform for user account deletion
                    $this->connection->send(json_encode([
                        'event' => 'user.deleted',
                        'data' => [
                            'email' => $event['data']['email'],
                            'password' => $event['data']['password']
                        ]
                    ]));
                    break;
                default:
                    // Ignore unknown events
                    break;
            }
        }

        return new Response('Real-time events handled successfully', 201);
    }
}
