using Polly;

var circuitBreaker = Policy
    .Handle<KMSException>()
    .CircuitBreakerAsync(
        exceptionsAllowedBeforeBreaking: 5, // maximum number of exceptions before breaking
        durationOfBreak: TimeSpan.FromMinutes(10), // duration of break in minutes
        onBreak: (ex, span) =>
        {
            Console.WriteLine($"Circuit breaker opened for {span.TotalMinutes} minutes due to {ex}");
        },
