# Dynamic Resource Manager
---

import os
from kubernetes import client
from datetime import datetime

def get_available_resources():
    # Get the available resources from Kubernetes API
    api = client.CoreV1Api()
    return api.list_namespaced_pod(namespace="default", watch=False)

def allocate_resources(request):
    # Allocate resources based on request
    pods = get_available_resources()
    if len(pods) > 0:
        for pod in pods:
            if pod.metadata.name not in request.keys():
                pod.spec.containers[0].resources = {
                    "requests": {"cpu": 1, "memory": "2Gi"},
                    "limits": {"cpu": 2, "memory": "4Gi"}
                }
                api.create_namespaced_pod(namespace="default", pod=pod)
            else:
                continue
        return True
    else:
        return False

def schedule_resources(request):
    # Schedule resources based on request and available resources
    pods = get_available_resources()
    if len(pods) > 0:
        for pod in pods:
            if pod.metadata.name not in request.keys():
                continue
            else:
                schedule_time = datetime.now() + timedelta(minutes=15)
                pod.spec.containers[0].resources = {
                    "requests": {"cpu": 2, "memory": "4Gi"},
                    "limits": {"cpu": 3, "memory": "6Gi"}
                }
                api.create_namespaced_pod(namespace="default", pod=pod)
            return True
        else:
            return False
