import os
from requests import get
from urllib.parse import quote

def get_stream_quality(url):
    # Get the quality of a video stream
    response = get(url)
    if response.status_code == 200:
        return "high"
    else:
        return "low"

def set_stream_quality(url, quality):
    # Set the quality of a video stream
    response = get(url)
    if response.status_code == 200:
        if quality == "high":
            response.json()["quality"] = "high"
        else:
            response.json()["quality"] = "low"
        return True
    else:
        return False

def monitor_stream_quality(url):
    # Monitor the quality of a video stream in real-time
    status = get_stream_quality(url)
    if status == "high":
        set_stream_quality(url, "low")
        return True
    else:
        set_stream_quality(url, "high")
        return False
