package com.example.logging;

import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class LoggingFramework {
    private static final int DEFAULT_THREAD_COUNT = 10;
    private static final long DEFAULT_PERIOD_SECONDS = 1L;

    private ScheduledExecutorService executor;
    private int threadCount;
    private long periodSeconds;
    private LoggingPlugin[] plugins;

    public LoggingFramework(int threadCount, long periodSeconds, LoggingPlugin... plugins) {
        this.threadCount = threadCount;
        this.periodSeconds = periodSeconds;
        this.plugins = plugins;
        this.executor = Executors.newScheduledThreadPool(this.threadCount);
    }

    public void start() {
        for (LoggingPlugin plugin : this.plugins) {
            executor.scheduleAtFixedRate(plugin, 0L, this.periodSeconds, TimeUnit.SECONDS);
        }
    }

    public void stop() {
        if (executor != null) {
            executor.shutdown();
        }
    }
}

interface LoggingPlugin {
    void run();
}

class DataIngestionPlugin implements LoggingPlugin {
    private final Logger logger;

    public DataIngestionPlugin(Logger logger) {
        this.logger = logger;
    }

    @Override
    public void run() {
        // ingest data from external sources
        try {
            logger.info("Data ingestion successful");
        } catch (Exception e) {
            logger.error("Data ingestion failed", e);
        }
    }
}

