    while (1) {
        process_api_data(api_data);
        process_msg_data(msg_data);

        // Implement exponential backoff with jitter for transient failures
        if (errno == EINTR) {
            printf("Failed to process API data, retrying in %d seconds\n", rand() % 10);
            sleep(rand() % 10);
